function runBoosterDefinition(rawId) {
  const id = String(rawId || "").trim().toLowerCase();
  if (!CASE_BOOSTER_TYPES.includes(id)) return null;
  const reward = Object.values(SEASON_PASS_BOOST_REWARDS).find((item) => item?.kind === id) || null;
  return {
    id,
    title:String(reward?.title || id),
    imageUrl:String(reward?.imageUrl || ""),
    runs:Math.max(1,Number(CASE_BOOSTER_RUNS[id] || 1))
  };
}

function runBoosterCatalogItems() {
  return CASE_BOOSTER_TYPES.map((id) => runBoosterDefinition(id)).filter(Boolean);
}

function seasonPassProgressionView() {
  return {
    maxLevel:SEASON_PASS_MAX_LEVEL,
    level50StartXp:SEASON_PASS_LEVEL_START_XP[SEASON_PASS_MAX_LEVEL - 1],
    level50CompleteXp:SEASON_PASS_LEVEL_50_COMPLETE_XP,
    overflowStepXp:SEASON_PASS_OVERFLOW_LEVEL_XP,
    overflowAvailableToAll:true,
    existingXpPolicy:'keep_raw_xp_never_reduce',
    balanceVersion:'v4-release',
    overflowReward:{type:"case",itemId:"gold",title:"Золотой кейс",imageUrl:"/assets/cases/gold_closed.png"}
  };
}

function seasonPassOverflowView(xpValue, claimedValue = 0) {
  const xp = Math.max(0, Math.floor(Number(xpValue) || 0));
  const claimed = Math.max(0, Math.floor(Number(claimedValue) || 0));
  const overflowXp = Math.max(0, xp - SEASON_PASS_LEVEL_50_COMPLETE_XP);
  const earned = Math.floor(overflowXp / SEASON_PASS_OVERFLOW_LEVEL_XP);
  return {
    unlocked:xp >= SEASON_PASS_LEVEL_50_COMPLETE_XP,
    baseXp:SEASON_PASS_LEVEL_50_COMPLETE_XP,
    stepXp:SEASON_PASS_OVERFLOW_LEVEL_XP,
    xp:overflowXp,
    xpWithin:overflowXp % SEASON_PASS_OVERFLOW_LEVEL_XP,
    earned,claimed,available:Math.max(0,earned-claimed),
    reward:{type:"case",itemId:"gold",title:"Золотой кейс",imageUrl:"/assets/cases/gold_closed.png"}
  };
}

function seasonPassTaskXpMultiplierForPlayer(season, player) {
  if (String(player?.premium_tier || "none") !== "elite_plus") return 1;
  const config = season?.tierSettings?.elitePlus || seasonPassElitePlusBenefitsView(defaultSeasonPassElitePlusBenefits());
  return config?.xpBoost === false ? 1 : 2;
}

const SEASON_PASS_CATCH_UP_WINDOW_DAYS = 7;
const SEASON_PASS_CATCH_UP_BELOW_LEVEL = 35;
const SEASON_PASS_CATCH_UP_MULTIPLIER = 2;

function seasonPassCatchUpView(season, player, nowMs = Date.now()) {
  const xp=Math.max(0,Math.floor(Number(player?.xp)||0));
  const level=seasonPassLevelFromXp(xp);
  const endMs=Date.parse(String(season?.endsAt||''));
  const activeSeason=String(season?.status||'')==='active';
  const windowMs=SEASON_PASS_CATCH_UP_WINDOW_DAYS*86400000;
  const remainingMs=Number.isFinite(endMs)?endMs-nowMs:-1;
  const startsAt=Number.isFinite(endMs)?endMs-windowMs:0;
  const targetXp=seasonPassXpForLevel(SEASON_PASS_CATCH_UP_BELOW_LEVEL);
  const active=Boolean(activeSeason&&remainingMs>0&&remainingMs<=windowMs&&level<SEASON_PASS_CATCH_UP_BELOW_LEVEL);
  return {
    active,
    multiplier:active?SEASON_PASS_CATCH_UP_MULTIPLIER:1,
    windowDays:SEASON_PASS_CATCH_UP_WINDOW_DAYS,
    eligibleBelowLevel:SEASON_PASS_CATCH_UP_BELOW_LEVEL,
    level,xp,targetXp,xpToTarget:Math.max(0,targetXp-xp),
    daysLeft:remainingMs>0?Math.max(1,Math.ceil(remainingMs/86400000)):0,
    startsAt:startsAt>0?new Date(startsAt).toISOString():'',
    endsAt:Number.isFinite(endMs)?new Date(endMs).toISOString():''
  };
}

function seasonPassEarnedXpMultiplierView(season, player, premiumMultiplier = 1, nowMs = Date.now()) {
  const premium=Math.max(1,Math.floor(Number(premiumMultiplier)||1));
  const catchUp=seasonPassCatchUpView(season,player,nowMs);
  const catchUpMultiplier=catchUp.active?SEASON_PASS_CATCH_UP_MULTIPLIER:1;
  return {multiplier:Math.max(premium,catchUpMultiplier),premiumMultiplier:premium,catchUpMultiplier,catchUp};
}

function legacySeasonPassLevelFromXpV1(value) {
  const xp=Math.max(0,Math.floor(Number(value)||0));
  let low=1,high=SEASON_PASS_MAX_LEVEL;
  while(low<high){const mid=Math.ceil((low+high)/2);if(xp>=LEGACY_SEASON_PASS_LEVEL_START_XP_V1[mid-1])low=mid;else high=mid-1;}
  return low;
}

function convertLegacySeasonPassXpToBalanceV2(value) {
  const xp=Math.max(0,Math.floor(Number(value)||0));
  const legacyFull=LEGACY_SEASON_PASS_LEVEL_START_XP_V1[SEASON_PASS_MAX_LEVEL];
  if (xp >= legacyFull) return SEASON_PASS_LEVEL_50_COMPLETE_XP + (xp - legacyFull);
  const level=legacySeasonPassLevelFromXpV1(xp);
  const oldStart=LEGACY_SEASON_PASS_LEVEL_START_XP_V1[level-1]||0;
  const oldNeed=Math.max(1,LEGACY_SEASON_PASS_LEVEL_XP_V1[level-1]||1);
  const fraction=Math.max(0,Math.min(1,(xp-oldStart)/oldNeed));
  const newStart=SEASON_PASS_LEVEL_START_XP[level-1]||0;
  const newNeed=Math.max(1,SEASON_PASS_LEVEL_XP[level-1]||1);
  return Math.max(0,Math.floor(newStart+fraction*newNeed));
}

function seasonPassBoostRewardDefinition(value) {
  if (!value) return null;
  if (typeof value === "string" && SEASON_PASS_BOOST_REWARDS[value]) return { publicType:value, ...SEASON_PASS_BOOST_REWARDS[value] };
  const itemId=String(value?.item_id ?? value?.itemId ?? "");
  for (const [publicType,definition] of Object.entries(SEASON_PASS_BOOST_REWARDS)) {
    if (definition.itemId === itemId) return { publicType, ...definition };
  }
  return null;
}

const SEASON_PASS_COSMETIC_PREFIX = "season_cosmetic:";
const SEASON_PASS_SHOWCASE_STYLE_PREFIX = "showcase_style:";
const SEASON_PASS_SEASONAL_CASE_PREFIX = "seasonal_case:";
const SEASON_PASS_COSMETIC_KINDS = Object.freeze(["avatar","frame","trail","skin","music"]);

function seasonPassSeasonalCaseRewardDefinition(value) {
  const raw=String(value?.item_id ?? value?.itemId ?? "");
  if(!raw.startsWith(SEASON_PASS_SEASONAL_CASE_PREFIX)) return null;
  const caseId=raw.slice(SEASON_PASS_SEASONAL_CASE_PREFIX.length).trim();
  return caseId ? { publicType:"seasonal_case",storedType:"case",caseId,storedItemId:`${SEASON_PASS_SEASONAL_CASE_PREFIX}${caseId}` } : null;
}

function seasonPassCosmeticCatalog(kind) {
  return ({ avatar:CASE_AVATARS, frame:CASE_FRAMES, trail:CASE_TRAILS, skin:CASE_SKINS, music:CASE_MUSIC_TRACKS })[String(kind||"")] || null;
}

function seasonPassAnyCosmeticCatalog(kind) {
  return { ...(seasonPassCosmeticCatalog(kind)||{}), ...(futureSeasonContentCatalog(kind)||{}) };
}

function defaultSeasonPassElitePlusBenefits() {
  return {
    xpBoost: Boolean(DEFAULT_SEASON_PASS_ELITE_PLUS_BENEFITS.xpBoost),
    bonusLevels: Number(DEFAULT_SEASON_PASS_ELITE_PLUS_BENEFITS.bonusLevels || 0),
    caseType: String(DEFAULT_SEASON_PASS_ELITE_PLUS_BENEFITS.caseType || ""),
    caseCount: Number(DEFAULT_SEASON_PASS_ELITE_PLUS_BENEFITS.caseCount || 0),
    cosmetics: DEFAULT_SEASON_PASS_ELITE_PLUS_BENEFITS.cosmetics.map((item) => ({ kind:String(item.kind), itemId:String(item.itemId) }))
  };
}

function seasonPassElitePlusBenefitsConfig(rawValue) {
  let parsed = null;
  if (rawValue && typeof rawValue === "object" && !Array.isArray(rawValue)) parsed = rawValue;
  else if (typeof rawValue === "string" && rawValue.trim()) {
    try { parsed = JSON.parse(rawValue); } catch {}
  }
  const defaults = defaultSeasonPassElitePlusBenefits();
  const source = parsed && Object.keys(parsed).length ? parsed : defaults;
  const xpBoost = source.xpBoost !== false;
  const bonusLevels = Math.max(0, Math.min(25, Math.floor(Number(source.bonusLevels ?? defaults.bonusLevels) || 0)));
  const requestedCase = String(source.caseType ?? defaults.caseType ?? "").trim();
  const caseType = requestedCase && requestedCase !== "none" ? (normalizeCaseType(requestedCase) || "") : "";
  const caseCount = caseType ? Math.max(0, Math.min(10, Math.floor(Number(source.caseCount ?? defaults.caseCount) || 0))) : 0;
  const rawCosmetics = Array.isArray(source.cosmetics) ? source.cosmetics : defaults.cosmetics;
  const cosmetics = [];
  for (const entry of rawCosmetics.slice(0, 2)) {
    const kind = String(entry?.kind || "").trim();
    const itemId = String(entry?.itemId || entry?.item_id || "").trim();
    if (!SEASON_PASS_COSMETIC_KINDS.includes(kind) || !itemId) continue;
    if (!seasonPassAnyCosmeticCatalog(kind)?.[itemId]) continue;
    if (cosmetics.some((item) => item.kind === kind && item.itemId === itemId)) continue;
    cosmetics.push({ kind, itemId });
  }
  return { xpBoost, bonusLevels, caseType, caseCount, cosmetics };
}

function seasonPassElitePlusBenefitsView(rawValue, options = {}) {
  const config = seasonPassElitePlusBenefitsConfig(rawValue);
  const publicView = Boolean(options.publicView);
  const caseLabels = { small:"Обычный кейс", sweet:"Серебряный кейс", gold:"Золотой кейс", mythic:"Мифический кейс", legendary:"Легендарный кейс", alex:"Кейс Алекса" };
  const cosmetics = config.cosmetics.map(({kind,itemId}) => {
    const item = seasonPassAnyCosmeticCatalog(kind)?.[itemId];
    const future = Boolean(futureSeasonContentItem(kind,itemId));
    const released = !future || liveContentRouteAllowedCached(kind,itemId,"manual");
    if (publicView && future && !released) {
      return { kind:"secret", itemId:"", title:"Секретная награда сезона", imageUrl:"/assets/season-pass/season.png?v=07939", future:true, released:false };
    }
    return {
      kind, itemId,
      title:String(item?.title || itemId),
      imageUrl:seasonPassCosmeticImage(kind,itemId),
      future,
      released
    };
  });
  return {
    xpBoost: config.xpBoost,
    bonusLevels: config.bonusLevels,
    case: config.caseType && config.caseCount > 0 ? {
      type:config.caseType,
      count:config.caseCount,
      title:String(caseLabels[config.caseType] || "Кейс"),
      imageUrl:ownerPanelCaseAsset(config.caseType)
    } : null,
    cosmetics
  };
}

function seasonPassCosmeticImage(kind, itemId) {
  const k=String(kind||""), id=String(itemId||"");
  const future=futureSeasonContentItem(k,id);
  if (future?.imageUrl) return String(future.imageUrl);
  if (k === "skin") return ownerPanelSkinAsset(id);
  if (["avatar","frame","trail"].includes(k)) return String(LIVEOPS_CONTENT_IMAGES?.[k]?.[id] || "/assets/season-pass/season.png?v=07939");
  if (k === "music") return String(CASE_MUSIC_TRACKS?.[id]?.imageUrl || "/assets/season-pass/season.png?v=07939");
  return "/assets/season-pass/season.png?v=07939";
}

function seasonPassCosmeticRewardDefinition(value) {
  if (!value) return null;
  const raw=String(value?.item_id ?? value?.itemId ?? "");
  if (!raw.startsWith(SEASON_PASS_COSMETIC_PREFIX)) return null;
  const body=raw.slice(SEASON_PASS_COSMETIC_PREFIX.length);
  const split=body.indexOf(":");
  if (split <= 0) return null;
  let kind=body.slice(0,split), itemId=body.slice(split+1);
  // Совместимость с ранней скрытой сборкой v9.4: стабильный itemId сохранён, физический файл теперь season2.
  // лежал в папке рамок, хотя фактически это аватарка.
  if (kind === "frame" && itemId === "season3_frame_elite_plus_portrait") {
    kind = "avatar";
    itemId = "season3_avatar_elite_plus";
  }
  if (!SEASON_PASS_COSMETIC_KINDS.includes(kind)) return null;
  const catalog=seasonPassAnyCosmeticCatalog(kind);
  const item=catalog?.[itemId];
  if (!item) return null;
  const future=Boolean(futureSeasonContentItem(kind,itemId));
  const liveRule=future?liveContentReleaseRuleCached(kind,itemId):null,rewardSeasonId=String(value?.season_id??value?.seasonId??"");let released=!future||Boolean(liveRule?.released);
  if(future&&rewardSeasonId){const passRoute=liveContentRoute(liveRule,"season_pass",rewardSeasonId),rewardLevel=Math.max(1,Math.min(50,Math.floor(Number(value?.level)||1))),rewardLane=String(value?.lane||"")==="premium"?"premium":"free";released=Boolean(liveRule?.released&&String(liveRule?.seasonId||"")===rewardSeasonId&&passRoute&&Number(passRoute.level)===rewardLevel&&String(passRoute.lane||"free")===rewardLane);}
  return { publicType:kind, storedType:"points", kind, itemId, storedItemId:`${SEASON_PASS_COSMETIC_PREFIX}${kind}:${itemId}`, title:String(item.title||itemId), imageUrl:seasonPassCosmeticImage(kind,itemId), future, released, seasonLabel:future?futureSeasonContentLabel(kind,itemId):"", audioUrl:String(item.audioUrl||item.src||"") };
}

function seasonPassShowcaseStyleRewardDefinition(value) {
  if (!value) return null;
  const raw=String(value?.item_id ?? value?.itemId ?? "");
  let styleId="";
  if(raw.startsWith(SEASON_PASS_SHOWCASE_STYLE_PREFIX))styleId=raw.slice(SEASON_PASS_SHOWCASE_STYLE_PREFIX.length).trim();
  else if(String(value?.reward_type ?? value?.rewardType ?? "") === "showcase_style")styleId=raw.trim();
  if(!styleId)return null;
  const style=achievementShowcaseRewardStyleDefinition(styleId);
  if(!style)return null;
  return {publicType:"showcase_style",storedType:"points",styleId:String(style.id),itemId:String(style.id),storedItemId:`${SEASON_PASS_SHOWCASE_STYLE_PREFIX}${style.id}`,title:String(style.title||style.id),imageUrl:String(style.imageUrl||""),hidden:Boolean(style.hidden),seasonLabel:String(style.seasonLabel||""),rarity:String(style.rarity||"seasonal")};
}

function seasonPassPublicRewardType(row) {
  return seasonPassSeasonalCaseRewardDefinition(row)?.publicType || seasonPassShowcaseStyleRewardDefinition(row)?.publicType || seasonPassCosmeticRewardDefinition(row)?.publicType || seasonPassBoostRewardDefinition(row)?.publicType || String(row?.reward_type ?? row?.rewardType ?? "");
}

function seasonPassPublicRewardItemId(row) {
  const seasonalCase=seasonPassSeasonalCaseRewardDefinition(row);
  if(seasonalCase) return seasonalCase.caseId;
  const showcaseStyle=seasonPassShowcaseStyleRewardDefinition(row);
  if(showcaseStyle)return showcaseStyle.styleId;
  const cosmetic=seasonPassCosmeticRewardDefinition(row);
  return cosmetic ? cosmetic.itemId : String(row?.item_id ?? row?.itemId ?? "");
}

function seasonPassApplyCosmeticToState(state, cosmetic) {
  if (!state || !cosmetic) return false;
  const id=String(cosmetic.itemId||"");
  if (!id) return false;
  if (cosmetic.kind === "avatar") { state.ownedAvatars=[...new Set([...(state.ownedAvatars||[]),id])]; return true; }
  if (cosmetic.kind === "frame") { state.ownedFrames=[...new Set([...(state.ownedFrames||[]),id])]; return true; }
  if (cosmetic.kind === "trail") { state.ownedTrails=[...new Set([...(state.ownedTrails||[]),id])]; return true; }
  if (cosmetic.kind === "music") { state.ownedMusicTracks=caseParseOwned(JSON.stringify([...(state.ownedMusicTracks||[]),id]),"music",CASE_MUSIC_TRACKS); return true; }
  if (cosmetic.kind === "skin") { state.ownedSkins=normalizeCurrentOwnedSkins([...(state.ownedSkins||[]),id]); return true; }
  return false;
}

async function seasonPassHasXpX2(env, seasonId, telegramId, player = null) {
  try {
    // ×2 XP is not an inventory consumable. It is an Elite+ benefit that is
    // valid only while the player has Elite+ in the active season.
    if (String(player?.premium_tier || "none") !== "elite_plus") return false;
    const seasonRow=await env.DB.prepare(`SELECT elite_plus_benefits_json FROM season_pass_seasons WHERE season_id=? LIMIT 1`).bind(String(seasonId)).first();
    const config=seasonPassElitePlusBenefitsConfig(seasonRow?.elite_plus_benefits_json);
    return Boolean(config.xpBoost);
  } catch (error) {
    console.error("season pass xp boost check failed", error);
    return false;
  }
}

function configuredSeasonPassState(env, nowMs = Date.now()) {
  const startsAt = String(env?.SEASON_PASS_START_AT || DEFAULT_SEASON_PASS_START_AT);
  const endsAt = String(env?.SEASON_PASS_END_AT || DEFAULT_SEASON_PASS_END_AT);
  const startMs = Date.parse(startsAt);
  const endMs = Date.parse(endsAt);
  const safeStartMs = Number.isFinite(startMs) ? startMs : Date.parse(DEFAULT_SEASON_PASS_START_AT);
  const safeEndMs = Number.isFinite(endMs) ? endMs : null;
  const graceRaw = String(env?.SEASON_PASS_CLAIM_GRACE_END_AT || DEFAULT_SEASON_PASS_CLAIM_GRACE_END_AT);
  const graceMs = Date.parse(graceRaw);
  const safeGraceMs = Number.isFinite(graceMs) ? graceMs : Date.parse(DEFAULT_SEASON_PASS_CLAIM_GRACE_END_AT);
  const status = nowMs < safeStartMs ? "upcoming" : safeEndMs != null && nowMs >= safeEndMs ? "ended" : "active";
  return {
    id: String(env?.SEASON_PASS_ID || DEFAULT_SEASON_PASS_ID),
    title: String(env?.SEASON_PASS_TITLE || DEFAULT_SEASON_PASS_TITLE),
    status,
    startsAt: new Date(safeStartMs).toISOString(),
    endsAt: safeEndMs == null ? null : new Date(safeEndMs).toISOString(),
    claimGraceEndsAt: new Date(safeGraceMs).toISOString(),
    claimWindowOpen: false,
    serverTime: new Date(nowMs).toISOString(),
    assetBase: "/assets/season-pass/",
    baseRunXp:100,
    levelPricePoints:DEFAULT_SEASON_PASS_LEVEL_PRICE_POINTS,
    progression:seasonPassProgressionView(),
    prices:{elite:{...DEFAULT_SEASON_PASS_ELITE_PRICE},elite_plus:{...DEFAULT_SEASON_PASS_ELITE_PLUS_PRICE}},
    tierSettings:{elitePlus:seasonPassElitePlusBenefitsView(defaultSeasonPassElitePlusBenefits())}
  };
}

