function firstD1BatchRow(result) {
  return result?.results?.[0] || {};
}

async function recordServerCronDispatchAnalytics(env, summary, now = Math.floor(Date.now() / 1000)) {
  const jobs = Array.isArray(summary) ? summary : [];
  if (!jobs.length) return { recorded: 0 };
  const bucketAt = Math.floor(now / 3600) * 3600;
  const failures = jobs.reduce((total, item) => total + (item?.success ? 0 : 1), 0);
  const durationMs = jobs.reduce((total, item) => total + Math.max(0, Number(item?.durationMs || 0)), 0);
  await env.DB.prepare(
    `INSERT INTO server_analytics_hourly(
       bucket_at,cron_runs,cron_failures,cron_duration_ms,created_at,updated_at
     ) VALUES(?,?,?,?,?,?)
     ON CONFLICT(bucket_at) DO UPDATE SET
       cron_runs=server_analytics_hourly.cron_runs+excluded.cron_runs,
       cron_failures=server_analytics_hourly.cron_failures+excluded.cron_failures,
       cron_duration_ms=server_analytics_hourly.cron_duration_ms+excluded.cron_duration_ms,
       updated_at=excluded.updated_at`
  ).bind(bucketAt, jobs.length, failures, durationMs, now, now).run();
  return { recorded: jobs.length, failures, durationMs, bucketAt };
}

async function collectServerAnalyticsHourly(env, now = Math.floor(Date.now() / 1000)) {
  await ensureServerOptimizationSchema(env);
  const currentHour = Math.floor(now / 3600) * 3600;
  const bucketAt = Math.max(0, currentHour - 3600);
  const endAt = bucketAt + 3600;
  const results = await env.DB.batch([
    env.DB.prepare(`SELECT COUNT(DISTINCT telegram_id) AS count FROM leaderboard_runs WHERE created_at>=? AND created_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM admin_profile_state WHERE created_at>=? AND created_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT COUNT(*) AS total,SUM(CASE WHEN accepted=1 THEN 1 ELSE 0 END) AS accepted FROM leaderboard_runs WHERE created_at>=? AND created_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM level_case_openings WHERE opened_at>=? AND opened_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM granted_cases WHERE opened_at>=? AND opened_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM shop_stock_consumptions WHERE created_at>=? AND created_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT SUM(CASE WHEN status='delivered' THEN 1 ELSE 0 END) AS delivered,SUM(CASE WHEN status='failed' THEN 1 ELSE 0 END) AS failed FROM reward_delivery_queue WHERE updated_at>=? AND updated_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT SUM(CASE WHEN status='sent' THEN 1 ELSE 0 END) AS sent,SUM(CASE WHEN status='failed' THEN 1 ELSE 0 END) AS failed FROM leaderboard_staff_notifications WHERE updated_at>=? AND updated_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT SUM(CASE WHEN status='sent' THEN 1 ELSE 0 END) AS sent,SUM(CASE WHEN status='failed' THEN 1 ELSE 0 END) AS failed FROM player_notification_queue WHERE updated_at>=? AND updated_at<?`).bind(bucketAt, endAt),
    env.DB.prepare(`SELECT cron_runs AS runs,cron_failures AS failures,cron_duration_ms AS duration FROM server_analytics_hourly WHERE bucket_at=?`).bind(bucketAt)
  ]);
  const active = firstD1BatchRow(results[0]);
  const players = firstD1BatchRow(results[1]);
  const runs = firstD1BatchRow(results[2]);
  const levelCases = firstD1BatchRow(results[3]);
  const grantedCases = firstD1BatchRow(results[4]);
  const shop = firstD1BatchRow(results[5]);
  const rewards = firstD1BatchRow(results[6]);
  const staff = firstD1BatchRow(results[7]);
  const player = firstD1BatchRow(results[8]);
  const cron = firstD1BatchRow(results[9]);
  await env.DB.prepare(
    `INSERT INTO server_analytics_hourly(
       bucket_at,active_players,new_players,runs_total,runs_accepted,cases_opened,shop_operations,
       rewards_delivered,rewards_failed,staff_notifications_sent,staff_notifications_failed,
       player_notifications_sent,player_notifications_failed,cron_runs,cron_failures,cron_duration_ms,created_at,updated_at
     ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
     ON CONFLICT(bucket_at) DO UPDATE SET
       active_players=excluded.active_players,new_players=excluded.new_players,runs_total=excluded.runs_total,
       runs_accepted=excluded.runs_accepted,cases_opened=excluded.cases_opened,shop_operations=excluded.shop_operations,
       rewards_delivered=excluded.rewards_delivered,rewards_failed=excluded.rewards_failed,
       staff_notifications_sent=excluded.staff_notifications_sent,staff_notifications_failed=excluded.staff_notifications_failed,
       player_notifications_sent=excluded.player_notifications_sent,player_notifications_failed=excluded.player_notifications_failed,
       cron_runs=excluded.cron_runs,cron_failures=excluded.cron_failures,cron_duration_ms=excluded.cron_duration_ms,updated_at=excluded.updated_at`
  ).bind(
    bucketAt, Number(active.count || 0), Number(players.count || 0), Number(runs.total || 0), Number(runs.accepted || 0),
    Number(levelCases.count || 0) + Number(grantedCases.count || 0), Number(shop.count || 0), Number(rewards.delivered || 0),
    Number(rewards.failed || 0), Number(staff.sent || 0), Number(staff.failed || 0), Number(player.sent || 0),
    Number(player.failed || 0), Number(cron.runs || 0), Number(cron.failures || 0), Number(cron.duration || 0), now, now
  ).run();
  return { bucketAt };
}

async function processHourlyServerMaintenance(env) {
  return runServerCronSteps("hourly-maintenance", [
    ["flashReservations", () => cleanupStaleFlashOfferReservations(env)],
    ["fraud", () => scanFraudAlerts(env)],
    ["stockForecast", () => processV67StockForecastAlerts(env)],
    ["smartAlerts", () => scanV77SmartAlerts(env)],
    ["analytics", () => collectServerAnalyticsHourly(env)]
  ]);
}

async function processDailyServerCleanup(env) {
  const now = Math.floor(Date.now() / 1000);
  await ensureV78Schema(env);
  return runServerCronSteps("daily-cleanup", [
    ["training", () => processV78Cron(env)],
    ["seasonPass", () => cleanupExpiredSeasonPassSeasons(env)],
    ["history", async () => {
      await env.DB.batch([
        env.DB.prepare(`DELETE FROM admin_performance_samples WHERE created_at<?`).bind(now - 7 * V67_DAY),
        env.DB.prepare(`DELETE FROM stock_forecast_snapshots WHERE created_at<?`).bind(now - 30 * V67_DAY),
        env.DB.prepare(`DELETE FROM player_notification_log WHERE sent_at<?`).bind(now - 30 * V67_DAY),
        env.DB.prepare(`DELETE FROM leaderboard_staff_notifications WHERE status='sent' AND sent_at>0 AND sent_at<?`).bind(now - 30 * V67_DAY),
        env.DB.prepare(`DELETE FROM player_notification_queue WHERE status='sent' AND updated_at<?`).bind(now - 30 * V67_DAY),
        env.DB.prepare(`DELETE FROM server_analytics_hourly WHERE bucket_at<?`).bind(now - SERVER_ANALYTICS_RETENTION_SECONDS)
      ]);
    }]
  ]);
}

async function executeServerCronJob(jobKey, env) {
  if (jobKey === "critical-queues") return processCriticalServerQueues(env);
  if (jobKey === "liveops-minute") return processMinuteLiveOps(env);
  if (jobKey === "health-five-minutes") return processFiveMinuteServerHealth(env);
  if (jobKey === "automations-five-minutes") return processFiveMinuteAutomations(env);
  if (jobKey === "hourly-maintenance") return processHourlyServerMaintenance(env);
  if (jobKey === "daily-cleanup") return processDailyServerCleanup(env);
  throw new Error(`Unknown server Cron job: ${jobKey}`);
}

async function processServerCron(env, controller = null) {
  await ensureServerOptimizationSchema(env);
  const now = Math.floor(Date.now() / 1000);
  await setSystemState(env, "cron:last_start", String(now));
  const due = await env.DB.prepare(
    `SELECT job_key,interval_seconds,next_run_at
     FROM server_cron_jobs
     WHERE enabled=1 AND next_run_at<=? AND (lease_until=0 OR lease_until<?)
     ORDER BY priority ASC,next_run_at ASC,job_key ASC
     LIMIT ?`
  ).bind(now, now, SERVER_CRON_MAX_JOBS_PER_TICK).all();
  const summary = [];
  for (const row of due.results || []) {
    const jobKey = String(row.job_key || "");
    const token = caseGrantId("cron_lock");
    const startedAt = Math.floor(Date.now() / 1000);
    const startedMs = Date.now();
    const claim = await env.DB.prepare(
      `UPDATE server_cron_jobs
       SET lease_token=?,lease_until=?,last_started_at=?,last_status='running',last_error='',updated_at=?
       WHERE job_key=? AND enabled=1 AND next_run_at<=? AND (lease_until=0 OR lease_until<?)`
    ).bind(token, startedAt + SERVER_CRON_LEASE_SECONDS, startedAt, startedAt, jobKey, startedAt, startedAt).run();
    if (Number(claim.meta?.changes || 0) < 1) continue;
    let success = true;
    let errorText = "";
    try {
      await executeServerCronJob(jobKey, env);
      try { await clearOperationalIssue(env, `cron:${jobKey}`); } catch {}
    } catch (error) {
      success = false;
      errorText = String(error?.message || error).slice(0, 500);
      console.error(`Cron job ${jobKey} failed`, error);
      try {
        await notifyOperationalIssue(env, `cron:${jobKey}`, `🔴 <b>Ошибка фоновой задачи</b>\n\nЗадача: <code>${escapeHtml(jobKey)}</code>\n${escapeHtml(errorText)}`);
      } catch {}
    }
    const finishedAt = Math.floor(Date.now() / 1000);
    const durationMs = Math.max(0, Date.now() - startedMs);
    const interval = Math.max(60, Number(row.interval_seconds || 60));
    await env.DB.prepare(
      `UPDATE server_cron_jobs SET
         next_run_at=?,lease_token='',lease_until=0,last_finished_at=?,
         last_success_at=CASE WHEN ?=1 THEN ? ELSE last_success_at END,
         last_duration_ms=?,last_status=?,last_error=?,runs_total=runs_total+1,
         failures_total=failures_total+CASE WHEN ?=1 THEN 0 ELSE 1 END,updated_at=?
       WHERE job_key=? AND lease_token=?`
    ).bind(finishedAt + interval, finishedAt, success ? 1 : 0, finishedAt, durationMs, success ? "success" : "failed", errorText, success ? 1 : 0, finishedAt, jobKey, token).run();
    summary.push({ jobKey, success, durationMs });
  }
  const completedAt = Math.floor(Date.now() / 1000);
  try {
    await recordServerCronDispatchAnalytics(env, summary, completedAt);
  } catch (error) {
    console.error("Cron analytics write failed", error);
  }
  await setSystemState(env, "cron:last_success", String(completedAt));
  await setSystemState(env, "cron:last_dispatch", JSON.stringify({
    scheduledTime: Number(controller?.scheduledTime || 0),
    completedAt,
    jobs: summary
  }));
  return { processed: summary.length, jobs: summary };
}


function jsonResponse(payload, status = 200) {
  return new Response(JSON.stringify(payload), { status, headers: apiHeaders() });
}

async function readJson(request) {
  const type = request.headers.get("content-type") || "";
  if (!type.toLowerCase().includes("application/json")) throw new ApiError(415, "Ожидался JSON-запрос.");
  try {
    return await request.json();
  } catch {
    throw new ApiError(400, "Некорректный JSON-запрос.");
  }
}

class ApiError extends Error {
  constructor(status, message, details = undefined) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

let playerGiftInboxSchemaPromise = null;

async function ensurePlayerGiftInboxSchema(env) {
  requireDatabase(env);
  if (!playerGiftInboxSchemaPromise) {
    playerGiftInboxSchemaPromise = env.DB.batch([
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS player_gift_inbox (
        gift_id TEXT NOT NULL,
        telegram_id TEXT NOT NULL,
        gift_kind TEXT NOT NULL DEFAULT 'gift',
        title TEXT NOT NULL DEFAULT '',
        message_text TEXT NOT NULL DEFAULT '',
        reason TEXT NOT NULL DEFAULT '',
        rewards_json TEXT NOT NULL DEFAULT '[]',
        status TEXT NOT NULL DEFAULT 'pending',
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL,
        claimed_at INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY(gift_id, telegram_id)
      )`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_player_gift_inbox_player ON player_gift_inbox(telegram_id,status,created_at DESC)`),
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS player_mail_metadata (
        gift_id TEXT NOT NULL,
        telegram_id TEXT NOT NULL,
        preview_text TEXT NOT NULL DEFAULT '',
        image_url TEXT NOT NULL DEFAULT '',
        read_at INTEGER NOT NULL DEFAULT 0,
        PRIMARY KEY(gift_id, telegram_id)
      )`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_player_mail_metadata_unread ON player_mail_metadata(telegram_id,read_at,gift_id)`)
    ]).catch((error) => {
      playerGiftInboxSchemaPromise = null;
      throw error;
    });
  }
  return playerGiftInboxSchemaPromise;
}

function normalizePlayerGiftRewards(input) {
  const allowed = new Set(["points", "zefir", "coffee", "case", "avatar", "frame", "trail", "skin", "showcase_style", "booster", "season_pass_xp", "season_pass_tier", "season_pass_xp_grant"]);
  const merged = new Map();
  for (const raw of Array.isArray(input) ? input : []) {
    if (!raw || typeof raw !== "object") continue;
    let kind = String(raw.kind || "").trim().toLowerCase();
    if (kind === "treats" || kind === "marshmallow") kind = "zefir";
    if (!allowed.has(kind)) continue;
    if (kind === "season_pass_xp") {
      const seasonId = String(raw.seasonId || raw.season_id || "").trim().slice(0, 120);
      const taskId = String(raw.taskId || raw.task_id || "").trim().slice(0, 80);
      const periodKey = String(raw.periodKey || raw.period_key || "").trim().slice(0, 24);
      if (!/^[A-Za-z0-9_-]{1,120}$/.test(seasonId) || !/^[A-Za-z0-9_-]{2,80}$/.test(taskId) || !/^[DW]:\d{4}-\d{2}-\d{2}$/.test(periodKey)) continue;
      const amount = Math.max(1, Math.min(5000000, Math.floor(Number(raw.amount || 1))));
      const key = `${kind}:${seasonId}:${taskId}:${periodKey}`;
      if (!merged.has(key)) merged.set(key, { kind, id:"", amount, seasonId, taskId, periodKey });
      continue;
    }
    if (kind === "season_pass_tier") {
      const id = String(raw.id || raw.rewardId || "").trim().slice(0, 180);
      const divider = id.lastIndexOf("|");
      const seasonId = divider > 0 ? id.slice(0, divider) : "";
      const tier = divider > 0 ? id.slice(divider + 1) : "";
      if (!/^[A-Za-z0-9_-]{1,120}$/.test(seasonId) || !["elite", "elite_plus"].includes(tier)) continue;
      const key = `${kind}:${seasonId}:${tier}`;
      if (!merged.has(key)) merged.set(key, { kind, id:`${seasonId}|${tier}`, amount:1 });
      continue;
    }
    if (kind === "season_pass_xp_grant") {
      const seasonId = String(raw.id || raw.rewardId || raw.seasonId || raw.season_id || "").trim().slice(0, 120);
      if (!/^[A-Za-z0-9_-]{1,120}$/.test(seasonId)) continue;
      const amount = Math.max(1, Math.min(5000000, Math.floor(Number(raw.amount || 1))));
      const key = `${kind}:${seasonId}`;
      const current = merged.get(key);
      if (current) current.amount = Math.min(5000000, current.amount + amount);
      else merged.set(key, { kind, id:seasonId, amount });
      continue;
    }
    if (kind === "booster") {
      const id = String(raw.id || raw.rewardId || "").trim().toLowerCase();
      if (!runBoosterDefinition(id)) continue;
      const amount = Math.max(1, Math.min(999, Math.floor(Number(raw.amount || 1))));
      const key = `${kind}:${id}`;
      const current = merged.get(key);
      if (current) current.amount = Math.min(999, current.amount + amount);
      else merged.set(key, { kind, id, amount });
      continue;
    }
    const id = String(raw.id || raw.rewardId || "").trim().slice(0, 96);
    if (["case", "avatar", "frame", "trail", "skin", "showcase_style"].includes(kind) && !id) continue;
    const amount = ["avatar", "frame", "trail", "skin", "showcase_style"].includes(kind)
      ? 1
      : Math.max(1, Math.min(5000000, Math.floor(Number(raw.amount || 1))));
    const key = `${kind}:${id}`;
    const current = merged.get(key);
    if (current && !["avatar", "frame", "trail", "skin", "showcase_style"].includes(kind)) current.amount = Math.min(5000000, current.amount + amount);
    else if (!current) merged.set(key, { kind, id, amount });
  }
  return [...merged.values()].slice(0, 30);
}

function playerGiftRewardView(reward) {
  const normalized = normalizePlayerGiftRewards([reward])[0];
  if (!normalized) return null;
  return { ...normalized, label: safeRewardDescription(normalized) };
}

function playerMailPreviewText(value, fallback = "") {
  const compact = String(value || fallback || "").replace(/\s+/g, " ").trim();
  return compact.slice(0, 120);
}

async function createPlayerGiftInbox(env, telegramId, spec = {}) {
  await ensurePlayerGiftInboxSchema(env);
  const id = String(telegramId || "").trim();
  if (!/^\d{4,20}$/.test(id)) throw new Error("Некорректный Telegram ID подарка");
  const rewards = normalizePlayerGiftRewards(spec.rewards);
  const allowEmptyRewards = spec.allowEmptyRewards === true;
  if (!rewards.length && !allowEmptyRewards) throw new Error("В подарке нет поддерживаемых наград");
  const giftId = String(spec.giftId || caseGrantId("gift")).replace(/[^A-Za-z0-9:_-]/g, "_").slice(0, 120);
  const now = Math.floor(Date.now() / 1000);
  const status = rewards.length ? "pending" : "info";
  const title = String(spec.title || (rewards.length ? "Подарок" : "Письмо")).slice(0, 120);
  const message = String(spec.message || "").slice(0, 3500);
  const reason = String(spec.reason || "").slice(0, 300);
  const preview = playerMailPreviewText(spec.preview, message || reason || title);
  const imageUrl = String(spec.imageUrl || "").trim().slice(0, 1000);
  const giftKind = String(spec.kind || (rewards.length ? "gift" : "letter")).slice(0,30);
  const rewardsJson = JSON.stringify(rewards);
  const batch = await env.DB.batch([
    env.DB.prepare(`INSERT OR IGNORE INTO player_gift_inbox(gift_id,telegram_id,gift_kind,title,message_text,reason,rewards_json,status,created_at,updated_at,claimed_at) VALUES(?,?,?,?,?,?,?,?,?,?,0)`)
      .bind(giftId,id,giftKind,title,message,reason,rewardsJson,status,now,now),
    env.DB.prepare(`INSERT OR IGNORE INTO player_mail_metadata(gift_id,telegram_id,preview_text,image_url,read_at) VALUES(?,?,?,?,0)`)
      .bind(giftId,id,preview,imageUrl)
  ]);
  const created = Number(batch?.[0]?.meta?.changes || 0) > 0;
  const mailMetadataCreated = Number(batch?.[1]?.meta?.changes || 0) > 0;
  const stored = await env.DB.prepare(`SELECT gift_id,gift_kind,title,rewards_json,status FROM player_gift_inbox WHERE gift_id=? AND telegram_id=? LIMIT 1`).bind(giftId,id).first();
  if (!stored?.gift_id) throw new Error("Письмо не зафиксировано в игровой почте");
  const storedRewards = normalizePlayerGiftRewards(safeJson(stored.rewards_json, []));
  if (JSON.stringify(storedRewards) !== rewardsJson || String(stored.gift_kind || "") !== giftKind) {
    throw new Error("Конфликт идентификатора письма: в игровой почте уже хранится другая награда");
  }
  // Mail is part of the player's authoritative account state. Without a revision
  // bump a slower startup/profile response can overwrite a freshly loaded inbox
  // in the open Mini App, producing the false state “Telegram arrived, mail did not”.
  if (created || mailMetadataCreated) {
    await ensurePlayerAccountRevisionAvailable(env);
    await bumpPlayerAccountRevisionStatement(env,id,now).run();
  }
  return { giftId, created, rewards, status:String(stored.status || status) };
}

function ownerPanelGiftAuditCandidate(row) {
  const details = safeJson(row?.details_json, {});
  const giftId = String(details?.giftId || "").trim();
  if (!/^[A-Za-z0-9:_-]{4,120}$/.test(giftId)) return null;
  let kind = String(details?.kind || "").trim().toLowerCase();
  if (kind === "treats" || kind === "marshmallow") kind = "zefir";
  if (!["points", "zefir", "coffee", "case", "avatar", "frame", "trail", "skin", "showcase_style", "booster"].includes(kind)) return null;
  const itemId = String(details?.itemId || "").trim().slice(0, 96);
  const rawAmount = ["avatar","frame","trail","skin","showcase_style"].includes(kind) ? 1 : Math.floor(Number(row?.new_value ?? details?.amount ?? 1));
  if (!Number.isFinite(rawAmount) || rawAmount < 1) return null;
  const rewards = normalizePlayerGiftRewards([{ kind, id:itemId, amount:rawAmount }]);
  if (!rewards.length) return null;
  return {
    auditId: Math.max(0, Math.floor(Number(row?.id || 0))),
    giftId,
    rewards,
    reason: String(details?.reason || "Выдача из панели владельца").trim().slice(0, 300) || "Выдача из панели владельца",
    createdAt: Math.max(1, Math.floor(Number(row?.created_at || 0)))
  };
}

async function repairOwnerPanelGiftInboxFromAudit(env, telegramId) {
  const id = String(telegramId || "").trim();
  if (!/^\d{4,20}$/.test(id)) return 0;
  await ensurePlayerGiftInboxSchema(env);

  let auditRows;
  try {
    const result = await env.DB.prepare(`SELECT id,new_value,details_json,created_at
      FROM staff_action_log
      WHERE target_telegram_id=? AND action='owner_panel_grant' AND target_type='gift_inbox' AND success=1
      ORDER BY created_at DESC,id DESC LIMIT 24`).bind(id).all();
    auditRows = result.results || [];
  } catch (error) {
    console.error("owner gift inbox audit repair lookup failed", error);
    return 0;
  }

  const candidateMap = new Map();
  for (const row of auditRows) {
    const candidate = ownerPanelGiftAuditCandidate(row);
    if (candidate && !candidateMap.has(candidate.giftId)) candidateMap.set(candidate.giftId, candidate);
  }
  const candidates = [...candidateMap.values()];
  if (!candidates.length) return 0;

  const placeholders = candidates.map(() => "?").join(",");
  const existing = await env.DB.prepare(`SELECT gift_id FROM player_gift_inbox WHERE telegram_id=? AND gift_id IN (${placeholders})`)
    .bind(id, ...candidates.map((item) => item.giftId)).all();
  const existingIds = new Set((existing.results || []).map((row) => String(row.gift_id || "")));
  const missing = candidates.filter((item) => !existingIds.has(item.giftId));
  if (!missing.length) return 0;

  // The economic queue is the idempotency ledger. A missing inbox row may be
  // reconstructed as claimable only when no delivered queue row proves that the
  // reward was already applied. This prevents a repaired historical letter from
  // ever granting the same compensation twice.
  let queueRows = [];
  try {
    const queueWhere = missing.map(() => "source_id GLOB ?").join(" OR ");
    const queueResult = await env.DB.prepare(`SELECT source_id,status,delivered_at FROM reward_delivery_queue
      WHERE telegram_id=? AND source_type='gift_inbox' AND (${queueWhere})`)
      .bind(id, ...missing.map((item) => `${item.giftId}_*`)).all();
    queueRows = queueResult.results || [];
  } catch (error) {
    // If the idempotency ledger cannot be inspected, do not guess. Returning an
    // empty repair is safer than risking a duplicate economic delivery.
    console.error("owner gift inbox audit repair queue lookup failed", error);
    return 0;
  }

  const now = Math.floor(Date.now() / 1000);
  const statements = [];
  for (const item of missing) {
    const relatedQueue = queueRows.filter((row) => String(row.source_id || "").startsWith(`${item.giftId}_`));
    const allDelivered = relatedQueue.length > 0 && relatedQueue.every((row) => String(row.status || "") === "delivered");
    const claimedAt = allDelivered ? Math.max(item.createdAt, ...relatedQueue.map((row) => Math.max(0, Number(row.delivered_at || 0)))) : 0;
    const status = allDelivered ? "claimed" : "pending";
    const rewardLabel = item.rewards.map((reward) => safeRewardDescription(reward)).join(", ");
    const message = "Для вас подготовлена награда.";
    const preview = playerMailPreviewText(rewardLabel ? `${rewardLabel} · ${item.reason}` : item.reason, message);
    statements.push(
      env.DB.prepare(`INSERT OR IGNORE INTO player_gift_inbox(gift_id,telegram_id,gift_kind,title,message_text,reason,rewards_json,status,created_at,updated_at,claimed_at)
        VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(item.giftId,id,"gift","Подарок от команды",message,item.reason,JSON.stringify(item.rewards),status,item.createdAt,now,claimedAt),
      env.DB.prepare(`INSERT OR IGNORE INTO player_mail_metadata(gift_id,telegram_id,preview_text,image_url,read_at) VALUES(?,?,?,?,?)`)
        .bind(item.giftId,id,preview,"",allDelivered ? claimedAt : 0)
    );
  }

  if (!statements.length) return 0;
  const results = await env.DB.batch(statements);
  let repaired = 0;
  for (let index = 0; index < results.length; index += 2) repaired += Number(results[index]?.meta?.changes || 0) > 0 ? 1 : 0;
  if (repaired > 0) {
    await ensurePlayerAccountRevisionAvailable(env);
    await bumpPlayerAccountRevisionStatement(env,id,now).run();
    console.info("owner gift inbox repaired from audit", { telegramId:id, repaired });
  }
  return repaired;
}

async function repairCompensationCampaignGiftInbox(env, telegramId) {
  const id = String(telegramId || "").trim();
  if (!/^\d{4,20}$/.test(id)) return 0;
  await ensurePlayerGiftInboxSchema(env);

  let campaignRows = [];
  try {
    const result = await env.DB.prepare(`SELECT c.campaign_id,c.title,c.reason,c.message_text,c.reward_bundle_json,c.created_at,
        r.processed_at,COALESCE(m.enabled,0) AS inbox_enabled,COALESCE(m.preview_text,'') AS preview_text
      FROM admin_campaign_recipients r
      JOIN admin_campaigns c ON c.campaign_id=r.campaign_id
      LEFT JOIN admin_campaign_mail_config m ON m.campaign_id=c.campaign_id
      WHERE r.telegram_id=? AND r.status IN ('processed','failed') AND c.reward_kind='gift_bundle' AND COALESCE(m.enabled,0)=1
      ORDER BY COALESCE(r.processed_at,c.created_at) DESC,c.created_at DESC LIMIT 24`).bind(id).all();
    campaignRows = result.results || [];
  } catch (error) {
    console.error("compensation gift inbox recovery lookup failed", error);
    return 0;
  }
  if (!campaignRows.length) return 0;

  const candidates = [];
  for (const row of campaignRows) {
    const campaignId = String(row.campaign_id || "").trim();
    if (!campaignId) continue;
    const giftId = `campaign_${campaignId}`.replace(/[^A-Za-z0-9:_-]/g, "_").slice(0,120);
    const rewards = normalizePlayerGiftRewards(safeJson(row.reward_bundle_json, []));
    if (!rewards.length) continue;
    candidates.push({
      giftId, rewards,
      title: String(row.title || "Компенсация").slice(0,120),
      message: String(row.message_text || "").trim() === "__CC_SILENT__" ? "" : String(row.message_text || "").slice(0,3500),
      reason: String(row.reason || "Компенсация").slice(0,300),
      preview: String(row.preview_text || "").slice(0,120),
      createdAt: Math.max(1, Math.floor(Number(row.processed_at || row.created_at || 0)))
    });
  }
  if (!candidates.length) return 0;

  const placeholders = candidates.map(() => "?").join(",");
  const existing = await env.DB.prepare(`SELECT gift_id FROM player_gift_inbox WHERE telegram_id=? AND gift_id IN (${placeholders})`)
    .bind(id, ...candidates.map((item) => item.giftId)).all();
  const existingIds = new Set((existing.results || []).map((row) => String(row.gift_id || "")));
  const missing = candidates.filter((item) => !existingIds.has(item.giftId));
  if (!missing.length) return 0;

  let queueRows = [];
  try {
    const queueWhere = missing.map(() => "source_id GLOB ?").join(" OR ");
    const queueResult = await env.DB.prepare(`SELECT source_id,status,delivered_at FROM reward_delivery_queue
      WHERE telegram_id=? AND source_type='gift_inbox' AND (${queueWhere})`)
      .bind(id, ...missing.map((item) => `${item.giftId}_*`)).all();
    queueRows = queueResult.results || [];
  } catch (error) {
    console.error("compensation gift inbox recovery queue lookup failed", error);
    return 0;
  }

  const now = Math.floor(Date.now() / 1000);
  const statements = [];
  for (const item of missing) {
    const relatedQueue = queueRows.filter((row) => String(row.source_id || "").startsWith(`${item.giftId}_`));
    const allDelivered = relatedQueue.length >= item.rewards.length && relatedQueue.every((row) => String(row.status || "") === "delivered");
    const claimedAt = allDelivered ? Math.max(item.createdAt, ...relatedQueue.map((row) => Math.max(0, Number(row.delivered_at || 0)))) : 0;
    const status = allDelivered ? "claimed" : "pending";
    const preview = playerMailPreviewText(item.preview, item.message || item.reason || item.title);
    statements.push(
      env.DB.prepare(`INSERT OR IGNORE INTO player_gift_inbox(gift_id,telegram_id,gift_kind,title,message_text,reason,rewards_json,status,created_at,updated_at,claimed_at)
        VALUES(?,?,?,?,?,?,?,?,?,?,?)`).bind(item.giftId,id,"compensation",item.title,item.message,item.reason,JSON.stringify(item.rewards),status,item.createdAt,now,claimedAt),
      env.DB.prepare(`INSERT OR IGNORE INTO player_mail_metadata(gift_id,telegram_id,preview_text,image_url,read_at) VALUES(?,?,?,?,?)`)
        .bind(item.giftId,id,preview,"",allDelivered ? claimedAt : 0)
    );
  }
  if (!statements.length) return 0;
  const results = await env.DB.batch(statements);
  let repaired = 0;
  for (let index = 0; index < results.length; index += 2) repaired += Number(results[index]?.meta?.changes || 0) > 0 ? 1 : 0;
  if (repaired > 0) {
    await ensurePlayerAccountRevisionAvailable(env);
    await bumpPlayerAccountRevisionStatement(env,id,now).run();
    console.info("compensation gift inbox repaired from campaign history", { telegramId:id, repaired });
  }
  return repaired;
}

async function repairPlayerGiftInboxAuthoritativeSources(env, telegramId) {
  let repaired = 0;
  try { repaired += await repairOwnerPanelGiftInboxFromAudit(env, telegramId); }
  catch (error) { console.error("owner gift inbox recovery failed", error); }
  try { repaired += await repairCompensationCampaignGiftInbox(env, telegramId); }
  catch (error) { console.error("compensation gift inbox recovery failed", error); }
  return repaired;
}

function seasonPassTaskMailGiftId(seasonId, taskId, periodKey) {
  const raw = `${String(seasonId || "")}|${String(taskId || "")}|${String(periodKey || "")}`;
  const taskPart = String(taskId || "task").replace(/[^A-Za-z0-9_-]/g, "_").slice(0, 38) || "task";
  const periodPart = String(periodKey || "period").replace(/[^A-Za-z0-9:_-]/g, "_").slice(0, 20) || "period";
  return `season_task:${retentionV2ShortHash(raw)}:${taskPart}:${periodPart}`.slice(0, 120);
}

async function syncSeasonPassTaskGiftInbox(env, telegramId, options = {}) {
  const id = String(telegramId || "").trim();
  if (!/^\d{4,20}$/.test(id)) return 0;
  await Promise.all([ensureSeasonPassSchema(env), ensurePlayerGiftInboxSchema(env)]);
  const seasonId = String(options.seasonId || options.season_id || "").trim();
  const requestedPairs = Array.isArray(options.pairs) ? options.pairs.slice(0, 30) : [];
  const binds = [id];
  let where = `n.telegram_id=? AND n.xp_reward>0 AND NOT EXISTS(
    SELECT 1 FROM season_pass_task_claims c
    WHERE c.season_id=n.season_id AND c.telegram_id=n.telegram_id AND c.task_id=n.task_id AND c.period_key=n.period_key AND c.status='delivered'
  )`;
  if (seasonId) { where += ` AND n.season_id=?`; binds.push(seasonId); }
  const pairs = requestedPairs.map((item) => ({ taskId:String(item?.taskId || item?.task_id || "").trim(), periodKey:String(item?.periodKey || item?.period_key || "").trim() }))
    .filter((item) => /^[A-Za-z0-9_-]{2,80}$/.test(item.taskId) && /^[DW]:\d{4}-\d{2}-\d{2}$/.test(item.periodKey));
  if (requestedPairs.length && !pairs.length) return 0;
  if (pairs.length) {
    where += ` AND (${pairs.map(() => `(n.task_id=? AND n.period_key=?)`).join(" OR ")})`;
    for (const pair of pairs) binds.push(pair.taskId, pair.periodKey);
  }
  const result = await env.DB.prepare(`SELECT n.season_id,n.task_id,n.period_key,n.task_title,n.xp_reward,n.completed_at
    FROM season_pass_task_notifications n WHERE ${where}
    ORDER BY n.completed_at DESC,n.task_id LIMIT 24`).bind(...binds).all();
  const rows = result.results || [];
  if (!rows.length) return 0;
  const now = Math.floor(Date.now() / 1000);
  const statements = [];
  const expectedMail = new Map();
  for (const row of rows) {
    const rowSeasonId = String(row.season_id || "").trim();
    const taskId = String(row.task_id || "").trim();
    const periodKey = String(row.period_key || "").trim();
    if (!rowSeasonId || !taskId || !periodKey) continue;
    const xp = Math.max(1, Math.floor(Number(row.xp_reward) || 1));
    const taskTitle = String(row.task_title || "Задание").trim().slice(0, 180) || "Задание";
    const giftId = seasonPassTaskMailGiftId(rowSeasonId, taskId, periodKey);
    const rewards = normalizePlayerGiftRewards([{ kind:"season_pass_xp", amount:xp, seasonId:rowSeasonId, taskId, periodKey }]);
    if (!rewards.length) continue;
    const createdAt = Math.max(1, Math.floor(Number(row.completed_at) || now));
    const title = "Задание сезонного пропуска выполнено";
    const message = `Задание «${taskTitle}» выполнено. Заберите XP сезонного пропуска.`;
    const reason = "Награда за выполненное задание сезонного пропуска";
    const preview = playerMailPreviewText(`${taskTitle} · +${xp.toLocaleString("ru-RU")} XP`, message);
    expectedMail.set(giftId, JSON.stringify(rewards));
    statements.push(
      env.DB.prepare(`INSERT OR IGNORE INTO player_gift_inbox(gift_id,telegram_id,gift_kind,title,message_text,reason,rewards_json,status,created_at,updated_at,claimed_at) VALUES(?,?,?,?,?,?,?,'pending',?,?,0)`)
        .bind(giftId,id,"season_pass_task",title,message,reason,JSON.stringify(rewards),createdAt,now),
      env.DB.prepare(`INSERT OR IGNORE INTO player_mail_metadata(gift_id,telegram_id,preview_text,image_url,read_at) VALUES(?,?,?,?,0)`)
        .bind(giftId,id,preview,"/assets/ui/icon_battlepass.png")
    );
  }
  let created = 0;
  for (let index = 0; index < statements.length; index += 40) {
    const results = await env.DB.batch(statements.slice(index, index + 40));
    for (let resultIndex = 0; resultIndex < results.length; resultIndex += 2) {
      if (Number(results[resultIndex]?.meta?.changes || 0) > 0) created += 1;
    }
  }
  if (created > 0) {
    await ensurePlayerAccountRevisionAvailable(env);
    await bumpPlayerAccountRevisionStatement(env,id,now).run();
  }
  const expectedIds = [...expectedMail.keys()];
  if (expectedIds.length) {
    const placeholders = expectedIds.map(() => "?").join(",");
    const stored = await env.DB.prepare(`SELECT gift_id,rewards_json FROM player_gift_inbox WHERE telegram_id=? AND gift_id IN (${placeholders})`).bind(id,...expectedIds).all();
    const storedMap = new Map((stored.results || []).map((row) => [String(row.gift_id || ""), JSON.stringify(normalizePlayerGiftRewards(safeJson(row.rewards_json, [])))]));
    for (const giftId of expectedIds) {
      if (!storedMap.has(giftId)) throw new Error(`Письмо сезонного задания не зафиксировано: ${giftId}`);
      if (storedMap.get(giftId) !== expectedMail.get(giftId)) throw new Error(`Конфликт письма сезонного задания: ${giftId}`);
    }
  }
  return created;
}

async function maintainPlayerGiftInboxState(env, telegramId) {
  await ensurePlayerGiftInboxSchema(env);
  const id = String(telegramId || "");
  const now = Math.floor(Date.now() / 1000);
  const staleReset = await env.DB.prepare(`UPDATE player_gift_inbox SET status='pending',updated_at=? WHERE telegram_id=? AND status='claiming' AND updated_at<?`)
    .bind(now, id, now - GIFT_INBOX_STALE_SECONDS).run();
  // Self-heal a gift whose economic queue already finished but whose inbox row
  // did not reach the final state (for example because another queue worker won
  // the delivery lease). A pending gift with no queue rows is never touched.
  const completedRepair = await env.DB.prepare(`UPDATE player_gift_inbox
    SET status='claimed',claimed_at=CASE WHEN claimed_at>0 THEN claimed_at ELSE ? END,updated_at=?
    WHERE telegram_id=? AND status IN ('pending','claiming')
      AND EXISTS(
        SELECT 1 FROM reward_delivery_queue q
        WHERE q.telegram_id=player_gift_inbox.telegram_id AND q.source_type='gift_inbox'
          AND q.source_id GLOB (player_gift_inbox.gift_id || '_*')
      )
      AND NOT EXISTS(
        SELECT 1 FROM reward_delivery_queue q
        WHERE q.telegram_id=player_gift_inbox.telegram_id AND q.source_type='gift_inbox'
          AND q.source_id GLOB (player_gift_inbox.gift_id || '_*') AND q.status<>'delivered'
      )`).bind(now,now,id).run();
  const changed = Number(staleReset?.meta?.changes || 0) + Number(completedRepair?.meta?.changes || 0);
  if (changed > 0) {
    await ensurePlayerAccountRevisionAvailable(env);
    await bumpPlayerAccountRevisionStatement(env,id,now).run();
  }
  return changed;
}

async function playerGiftInboxPayload(env, telegramId) {
  await ensurePlayerGiftInboxSchema(env);
  const id = String(telegramId || "");
  const [rows,countsRow] = await Promise.all([
    env.DB.prepare(`SELECT g.gift_id,g.gift_kind,g.title,g.message_text,g.reason,g.rewards_json,g.status,g.created_at,g.claimed_at,m.preview_text,m.image_url,m.read_at,CASE WHEN m.gift_id IS NULL THEN 0 ELSE 1 END AS has_mail_meta FROM player_gift_inbox g LEFT JOIN player_mail_metadata m ON m.gift_id=g.gift_id AND m.telegram_id=g.telegram_id WHERE g.telegram_id=? ORDER BY CASE WHEN COALESCE(m.read_at,CASE WHEN g.status IN ('pending','claiming','info') THEN 0 ELSE g.created_at END)=0 THEN 0 ELSE 1 END, CASE g.status WHEN 'pending' THEN 0 WHEN 'claiming' THEN 1 WHEN 'info' THEN 2 ELSE 3 END, g.created_at DESC LIMIT 24`).bind(id).all(),
    env.DB.prepare(`SELECT SUM(CASE WHEN g.status IN ('pending','claiming') THEN 1 ELSE 0 END) AS pending_count,SUM(CASE WHEN COALESCE(m.read_at,CASE WHEN g.status IN ('pending','claiming','info') THEN 0 ELSE g.created_at END)=0 THEN 1 ELSE 0 END) AS unread_count FROM player_gift_inbox g LEFT JOIN player_mail_metadata m ON m.gift_id=g.gift_id AND m.telegram_id=g.telegram_id WHERE g.telegram_id=?`).bind(id).first()
  ]);
  const items = (rows.results || []).map((row) => {
    const rewards = normalizePlayerGiftRewards(safeJson(row.rewards_json, [])).map(playerGiftRewardView).filter(Boolean);
    const status = String(row.status || "pending");
    const readAt = Number(row.has_mail_meta || 0) ? Number(row.read_at || 0) : (['pending','claiming','info'].includes(status) ? 0 : Number(row.created_at || 0));
    const message = String(row.message_text || "");
    const reason = String(row.reason || "");
    return {
      id: String(row.gift_id || ""), kind: String(row.gift_kind || "gift"), title: String(row.title || "Письмо"),
      message, reason, preview: playerMailPreviewText(row.preview_text, message || reason || "Откройте письмо, чтобы узнать подробности."),
      imageUrl: String(row.image_url || ""), status, createdAt: Number(row.created_at || 0), claimedAt: Number(row.claimed_at || 0),
      readAt, unread: readAt <= 0, hasRewards: rewards.length > 0, rewards
    };
  });
  return { ok:true, pendingCount:Math.max(0,Number(countsRow?.pending_count || 0)), unreadCount:Math.max(0,Number(countsRow?.unread_count || 0)), items };
}

async function playerGiftInboxSnapshot(env, telegramId, options = {}) {
  if (options.maintenancePromise) await options.maintenancePromise;
  else await maintainPlayerGiftInboxState(env, telegramId);
  const revision = options.revisionPromise ? await options.revisionPromise : await readPlayerAccountRevision(env, telegramId);
  const payload = await playerGiftInboxPayload(env, telegramId);
  return { ...payload, accountRevision:Math.max(0,Number(revision || 0)), generatedAt:Date.now() };
}

async function notifyPlayerGiftAvailable(env, telegramId, gift) {
  try {
    const subscriber = await env.DB.prepare(`SELECT chat_id FROM bot_subscribers WHERE telegram_id=? AND active=1 LIMIT 1`).bind(String(telegramId)).first();
    if (!subscriber?.chat_id) return false;
    const rewards = normalizePlayerGiftRewards(gift?.rewards || []);
    const rewardLines = rewards.map((reward) => `• ${escapeHtml(safeRewardDescription(reward))}`).join("\n");
    const reason = String(gift?.reason || "").trim();
    const message = String(gift?.message || "").trim();
    const rewardBlock = rewards.length ? `\n\n<b>Вам доступно:</b>\n${rewardLines}\n\nОткройте Почту в игре, чтобы получить награду.` : `\n\nОткройте Почту в игре, чтобы прочитать письмо.`;
    const text = `<b>${rewards.length ? "🎁" : "💌"} ${escapeHtml(String(gift?.title || (rewards.length ? "Вам подарок" : "Новое письмо")))}</b>${message ? `\n\n${escapeHtml(message)}` : ""}${reason ? `\n\n<b>Причина:</b> ${escapeHtml(reason)}` : ""}${rewardBlock}`;
    await sendTelegramMessage(env, subscriber.chat_id, text, { inline_keyboard: [
      [{ text:rewards.length ? "🎁 Открыть игру" : "💌 Открыть игру", web_app:{ url:configuredGameUrl(env) } }],
      [{ text:"⬅️ Назад в меню", callback_data:"menu:home" }]
    ] });
    return true;
  } catch (error) {
    console.warn("Gift inbox notification failed", String(error?.message || error));
    return false;
  }
}

async function getPlayerGiftInbox(request, env) {
  try {
    const body = await readJson(request);
    requireBotToken(env);
    const auth = await validateTelegramInitData(String(body.initData || ""), env);
    const telegramId = String(auth.user.id);
    await repairPlayerGiftInboxAuthoritativeSources(env, telegramId);
    try {
      const season = await loadSeasonPassSeason(env);
      if (season?.id && seasonPassCapabilities(season).canClaimTasks) await syncSeasonPassTaskGiftInbox(env, telegramId, { seasonId:season.id });
    } catch (syncError) {
      console.error("season pass task mail backfill failed", syncError);
    }
    return jsonResponse(await playerGiftInboxSnapshot(env, telegramId));
  } catch (error) {
    if (error instanceof ApiError) return jsonResponse({ ok:false, error:error.message }, error.status);
    console.error("getPlayerGiftInbox failed", error);
    return jsonResponse({ ok:false, error:"Не удалось загрузить подарки." }, 500);
  }
}

async function markPlayerGiftMailRead(request, env) {
  try {
    const body = await readJson(request);
    requireBotToken(env);
    const auth = await validateTelegramInitData(String(body.initData || ""), env);
    const telegramId = String(auth.user.id);
    const giftId = String(body.giftId || "").trim().slice(0,120);
    if (!giftId) throw new ApiError(400,"Письмо не найдено.");
    await ensurePlayerGiftInboxSchema(env);
    const row = await env.DB.prepare(`SELECT g.gift_id,COALESCE(m.read_at,0) AS read_at FROM player_gift_inbox g LEFT JOIN player_mail_metadata m ON m.gift_id=g.gift_id AND m.telegram_id=g.telegram_id WHERE g.gift_id=? AND g.telegram_id=? LIMIT 1`).bind(giftId,telegramId).first();
    if (!row) throw new ApiError(404,"Письмо не найдено.");
    const now = Math.floor(Date.now()/1000);
    await env.DB.prepare(`INSERT INTO player_mail_metadata(gift_id,telegram_id,preview_text,image_url,read_at) VALUES(?,?,'','',?) ON CONFLICT(gift_id,telegram_id) DO UPDATE SET read_at=CASE WHEN player_mail_metadata.read_at>0 THEN player_mail_metadata.read_at ELSE excluded.read_at END`).bind(giftId,telegramId,now).run();
    if (Number(row.read_at || 0) <= 0) {
      await ensurePlayerAccountRevisionAvailable(env);
      await bumpPlayerAccountRevisionStatement(env,telegramId,now).run();
    }
    return jsonResponse(await playerGiftInboxSnapshot(env,telegramId));
  } catch (error) {
    if (error instanceof ApiError) return jsonResponse({ok:false,error:error.message},error.status);
    console.error("markPlayerGiftMailRead failed",error);
    return jsonResponse({ok:false,error:"Не удалось отметить письмо прочитанным."},500);
  }
}

async function processGiftInboxRewardQueue(env, telegramId, giftId) {
  await ensureSafeControlCenterSchema(env);
  const now = Math.floor(Date.now() / 1000);
  const sourcePattern = `${String(giftId)}_*`;
  const rows = await env.DB.prepare(
    `SELECT id,telegram_id,source_type,source_id,reward_kind,reward_id,amount,reason,attempts
     FROM reward_delivery_queue
     WHERE telegram_id=? AND source_type='gift_inbox' AND source_id GLOB ?
       AND status IN ('pending','failed','delivering') AND available_at<=? AND attempts<5
       AND (lease_until=0 OR lease_until<?)
     ORDER BY created_at ASC,id ASC LIMIT 30`
  ).bind(String(telegramId), sourcePattern, now, now).all();
  let delivered = 0;
  let failed = 0;
  for (const row of rows.results || []) {
    const token = caseGrantId("gift_reward_lock");
    const claimAt = Math.floor(Date.now() / 1000);
    const lock = await env.DB.prepare(
      `UPDATE reward_delivery_queue SET status='delivering',lease_token=?,lease_until=?,updated_at=?
       WHERE id=? AND telegram_id=? AND source_type='gift_inbox' AND source_id GLOB ?
         AND status IN ('pending','failed','delivering') AND attempts<5 AND available_at<=?
         AND (lease_until=0 OR lease_until<?)`
    ).bind(token, claimAt + GIFT_INBOX_REWARD_LEASE_SECONDS, claimAt, row.id, String(telegramId), sourcePattern, claimAt, claimAt).run();
    if (Number(lock.meta?.changes || 0) < 1) continue;
    try {
      await deliverQueuedReward(env, row, token);
      delivered += 1;
    } catch (error) {
      const finishedAt = Math.floor(Date.now() / 1000);
      const attempts = Math.max(1, Number(row.attempts || 0) + 1);
      const delay = Math.min(3600, 15 * (2 ** Math.max(0, attempts - 1)));
      await env.DB.prepare(`UPDATE reward_delivery_queue SET status='failed',attempts=?,last_error=?,updated_at=?,lease_token='',lease_until=0,available_at=? WHERE id=? AND lease_token=?`)
        .bind(attempts, String(error?.message || error).slice(0,500), finishedAt, finishedAt + delay, row.id, token).run();
      failed += 1;
    }
  }
  return { delivered, failed };
}

async function claimPlayerGift(request, env, ctx) {
  try {
    const body = await readJson(request);
    requireBotToken(env);
    const auth = await validateTelegramInitData(String(body.initData || ""), env);
    const telegramId = String(auth.user.id);
    const giftId = String(body.giftId || "").trim();
    if (!/^[A-Za-z0-9:_-]{4,120}$/.test(giftId)) throw new ApiError(400, "Некорректный подарок.");
    await ensurePlayerGiftInboxSchema(env);
    const now = Math.floor(Date.now() / 1000);
    await env.DB.prepare(`UPDATE player_gift_inbox SET status='pending',updated_at=? WHERE telegram_id=? AND gift_id=? AND status='claiming' AND updated_at<?`).bind(now,telegramId,giftId,now-GIFT_INBOX_STALE_SECONDS).run();
    let row = await env.DB.prepare(`SELECT * FROM player_gift_inbox WHERE telegram_id=? AND gift_id=? LIMIT 1`).bind(telegramId,giftId).first();
    if (!row) throw new ApiError(404, "Подарок не найден.");
    if (String(row.status) === "claimed") {
      return jsonResponse({ ok:true, repeated:true, gifts:await playerGiftInboxSnapshot(env,telegramId) });
    }
    const lock = await env.DB.prepare(`UPDATE player_gift_inbox SET status='claiming',updated_at=? WHERE telegram_id=? AND gift_id=? AND status='pending'`).bind(now,telegramId,giftId).run();
    if (Number(lock.meta?.changes || 0) < 1) throw new ApiError(409, "Подарок уже обрабатывается. Попробуйте ещё раз через несколько секунд.");
    await ensurePlayerAccountRevisionAvailable(env);
    await bumpPlayerAccountRevisionStatement(env,telegramId,now).run();
    const rewards = normalizePlayerGiftRewards(safeJson(row.rewards_json, []));
    const seasonTaskRewards = rewards.filter((reward) => String(reward?.kind || "") === "season_pass_xp");
    if (seasonTaskRewards.length) {
      if (seasonTaskRewards.length !== rewards.length || seasonTaskRewards.length !== 1) {
        const resetAt = Math.floor(Date.now()/1000);
        const reset = await env.DB.prepare(`UPDATE player_gift_inbox SET status='pending',updated_at=? WHERE telegram_id=? AND gift_id=? AND status='claiming'`).bind(resetAt,telegramId,giftId).run();
        if (Number(reset?.meta?.changes || 0) > 0) await bumpPlayerAccountRevisionStatement(env,telegramId,resetAt).run();
        throw new ApiError(409,"Письмо содержит несовместимый набор наград.");
      }
      try {
        const taskResult = await claimSeasonPassTaskGiftReward(env,telegramId,seasonTaskRewards[0],ctx);
        const claimedAt = Math.floor(Date.now()/1000);
        await env.DB.prepare(`UPDATE player_gift_inbox SET status='claimed',claimed_at=CASE WHEN claimed_at>0 THEN claimed_at ELSE ? END,updated_at=? WHERE telegram_id=? AND gift_id=? AND status IN ('claiming','pending')`).bind(claimedAt,claimedAt,telegramId,giftId).run();
        const gifts = await playerGiftInboxSnapshot(env,telegramId);
        return jsonResponse({ok:true,gifts,deliveryCommitted:true,seasonPassRefreshRequired:true,repeated:Boolean(taskResult?.repeated),receivedSeasonPassXp:Math.max(0,Number(taskResult?.xp||0))});
      } catch (taskError) {
        const resetAt = Math.floor(Date.now()/1000);
        const reset = await env.DB.prepare(`UPDATE player_gift_inbox SET status='pending',updated_at=? WHERE telegram_id=? AND gift_id=? AND status='claiming'`).bind(resetAt,telegramId,giftId).run().catch(()=>null);
        if (Number(reset?.meta?.changes || 0) > 0) await bumpPlayerAccountRevisionStatement(env,telegramId,resetAt).run().catch(()=>{});
        throw taskError;
      }
    }
    if (!rewards.length) {
      const emptyClaim = await env.DB.prepare(`UPDATE player_gift_inbox SET status='claimed',claimed_at=?,updated_at=? WHERE telegram_id=? AND gift_id=? AND status='claiming' AND updated_at=?`).bind(now,now,telegramId,giftId,now).run();
      if (Number(emptyClaim?.meta?.changes || 0) > 0) await bumpPlayerAccountRevisionStatement(env,telegramId,now).run();
    } else {
      for (let index = 0; index < rewards.length; index += 1) {
        await enqueueRewardDelivery(env, telegramId, "gift_inbox", `${giftId}_${index}`, rewards[index], String(row.reason || row.title || "Подарок"));
      }
      await env.DB.prepare(`UPDATE reward_delivery_queue SET status=CASE WHEN status='failed' THEN 'pending' ELSE status END,available_at=?,lease_token='',lease_until=0,updated_at=? WHERE telegram_id=? AND source_type='gift_inbox' AND source_id GLOB ? AND status IN ('pending','failed')`).bind(now,now,telegramId,`${giftId}_*`).run();
      await processGiftInboxRewardQueue(env, telegramId, giftId);
      const remaining = await env.DB.prepare(`SELECT COUNT(*) AS count FROM reward_delivery_queue WHERE telegram_id=? AND source_type='gift_inbox' AND source_id GLOB ? AND status<>'delivered'`).bind(telegramId,`${giftId}_*`).first();
      if (Number(remaining?.count || 0) > 0) {
        const resetAt = Math.floor(Date.now()/1000);
        const reset = await env.DB.prepare(`UPDATE player_gift_inbox SET status='pending',updated_at=? WHERE telegram_id=? AND gift_id=? AND status='claiming' AND updated_at=?`).bind(resetAt,telegramId,giftId,now).run();
        if (Number(reset?.meta?.changes || 0) > 0) await bumpPlayerAccountRevisionStatement(env,telegramId,resetAt).run();
        throw new ApiError(503, "Не удалось выдать весь подарок. Ничего не потеряно — попробуйте ещё раз.");
      }
      const claimedAt = Math.floor(Date.now() / 1000);
      // Once every queue row is delivered the gift is economically complete.
      // Finalize the inbox row even if a stale-state repair changed claiming back
      // to pending while this request was running. Queue delivery itself is
      // idempotent, so requiring the old updated_at lease here only creates a UI
      // race without adding economic protection.
      const finalClaim = await env.DB.prepare(`UPDATE player_gift_inbox SET status='claimed',claimed_at=?,updated_at=? WHERE telegram_id=? AND gift_id=? AND status IN ('claiming','pending')`).bind(claimedAt,claimedAt,telegramId,giftId).run();
      if (Number(finalClaim?.meta?.changes || 0) > 0) await bumpPlayerAccountRevisionStatement(env,telegramId,claimedAt).run();
      try { await recordPlayerTimeline(env,telegramId,"gift_claim",`получил подарок «${String(row.title||"Подарок")}»`,{giftId,rewards,reason:row.reason},`gift_${giftId}`,null); } catch {}
    }
    // The economic transaction and inbox finalization are the synchronous
    // contract of /api/gifts/claim. Do not keep the player's button in
    // "Получаем…" while profile/case snapshots are rebuilt: return the final
    // gift state immediately and refresh the rest of the account in background.
    const gifts = await playerGiftInboxSnapshot(env,telegramId);
    const rewardKinds = new Set(rewards.map((reward)=>String(reward?.kind||"").toLowerCase()));
    const caseRefreshRequired = [...rewardKinds].some((kind)=>["case","seasonal_case","avatar","frame","trail","skin","music","season_pass_tier"].includes(kind));
    const profileRefreshRequired = [...rewardKinds].some((kind)=>["points","zefir","coffee","avatar","frame","trail","skin","music","season_pass_tier","season_pass_xp_grant"].includes(kind));
    const seasonPassRefreshRequired = [...rewardKinds].some((kind)=>["season_pass_tier","season_pass_xp_grant"].includes(kind));
    scheduleRunSettlementBackground(ctx,
      ensureAuthoritativeProfileRow(env,telegramId,`gift-post-claim:${giftId}`),
      "gift post-claim profile fold failed"
    );
    scheduleRunSettlementBackground(ctx,
      reconcileDeliveredSeasonPassCasesForPlayer(env,telegramId),
      "gift post-claim case reconcile failed"
    );
    return jsonResponse({ ok:true, gifts, deliveryCommitted:true, caseRefreshRequired, profileRefreshRequired, seasonPassRefreshRequired });
  } catch (error) {
    if (error instanceof ApiError) return jsonResponse({ ok:false, error:error.message }, error.status);
    console.error("claimPlayerGift failed", error);
    return jsonResponse({ ok:false, error:"Не удалось получить подарок." }, 500);
  }
}

let playerAccountRevisionSchemaReady = false;
let playerAccountRevisionSchemaPromise = null;

async function ensurePlayerAccountRevisionSchema(env) {
  if (playerAccountRevisionSchemaReady) return;
  if (playerAccountRevisionSchemaPromise) return playerAccountRevisionSchemaPromise;
  playerAccountRevisionSchemaPromise = (async () => {
    await env.DB.batch([
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS player_account_revision (
        telegram_id TEXT PRIMARY KEY,
        revision INTEGER NOT NULL DEFAULT 1 CHECK(revision >= 1),
        updated_at INTEGER NOT NULL DEFAULT 0
      )`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_player_account_revision_updated ON player_account_revision(updated_at DESC)`),
      env.DB.prepare(`CREATE TRIGGER IF NOT EXISTS trg_account_revision_profile_insert
        AFTER INSERT ON admin_profile_state BEGIN
          INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(NEW.telegram_id,1,unixepoch())
          ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at;
        END`),
      env.DB.prepare(`CREATE TRIGGER IF NOT EXISTS trg_account_revision_profile_economy
        AFTER UPDATE OF wallet,treats,coffee,profile_xp ON admin_profile_state
        WHEN OLD.wallet<>NEW.wallet OR OLD.treats<>NEW.treats OR OLD.coffee<>NEW.coffee OR OLD.profile_xp<>NEW.profile_xp
        BEGIN
          INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(NEW.telegram_id,1,unixepoch())
          ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at;
        END`),
      env.DB.prepare(`CREATE TRIGGER IF NOT EXISTS trg_account_revision_case_state_insert
        AFTER INSERT ON case_player_state BEGIN
          INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(NEW.telegram_id,1,unixepoch())
          ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at;
        END`),
      env.DB.prepare(`CREATE TRIGGER IF NOT EXISTS trg_account_revision_case_state_update
        AFTER UPDATE ON case_player_state BEGIN
          INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(NEW.telegram_id,1,unixepoch())
          ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at;
        END`),
      env.DB.prepare(`CREATE TRIGGER IF NOT EXISTS trg_account_revision_granted_case_insert
        AFTER INSERT ON granted_cases BEGIN
          INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(NEW.telegram_id,1,unixepoch())
          ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at;
        END`),
      env.DB.prepare(`CREATE TRIGGER IF NOT EXISTS trg_account_revision_granted_case_update
        AFTER UPDATE ON granted_cases BEGIN
          INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(NEW.telegram_id,1,unixepoch())
          ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at;
        END`),
      env.DB.prepare(`CREATE TRIGGER IF NOT EXISTS trg_account_revision_pass_insert
        AFTER INSERT ON season_pass_players BEGIN
          INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(NEW.telegram_id,1,unixepoch())
          ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at;
        END`),
      env.DB.prepare(`CREATE TRIGGER IF NOT EXISTS trg_account_revision_pass_update
        AFTER UPDATE ON season_pass_players BEGIN
          INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(NEW.telegram_id,1,unixepoch())
          ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at;
        END`)
    ]);
    playerAccountRevisionSchemaReady = true;
  })().finally(() => { playerAccountRevisionSchemaPromise = null; });
  return playerAccountRevisionSchemaPromise;
}

function bumpPlayerAccountRevisionStatement(env, telegramId, now = Math.floor(Date.now()/1000)) {
  return env.DB.prepare(`INSERT INTO player_account_revision(telegram_id,revision,updated_at) VALUES(?,1,?)
    ON CONFLICT(telegram_id) DO UPDATE SET revision=player_account_revision.revision+1,updated_at=excluded.updated_at`).bind(String(telegramId), now);
}

async function ensurePlayerAccountRevisionAvailable(env) {
  if (playerAccountRevisionSchemaReady) return;
  try {
    await env.DB.prepare(`SELECT revision FROM player_account_revision LIMIT 1`).first();
    playerAccountRevisionSchemaReady = true;
  } catch {
    await ensurePlayerAccountRevisionSchema(env);
  }
}

async function readPlayerAccountRevision(env, telegramId) {
  await ensurePlayerAccountRevisionAvailable(env);
  const id = String(telegramId || '');
  if (!id) return 0;
  const row = await env.DB.prepare(`SELECT revision FROM player_account_revision WHERE telegram_id=? LIMIT 1`).bind(id).first();
  return Math.max(0, Number(row?.revision || 0));
}

async function getPlayerAccountRevisionResponse(request, env) {
  try {
    const body = await readJson(request);
    const initData = String(body.initData || '');
    if (!initData) throw new ApiError(401, 'Telegram initData отсутствует.');
    requireBotToken(env);
    const auth = await validateTelegramInitData(initData, env);
    return jsonResponse({ ok:true, accountRevision:await readPlayerAccountRevision(env,String(auth.user.id)), generatedAt:Date.now() });
  } catch (error) {
    if (error instanceof ApiError) return jsonResponse({ ok:false, error:error.message }, error.status);
    console.error('getPlayerAccountRevisionResponse failed', error);
    return jsonResponse({ ok:false, error:'Не удалось проверить состояние аккаунта.' }, 500);
  }
}


// ===================== LIVEOPS RETENTION PLATFORM v2 =====================
let retentionPlatformV2SchemaReady = false;
let retentionPlatformV2SchemaPromise = null;
let activeRunLiveOpsCache = { value:null, expiresAt:0, promise:null };

async function ensureRetentionPlatformV2Schema(env) {
  requireDatabase(env);
  if (retentionPlatformV2SchemaReady) return;
  if (!retentionPlatformV2SchemaPromise) {
    retentionPlatformV2SchemaPromise = (async () => {
      try {
        await env.DB.prepare(`SELECT
          (SELECT COUNT(*) FROM automation_mail_deliveries WHERE 0) +
          (SELECT COUNT(*) FROM friend_coop_task_config WHERE 0) +
          (SELECT COUNT(*) FROM friend_coop_claims WHERE 0) +
          (SELECT COUNT(*) FROM newcomer_path_steps WHERE 0) +
          (SELECT COUNT(*) FROM newcomer_path_claims WHERE 0) AS ok`).first();
        retentionPlatformV2SchemaReady = true;
        return;
      } catch (error) {
        if (!isMissingRuntimeDatabaseSchemaError(error)) throw error;
      }
      const now=Math.floor(Date.now()/1000);
      await env.DB.batch([
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS automation_mail_deliveries (execution_key TEXT PRIMARY KEY,chain_key TEXT NOT NULL,telegram_id TEXT NOT NULL,gift_id TEXT NOT NULL UNIQUE,created_at INTEGER NOT NULL)`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_automation_mail_chain ON automation_mail_deliveries(chain_key,created_at DESC)`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_automation_mail_player ON automation_mail_deliveries(telegram_id,created_at DESC)`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS friend_coop_task_config (id INTEGER PRIMARY KEY CHECK(id=1),task_key TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,title TEXT NOT NULL DEFAULT 'Вместе вкуснее',description TEXT NOT NULL DEFAULT 'Выполняйте цель вместе с другом.',metric TEXT NOT NULL DEFAULT 'runs',target_value INTEGER NOT NULL DEFAULT 6,reward_json TEXT NOT NULL DEFAULT '{"kind":"case","id":"small","amount":1}',starts_at INTEGER NOT NULL DEFAULT 0,ends_at INTEGER NOT NULL DEFAULT 0,cycle_started_at INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL DEFAULT 0,updated_by TEXT NOT NULL DEFAULT '')`),
        env.DB.prepare(`INSERT OR IGNORE INTO friend_coop_task_config(id,task_key,enabled,title,description,metric,target_value,reward_json,starts_at,ends_at,cycle_started_at,updated_at,updated_by) VALUES(1,'coop_default',0,'Вместе вкуснее','Сделайте 6 зачтённых забегов на двоих.','runs',6,'{"kind":"case","id":"small","amount":1}',0,0,?,?, 'runtime-v2')`).bind(now,now),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS friend_coop_claims (task_key TEXT NOT NULL,pair_key TEXT NOT NULL,telegram_id TEXT NOT NULL,queue_id INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',claimed_at INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY(task_key,pair_key,telegram_id))`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_friend_coop_claims_player ON friend_coop_claims(telegram_id,claimed_at DESC)`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_friend_coop_claims_task ON friend_coop_claims(task_key,claimed_at DESC)`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS newcomer_path_steps (step_day INTEGER PRIMARY KEY,enabled INTEGER NOT NULL DEFAULT 1,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',runs_required INTEGER NOT NULL DEFAULT 1,cta_type TEXT NOT NULL DEFAULT 'game',reward_json TEXT NOT NULL DEFAULT '{}',updated_at INTEGER NOT NULL DEFAULT 0,updated_by TEXT NOT NULL DEFAULT '')`),
        env.DB.prepare(`INSERT OR IGNORE INTO newcomer_path_steps(step_day,enabled,title,description,runs_required,cta_type,reward_json,updated_at,updated_by) VALUES(1,1,'Первый сладкий забег','Заверши первый полноценный забег и забери стартовый подарок.',1,'game','{"kind":"points","amount":500}',?,'runtime-v2')`).bind(now),
        env.DB.prepare(`INSERT OR IGNORE INTO newcomer_path_steps(step_day,enabled,title,description,runs_required,cta_type,reward_json,updated_at,updated_by) VALUES(2,1,'Загляни в коллекцию','Вернись на второй день, сделай ещё один забег и познакомься с кейсами и Альбомом.',2,'album','{"kind":"zefir","amount":20}',?,'runtime-v2')`).bind(now),
        env.DB.prepare(`INSERT OR IGNORE INTO newcomer_path_steps(step_day,enabled,title,description,runs_required,cta_type,reward_json,updated_at,updated_by) VALUES(3,1,'Играть вместе веселее','На третий день сделай ещё один забег и открой «Друзья кафе».',3,'referrals','{"kind":"case","id":"small","amount":1}',?,'runtime-v2')`).bind(now),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS newcomer_path_claims (telegram_id TEXT NOT NULL,step_day INTEGER NOT NULL,queue_id INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'pending',claimed_at INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY(telegram_id,step_day))`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_newcomer_claims_day ON newcomer_path_claims(step_day,claimed_at DESC)`)
      ]);
      retentionPlatformV2SchemaReady = true;
    })().catch((error)=>{retentionPlatformV2SchemaPromise=null;retentionPlatformV2SchemaReady=false;throw error;});
  }
  await retentionPlatformV2SchemaPromise;
}

function retentionV2Reward(raw) {
  const reward=referralSafeReward(raw);
  return ['points','zefir','coffee','case'].includes(String(reward?.kind||'')) ? reward : {kind:'none'};
}
function retentionV2RewardArray(raw){const reward=retentionV2Reward(raw);return reward.kind==='none'?[]:[reward];}
function retentionV2ShortHash(value){let h=2166136261;for(const ch of String(value||'')){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0).toString(36);}
function retentionV2PairKey(a,b){const x=String(a||''),y=String(b||'');return x<y?`${x}:${y}`:`${y}:${x}`;}

function normalizeLiveOpsRunEconomy(payload={}) {
  const economy=payload&&typeof payload==='object'&&payload.economy&&typeof payload.economy==='object'?payload.economy:{};
  const multiplier=(value)=>Math.max(1,Math.min(3,Math.round(Number(value)||1)));
  return {pointsMultiplier:multiplier(economy.pointsMultiplier),treatsMultiplier:multiplier(economy.treatsMultiplier),coffeeMultiplier:multiplier(economy.coffeeMultiplier)};
}
function invalidateActiveRunLiveOpsCache(){activeRunLiveOpsCache={value:null,expiresAt:0,promise:null};}
async function activeRunLiveOpsEvent(env,force=false){
  const nowMs=Date.now();
  if(!force&&activeRunLiveOpsCache.value&&activeRunLiveOpsCache.expiresAt>nowMs)return activeRunLiveOpsCache.value;
  if(!force&&activeRunLiveOpsCache.promise)return activeRunLiveOpsCache.promise;
  const promise=(async()=>{
    const now=Math.floor(Date.now()/1000);
    let row=null;
    try{row=await env.DB.prepare(`SELECT event_id,title,ends_at,published_json FROM liveops_events WHERE status='active' AND starts_at<=? AND ends_at>? ORDER BY starts_at DESC LIMIT 1`).bind(now,now).first();}catch(error){if(!isMissingRuntimeDatabaseSchemaError(error))throw error;}
    if(!row)return {active:false,multipliers:{pointsMultiplier:1,treatsMultiplier:1,coffeeMultiplier:1}};
    const payload=safeJson(row.published_json,{}),multipliers=normalizeLiveOpsRunEconomy(payload);
    return {active:true,id:String(row.event_id||''),title:String(row.title||'LiveOps событие'),endsAt:Number(row.ends_at||0),notice:String(payload.playerNotice?.text||'').slice(0,220),multipliers};
  })();
  activeRunLiveOpsCache.promise=promise;
  try{const value=await promise;activeRunLiveOpsCache={value,expiresAt:Date.now()+15000,promise:null};return value;}catch(error){activeRunLiveOpsCache={value:null,expiresAt:0,promise:null};throw error;}
}

async function newcomerPathState(env,telegramId){
  await ensureRetentionPlatformV2Schema(env);
  const id=String(telegramId||'');
  if(!id)return {available:false,dayNumber:0,runs:0,steps:[]};
  const [profile,stepsResult,claimsResult,runsRow]=await Promise.all([
    env.DB.prepare(`SELECT created_at FROM admin_profile_state WHERE telegram_id=? LIMIT 1`).bind(id).first(),
    env.DB.prepare(`SELECT * FROM newcomer_path_steps WHERE enabled=1 ORDER BY step_day`).all(),
    env.DB.prepare(`SELECT step_day,status,claimed_at FROM newcomer_path_claims WHERE telegram_id=?`).bind(id).all(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM player_economy_run_ledger WHERE telegram_id=? AND duration_ms>=?`).bind(id,positiveInt(env.LEADERBOARD_MIN_RUN_SECONDS,DEFAULT_LEADERBOARD_MIN_RUN_SECONDS)*1000).first().catch(()=>({count:0}))
  ]);
  const createdAt=Math.max(0,Number(profile?.created_at||0));
  if(!createdAt)return {available:false,dayNumber:0,runs:0,steps:[]};
  const todayKey=dailyLoyaltyDayKey(Date.now(),180),createdKey=dailyLoyaltyDayKey(createdAt*1000,180);
  const dayNumber=Math.max(1,dailyLoyaltyDayOrdinal(todayKey)-dailyLoyaltyDayOrdinal(createdKey)+1),runs=Math.max(0,Number(runsRow?.count||0));
  const claims=new Map((claimsResult.results||[]).map(row=>[Number(row.step_day),row]));
  let previousClaimed=true;
  const steps=(stepsResult.results||[]).map(row=>{
    const day=Math.max(1,Number(row.step_day||1)),claim=claims.get(day),claimed=String(claim?.status||'')==='claimed';
    const reward=retentionV2Reward(row.reward_json),dayReached=dayNumber>=day,progress=Math.min(Math.max(0,Number(row.runs_required||1)),runs);
    const ready=!claimed&&previousClaimed&&dayReached&&runs>=Number(row.runs_required||1);
    const status=claimed?'claimed':ready?'ready':!previousClaimed?'previous':!dayReached?'day': 'progress';
    const view={day,title:String(row.title||`День ${day}`),description:String(row.description||''),runsRequired:Number(row.runs_required||1),runs:progress,ctaType:String(row.cta_type||'game'),reward,rewardLabel:referralRewardLabel(reward),claimed,claimedAt:Number(claim?.claimed_at||0),ready,status};
    previousClaimed=previousClaimed&&claimed;
    return view;
  });
  const completed=steps.length>0&&steps.every(step=>step.claimed),available=dayNumber<=7&&!completed&&steps.length>0;
  return {available,completed,dayNumber,runs,steps};
}

async function claimNewcomerPath(request,env,ctx=null){
  try{
    const body=await readJson(request);requireBotToken(env);const auth=await validateTelegramInitData(String(body.initData||''),env),telegramId=String(auth.user.id),stepDay=Math.max(1,Math.min(3,Math.floor(Number(body.stepDay)||0)));
    await ensureRetentionPlatformV2Schema(env);let state=await newcomerPathState(env,telegramId),step=state.steps.find(x=>x.day===stepDay);if(!step)throw new ApiError(404,'Этап пути новичка не найден.');if(step.claimed)return jsonResponse({ok:true,repeated:true,newcomerPath:state});if(!state.available||!step.ready)throw new ApiError(409,'Этот этап пока не готов к получению.');
    const reward=retentionV2Reward(step.reward);if(reward.kind==='none')throw new ApiError(409,'Для этапа не настроена награда.');const now=Math.floor(Date.now()/1000);
    await env.DB.prepare(`INSERT OR IGNORE INTO newcomer_path_claims(telegram_id,step_day,queue_id,status,claimed_at,updated_at) VALUES(?,?,0,'pending',0,?)`).bind(telegramId,stepDay,now).run();
    let claim=await env.DB.prepare(`SELECT * FROM newcomer_path_claims WHERE telegram_id=? AND step_day=? LIMIT 1`).bind(telegramId,stepDay).first();if(String(claim?.status||'')==='claimed')return jsonResponse({ok:true,repeated:true,newcomerPath:await newcomerPathState(env,telegramId)});
    let queueId=Math.max(0,Number(claim?.queue_id||0)),sourceId=`${telegramId}:day:${stepDay}`;
    if(!queueId){queueId=await enqueueRewardDelivery(env,telegramId,'newcomer_path',sourceId,reward,`Путь новичка · ${step.title}`);if(!queueId){const existing=await env.DB.prepare(`SELECT id FROM reward_delivery_queue WHERE source_type='newcomer_path' AND source_id=? AND telegram_id=? LIMIT 1`).bind(sourceId,telegramId).first();queueId=Number(existing?.id||0);}if(queueId)await env.DB.prepare(`UPDATE newcomer_path_claims SET queue_id=?,updated_at=? WHERE telegram_id=? AND step_day=?`).bind(queueId,now,telegramId,stepDay).run();}
    await processPlayerRewardDeliveryQueue(env,telegramId,5);const delivery=queueId?await env.DB.prepare(`SELECT status,last_error FROM reward_delivery_queue WHERE id=? LIMIT 1`).bind(queueId).first():null;
    if(String(delivery?.status||'')!=='delivered')throw new ApiError(503,String(delivery?.last_error||'Награда сохранена и будет выдана при повторной попытке.'));
    const claimedAt=Math.floor(Date.now()/1000);await env.DB.prepare(`UPDATE newcomer_path_claims SET status='claimed',claimed_at=?,updated_at=? WHERE telegram_id=? AND step_day=?`).bind(claimedAt,claimedAt,telegramId,stepDay).run();
    scheduleRunSettlementBackground(ctx,recordPlayerTimeline(env,telegramId,'newcomer_path',`завершил этап «${step.title}»`,{stepDay,reward},`newcomer_${telegramId}_${stepDay}`,auth.user,claimedAt),'newcomer timeline failed');
    return jsonResponse({ok:true,newcomerPath:await newcomerPathState(env,telegramId),profileRefreshRequired:['points','zefir','coffee'].includes(reward.kind),caseRefreshRequired:reward.kind==='case'});
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('claimNewcomerPath failed',error);return jsonResponse({ok:false,error:'Не удалось получить награду пути новичка.'},500);}
}

async function friendCoopConfig(env){
  await ensureRetentionPlatformV2Schema(env);const row=await env.DB.prepare(`SELECT * FROM friend_coop_task_config WHERE id=1 LIMIT 1`).first();const now=Math.floor(Date.now()/1000),start=Math.max(0,Number(row?.starts_at||0)),end=Math.max(0,Number(row?.ends_at||0)),enabled=Number(row?.enabled||0)===1,active=enabled&&(!start||now>=start)&&(!end||now<end);
  const metric=['runs','coffee','zefir','score'].includes(String(row?.metric||''))?String(row.metric):'runs';const reward=retentionV2Reward(row?.reward_json);
  return {taskKey:String(row?.task_key||'coop_default'),enabled,active,title:String(row?.title||'Вместе вкуснее'),description:String(row?.description||''),metric,target:Math.max(1,Number(row?.target_value||1)),reward,rewardLabel:referralRewardLabel(reward),startsAt:start,endsAt:end,cycleStartedAt:Math.max(0,Number(row?.cycle_started_at||0)),updatedAt:Number(row?.updated_at||0)};
}
async function friendCoopProgress(env,a,b,config){
  const start=config.startsAt||config.cycleStartedAt||0,end=config.endsAt||Math.floor(Date.now()/1000)+1,minMs=positiveInt(env.LEADERBOARD_MIN_RUN_SECONDS,DEFAULT_LEADERBOARD_MIN_RUN_SECONDS)*1000;
  const metric=String(config.metric||'runs');let expr='COUNT(*)';if(metric==='coffee')expr='COALESCE(SUM(coffee),0)';else if(metric==='zefir')expr='COALESCE(SUM(treats),0)';else if(metric==='score')expr='COALESCE(SUM(raw_score),0)';
  const row=await env.DB.prepare(`SELECT ${expr} AS value FROM player_economy_run_ledger WHERE telegram_id IN (?,?) AND created_at>=? AND created_at<? AND duration_ms>=?`).bind(String(a),String(b),start,end,minMs).first();return Math.max(0,Number(row?.value||0));
}
async function friendCoopStateForPlayer(env,telegramId){
  await Promise.all([ensureRetentionPlatformV2Schema(env),ensureReferralSchema(env)]);const id=String(telegramId),config=await friendCoopConfig(env);if(!config.enabled)return {ok:true,config,partners:[]};
  const links=(await env.DB.prepare(`SELECT invitee_telegram_id AS partner_id FROM referral_links WHERE referrer_telegram_id=? AND status='active' UNION SELECT referrer_telegram_id AS partner_id FROM referral_links WHERE invitee_telegram_id=? AND status='active' LIMIT 8`).bind(id,id).all()).results||[];
  const partnerIds=links.map(r=>String(r.partner_id||'')).filter(Boolean),identities=await referralPlayerIdentityMap(env,partnerIds);const partners=[];
  for(const partnerId of partnerIds){const pairKey=retentionV2PairKey(id,partnerId),[progress,claim]=await Promise.all([friendCoopProgress(env,id,partnerId,config),env.DB.prepare(`SELECT status,claimed_at FROM friend_coop_claims WHERE task_key=? AND pair_key=? AND telegram_id=? LIMIT 1`).bind(config.taskKey,pairKey,id).first()]);const who=identities.get(partnerId)||{};partners.push({telegramId:partnerId,displayName:who.displayName||who.username||'Друг',username:who.username||'',pairKey,progress,target:config.target,completed:progress>=config.target,claimed:String(claim?.status||'')==='claimed',claimStatus:String(claim?.status||''),claimedAt:Number(claim?.claimed_at||0)});}
  partners.sort((a,b)=>Number(b.completed)-Number(a.completed)||b.progress-a.progress);return {ok:true,config,partners};
}
async function getFriendCoopState(request,env){try{const body=await readJson(request);requireBotToken(env);const auth=await validateTelegramInitData(String(body.initData||''),env);return jsonResponse(await friendCoopStateForPlayer(env,String(auth.user.id)));}catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('getFriendCoopState failed',error);return jsonResponse({ok:false,error:'Не удалось загрузить совместное задание.'},500);}}
async function claimFriendCoopTask(request,env,ctx=null){
  try{const body=await readJson(request);requireBotToken(env);const auth=await validateTelegramInitData(String(body.initData||''),env),telegramId=String(auth.user.id),partnerId=String(body.partnerId||'').trim();if(!/^\d{4,20}$/.test(partnerId)||partnerId===telegramId)throw new ApiError(400,'Некорректный друг.');const state=await friendCoopStateForPlayer(env,telegramId),partner=state.partners.find(x=>x.telegramId===partnerId);if(!state.config?.active)throw new ApiError(409,'Совместное задание сейчас не активно.');if(!partner)throw new ApiError(404,'Активный друг не найден.');if(!partner.completed)throw new ApiError(409,'Совместная цель ещё не выполнена.');if(partner.claimed)return jsonResponse({ok:true,repeated:true,coop:state});const reward=retentionV2Reward(state.config.reward);if(reward.kind==='none')throw new ApiError(409,'Награда совместного задания не настроена.');const now=Math.floor(Date.now()/1000),sourceId=`${state.config.taskKey}:${partner.pairKey}`;
    await env.DB.prepare(`INSERT OR IGNORE INTO friend_coop_claims(task_key,pair_key,telegram_id,queue_id,status,claimed_at,updated_at) VALUES(?,?,?,0,'pending',0,?)`).bind(state.config.taskKey,partner.pairKey,telegramId,now).run();let claim=await env.DB.prepare(`SELECT * FROM friend_coop_claims WHERE task_key=? AND pair_key=? AND telegram_id=? LIMIT 1`).bind(state.config.taskKey,partner.pairKey,telegramId).first();if(String(claim?.status||'')==='claimed')return jsonResponse({ok:true,repeated:true,coop:await friendCoopStateForPlayer(env,telegramId)});let queueId=Math.max(0,Number(claim?.queue_id||0));if(!queueId){queueId=await enqueueRewardDelivery(env,telegramId,'friend_coop',sourceId,reward,`Совместное задание · ${state.config.title}`);if(!queueId){const q=await env.DB.prepare(`SELECT id FROM reward_delivery_queue WHERE source_type='friend_coop' AND source_id=? AND telegram_id=? LIMIT 1`).bind(sourceId,telegramId).first();queueId=Number(q?.id||0);}if(queueId)await env.DB.prepare(`UPDATE friend_coop_claims SET queue_id=?,updated_at=? WHERE task_key=? AND pair_key=? AND telegram_id=?`).bind(queueId,now,state.config.taskKey,partner.pairKey,telegramId).run();}
    await processPlayerRewardDeliveryQueue(env,telegramId,5);const delivery=queueId?await env.DB.prepare(`SELECT status,last_error FROM reward_delivery_queue WHERE id=? LIMIT 1`).bind(queueId).first():null;if(String(delivery?.status||'')!=='delivered')throw new ApiError(503,String(delivery?.last_error||'Награда сохранена и будет выдана при повторной попытке.'));const claimedAt=Math.floor(Date.now()/1000);await env.DB.prepare(`UPDATE friend_coop_claims SET status='claimed',claimed_at=?,updated_at=? WHERE task_key=? AND pair_key=? AND telegram_id=?`).bind(claimedAt,claimedAt,state.config.taskKey,partner.pairKey,telegramId).run();scheduleRunSettlementBackground(ctx,recordPlayerTimeline(env,telegramId,'friend_coop',`получил награду за совместное задание`,{taskKey:state.config.taskKey,partnerId,reward},`friend_coop_${retentionV2ShortHash(sourceId)}_${telegramId}`,auth.user,claimedAt),'friend coop timeline failed');return jsonResponse({ok:true,coop:await friendCoopStateForPlayer(env,telegramId),profileRefreshRequired:['points','zefir','coffee'].includes(reward.kind),caseRefreshRequired:reward.kind==='case'});
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('claimFriendCoopTask failed',error);return jsonResponse({ok:false,error:'Не удалось получить совместную награду.'},500);}
}

async function retentionEngagementAnalytics(env,now=Math.floor(Date.now()/1000)){
  await ensureRetentionPlatformV2Schema(env);const week=now-7*86400;
  const [mail,autoMail,newcomer,coop,event]=await Promise.all([
    env.DB.prepare(`SELECT COUNT(*) AS sent,SUM(CASE WHEN COALESCE(m.read_at,0)>0 THEN 1 ELSE 0 END) AS read,SUM(CASE WHEN g.status='claimed' THEN 1 ELSE 0 END) AS claimed FROM player_gift_inbox g LEFT JOIN player_mail_metadata m ON m.gift_id=g.gift_id AND m.telegram_id=g.telegram_id WHERE g.created_at>=?`).bind(week).first().catch(()=>({})),
    env.DB.prepare(`SELECT COUNT(*) AS sent,SUM(CASE WHEN COALESCE(m.read_at,0)>0 THEN 1 ELSE 0 END) AS read,SUM(CASE WHEN g.status='claimed' THEN 1 ELSE 0 END) AS claimed FROM automation_mail_deliveries d LEFT JOIN player_gift_inbox g ON g.gift_id=d.gift_id AND g.telegram_id=d.telegram_id LEFT JOIN player_mail_metadata m ON m.gift_id=d.gift_id AND m.telegram_id=d.telegram_id WHERE d.created_at>=?`).bind(week).first().catch(()=>({})),
    env.DB.prepare(`SELECT step_day,COUNT(*) AS claims FROM newcomer_path_claims WHERE status='claimed' GROUP BY step_day ORDER BY step_day`).all().catch(()=>({results:[]})),
    env.DB.prepare(`SELECT COUNT(*) AS claims,COUNT(DISTINCT pair_key) AS pairs FROM friend_coop_claims WHERE status='claimed' AND claimed_at>=?`).bind(week).first().catch(()=>({})),
    activeRunLiveOpsEvent(env).catch(()=>({active:false,multipliers:{pointsMultiplier:1,treatsMultiplier:1,coffeeMultiplier:1}}))
  ]);
  const mailView=(row)=>{const sent=Number(row?.sent||0),read=Number(row?.read||0),claimed=Number(row?.claimed||0);return{sent,read,claimed,readRate:sent?Math.round(read/sent*1000)/10:0,claimRate:sent?Math.round(claimed/sent*1000)/10:0};};
  return {mail7d:mailView(mail),automationMail7d:mailView(autoMail),newcomer:{claims:Object.fromEntries((newcomer.results||[]).map(r=>[`day${Number(r.step_day||0)}`,Number(r.claims||0)]))},friendCoop7d:{claims:Number(coop?.claims||0),pairs:Number(coop?.pairs||0)},liveOps:event};
}

