function botSupportPhotoChoiceMarkup() {
  return { inline_keyboard: [
    [{ text: "\u{1F4F7} \u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c \u0444\u043e\u0442\u043e", callback_data: "support:photo:add" }, { text: "\u2705 \u0411\u0435\u0437 \u0444\u043e\u0442\u043e", callback_data: "support:photo:skip" }],
    [{ text: "\u2716 \u041e\u0442\u043c\u0435\u043d\u0430", callback_data: "support:cancel" }]
  ] };
}

function botSupportDraftPreviewText(data) {
  const area = data.area ? `\n\u0413\u0434\u0435: <b>${escapeHtml(BOT_SUPPORT_AREA_LABELS[data.area] || data.area)}</b>` : "";
  return `\u{1F4CB} <b>\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435</b>\n\n\u041a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f: <b>${escapeHtml(SUPPORT_TICKET_CATEGORIES[data.category] || data.category || "other")}</b>${area}\n\u0422\u0435\u043c\u0430: <b>${escapeHtml(String(data.subject || ""))}</b>\n\u0424\u043e\u0442\u043e: <b>${data.photo ? "\u043f\u0440\u0438\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u043e" : "\u043d\u0435\u0442"}</b>\n\n${escapeHtml(String(data.message || "").slice(0,2400))}`;
}

function botSupportDraftConfirmMarkup() {
  return { inline_keyboard: [
    [{ text: "\u2705 \u041e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c", callback_data: "support:send" }],
    [{ text: "\u2716 \u041e\u0442\u043c\u0435\u043d\u0430", callback_data: "support:cancel" }]
  ] };
}

function botSupportPhotoFromMessage(message) {
  const photos = Array.isArray(message?.photo) ? message.photo : [];
  if (photos.length) {
    const photo = photos[photos.length - 1] || {};
    return { fileId: String(photo.file_id || ""), fileUniqueId: String(photo.file_unique_id || ""), mimeType: "image/jpeg", fileName: `telegram-photo-${Number(message.message_id || 0)}.jpg`, sizeBytes: Number(photo.file_size || 0), telegramMessageId: Number(message.message_id || 0), width: Number(photo.width || 0), height: Number(photo.height || 0) };
  }
  const doc = message?.document || null;
  if (doc && /^image\//i.test(String(doc.mime_type || "")) && String(doc.file_id || "")) {
    return { fileId: String(doc.file_id), fileUniqueId: String(doc.file_unique_id || ""), mimeType: String(doc.mime_type || "image/jpeg"), fileName: String(doc.file_name || `telegram-image-${Number(message.message_id || 0)}`).slice(0,120), sizeBytes: Number(doc.file_size || 0), telegramMessageId: Number(message.message_id || 0), width: 0, height: 0 };
  }
  return null;
}

async function botSupportDiagnostics(env, user, data = {}) {
  const telegramId = String(user?.id || "");
  const [profileResult, caseResult, runResult, passResult] = await Promise.allSettled([
    env.DB.prepare(`SELECT wallet,best_score,treats,coffee,profile_xp,revision,updated_at FROM admin_profile_state WHERE telegram_id=? LIMIT 1`).bind(telegramId).first(),
    env.DB.prepare(`SELECT active_skin_id,active_avatar_id,active_frame_id,active_trail_id,active_music_id,revision,updated_at FROM case_player_state WHERE telegram_id=? LIMIT 1`).bind(telegramId).first(),
    env.DB.prepare(`SELECT run_id,score,duration_ms,accepted,rejection_reason,created_at FROM leaderboard_runs WHERE telegram_id=? ORDER BY created_at DESC LIMIT 1`).bind(telegramId).first(),
    env.DB.prepare(`SELECT p.season_id,p.xp,p.premium_tier,p.revision,p.updated_at FROM season_pass_players p WHERE p.telegram_id=? ORDER BY p.updated_at DESC LIMIT 1`).bind(telegramId).first()
  ]);
  return {
    client: { channel: "telegram_bot", area: String(data.area || ""), chatType: String(data.chatType || "private") },
    server: { gameVersion: GAME_VERSION, workerBuild: WORKER_BUILD },
    telegram: { id: telegramId, username: String(user?.username || "").slice(0,64), firstName: String(user?.first_name || "").slice(0,100), lastName: String(user?.last_name || "").slice(0,100), languageCode: String(user?.language_code || "").slice(0,24), premium: Boolean(user?.is_premium) },
    profile: profileResult.status === "fulfilled" && profileResult.value ? profileResult.value : null,
    cosmetics: caseResult.status === "fulfilled" && caseResult.value ? caseResult.value : null,
    lastRun: runResult.status === "fulfilled" && runResult.value ? runResult.value : null,
    seasonPass: passResult.status === "fulfilled" && passResult.value ? passResult.value : null
  };
}

async function notifyBotSupportPhotoOwners(env, ticketId, subject, photo) {
  if (!photo?.fileId) return;
  const owners = [...new Set([...botOwnerTelegramIds(env), ...botAdminTelegramIds(env)].map(String).filter(Boolean))];
  for (const chatId of owners) {
    try {
      await telegramApi(env, "sendPhoto", { chat_id: chatId, photo: photo.fileId, caption: `\u{1F4F7} <b>\u0424\u043e\u0442\u043e \u043a \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044e #${ticketId}</b>\n${escapeHtml(String(subject || ""))}`, parse_mode: "HTML" });
    } catch (error) { console.error("bot support photo owner notification failed", error); }
  }
}

async function createBotPlayerSupportTicket(env, user, chatId, data, runtime = {}) {
  await ensurePlayerSupportSchema(env);
  const telegramId = String(user.id), category = String(data.category || "other"), subject = String(data.subject || "").trim().replace(/\s+/g, " ").slice(0,120), message = String(data.message || "").trim().slice(0,SUPPORT_MAX_MESSAGE_LENGTH);
  if (![...PLAYER_SUPPORT_CATEGORIES, "feedback"].includes(category)) throw new ApiError(400, "\u041d\u0435\u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u0430\u044f \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0438\u044f.");
  if (subject.length < 3 || message.length < 5) throw new ApiError(400, "\u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \u0442\u0435\u043c\u0443 \u0438 \u043e\u043f\u0438\u0441\u0430\u043d\u0438\u0435.");
  const requestId = supportRequestId(data.requestId, "bot_ticket");
  const repeated = await env.DB.prepare(`SELECT t.id FROM support_ticket_meta m JOIN support_tickets t ON t.id=m.ticket_id WHERE m.source='player' AND m.request_id=? AND t.player_telegram_id=? LIMIT 1`).bind(requestId, telegramId).first();
  if (repeated) return { ticketId: Number(repeated.id), repeated: true };
  const now = Math.floor(Date.now() / 1000);
  const [openRow, dailyRow] = await Promise.all([
    env.DB.prepare(`SELECT COUNT(*) AS count FROM support_tickets t JOIN support_ticket_meta m ON m.ticket_id=t.id WHERE t.player_telegram_id=? AND m.source='player' AND t.status IN ('new','working')`).bind(telegramId).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM support_tickets t JOIN support_ticket_meta m ON m.ticket_id=t.id WHERE t.player_telegram_id=? AND m.source='player' AND t.created_at>=?`).bind(telegramId, now - 86400).first()
  ]);
  if (Number(openRow?.count || 0) >= SUPPORT_MAX_OPEN_TICKETS) throw new ApiError(429, `\u041e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u043c\u043e\u0436\u043d\u043e \u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043d\u0435 \u0431\u043e\u043b\u0435\u0435 ${SUPPORT_MAX_OPEN_TICKETS} \u043e\u0442\u043a\u0440\u044b\u0442\u044b\u0445 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0439.`);
  if (Number(dailyRow?.count || 0) >= SUPPORT_MAX_DAILY_TICKETS) throw new ApiError(429, "\u041b\u0438\u043c\u0438\u0442 \u043d\u043e\u0432\u044b\u0445 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0439 \u043d\u0430 \u0441\u0435\u0433\u043e\u0434\u043d\u044f \u0438\u0441\u0447\u0435\u0440\u043f\u0430\u043d.");
  const playerName = telegramDisplayName(user), diagnostics = await botSupportDiagnostics(env, user, { area: data.area || "", chatType: "private" });
  const insert = await env.DB.prepare(`INSERT INTO support_tickets(created_by,created_by_name,player_telegram_id,player_name,category,description,status,assigned_to,assigned_to_name,resolution,created_at,updated_at,closed_at) VALUES(?,?,?,?,?,?,'new','','','',?,?,0)`).bind(telegramId, playerName, telegramId, playerName, category, message, now, now).run();
  let ticketId = Number(insert.meta?.last_row_id || 0);
  if (!ticketId) ticketId = Number((await env.DB.prepare(`SELECT id FROM support_tickets WHERE player_telegram_id=? AND created_at=? ORDER BY id DESC LIMIT 1`).bind(telegramId, now).first())?.id || 0);
  if (!ticketId) throw new ApiError(500, "\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435.");
  const msgInsert = await env.DB.prepare(`INSERT INTO support_messages(ticket_id,author_kind,author_telegram_id,author_name,message_text,request_id,client_json,created_at,telegram_delivered_at,telegram_error) VALUES(?,'player',?,?,?,?,?,?,0,'')`).bind(ticketId, telegramId, playerName, message, `${requestId}:initial`, JSON.stringify({ channel: "telegram_bot", area: String(data.area || "") }), now).run();
  const messageId = Number(msgInsert.meta?.last_row_id || 0);
  await env.DB.batch([
    env.DB.prepare(`INSERT INTO support_ticket_meta(ticket_id,source,subject,request_id,client_json,player_last_read_at,staff_last_read_at,last_player_message_at,last_staff_message_at,created_at,updated_at) VALUES(?,'player',?,?,?,?,0,?,0,?,?)`).bind(ticketId, subject, requestId, JSON.stringify(diagnostics), now, now, now, now),
    env.DB.prepare(`INSERT OR REPLACE INTO support_ticket_channels(ticket_id,channel,created_at,updated_at) VALUES(?,'bot',?,?)`).bind(ticketId, now, now)
  ]);
  await ensureSupportOperationsForTicket(env,ticketId,category,String(data.area || ""),"bot",now);
  const photo = data.photo && data.photo.fileId ? data.photo : null;
  if (photo) {
    await env.DB.prepare(`INSERT INTO support_attachments(ticket_id,message_id,uploader_kind,mime_type,file_name,size_bytes,telegram_file_id,telegram_file_unique_id,telegram_message_id,status,error_text,created_at,updated_at) VALUES(?,?,'player',?,?,?,?,?,?, 'uploaded','',?,?)`)
      .bind(ticketId, messageId, String(photo.mimeType || "image/jpeg"), String(photo.fileName || `support-${ticketId}.jpg`).slice(0,120), Number(photo.sizeBytes || 0), String(photo.fileId), String(photo.fileUniqueId || ""), Number(photo.telegramMessageId || 0), now, now).run();
  }
  const notification = supportNewTicketNotification({ ticketId, subject, category, message, diagnostics, playerName, telegramId });
  const background = (async () => {
    await notifySubscribedStaff(env, "new_tickets", `${notification}\n\n\u{1F916} \u041a\u0430\u043d\u0430\u043b: <b>Telegram-\u0431\u043e\u0442</b>`);
    await processPendingLeaderboardStaffNotifications(env, 20).catch((error) => console.error("bot support instant staff notification failed", error));
    if (photo) await notifyBotSupportPhotoOwners(env, ticketId, subject, photo);
    try { await recordPlayerTimeline(env, telegramId, "support", `\u0441\u043e\u0437\u0434\u0430\u043b \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 #${ticketId} \u0447\u0435\u0440\u0435\u0437 \u0431\u043e\u0442`, { ticketId, category, subject, channel: "bot" }, `support_bot_${ticketId}`, user, now); } catch (error) { console.error("bot support timeline failed", error); }
  })();
  if (!runWorkerBackground(runtime, background, "bot support create background")) void background.catch((error) => console.error("bot support create background failed", error));
  return { ticketId, repeated: false };
}

async function botSupportAppendReply(env, user, ticketId, text, messageId, runtime = {}) {
  await ensurePlayerSupportSchema(env);
  const telegramId = String(user.id), body = String(text || "").trim().slice(0, SUPPORT_MAX_MESSAGE_LENGTH);
  if (body.length < 1) throw new ApiError(400, "\u0412\u0432\u0435\u0434\u0438\u0442\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435.");
  const ticket = await env.DB.prepare(`SELECT t.*,m.source FROM support_tickets t JOIN support_ticket_meta m ON m.ticket_id=t.id WHERE t.id=? AND t.player_telegram_id=? AND m.source='player' LIMIT 1`).bind(Number(ticketId), telegramId).first();
  if (!ticket) throw new ApiError(404, "\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e.");
  if (!["new", "working"].includes(String(ticket.status))) throw new ApiError(409, "\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0443\u0436\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u043e.");
  const req = `botmsg_${String(user.id)}_${Number(messageId || Date.now())}`.slice(0,96), now = Math.floor(Date.now() / 1000), name = telegramDisplayName(user);
  const existing = await env.DB.prepare(`SELECT id FROM support_messages WHERE ticket_id=? AND request_id=? LIMIT 1`).bind(Number(ticketId), req).first();
  if (!existing) {
    await env.DB.batch([
      env.DB.prepare(`INSERT INTO support_messages(ticket_id,author_kind,author_telegram_id,author_name,message_text,request_id,client_json,created_at,telegram_delivered_at,telegram_error) VALUES(?,'player',?,?,?,?,?,?,0,'')`).bind(Number(ticketId), telegramId, name, body, req, JSON.stringify({ channel: "telegram_bot" }), now),
      env.DB.prepare(`UPDATE support_tickets SET updated_at=? WHERE id=?`).bind(now, Number(ticketId)),
      env.DB.prepare(`UPDATE support_ticket_meta SET last_player_message_at=?,updated_at=? WHERE ticket_id=?`).bind(now, now, Number(ticketId))
    ]);
    const task = (async () => {
      await notifySubscribedStaff(env, "new_tickets", `\u{1F4AC} <b>\u041e\u0442\u0432\u0435\u0442 \u0438\u0433\u0440\u043e\u043a\u0430 \u0432 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0438 #${Number(ticketId)}</b>\n\n\u0418\u0433\u0440\u043e\u043a: <b>${escapeHtml(name)}</b> \u00b7 <code>${escapeHtml(telegramId)}</code>\n\u041a\u0430\u043d\u0430\u043b: <b>Telegram-\u0431\u043e\u0442</b>\n\n${escapeHtml(body.slice(0,1800))}`);
      await processPendingLeaderboardStaffNotifications(env,20).catch((error)=>console.error("bot support reply notification failed",error));
    })();
    if (!runWorkerBackground(runtime, task, "bot support reply background")) void task.catch(() => {});
  }
  return { ticketId: Number(ticketId), repeated: Boolean(existing) };
}

async function resolveBotPlayerSupportTicket(env, user, ticketId, runtime = {}) {
  await ensurePlayerSupportSchema(env);
  const telegramId = String(user.id), id = Number(ticketId), row = await env.DB.prepare(`SELECT t.id,t.status FROM support_tickets t JOIN support_ticket_meta m ON m.ticket_id=t.id WHERE t.id=? AND t.player_telegram_id=? AND m.source='player' LIMIT 1`).bind(id, telegramId).first();
  if (!row) throw new ApiError(404, "\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e.");
  if (["resolved","rejected"].includes(String(row.status))) return { ticketId:id,repeated:true };
  const now = Math.floor(Date.now()/1000), req = `player_resolve_${id}`;
  await env.DB.batch([
    env.DB.prepare(`UPDATE support_tickets SET status='resolved',resolution=CASE WHEN TRIM(resolution)='' THEN ? ELSE resolution END,updated_at=?,closed_at=? WHERE id=?`).bind("\u0418\u0433\u0440\u043e\u043a \u043e\u0442\u043c\u0435\u0442\u0438\u043b \u0432\u043e\u043f\u0440\u043e\u0441 \u0440\u0435\u0448\u0451\u043d\u043d\u044b\u043c.",now,now,id),
    env.DB.prepare(`INSERT OR IGNORE INTO support_messages(ticket_id,author_kind,author_telegram_id,author_name,message_text,request_id,client_json,created_at,telegram_delivered_at,telegram_error) VALUES(?,'system','','',?,?,'{}',?,0,'')`).bind(id,"\u0418\u0433\u0440\u043e\u043a \u043e\u0442\u043c\u0435\u0442\u0438\u043b \u0432\u043e\u043f\u0440\u043e\u0441 \u0440\u0435\u0448\u0451\u043d\u043d\u044b\u043c.",req,now),
    env.DB.prepare(`UPDATE support_ticket_meta SET player_last_read_at=?,updated_at=? WHERE ticket_id=?`).bind(now,now,id)
  ]);
  const task = notifySubscribedStaff(env,"new_tickets",`\u2705 <b>\u0418\u0433\u0440\u043e\u043a \u043e\u0442\u043c\u0435\u0442\u0438\u043b \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 #${id} \u0440\u0435\u0448\u0451\u043d\u043d\u044b\u043c</b>\n\n<code>${escapeHtml(telegramId)}</code>`);
  if (!runWorkerBackground(runtime, task, "bot support resolved notification")) void task.catch(() => {});
  return { ticketId:id,repeated:false };
}

async function recordPlayerSupportFeedback(env, user, ticketId, closeToken, rating, runtime = {}) {
  await ensurePlayerSupportSchema(env);
  const telegramId = String(user?.id || ""), id = Number(ticketId || 0), token = String(closeToken || ""), value = String(rating || "");
  if (!id || !/^\d{8,12}$/.test(token) || !["up","down"].includes(value)) throw new ApiError(400,"Некорректная оценка обращения.");
  const row = await env.DB.prepare(`SELECT t.id,t.status,t.closed_at,t.player_telegram_id,t.assigned_to,t.assigned_to_name,m.source FROM support_tickets t JOIN support_ticket_meta m ON m.ticket_id=t.id WHERE t.id=? AND t.player_telegram_id=? AND m.source='player' LIMIT 1`).bind(id,telegramId).first();
  if (!row) throw new ApiError(404,"Обращение не найдено.");
  if (String(row.status)!=='resolved' || String(Number(row.closed_at||0))!==token) throw new ApiError(409,"Эта оценка уже не относится к текущему закрытию обращения.");
  const existing = await env.DB.prepare(`SELECT id,rating FROM support_ticket_feedback WHERE ticket_id=? AND close_token=? LIMIT 1`).bind(id,token).first();
  if (existing) return {ticketId:id,rating:String(existing.rating||value),repeated:true,reopened:false};
  const now=Math.floor(Date.now()/1000),systemText=value==='up'?'Игрок оценил ответ поддержки: 👍 помогло.':'Игрок оценил ответ поддержки: 👎 не помогло. Обращение автоматически возвращено в работу.';
  const feedbackInsert=env.DB.prepare(`INSERT OR IGNORE INTO support_ticket_feedback(ticket_id,close_token,rating,source,player_telegram_id,created_at) VALUES(?,?,?,'bot',?,?)`).bind(id,token,value,telegramId,now);
  const messageInsert=env.DB.prepare(`INSERT OR IGNORE INTO support_messages(ticket_id,author_kind,author_telegram_id,author_name,message_text,request_id,client_json,created_at,telegram_delivered_at,telegram_error) VALUES(?,'system','','',?,?,'{}',?,0,'')`).bind(id,systemText,`feedback_${id}_${token}`,now);
  if(value==='down'){
    const results=await env.DB.batch([
      feedbackInsert,
      messageInsert,
      env.DB.prepare(`UPDATE support_tickets SET status='working',resolution='',updated_at=?,closed_at=0 WHERE id=? AND status='resolved' AND closed_at=?`).bind(now,id,Number(token)),
      env.DB.prepare(`UPDATE support_ticket_meta SET last_player_message_at=?,player_last_read_at=?,updated_at=? WHERE ticket_id=?`).bind(now,now,now,id)
    ]);
    const inserted=Number(results?.[0]?.meta?.changes||0)>0;
    if(!inserted)return {ticketId:id,rating:value,repeated:true,reopened:String(row.status)==='resolved'};
    const task=(async()=>{await notifySubscribedStaff(env,'new_tickets',`👎 <b>Игроку не помог ответ по обращению #${id}</b>

Игрок: <code>${escapeHtml(telegramId)}</code>
Обращение автоматически возвращено в работу.`);await processPendingLeaderboardStaffNotifications(env,20).catch((error)=>console.error('support negative feedback notification failed',error));})();
    if(!runWorkerBackground(runtime,task,'support negative feedback'))void task.catch(()=>{});
    return {ticketId:id,rating:value,repeated:false,reopened:true};
  }
  const results=await env.DB.batch([
    feedbackInsert,
    messageInsert,
    env.DB.prepare(`UPDATE support_ticket_meta SET player_last_read_at=?,updated_at=? WHERE ticket_id=?`).bind(now,now,id)
  ]);
  const inserted=Number(results?.[0]?.meta?.changes||0)>0;
  return {ticketId:id,rating:value,repeated:!inserted,reopened:false};
}

async function showBotSupportTickets(chatId, user, env) {
  const state = await playerSupportStateData(env, String(user.id));
  const tickets = (state.tickets || []).slice(0,5);
  const lines = tickets.map((t) => `${t.unread ? "\u{1F534}" : "\u{1F39F}"} #${t.id} \u00b7 <b>${escapeHtml(t.categoryLabel)}</b> \u00b7 ${escapeHtml(t.statusLabel)}\n${escapeHtml(String(t.subject || "").slice(0,90))}`).join("\n\n") || "\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0439 \u043f\u043e\u043a\u0430 \u043d\u0435\u0442.";
  const buttons = tickets.map((t) => [{ text: `${t.unread ? "\u{1F534} " : ""}#${t.id} \u00b7 ${String(t.categoryLabel).slice(0,22)}`, callback_data: `support:ticket:${t.id}` }]);
  buttons.push([{text:"\u2795 \u041d\u043e\u0432\u043e\u0435 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435",callback_data:"support:home"}],[{text:"\u2190 \u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430",callback_data:"support:home"}]);
  await sendTelegramMessage(env, chatId, `\u{1F4C2} <b>\u041c\u043e\u0438 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044f</b>\n\n\u041e\u0442\u043a\u0440\u044b\u0442\u043e: <b>${state.openCount}</b> \u00b7 \u043d\u043e\u0432\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432: <b>${state.unreadCount}</b>\n\n${lines}`, {inline_keyboard:buttons});
}

async function showBotSupportTicketDetail(chatId, user, ticketId, env) {
  const state = await playerSupportStateData(env, String(user.id));
  const ticket = (state.tickets || []).find((t) => Number(t.id) === Number(ticketId));
  if (!ticket) { await sendTelegramMessage(env,chatId,"\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043d\u0435 \u043d\u0430\u0439\u0434\u0435\u043d\u043e.",botSupportHomeMarkup(env,state)); return; }
  const now=Math.floor(Date.now()/1000);await env.DB.prepare(`UPDATE support_ticket_meta SET player_last_read_at=?,updated_at=MAX(updated_at,?) WHERE ticket_id=?`).bind(now,now,Number(ticket.id)).run().catch(()=>{});
  const messages=(ticket.messages||[]).slice(-8).map((m)=>{const who=m.authorKind==='staff'?"\u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430":m.authorKind==='player'?"\u0412\u044b":"\u0421\u0438\u0441\u0442\u0435\u043c\u0430";return `<b>${who}</b> \u00b7 ${escapeHtml(formatUtcDate(m.createdAt))}\n${escapeHtml(String(m.text||"").slice(0,700))}`;}).join("\n\n")||"\u0418\u0441\u0442\u043e\u0440\u0438\u044f \u043f\u0443\u0441\u0442\u0430.";
  const open=["new","working"].includes(ticket.status);const buttons=[];if(open)buttons.push([{text:"\u{1F4AC} \u041e\u0442\u0432\u0435\u0442\u0438\u0442\u044c",callback_data:`support:reply:${ticket.id}`},{text:"\u2705 \u0412\u043e\u043f\u0440\u043e\u0441 \u0440\u0435\u0448\u0451\u043d",callback_data:`support:resolve:${ticket.id}`}]);buttons.push([{text:"\u2190 \u041c\u043e\u0438 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044f",callback_data:"support:my"}]);
  await sendTelegramMessage(env,chatId,`\u{1F39F} <b>\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 #${ticket.id}</b>\n${escapeHtml(ticket.categoryLabel)} \u00b7 <b>${escapeHtml(ticket.statusLabel)}</b> \u00b7 ${escapeHtml(supportChannelLabel(ticket.channel))}\n<b>${escapeHtml(ticket.subject)}</b>\n\n${messages}${(ticket.attachments||[]).length?`\n\n\u{1F4CE} \u0412\u043b\u043e\u0436\u0435\u043d\u0438\u0439: ${ticket.attachments.length}`:""}`,{inline_keyboard:buttons});
}

async function beginBotSupportDraft(query, mode, env) {
  const chatId=query.message?.chat?.id;if(!chatId)return;
  await clearStaffWorkflow(query.from.id,env).catch(()=>{});await clearBotPlayerSupportWorkflow(query.from.id,env).catch(()=>{});
  const requestId=supportRequestId("","bot_ticket");
  if(mode==="help"){await setBotPlayerSupportWorkflow(query.from.id,chatId,"help_category",{requestId,mode},env);await answerCallback(env,query.id,"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0442\u0435\u043c\u0443.");await sendTelegramMessage(env,chatId,"\u{1F198} <b>\u0421 \u0447\u0435\u043c \u043d\u0443\u0436\u043d\u0430 \u043f\u043e\u043c\u043e\u0449\u044c?</b>\n\n\u0415\u0441\u043b\u0438 \u043e\u0442\u0432\u0435\u0442 \u0443\u0436\u0435 \u0435\u0441\u0442\u044c \u0432 FAQ, \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0435\u0433\u043e \u0434\u043e \u0441\u043e\u0437\u0434\u0430\u043d\u0438\u044f \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044f.",botSupportHelpCategoryMarkup());return;}
  const category=mode==="bug"?"bug":mode==="idea"?"suggestion":"feedback";
  if(mode==="bug"){await setBotPlayerSupportWorkflow(query.from.id,chatId,"area",{requestId,mode,category},env);await answerCallback(env,query.id,"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u0440\u0430\u0437\u0434\u0435\u043b.");await sendTelegramMessage(env,chatId,"\u{1F41E} <b>\u0413\u0434\u0435 \u0432\u043e\u0437\u043d\u0438\u043a\u043b\u0430 \u043e\u0448\u0438\u0431\u043a\u0430?</b>",botSupportAreaMarkup());return;}
  await setBotPlayerSupportWorkflow(query.from.id,chatId,"subject",{requestId,mode,category},env);await answerCallback(env,query.id,"\u041d\u0430\u0447\u0438\u043d\u0430\u0435\u043c.");await sendTelegramMessage(env,chatId,"<b>\u041a\u043e\u0440\u043e\u0442\u043a\u043e \u043d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0442\u0435\u043c\u0443</b>\n\n\u041e\u0434\u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0430, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440: \u00ab\u0418\u0434\u0435\u044f \u0434\u043b\u044f \u043d\u043e\u0432\u043e\u0433\u043e \u043a\u0435\u0439\u0441\u0430\u00bb.");
}

async function handleBotSupportCallback(query, env, runtime = {}) {
  const data=String(query.data||"");if(!data.startsWith("support:"))return false;const chatId=query.message?.chat?.id;if(!chatId)return true;
  if(data==="support:home"){await answerCallback(env,query.id,"\u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430");await showBotSupportHome(chatId,query.from,env);return true;}
  if(data==="support:my"){await answerCallback(env,query.id,"\u041c\u043e\u0438 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044f");await showBotSupportTickets(chatId,query.from,env);return true;}
  const start=data.match(/^support:new:(help|bug|idea|feedback)$/);if(start){await beginBotSupportDraft(query,start[1],env);return true;}
  const help=data.match(/^support:help:(purchase|reward|account|other)$/);if(help){let wf=await getBotPlayerSupportWorkflow(query.from.id,env);const requestId=wf?.data?.requestId||supportRequestId("","bot_ticket");await setBotPlayerSupportWorkflow(query.from.id,chatId,"subject",{requestId,mode:"help",category:help[1]},env);await answerCallback(env,query.id,"\u0422\u0435\u043c\u0430 \u0432\u044b\u0431\u0440\u0430\u043d\u0430.");await sendTelegramMessage(env,chatId,"<b>\u041a\u043e\u0440\u043e\u0442\u043a\u043e \u043d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0442\u0435\u043c\u0443 \u0432\u043e\u043f\u0440\u043e\u0441\u0430</b>");return true;}
  const area=data.match(/^support:area:(game|shop|pass|cases|rating|bot|other)$/);if(area){const wf=await getBotPlayerSupportWorkflow(query.from.id,env);if(!wf){await answerCallback(env,query.id,"\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0443\u0441\u0442\u0430\u0440\u0435\u043b\u043e.",true);return true;}await updateBotPlayerSupportWorkflow(query.from.id,{step:"subject",data:{area:area[1]}},env);await answerCallback(env,query.id,"\u0420\u0430\u0437\u0434\u0435\u043b \u0432\u044b\u0431\u0440\u0430\u043d.");await sendTelegramMessage(env,chatId,"<b>\u041a\u043e\u0440\u043e\u0442\u043a\u043e \u043d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u0442\u0435\u043c\u0443 \u043e\u0448\u0438\u0431\u043a\u0438</b>");return true;}
  if(data==="support:photo:add"){const wf=await getBotPlayerSupportWorkflow(query.from.id,env);if(!wf||wf.step!=="photo_choice"){await answerCallback(env,query.id,"\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0443\u0441\u0442\u0430\u0440\u0435\u043b\u043e.",true);return true;}await updateBotPlayerSupportWorkflow(query.from.id,{step:"photo"},env);await answerCallback(env,query.id,"\u041f\u0440\u0438\u0448\u043b\u0438\u0442\u0435 \u0444\u043e\u0442\u043e.");await sendTelegramMessage(env,chatId,"\u{1F4F7} \u041e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 <b>\u043e\u0434\u043d\u0443 \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u044e</b> \u043e\u0431\u044b\u0447\u043d\u044b\u043c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435\u043c. \u041e\u043d\u0430 \u0431\u0443\u0434\u0435\u0442 \u043f\u0440\u0438\u043a\u0440\u0435\u043f\u043b\u0435\u043d\u0430 \u043a \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044e.",{inline_keyboard:[[{text:"\u0411\u0435\u0437 \u0444\u043e\u0442\u043e",callback_data:"support:photo:skip"}],[{text:"\u2716 \u041e\u0442\u043c\u0435\u043d\u0430",callback_data:"support:cancel"}]]});return true;}
  if(data==="support:photo:skip"){const wf=await getBotPlayerSupportWorkflow(query.from.id,env);if(!wf||!["photo_choice","photo"].includes(wf.step)){await answerCallback(env,query.id,"\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0443\u0441\u0442\u0430\u0440\u0435\u043b\u043e.",true);return true;}const next=await updateBotPlayerSupportWorkflow(query.from.id,{step:"confirm",data:{photo:null}},env);await answerCallback(env,query.id,"\u0411\u0435\u0437 \u0444\u043e\u0442\u043e.");await sendTelegramMessage(env,chatId,botSupportDraftPreviewText(next.data),botSupportDraftConfirmMarkup());return true;}
  if(data==="support:send"){const wf=await getBotPlayerSupportWorkflow(query.from.id,env);if(!wf||wf.step!=="confirm"){await answerCallback(env,query.id,"\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u0443\u0441\u0442\u0430\u0440\u0435\u043b\u043e.",true);return true;}try{const created=await createBotPlayerSupportTicket(env,query.from,chatId,wf.data,runtime);await clearBotPlayerSupportWorkflow(query.from.id,env);await answerCallback(env,query.id,"\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043e\u0442\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043e.");await sendTelegramMessage(env,chatId,`\u2705 <b>\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 #${created.ticketId} \u0441\u043e\u0437\u0434\u0430\u043d\u043e</b>\n\n\u041e\u0442\u0432\u0435\u0442 \u043f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0438 \u043f\u0440\u0438\u0434\u0451\u0442 \u0441\u044e\u0434\u0430 \u0432 \u0431\u043e\u0442 \u0438 \u043e\u0441\u0442\u0430\u043d\u0435\u0442\u0441\u044f \u0432 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u0432 \u0438\u0433\u0440\u0435.`,{inline_keyboard:[[{text:`\u{1F39F} \u041e\u0442\u043a\u0440\u044b\u0442\u044c #${created.ticketId}`,callback_data:`support:ticket:${created.ticketId}`}],[{text:"\u2190 \u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430",callback_data:"support:home"}]]});}catch(error){await answerCallback(env,query.id,"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c.",true);await sendTelegramMessage(env,chatId,escapeHtml(String(error?.message||"\u041e\u0448\u0438\u0431\u043a\u0430 \u043e\u0442\u043f\u0440\u0430\u0432\u043a\u0438.")),{inline_keyboard:[[{text:"\u2190 \u041f\u043e\u0434\u0434\u0435\u0440\u0436\u043a\u0430",callback_data:"support:home"}]]});}return true;}
  const open=data.match(/^support:ticket:(\d+)$/);if(open){await answerCallback(env,query.id,"\u041e\u0442\u043a\u0440\u044b\u0432\u0430\u044e.");await showBotSupportTicketDetail(chatId,query.from,Number(open[1]),env);return true;}
  const reply=data.match(/^support:reply:(\d+)$/);if(reply){const state=await playerSupportStateData(env,String(query.from.id));const t=(state.tickets||[]).find(x=>Number(x.id)===Number(reply[1])&&["new","working"].includes(x.status));if(!t){await answerCallback(env,query.id,"\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0437\u0430\u043a\u0440\u044b\u0442\u043e.",true);return true;}await setBotPlayerSupportWorkflow(query.from.id,chatId,"reply_existing",{ticketId:Number(reply[1])},env);await answerCallback(env,query.id,"\u041d\u0430\u043f\u0438\u0448\u0438\u0442\u0435 \u043e\u0442\u0432\u0435\u0442.");await sendTelegramMessage(env,chatId,`\u{1F4AC} <b>\u041e\u0442\u0432\u0435\u0442 \u0432 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 #${Number(reply[1])}</b>\n\n\u041e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0435\u0435 \u0442\u0435\u043a\u0441\u0442\u043e\u0432\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435.`,{inline_keyboard:[[{text:"\u2716 \u041e\u0442\u043c\u0435\u043d\u0430",callback_data:"support:cancel"}]]});return true;}
  const resolved=data.match(/^support:resolve:(\d+)$/);if(resolved){try{await resolveBotPlayerSupportTicket(env,query.from,Number(resolved[1]),runtime);await answerCallback(env,query.id,"\u041e\u0442\u043c\u0435\u0447\u0435\u043d\u043e \u0440\u0435\u0448\u0451\u043d\u043d\u044b\u043c.");await showBotSupportTicketDetail(chatId,query.from,Number(resolved[1]),env);}catch(error){await answerCallback(env,query.id,String(error?.message||"\u041e\u0448\u0438\u0431\u043a\u0430"),true);}return true;}
  const feedback=data.match(/^support:fb:(\d+):(\d+):(up|down)$/);if(feedback){try{const result=await recordPlayerSupportFeedback(env,query.from,Number(feedback[1]),feedback[2],feedback[3],runtime);if(result.rating==='down'){await answerCallback(env,query.id,'Спасибо. Обращение возвращено в работу.');await sendTelegramMessage(env,chatId,`👎 <b>Спасибо за оценку</b>

Обращение #${Number(feedback[1])} снова открыто. Напишите, что осталось нерешённым — поддержка продолжит работу.`,{inline_keyboard:[[{text:'💬 Дополнить обращение',callback_data:`support:reply:${Number(feedback[1])}`}],[{text:'📂 Мои обращения',callback_data:'support:my'}]]});}else{await answerCallback(env,query.id,'Спасибо за оценку!');await sendTelegramMessage(env,chatId,`👍 <b>Спасибо за обратную связь!</b>

Рады, что смогли помочь с обращением #${Number(feedback[1])}.`,{inline_keyboard:[[{text:'📂 Мои обращения',callback_data:'support:my'}],[{text:'🎮 Открыть игру',web_app:{url:configuredGameUrl(env)}}]]});}}catch(error){await answerCallback(env,query.id,String(error?.message||'Не удалось сохранить оценку.'),true);}return true;}
  if(data==="support:cancel"){await clearBotPlayerSupportWorkflow(query.from.id,env);await answerCallback(env,query.id,"\u041e\u0442\u043c\u0435\u043d\u0435\u043d\u043e.");await showBotSupportHome(chatId,query.from,env);return true;}
  return false;
}

async function handleBotPlayerSupportWorkflowMessage(message, env, runtime = {}) {
  const workflow=await getBotPlayerSupportWorkflow(message.from.id,env);if(!workflow||String(workflow.chatId)!==String(message.chat.id))return false;
  const text=String(message.text||message.caption||"").trim(),data=workflow.data||{};
  if(workflow.step==="subject"){
    if(!message.text||text.length<3||text.length>120){await sendTelegramMessage(env,message.chat.id,"\u0422\u0435\u043c\u0430 \u0434\u043e\u043b\u0436\u043d\u0430 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043e\u0442 3 \u0434\u043e 120 \u0441\u0438\u043c\u0432\u043e\u043b\u043e\u0432.");return true;}
    await updateBotPlayerSupportWorkflow(message.from.id,{step:"description",data:{subject:text}},env);await sendTelegramMessage(env,message.chat.id,"<b>\u041e\u043f\u0438\u0448\u0438\u0442\u0435 \u0432\u043e\u043f\u0440\u043e\u0441 \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435</b>\n\n\u0427\u0442\u043e \u043f\u0440\u043e\u0438\u0437\u043e\u0448\u043b\u043e, \u043a\u0430\u043a \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u044c \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0443 \u0438\u043b\u0438 \u0447\u0442\u043e \u0432\u044b \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430\u0435\u0442\u0435.");return true;
  }
  if(workflow.step==="description"){
    if(!message.text||text.length<5){await sendTelegramMessage(env,message.chat.id,"\u041e\u043f\u0438\u0448\u0438\u0442\u0435 \u0432\u043e\u043f\u0440\u043e\u0441 \u0447\u0443\u0442\u044c \u043f\u043e\u0434\u0440\u043e\u0431\u043d\u0435\u0435.");return true;}
    await updateBotPlayerSupportWorkflow(message.from.id,{step:"photo_choice",data:{message:text.slice(0,SUPPORT_MAX_MESSAGE_LENGTH)}},env);await sendTelegramMessage(env,message.chat.id,"\u{1F4F7} <b>\u041f\u0440\u0438\u043a\u0440\u0435\u043f\u0438\u0442\u044c \u0444\u043e\u0442\u043e?</b>\n\n\u0415\u0441\u043b\u0438 \u0441\u043a\u0440\u0438\u043d\u0448\u043e\u0442 \u043d\u0435 \u043d\u0443\u0436\u0435\u043d, \u043c\u043e\u0436\u043d\u043e \u0441\u0440\u0430\u0437\u0443 \u043f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u044c.",botSupportPhotoChoiceMarkup());return true;
  }
  if(workflow.step==="photo"){
    const photo=botSupportPhotoFromMessage(message);if(!photo){await sendTelegramMessage(env,message.chat.id,"\u041f\u0440\u0438\u0448\u043b\u0438\u0442\u0435 \u0444\u043e\u0442\u043e\u0433\u0440\u0430\u0444\u0438\u044e \u0438\u043b\u0438 \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u00ab\u0411\u0435\u0437 \u0444\u043e\u0442\u043e\u00bb.",{inline_keyboard:[[{text:"\u0411\u0435\u0437 \u0444\u043e\u0442\u043e",callback_data:"support:photo:skip"}],[{text:"\u2716 \u041e\u0442\u043c\u0435\u043d\u0430",callback_data:"support:cancel"}]]});return true;}
    if(photo.sizeBytes>10*1024*1024){await sendTelegramMessage(env,message.chat.id,"\u0424\u0430\u0439\u043b \u0441\u043b\u0438\u0448\u043a\u043e\u043c \u0431\u043e\u043b\u044c\u0448\u043e\u0439. \u041f\u0440\u0438\u0448\u043b\u0438\u0442\u0435 \u0438\u0437\u043e\u0431\u0440\u0430\u0436\u0435\u043d\u0438\u0435 \u0434\u043e 10 \u041c\u0411.");return true;}
    const next=await updateBotPlayerSupportWorkflow(message.from.id,{step:"confirm",data:{photo}},env);await sendTelegramMessage(env,message.chat.id,botSupportDraftPreviewText(next.data),botSupportDraftConfirmMarkup());return true;
  }
  if(workflow.step==="reply_existing"){
    if(!message.text||text.length<1){await sendTelegramMessage(env,message.chat.id,"\u041e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u0442\u0435\u043a\u0441\u0442\u043e\u0432\u043e\u0435 \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435.");return true;}
    try{await botSupportAppendReply(env,message.from,Number(data.ticketId),text,Number(message.message_id||0),runtime);await clearBotPlayerSupportWorkflow(message.from.id,env);await sendTelegramMessage(env,message.chat.id,`\u2705 \u0421\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d\u043e \u0432 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 #${Number(data.ticketId)}.`);await showBotSupportTicketDetail(message.chat.id,message.from,Number(data.ticketId),env);}catch(error){await sendTelegramMessage(env,message.chat.id,escapeHtml(String(error?.message||"\u041d\u0435 \u0443\u0434\u0430\u043b\u043e\u0441\u044c \u043e\u0442\u043f\u0440\u0430\u0432\u0438\u0442\u044c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0435.")));}return true;
  }
  if(["help_category","area","photo_choice","confirm"].includes(workflow.step)){await sendTelegramMessage(env,message.chat.id,"\u041f\u0440\u043e\u0434\u043e\u043b\u0436\u0438\u0442\u0435 \u043a\u043d\u043e\u043f\u043a\u0430\u043c\u0438 \u0432 \u043f\u0440\u0435\u0434\u044b\u0434\u0443\u0449\u0435\u043c \u0441\u043e\u043e\u0431\u0449\u0435\u043d\u0438\u0438 \u0438\u043b\u0438 \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435.",{inline_keyboard:[[{text:"\u2716 \u041e\u0442\u043c\u0435\u043d\u0430",callback_data:"support:cancel"}]]});return true;}
  return false;
}


function ticketCategoryMarkup() {
  const entries = STAFF_SUPPORT_CATEGORIES.map((id) => [id, SUPPORT_TICKET_CATEGORIES[id]]);
  const rows = [];
  for (let index = 0; index < entries.length; index += 2) {
    rows.push(entries.slice(index, index + 2).map(([id, title]) => ({
      text: title.slice(0, 28),
      callback_data: `ticket_cat:${id}`
    })));
  }
  rows.push([{ text: "Отмена", callback_data: "ops_cancel" }]);
  return { inline_keyboard: rows };
}

async function startTicketWorkflow(chatId, user, env) {
  const access = await getTeamAccess(user, env);
  if (!access.authorized) {
    await sendTelegramMessage(env, chatId, access.reason === "expired"
      ? "Рабочая сессия истекла. Выполните <code>/staff</code>."
      : "Создавать обращения могут только сотрудники.");
    return;
  }
  await clearStaffWorkflow(user.id, env);
  await sendTelegramMessage(env, chatId,
    `<b>Новое обращение</b>\n\nВыберите категорию проблемы.`,
    ticketCategoryMarkup()
  );
}

async function beginTicketCategory(query, category, env) {
  const access = await getTeamAccess(query.from, env);
  const chatId = query.message?.chat?.id;
  if (!access.authorized) {
    await answerCallback(env, query.id, "Сначала выполните /staff.", true);
    return;
  }
  if (!STAFF_SUPPORT_CATEGORIES.includes(category)) {
    await answerCallback(env, query.id, "Неизвестная категория.", true);
    return;
  }
  await setStaffWorkflow(query.from.id, chatId, "ticket", "target", { category }, env);
  await answerCallback(env, query.id, "Категория выбрана.");
  await sendTelegramMessage(env, chatId,
    `<b>${escapeHtml(SUPPORT_TICKET_CATEGORIES[category])}</b>\n\nОтправьте Telegram ID игрока или точный <code>@username</code>.\nЕсли обращение не связано с конкретным игроком, отправьте <code>skip</code>.`
  );
}

async function handleTicketWorkflowMessage(message, workflow, env) {
  const chatId = message.chat.id;
  const user = message.from;
  const access = await getTeamAccess(user, env);
  if (!access.authorized) return true;
  const text = String(message.text || "").trim();
  const data = workflow.data || {};
  if (workflow.step === "target") {
    if (/^(skip|нет|пропустить)$/i.test(text)) {
      await updateStaffWorkflow(user.id, { step: "description", data: { targetId: "", playerName: "" } }, env);
      await sendTelegramMessage(env, chatId, "Опишите проблему или предложение одним сообщением.");
      return true;
    }
    const targetId = await resolvePlayerTelegramId(text, env);
    if (!targetId || !(await playerProfileExists(targetId, env))) {
      await sendTelegramMessage(env, chatId, "Игрок не найден. Отправьте Telegram ID, точный @username или <code>skip</code>.");
      return true;
    }
    const playerName = await playerDisplayNameById(targetId, env);
    await updateStaffWorkflow(user.id, { step: "description", data: { targetId, playerName } }, env);
    await sendTelegramMessage(env, chatId, `Игрок найден: <b>${escapeHtml(playerName)}</b>.\n\nТеперь опишите проблему одним сообщением.`);
    return true;
  }
  if (workflow.step === "description") {
    const description = text.slice(0, 2000).trim();
    if (description.length < 5) {
      await sendTelegramMessage(env, chatId, "Описание слишком короткое. Добавьте детали проблемы.");
      return true;
    }
    await ensureStaffOperationsSchema(env);
    const now = Math.floor(Date.now() / 1000);
    const result = await env.DB.prepare(
      `INSERT INTO support_tickets (
         created_by, created_by_name, player_telegram_id, player_name,
         category, description, status, created_at, updated_at
       ) VALUES (?, ?, ?, ?, ?, ?, 'new', ?, ?)`
    ).bind(
      String(user.id), telegramDisplayName(user), String(data.targetId || ""), String(data.playerName || ""),
      String(data.category || "other"), description, now, now
    ).run();
    let ticketId = Number(result?.meta?.last_row_id || 0);
    if (!ticketId) {
      const inserted = await env.DB.prepare(
        `SELECT id FROM support_tickets WHERE created_by = ? AND created_at = ? ORDER BY id DESC LIMIT 1`
      ).bind(String(user.id), now).first();
      ticketId = Number(inserted?.id || 0);
    }
    if (!ticketId) throw new ApiError(500, "Не удалось определить номер обращения.");
    await env.DB.batch([
      env.DB.prepare(`INSERT OR IGNORE INTO support_ticket_meta(ticket_id,source,subject,request_id,client_json,player_last_read_at,staff_last_read_at,last_player_message_at,last_staff_message_at,created_at,updated_at) VALUES(?,'staff','',NULL,'{}',0,?,0,?,?,?)`).bind(ticketId,now,now,now,now),
      env.DB.prepare(`INSERT OR IGNORE INTO support_messages(ticket_id,author_kind,author_telegram_id,author_name,message_text,request_id,client_json,created_at,telegram_delivered_at,telegram_error) VALUES(?,'staff',?,?,?,'legacy-initial','{}',?,0,'')`).bind(ticketId,String(user.id),telegramDisplayName(user),description,now),
      env.DB.prepare(`INSERT OR REPLACE INTO support_ticket_channels(ticket_id,channel,created_at,updated_at) VALUES(?,'staff',?,?)`).bind(ticketId,now,now)
    ]);
    await ensureSupportOperationsForTicket(env,ticketId,String(data.category || "other"),"","staff",now);
    await clearStaffWorkflow(user.id, env);
    await logStaffAction(env, user, access, "ticket_create", String(data.targetId || ""), "ticket", null, ticketId, {
      category: data.category,
      description: description.slice(0, 300)
    });
    const playerLine = data.targetId ? `\nИгрок: <b>${escapeHtml(data.playerName || data.targetId)}</b> · <code>${escapeHtml(data.targetId)}</code>` : "";
    const messageText = `<b>🎫 Новое обращение #${ticketId}</b>\n\nКатегория: <b>${escapeHtml(SUPPORT_TICKET_CATEGORIES[data.category] || data.category)}</b>${playerLine}\nСоздал: <b>${escapeHtml(telegramDisplayName(user))}</b>\n\n${escapeHtml(description)}`;
    await queueLeaderboardStaffNotification(env, `support-ticket-created:${ticketId}`, messageText);
    await sendTelegramMessage(env, chatId,
      `<b>Обращение #${ticketId} создано</b>${playerLine}\n\nКатегория: ${escapeHtml(SUPPORT_TICKET_CATEGORIES[data.category] || data.category)}\nСтатус: <b>новое</b>`,
      { inline_keyboard: [[{ text: "Открыть обращение", callback_data: `ticket_view:${ticketId}` }]] }
    );
    return true;
  }
  return true;
}

async function ticketAccess(chatId, user, env) {
  const access = await getTeamAccess(user, env);
  if (!access.authorized) {
    await sendTelegramMessage(env, chatId, access.reason === "expired" ? "Сессия истекла. Выполните <code>/staff</code>." : "Доступно только сотрудникам.");
    return null;
  }
  return access;
}

async function showTicketsList(chatId, user, mode, env) {
  const access = await ticketAccess(chatId, user, env);
  if (!access) return;
  await ensureStaffOperationsSchema(env);
  const normalizedMode = String(mode || "open").toLowerCase();
  const conditions = [];
  const binds = [];
  if (normalizedMode === "mine") { conditions.push("created_by = ?"); binds.push(String(user.id)); }
  else if (normalizedMode === "resolved") conditions.push("status IN ('resolved','rejected')");
  else if (normalizedMode !== "all") conditions.push("status IN ('new','working')");
  if (!access.owner && !access.permissions?.staff) {
    conditions.push("created_by = ?");
    binds.push(String(user.id));
  }
  const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
  const result = await env.DB.prepare(
    `SELECT id, created_by_name, player_telegram_id, player_name, category,
            description, status, assigned_to_name, created_at, updated_at
     FROM support_tickets ${where}
     ORDER BY CASE status WHEN 'new' THEN 0 WHEN 'working' THEN 1 ELSE 2 END,
              updated_at DESC LIMIT 20`
  ).bind(...binds).all();
  const rows = result.results || [];
  if (!rows.length) {
    await sendTelegramMessage(env, chatId, "Обращений по выбранному фильтру нет.");
    return;
  }
  const entries = rows.map((row) => {
    const player = row.player_telegram_id ? ` · ${row.player_name || row.player_telegram_id}` : "";
    return `#${Number(row.id)} · <b>${escapeHtml(ticketStatusLabel(row.status))}</b>\n${escapeHtml(SUPPORT_TICKET_CATEGORIES[row.category] || row.category)}${escapeHtml(player)}\n${escapeHtml(String(row.description || "").slice(0, 140))}${String(row.description || "").length > 140 ? "…" : ""}`;
  });
  const buttons = rows.slice(0, 10).map((row) => [{ text: `Открыть #${Number(row.id)}`, callback_data: `ticket_view:${Number(row.id)}` }]);
  await sendTelegramMessage(env, chatId, `<b>Обращения · ${rows.length}</b>\n\n${entries.join("\n\n")}`, { inline_keyboard: buttons });
}

async function showTicketDetails(chatId, user, ticketId, env) {
  const access = await ticketAccess(chatId, user, env);
  if (!access) return;
  await ensureStaffOperationsSchema(env);
  const row = await env.DB.prepare(`SELECT * FROM support_tickets WHERE id = ? LIMIT 1`).bind(Number(ticketId)).first();
  if (!row) {
    await sendTelegramMessage(env, chatId, "Обращение не найдено.");
    return;
  }
  if (!access.owner && !access.permissions?.staff && String(row.created_by) !== String(user.id)) {
    await sendTelegramMessage(env, chatId, "У вас нет доступа к этому обращению.");
    return;
  }
  const playerLine = row.player_telegram_id
    ? `Игрок: <b>${escapeHtml(row.player_name || row.player_telegram_id)}</b> · <code>${escapeHtml(row.player_telegram_id)}</code>\n`
    : "Игрок: не указан\n";
  const assignee = row.assigned_to_name || row.assigned_to || "не назначен";
  const keyboard = [];
  if (access.owner || access.permissions?.staff) {
    if (String(row.status) !== "working") keyboard.push([{ text: "🛠 В работу", callback_data: `ticket_status:${row.id}:working` }]);
    if (String(row.status) !== "resolved") keyboard.push([{ text: "✅ Решено", callback_data: `ticket_status:${row.id}:resolved` }]);
    if (String(row.status) !== "rejected") keyboard.push([{ text: "❌ Отклонить", callback_data: `ticket_status:${row.id}:rejected` }]);
  }
  keyboard.push([{ text: "📋 К списку", callback_data: "tickets_open" }]);
  await sendTelegramMessage(env, chatId,
    `<b>🎫 Обращение #${Number(row.id)}</b>\n\n` +
    `Категория: <b>${escapeHtml(SUPPORT_TICKET_CATEGORIES[row.category] || row.category)}</b>\n` +
    `Статус: <b>${escapeHtml(ticketStatusLabel(row.status))}</b>\n` +
    `${playerLine}` +
    `Создал: <b>${escapeHtml(row.created_by_name || row.created_by)}</b>\n` +
    `Ответственный: <b>${escapeHtml(assignee)}</b>\n` +
    `Создано: ${escapeHtml(formatUtcDate(row.created_at))}\n\n` +
    `<b>Описание</b>\n${escapeHtml(row.description)}${row.resolution ? `\n\n<b>Решение</b>\n${escapeHtml(row.resolution)}` : ""}`,
    { inline_keyboard: keyboard }
  );
}

async function updateTicketStatus(query, ticketId, status, env) {
  const chatId = query.message?.chat?.id;
  const access = await requireTeamPermission(chatId, query.from, "staff", env);
  if (!access) return;
  if (!["working", "resolved", "rejected"].includes(status)) {
    await answerCallback(env, query.id, "Некорректный статус.", true);
    return;
  }
  const row = await env.DB.prepare(`SELECT * FROM support_tickets WHERE id = ? LIMIT 1`).bind(Number(ticketId)).first();
  if (!row) {
    await answerCallback(env, query.id, "Обращение не найдено.", true);
    return;
  }
  const now = Math.floor(Date.now() / 1000);
  await env.DB.prepare(
    `UPDATE support_tickets SET status = ?, assigned_to = ?, assigned_to_name = ?,
     updated_at = ?, closed_at = CASE WHEN ? IN ('resolved','rejected') THEN ? ELSE 0 END
     WHERE id = ?`
  ).bind(status, String(query.from.id), telegramDisplayName(query.from), now, status, now, Number(ticketId)).run();
  await logStaffAction(env, query.from, access, "ticket_status", String(row.player_telegram_id || ""), "ticket", null, Number(ticketId), {
    ticketId: Number(ticketId), oldStatus: row.status, newStatus: status
  });
  if (String(row.created_by || "") && String(row.created_by) !== String(query.from.id)) {
    try {
      await sendTelegramMessage(env, String(row.created_by),
        `<b>Обращение #${Number(ticketId)} обновлено</b>

Статус: <b>${escapeHtml(ticketStatusLabel(status))}</b>
Ответственный: <b>${escapeHtml(telegramDisplayName(query.from))}</b>`
      );
    } catch (error) {
      console.error("Ticket creator notification failed", error);
    }
  }
  await answerCallback(env, query.id, `Статус: ${ticketStatusLabel(status)}.`);
  await showTicketDetails(chatId, query.from, Number(ticketId), env);
}

async function getSystemState(env, key) {
  const readState = () => env.DB.prepare(`SELECT state_value, updated_at FROM bot_system_state WHERE state_key = ? LIMIT 1`).bind(String(key)).first();
  let row;
  try {
    row = await readState();
  } catch (readError) {
    await ensureStaffOperationsSchema(env);
    row = await readState();
  }
  return row ? { value: String(row.state_value || ""), updatedAt: Number(row.updated_at || 0) } : null;
}

async function setSystemState(env, key, value) {
  const now = Math.floor(Date.now() / 1000);
  const writeState = () => env.DB.prepare(
    `INSERT INTO bot_system_state (state_key, state_value, updated_at) VALUES (?, ?, ?)
     ON CONFLICT(state_key) DO UPDATE SET state_value = excluded.state_value, updated_at = excluded.updated_at`
  ).bind(String(key), String(value ?? ""), now).run();
  try {
    await writeState();
  } catch (writeError) {
    await ensureStaffOperationsSchema(env);
    await writeState();
  }
}

async function deleteSystemState(env, key) {
  const deleteState = () => env.DB.prepare(`DELETE FROM bot_system_state WHERE state_key = ?`).bind(String(key)).run();
  try {
    await deleteState();
  } catch (deleteError) {
    await ensureStaffOperationsSchema(env);
    await deleteState();
  }
}

function moscowDateParts(nowMs = Date.now()) {
  const shifted = new Date(nowMs + 3 * 60 * 60 * 1000);
  return {
    year: shifted.getUTCFullYear(),
    month: shifted.getUTCMonth() + 1,
    day: shifted.getUTCDate(),
    hour: shifted.getUTCHours(),
    minute: shifted.getUTCMinutes()
  };
}

function moscowDateKey(nowMs = Date.now()) {
  const parts = moscowDateParts(nowMs);
  return `${parts.year}-${String(parts.month).padStart(2, "0")}-${String(parts.day).padStart(2, "0")}`;
}


let observabilitySchemaPromise = null;
async function ensureObservabilitySchema(env) {
  if (!observabilitySchemaPromise) {
    observabilitySchemaPromise = env.DB.batch([
      env.DB.prepare(ADMIN_OPERATIONAL_ISSUES_SCHEMA_SQL),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_admin_operational_issues_status ON admin_operational_issues(status, severity, updated_at DESC)`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_admin_operational_issues_source ON admin_operational_issues(source_type, source_id, updated_at DESC)`)
    ]).catch((error) => {
      observabilitySchemaPromise = null;
      throw error;
    });
  }
  await observabilitySchemaPromise;
}

function operationalSeverityIcon(severity) {
  return severity === "critical" ? "🔴" : severity === "high" ? "🟠" : severity === "warning" ? "🟡" : "🔵";
}

function operationalSeverityLabel(severity) {
  return severity === "critical" ? "Критично" : severity === "high" ? "Высокий" : severity === "warning" ? "Предупреждение" : "Информация";
}

function operationalIssueStatusLabel(status, snoozedUntil = 0) {
  if (status === "acknowledged") return "Принято в работу";
  if (status === "snoozed") return snoozedUntil > 0 ? `Отложено до ${formatUtcDate(snoozedUntil)}` : "Отложено";
  if (status === "resolved") return "Решено";
  return "Открыто";
}

async function upsertOperationalIssue(env, issue, now) {
  const fingerprint = String(issue.fingerprint || "").slice(0, 180);
  if (!fingerprint) return null;
  const existing = await env.DB.prepare(`SELECT * FROM admin_operational_issues WHERE fingerprint = ? LIMIT 1`).bind(fingerprint).first();
  const detailsJson = JSON.stringify(issue.details || {});
  if (!existing) {
    const result = await env.DB.prepare(
      `INSERT INTO admin_operational_issues
       (fingerprint, issue_type, severity, title, details_json, source_type, source_id, status,
        first_seen_at, last_seen_at, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'open', ?, ?, ?, ?)`
    ).bind(
      fingerprint, String(issue.issueType || "system"), String(issue.severity || "warning"),
      String(issue.title || "Проблема").slice(0, 180), detailsJson,
      String(issue.sourceType || "system"), String(issue.sourceId || ""), now, now, now, now
    ).run();
    const id = Number(result.meta?.last_row_id || 0);
    if (["high", "critical"].includes(String(issue.severity || ""))) {
      try {
        await notifySubscribedStaff(env, "bot_errors", `${operationalSeverityIcon(issue.severity)} <b>${escapeHtml(issue.title)}</b>\n\nОткройте раздел «Проблемы» в админ-панели.`);
      } catch (error) {
        console.error("Operational issue notification failed", error);
      }
    }
    return { id, created: true };
  }
  let nextStatus = String(existing.status || "open");
  const snoozedUntil = Number(existing.snoozed_until || 0);
  if ((nextStatus === "resolved" || nextStatus === "snoozed") && snoozedUntil <= now) nextStatus = "open";
  await env.DB.prepare(
    `UPDATE admin_operational_issues
     SET issue_type = ?, severity = ?, title = ?, details_json = ?, source_type = ?, source_id = ?,
         status = ?, last_seen_at = ?, resolved_at = CASE WHEN ? = 'resolved' THEN resolved_at ELSE 0 END,
         updated_at = ?
     WHERE id = ?`
  ).bind(
    String(issue.issueType || "system"), String(issue.severity || "warning"),
    String(issue.title || "Проблема").slice(0, 180), detailsJson,
    String(issue.sourceType || "system"), String(issue.sourceId || ""), nextStatus, now, nextStatus, now, Number(existing.id)
  ).run();
  return { id: Number(existing.id), created: false, reopened: nextStatus === "open" && String(existing.status) !== "open" };
}

const OPERATIONAL_PROBLEMS_SYNC_TTL_SECONDS = 90;
let operationalProblemsSyncMemory = { updatedAt: 0, promise: null };

async function operationalProblemsSyncAge(env) {
  const now = Math.floor(Date.now()/1000);
  if (operationalProblemsSyncMemory.updatedAt) return Math.max(0,now-operationalProblemsSyncMemory.updatedAt);
  const state = await getSystemState(env,"ops:problems:last_sync");
  operationalProblemsSyncMemory.updatedAt = Number(state?.value || state?.updatedAt || 0);
  return operationalProblemsSyncMemory.updatedAt ? Math.max(0,now-operationalProblemsSyncMemory.updatedAt) : 999999;
}

async function ensureOperationalProblemsFresh(env, options = {}) {
  const force = Boolean(options.force);
  const age = await operationalProblemsSyncAge(env);
  if (!force && age < OPERATIONAL_PROBLEMS_SYNC_TTL_SECONDS) return { skipped:true,age };
  if (operationalProblemsSyncMemory.promise) return operationalProblemsSyncMemory.promise;
  operationalProblemsSyncMemory.promise = (async()=>{
    const issues = await syncOperationalProblems(env, options);
    const now = Math.floor(Date.now()/1000);
    operationalProblemsSyncMemory.updatedAt = now;
    await setSystemState(env,"ops:problems:last_sync",String(now));
    return { skipped:false,issues };
  })().finally(()=>{operationalProblemsSyncMemory.promise=null;});
  return operationalProblemsSyncMemory.promise;
}

async function syncOperationalProblems(env, options = {}) {
  await ensureStaffOperationsSchema(env);
  await ensureSafeControlCenterSchema(env);
  await ensureLiveOpsAdminSchema(env);
  await ensureOperationsSecuritySchema(env);
  await ensureObservabilitySchema(env);
  const now = Math.floor(Date.now() / 1000);
  const issues = [];
  const add = (issue) => issues.push(issue);

  if (options.checkCron !== false) {
    const heartbeat = await getSystemState(env, "cron:last_success");
    const cronAge = heartbeat?.updatedAt ? now - heartbeat.updatedAt : 0;
    if (!heartbeat || cronAge > 300) {
      add({
        fingerprint: "cron:stale", issueType: "cron", severity: cronAge > 900 || !heartbeat ? "critical" : "high",
        title: !heartbeat ? "Cron ещё не подтверждал успешный запуск" : `Cron не завершался ${Math.max(1, Math.floor(cronAge / 60))} мин.`,
        details: { lastSuccessAt: heartbeat?.updatedAt || 0, ageSeconds: cronAge }, sourceType: "cron", sourceId: "staff_operations"
      });
    }
  }

  if (options.checkWebhook !== false) {
    try {
      const info = await telegramApi(env, "getWebhookInfo", {});
      const expected = expectedTelegramWebhookUrl(env);
      const actual = String(info?.url || "");
      const missingRequiredUpdates = telegramWebhookMissingRequiredUpdates(info);
      if (!actual || actual !== expected || missingRequiredUpdates || info?.last_error_message) {
        const title = missingRequiredUpdates
          ? "Telegram webhook не принимает кнопки админ-панели"
          : info?.last_error_message
            ? "Telegram webhook сообщает об ошибке"
            : "Telegram webhook настроен неверно";
        add({
          fingerprint: "telegram:webhook", issueType: "webhook", severity: missingRequiredUpdates || info?.last_error_message ? "high" : "warning",
          title,
          details: { expected, actual, pending: Number(info?.pending_update_count || 0), allowedUpdates: telegramWebhookAllowedUpdates(info), error: String(info?.last_error_message || "") },
          sourceType: "telegram", sourceId: "webhook"
        });
      }
    } catch (error) {
      add({
        fingerprint: "telegram:webhook", issueType: "webhook", severity: isTransientTelegramApiError(error) ? "warning" : "high",
        title: isTransientTelegramApiError(error) ? "Telegram API временно не ответил на проверку webhook" : "Не удалось проверить Telegram webhook",
        details: { error: String(error?.message || error).slice(0, 300) }, sourceType: "telegram", sourceId: "webhook"
      });
    }
  }

  try {
    const queue = await env.DB.prepare(
      `SELECT
         SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END) AS failed_count,
         SUM(CASE WHEN status IN ('pending','delivering') AND created_at <= ? THEN 1 ELSE 0 END) AS overdue_count,
         MIN(CASE WHEN status IN ('pending','delivering') THEN created_at ELSE NULL END) AS oldest_at
       FROM reward_delivery_queue`
    ).bind(now - 15 * 60).first();
    const failed = Number(queue?.failed_count || 0);
    const overdue = Number(queue?.overdue_count || 0);
    if (failed || overdue) {
      add({
        fingerprint: "rewards:delivery_queue", issueType: "reward_queue", severity: failed ? "critical" : "high",
        title: failed ? `Ошибок выдачи наград: ${failed}` : `Наград ожидают более 15 минут: ${overdue}`,
        details: { failed, overdue, oldestAt: Number(queue?.oldest_at || 0) }, sourceType: "reward_queue", sourceId: "delivery"
      });
    }
  } catch (error) {
    add({ fingerprint: "rewards:delivery_queue_check", issueType: "reward_queue", severity: "warning", title: "Не удалось проверить очередь наград", details: { error: String(error?.message || error).slice(0, 300) }, sourceType: "reward_queue", sourceId: "check" });
  }

  try {
    const stockRows = await readShopStockRows(env);
    for (const productId of ["zefir", "americano", "cappuccino"]) {
      const availability = shopStockAvailabilityFromRows(stockRows, "prize", productId);
      if (availability.limited && availability.remaining <= BOT_LOW_STOCK_THRESHOLD) {
        add({
          fingerprint: `stock:${productId}`, issueType: "stock", severity: availability.remaining <= 0 ? "critical" : "warning",
          title: availability.remaining <= 0 ? `${PRODUCTS[productId]?.title || productId} закончился` : `${PRODUCTS[productId]?.title || productId}: осталось ${availability.remaining}`,
          details: { productId, remaining: availability.remaining }, sourceType: "shop_stock", sourceId: productId
        });
      }
    }
  } catch (error) {
    add({ fingerprint: "stock:check", issueType: "stock", severity: "warning", title: "Не удалось проверить физические остатки", details: { error: String(error?.message || error).slice(0, 300) }, sourceType: "shop_stock", sourceId: "check" });
  }

  try {
    const season = await ensureSeason(env);
    const rewardType = String(season?.reward_type || "");
    const rewardAmount = Number(season?.reward_amount || 0);
    const rewardItemId = String(season?.reward_item_id || "");
    if (!rewardType || (rewardAmount <= 0 && !rewardItemId)) {
      add({
        fingerprint: `season:${season?.id || "current"}:reward`, issueType: "season", severity: "critical",
        title: "У текущего сезона не настроена награда", details: { seasonId: season?.id || "", title: season?.title || "", rewardType, rewardAmount, rewardItemId },
        sourceType: "season", sourceId: String(season?.id || "current")
      });
    }
    const endsAt = Number(season?.ends_at || 0);
    if (String(season?.status) === "active" && endsAt > now && endsAt - now <= 2 * 3600) {
      add({
        fingerprint: `season:${season.id}:ending`, issueType: "season", severity: "warning",
        title: `Сезон завершится менее чем через ${Math.max(1, Math.ceil((endsAt - now) / 60))} мин.`,
        details: { seasonId: season.id, endsAt }, sourceType: "season", sourceId: String(season.id)
      });
    }
  } catch (error) {
    add({ fingerprint: "season:check", issueType: "season", severity: "high", title: "Не удалось проверить текущий сезон", details: { error: String(error?.message || error).slice(0, 300) }, sourceType: "season", sourceId: "current" });
  }

  try {
    const integrity = await env.DB.prepare(`SELECT status, result_json, created_at FROM integrity_check_runs ORDER BY id DESC LIMIT 1`).first();
    if (!integrity) {
      add({ fingerprint: "integrity:missing", issueType: "integrity", severity: "warning", title: "Проверка целостности ещё не запускалась", details: {}, sourceType: "integrity", sourceId: "latest" });
    } else if (!/^(?:ok|passed|success)$/i.test(String(integrity.status || ""))) {
      const report = safeJson(integrity.result_json, {});
      const failedChecks = Array.isArray(report?.checks)
        ? report.checks
            .filter((item) => String(item?.level || "") === "error")
            .map((item) => String(item?.text || "").slice(0, 220))
            .filter((text) => !isNonCriticalIntegrityDiagnostic(text))
            .slice(0, 8)
        : [];
      // Старые сборки могли записать успешную проверку изображения как error,
      // а превышение диагностического subrequest-лимита — как критическую ошибку.
      // Такие записи не должны держать центр проблем в красном состоянии.
      if (failedChecks.length > 0) {
        add({
          fingerprint: "integrity:failed", issueType: "integrity", severity: "high",
          title: "Последняя проверка целостности завершилась с проблемами",
          details: {
            status: integrity.status,
            createdAt: Number(integrity.created_at || 0),
            errors: failedChecks.length,
            warnings: Number(report?.warnings || 0),
            failedChecks
          },
          sourceType: "integrity", sourceId: "latest"
        });
      }
    }
  } catch {}

  try {
    const oldTickets = await env.DB.prepare(`SELECT COUNT(*) AS count, MIN(created_at) AS oldest_at FROM support_tickets WHERE status IN ('new','working') AND created_at <= ?`).bind(now - 24 * 3600).first();
    if (Number(oldTickets?.count || 0) > 0) {
      add({ fingerprint: "tickets:old", issueType: "tickets", severity: "warning", title: `Обращений без решения более суток: ${Number(oldTickets.count)}`, details: { count: Number(oldTickets.count), oldestAt: Number(oldTickets.oldest_at || 0) }, sourceType: "tickets", sourceId: "old" });
    }
  } catch {}

  try {
    const fraud = await env.DB.prepare(`SELECT COUNT(*) AS count FROM fraud_alerts WHERE status IN ('open','reviewing') AND severity IN ('critical','high')`).first();
    if (Number(fraud?.count || 0) > 0) {
      add({ fingerprint: "fraud:high", issueType: "fraud", severity: "high", title: `Подозрительных результатов высокого приоритета: ${Number(fraud.count)}`, details: { count: Number(fraud.count) }, sourceType: "fraud", sourceId: "high" });
    }
  } catch {}

  try {
    const failedBroadcasts = await env.DB.prepare(`SELECT COUNT(*) AS count FROM bot_broadcast_deliveries WHERE status = 'failed' AND attempted_at >= ?`).bind(now - 3600).first();
    if (Number(failedBroadcasts?.count || 0) > 0) {
      add({ fingerprint: "broadcast:failed_hour", issueType: "broadcast", severity: "warning", title: `Ошибок рассылки за час: ${Number(failedBroadcasts.count)}`, details: { count: Number(failedBroadcasts.count) }, sourceType: "broadcast", sourceId: "last_hour" });
    }
  } catch {}

  try {
    const promos = (await env.DB.prepare(`SELECT code, redemption_count, max_redemptions FROM promo_codes WHERE enabled = 1 AND max_redemptions > 0 AND redemption_count * 100 >= max_redemptions * 90 ORDER BY redemption_count * 1.0 / max_redemptions DESC LIMIT 5`).all()).results || [];
    for (const promo of promos) {
      add({ fingerprint: `promo:${promo.code}:limit`, issueType: "promo", severity: Number(promo.redemption_count) >= Number(promo.max_redemptions) ? "high" : "warning", title: `Промокод ${promo.code} использован на ${Math.min(100, Math.floor(Number(promo.redemption_count) * 100 / Math.max(1, Number(promo.max_redemptions))))}%`, details: { code: promo.code, used: Number(promo.redemption_count), limit: Number(promo.max_redemptions) }, sourceType: "promo", sourceId: String(promo.code) });
    }
  } catch {}

  const seen = new Set();
  for (const issue of issues) {
    seen.add(String(issue.fingerprint));
    await upsertOperationalIssue(env, issue, now);
  }
  const activeRows = (await env.DB.prepare(`SELECT id, fingerprint FROM admin_operational_issues WHERE status != 'resolved'`).all()).results || [];
  for (const row of activeRows) {
    if (seen.has(String(row.fingerprint))) continue;
    await env.DB.prepare(`UPDATE admin_operational_issues SET status = 'resolved', resolved_at = ?, resolved_by = 'system', resolved_by_name = 'Система', snoozed_until = 0, updated_at = ? WHERE id = ?`).bind(now, now, Number(row.id)).run();
  }
  return issues;
}

async function buildAdminOverview(env, options = {}) {
  if (options.syncProblems !== false) await syncOperationalProblems(env, { checkWebhook: true });
  const startAt = moscowDayStartUnix();
  const now = Math.floor(Date.now() / 1000);
  const runtime = options?.runtime || {};
  const perfPrefix = String(options?.perfPrefix || "").trim();
  const phase = (label, task) => {
    if (!perfPrefix) return Promise.resolve().then(task);
    const startedAt = Date.now();
    return Promise.resolve().then(task).then((value) => {
      sampleAdminPerformancePhase(env, runtime, `${perfPrefix}:${label}`, startedAt, true);
      return value;
    }, (error) => {
      sampleAdminPerformancePhase(env, runtime, `${perfPrefix}:${label}`, startedAt, false, error?.message || error);
      throw error;
    });
  };
  const [activePlayers, newPlayers, runs, casesLevel, casesGranted, shopOps, queue, tickets, issues, errors, season, heartbeat] = await Promise.all([
    phase("active_players_d1", () => env.DB.prepare(`SELECT COUNT(DISTINCT telegram_id) AS count FROM leaderboard_runs WHERE created_at >= ?`).bind(startAt).first()),
    phase("new_players_d1", () => env.DB.prepare(`SELECT COUNT(*) AS count FROM admin_profile_state WHERE created_at >= ?`).bind(startAt).first()),
    phase("runs_d1", () => env.DB.prepare(`SELECT COUNT(*) AS total, SUM(CASE WHEN accepted = 1 THEN 1 ELSE 0 END) AS accepted FROM leaderboard_runs WHERE created_at >= ?`).bind(startAt).first()),
    phase("level_cases_d1", () => env.DB.prepare(`SELECT COUNT(*) AS count FROM level_case_openings WHERE opened_at >= ?`).bind(startAt).first()),
    phase("granted_cases_d1", () => env.DB.prepare(`SELECT COUNT(*) AS count FROM granted_cases WHERE opened_at >= ?`).bind(startAt).first()),
    phase("shop_ops_d1", () => env.DB.prepare(`SELECT COUNT(*) AS count FROM shop_stock_consumptions WHERE created_at >= ?`).bind(startAt).first()),
    phase("reward_queue_d1", () => env.DB.prepare(`SELECT SUM(CASE WHEN status IN ('pending','delivering') THEN 1 ELSE 0 END) AS pending, SUM(CASE WHEN status = 'failed' THEN 1 ELSE 0 END) AS failed FROM reward_delivery_queue`).first()),
    phase("tickets_d1", () => env.DB.prepare(`SELECT COUNT(*) AS count FROM support_tickets WHERE status IN ('new','working')`).first()),
    phase("issues_d1", () => env.DB.prepare(`SELECT COUNT(*) AS count, SUM(CASE WHEN severity IN ('critical','high') THEN 1 ELSE 0 END) AS urgent FROM admin_operational_issues WHERE status != 'resolved' AND (status != 'snoozed' OR snoozed_until <= ?)`).bind(now).first()),
    phase("errors_d1", () => env.DB.prepare(`SELECT COUNT(*) AS count FROM staff_action_log WHERE success = 0 AND created_at >= ?`).bind(now - 3600).first()),
    phase("season_d1", () => ensureSeason(env)),
    phase("heartbeat_d1", () => getSystemState(env, "cron:last_success"))
  ]);
  const cronAge = heartbeat?.updatedAt ? now - heartbeat.updatedAt : 0;
  const urgent = Number(issues?.urgent || 0);
  const issueCount = Number(issues?.count || 0);
  const healthIcon = urgent > 0 ? "🔴" : issueCount > 0 ? "🟡" : "🟢";
  return {
    healthIcon,
    issueCount,
    urgent,
    cronText: !heartbeat ? "нет данных" : cronAge <= 180 ? `${cronAge} сек. назад` : `${Math.max(1, Math.floor(cronAge / 60))} мин. назад`,
    seasonTitle: String(season?.title || "не настроен"),
    seasonStatus: seasonStatusLabel(season?.status || "scheduled"),
    activePlayers: Number(activePlayers?.count || 0),
    newPlayers: Number(newPlayers?.count || 0),
    runs: Number(runs?.total || 0),
    acceptedRuns: Number(runs?.accepted || 0),
    cases: Number(casesLevel?.count || 0) + Number(casesGranted?.count || 0),
    shopOps: Number(shopOps?.count || 0),
    queuePending: Number(queue?.pending || 0),
    queueFailed: Number(queue?.failed || 0),
    tickets: Number(tickets?.count || 0),
    errors: Number(errors?.count || 0)
  };
}

function operationalIssueActionButton(row) {
  const source = String(row?.source_type || "");
  if (source === "reward_queue") return { text: "📬 Открыть очередь", callback_data: "safe_queue" };
  if (source === "shop_stock") return { text: "📦 Открыть остатки", callback_data: "stock_refresh" };
  if (source === "tickets") return { text: "🎫 Открыть обращения", callback_data: "tickets_open" };
  if (source === "fraud") return { text: "🛡 Открыть антифрод", callback_data: "adm_fraud" };
  if (source === "integrity") return { text: "🔎 Проверить игру", callback_data: "safe_check" };
  if (source === "promo") return { text: "🎟 Открыть промокоды", callback_data: "v57_promos" };
  if (source === "season") return { text: "🏆 Открыть рейтинг", callback_data: "season_refresh" };
  if (source === "broadcast") return { text: "📣 Открыть кампании", callback_data: "adm_campaigns" };
  return { text: "🩺 Открыть систему", callback_data: "status_refresh" };
}

function operationalIssueDetailsText(row) {
  const details = parseJsonObject(row?.details_json, {});
  const lines = [];
  for (const [key, value] of Object.entries(details)) {
    if (value == null || value === "" || value === 0 || (Array.isArray(value) && value.length === 0)) continue;
    const label = ({ lastSuccessAt: "Последний успех", ageSeconds: "Возраст, сек.", expected: "Ожидаемый URL", actual: "Текущий URL", pending: "Очередь Telegram", error: "Ошибка", failed: "Ошибок", errors: "Критических ошибок", warnings: "Предупреждений", failedChecks: "Что не прошло проверку", createdAt: "Проверка выполнена", overdue: "Просрочено", oldestAt: "Самая старая запись", remaining: "Осталось", productId: "Товар", seasonId: "Сезон", endsAt: "Завершение", count: "Количество", code: "Код", used: "Использовано", limit: "Лимит" })[key] || key;
    if (Array.isArray(value)) {
      lines.push(`• <b>${escapeHtml(label)}</b>:`);
      for (const item of value.slice(0, 8)) lines.push(`  — ${escapeHtml(String(item))}`);
      continue;
    }
    const formatted = /At$/.test(key) && Number(value) > 1000000000 ? formatUtcDate(Number(value)) : String(value);
    lines.push(`• ${escapeHtml(label)}: <b>${escapeHtml(formatted)}</b>`);
  }
  return lines.length ? lines.join("\n") : "Подробности отсутствуют.";
}

async function showOperationalProblemsDashboard(chatId, user, env, resolved = false, runtime = {}) {
  const access = await requireTeamPermission(chatId, user, "staff", env);
  if (!access) return;
  await ensureObservabilitySchema(env);
  let refreshing = false;
  if (!resolved) {
    const age = await operationalProblemsSyncAge(env);
    if (age >= OPERATIONAL_PROBLEMS_SYNC_TTL_SECONDS) {
      const refreshTask = ensureOperationalProblemsFresh(env,{checkWebhook:true});
      if (runWorkerBackground(runtime,refreshTask,"operational problems refresh")) refreshing = true;
      else await refreshTask;
    }
  }
  const now = Math.floor(Date.now() / 1000);
  const where = resolved ? `status = 'resolved'` : `status != 'resolved' AND (status != 'snoozed' OR snoozed_until <= ${now})`;
  const rows = (await env.DB.prepare(
    `SELECT * FROM admin_operational_issues WHERE ${where}
     ORDER BY CASE severity WHEN 'critical' THEN 1 WHEN 'high' THEN 2 WHEN 'warning' THEN 3 ELSE 4 END, updated_at DESC LIMIT 30`
  ).all()).results || [];
  const critical = rows.filter((row) => row.severity === "critical").length;
  const high = rows.filter((row) => row.severity === "high").length;
  const warning = rows.filter((row) => row.severity === "warning").length;
  const header = resolved
    ? `<b>✅ Решённые проблемы</b>\n\nПоследние решённые записи: <b>${rows.length}</b>`
    : `<b>🚨 Центр проблем</b>\n\nКритичных: <b>${critical}</b> · высоких: <b>${high}</b> · предупреждений: <b>${warning}</b>`;
  const keyboard = rows.slice(0, 15).map((row) => [{ text: `${operationalSeverityIcon(row.severity)} #${row.id} ${String(row.title || "Проблема").slice(0, 40)}`, callback_data: `ops_issue:${row.id}` }]);
  keyboard.push([{ text: "🔄 Обновить", callback_data: resolved ? "ops_problems_resolved" : "ops_problems" }, { text: resolved ? "🚨 Открытые" : "✅ Решённые", callback_data: resolved ? "ops_problems" : "ops_problems_resolved" }]);
  const refreshNote = refreshing ? "\n\n<i>Свежая проверка системы выполняется в фоне. Повторное обновление покажет новые данные.</i>" : "";
  await sendTelegramMessage(env, chatId, `${header}\n\n${rows.length ? "Выберите проблему для подробностей." : resolved ? "Решённых проблем пока нет." : "✅ Активных проблем не обнаружено."}${refreshNote}`, { inline_keyboard: keyboard });
}

async function showOperationalIssueDetails(chatId, user, issueId, env) {
  const access = await requireTeamPermission(chatId, user, "staff", env);
  if (!access) return;
  await ensureObservabilitySchema(env);
  const row = await env.DB.prepare(`SELECT * FROM admin_operational_issues WHERE id = ? LIMIT 1`).bind(Number(issueId)).first();
  if (!row) {
    await sendTelegramMessage(env, chatId, "Проблема не найдена или уже удалена.");
    return;
  }
  const keyboard = [];
  if (row.status !== "resolved") {
    keyboard.push([
      { text: "👀 Принять", callback_data: `ops_issue_ack:${row.id}` },
      { text: "🙋 Назначить мне", callback_data: `ops_issue_assign:${row.id}` }
    ]);
    keyboard.push([
      { text: "⏰ Отложить на час", callback_data: `ops_issue_snooze:${row.id}` },
      { text: "✅ Решено", callback_data: `ops_issue_resolve:${row.id}` }
    ]);
  }
  keyboard.push([operationalIssueActionButton(row)]);
  keyboard.push([{ text: "⬅️ К проблемам", callback_data: row.status === "resolved" ? "ops_problems_resolved" : "ops_problems" }]);
  await sendTelegramMessage(env, chatId,
    `${operationalSeverityIcon(row.severity)} <b>${escapeHtml(row.title)}</b>\n\n` +
    `Приоритет: <b>${escapeHtml(operationalSeverityLabel(row.severity))}</b>\n` +
    `Статус: <b>${escapeHtml(operationalIssueStatusLabel(row.status, Number(row.snoozed_until || 0)))}</b>\n` +
    `Источник: <code>${escapeHtml(String(row.source_type || "system"))}:${escapeHtml(String(row.source_id || ""))}</code>\n` +
    `Обнаружено: <b>${escapeHtml(formatUtcDate(row.first_seen_at))}</b>\n` +
    `Последнее подтверждение: <b>${escapeHtml(formatUtcDate(row.last_seen_at))}</b>\n` +
    `${row.assigned_to_name ? `Ответственный: <b>${escapeHtml(row.assigned_to_name)}</b>\n` : ""}\n` +
    `<b>Подробности</b>\n${operationalIssueDetailsText(row)}`,
    { inline_keyboard: keyboard }
  );
}

async function updateOperationalIssue(query, issueId, action, env) {
  const chatId = query.message?.chat?.id;
  const access = await requireTeamPermission(chatId, query.from, "staff", env);
  if (!access) return;
  await ensureObservabilitySchema(env);
  const row = await env.DB.prepare(`SELECT * FROM admin_operational_issues WHERE id = ? LIMIT 1`).bind(Number(issueId)).first();
  if (!row) {
    await answerCallback(env, query.id, "Проблема не найдена.", true);
    return;
  }
  const now = Math.floor(Date.now() / 1000);
  if (action === "ack") {
    await env.DB.prepare(`UPDATE admin_operational_issues SET status = 'acknowledged', assigned_to = CASE WHEN assigned_to = '' THEN ? ELSE assigned_to END, assigned_to_name = CASE WHEN assigned_to_name = '' THEN ? ELSE assigned_to_name END, updated_at = ? WHERE id = ?`).bind(String(query.from.id), telegramDisplayName(query.from), now, Number(issueId)).run();
  } else if (action === "assign") {
    await env.DB.prepare(`UPDATE admin_operational_issues SET status = CASE WHEN status = 'open' THEN 'acknowledged' ELSE status END, assigned_to = ?, assigned_to_name = ?, updated_at = ? WHERE id = ?`).bind(String(query.from.id), telegramDisplayName(query.from), now, Number(issueId)).run();
  } else if (action === "snooze") {
    await env.DB.prepare(`UPDATE admin_operational_issues SET status = 'snoozed', snoozed_until = ?, assigned_to = ?, assigned_to_name = ?, updated_at = ? WHERE id = ?`).bind(now + 3600, String(query.from.id), telegramDisplayName(query.from), now, Number(issueId)).run();
  } else if (action === "resolve") {
    await env.DB.prepare(`UPDATE admin_operational_issues SET status = 'resolved', resolved_at = ?, resolved_by = ?, resolved_by_name = ?, snoozed_until = ?, updated_at = ? WHERE id = ?`).bind(now, String(query.from.id), telegramDisplayName(query.from), now + 3600, now, Number(issueId)).run();
  }
  await logStaffAction(env, query.from, access, `operational_issue_${action}`, null, "operational_issue", Number(row.id), Number(row.id), { title: row.title, sourceType: row.source_type, sourceId: row.source_id });
  await answerCallback(env, query.id, action === "resolve" ? "Проблема отмечена решённой." : action === "snooze" ? "Проблема отложена на час." : action === "assign" ? "Проблема назначена вам." : "Проблема принята в работу.");
  await showOperationalIssueDetails(chatId, query.from, Number(issueId), env);
}

async function startUniversalAdminSearch(chatId, user, env) {
  const access = await requireTeamPermission(chatId, user, "staff", env);
  if (!access) return;
  await setStaffWorkflow(user.id, chatId, "universal_search", "input", {}, env);
  const serviceRole = !access.owner && ["cashier", "cook"].includes(normalizeTeamRole(access.role));
  const prompt = serviceRole
    ? `<b>🔎 Поиск активного заказа</b>

Отправьте полный код физической награды. Поиск по игрокам, именам и истории заказов для вашей роли отключён.`
    : `<b>🔎 Универсальный поиск</b>

Отправьте одним сообщением:
` +
      `• Telegram ID или <code>@username</code>;
• физический код награды;
• промокод;
• номер обращения;
• ID события;
• название скина, рамки, следа или аватарки.

Поиск не изменяет данные.`;
  await sendTelegramMessage(env, chatId, prompt, { inline_keyboard: [[{ text: "Отмена", callback_data: "ops_cancel" }]] });
}

async function executeUniversalAdminSearch(chatId, user, rawQuery, env) {
  const access = await requireTeamPermission(chatId, user, "staff", env);
  if (!access) return;
  await ensureSafeControlCenterSchema(env);
  await ensureOperationsSecuritySchema(env);
  const query = String(rawQuery || "").trim().slice(0, 100);
  if (query.length < 2) {
    await sendTelegramMessage(env, chatId, "Введите минимум два символа для поиска.");
    return;
  }
  const lower = query.toLowerCase();
  const like = `%${lower.replace(/[%_]/g, "")}%`;
  const digits = query.replace(/\D/g, "");
  const telegramIdLike = digits.length >= 4 ? `%${digits}%` : "__NO_MATCH__";
  const results = [];
  const seen = new Set();
  const add = (result) => {
    const key = `${result.type}:${result.id}`;
    if (seen.has(key) || results.length >= 20) return;
    seen.add(key);
    results.push(result);
  };

  if (access.owner || access.permissions?.viewPlayers) {
    const resolved = await resolvePlayerTelegramId(query, env);
    if (resolved && await playerProfileExists(resolved, env)) add({ type: "player", id: resolved, title: await playerDisplayNameById(resolved, env), subtitle: `Telegram ID ${resolved}` });
    const players = (await env.DB.prepare(
      `SELECT telegram_id, display_name, username, best_score FROM leaderboard_all_time
       WHERE LOWER(display_name) LIKE ? OR LOWER(username) LIKE ? OR telegram_id LIKE ?
       ORDER BY updated_at DESC LIMIT 8`
    ).bind(like, like, telegramIdLike).all()).results || [];
    for (const row of players) add({ type: "player", id: String(row.telegram_id), title: String(row.display_name || (row.username ? `@${row.username}` : `Игрок ${row.telegram_id}`)), subtitle: `Рекорд ${Number(row.best_score || 0)}` });
  }

  if (access.owner || access.permissions?.redeemPhysical) {
    const compact = compactCode(query);
    const elevatedOrderAccess = canViewOrderHistory(access);
    const rewards = elevatedOrderAccess
      ? (await env.DB.prepare(
          `SELECT code, code_compact, product_name, owner_name, status FROM reward_codes
           WHERE code_compact = ? OR LOWER(code) LIKE ? OR LOWER(request_id) LIKE ? OR LOWER(owner_name) LIKE ?
           ORDER BY created_at DESC LIMIT 6`
        ).bind(compact, like, like, like).all()).results || []
      : compact.length >= 4
        ? (await env.DB.prepare(
            `SELECT code, code_compact, product_name, owner_name, status FROM reward_codes
             WHERE code_compact = ? AND status = 'active' LIMIT 1`
          ).bind(compact).all()).results || []
        : [];
    for (const row of rewards) add({ type: "reward", id: String(row.code_compact), title: String(row.product_name || row.code), subtitle: `${row.code} · ${row.status} · ${row.owner_name || "без имени"}` });
  }

  if (access.owner || access.permissions?.managePromocodes) {
    const promos = (await env.DB.prepare(`SELECT code, title, enabled, redemption_count, max_redemptions FROM promo_codes WHERE LOWER(code) LIKE ? OR LOWER(title) LIKE ? ORDER BY updated_at DESC LIMIT 6`).bind(like, like).all()).results || [];
    for (const row of promos) add({ type: "promo", id: String(row.code), title: String(row.title || row.code), subtitle: `${row.code} · ${Number(row.enabled) ? "включён" : "выключен"} · ${Number(row.redemption_count || 0)}/${Number(row.max_redemptions || 0) || "∞"}` });
  }

  if (access.owner || access.permissions?.manageSeasons) {
    const events = (await env.DB.prepare(`SELECT event_id, title, status, starts_at, ends_at FROM liveops_events WHERE LOWER(event_id) LIKE ? OR LOWER(title) LIKE ? ORDER BY updated_at DESC LIMIT 6`).bind(like, like).all()).results || [];
    for (const row of events) add({ type: "event", id: String(row.event_id), title: String(row.title || row.event_id), subtitle: `${row.status} · ${formatUtcDate(row.starts_at)} — ${formatUtcDate(row.ends_at)}` });
  }

  const ticketId = Number(query.replace(/^#/, ""));
  if (Number.isInteger(ticketId) && ticketId > 0) {
    const ticket = await env.DB.prepare(`SELECT id, category, status, player_name, player_telegram_id FROM support_tickets WHERE id = ? LIMIT 1`).bind(ticketId).first();
    if (ticket) add({ type: "ticket", id: String(ticket.id), title: `Обращение #${ticket.id}`, subtitle: `${ticket.category} · ${ticket.status} · ${ticket.player_name || ticket.player_telegram_id || "без игрока"}` });
  }

  if (access.owner || access.permissions?.manageCases || access.permissions?.viewContentAnalytics) {
    const catalogs = [
      ["skin", SKINS], ["avatar", CASE_AVATARS], ["frame", CASE_FRAMES], ["trail", CASE_TRAILS]
    ];
    for (const [kind, catalog] of catalogs) {
      for (const [id, item] of Object.entries(catalog || {})) {
        if (String(id).toLowerCase().includes(lower) || String(item?.title || "").toLowerCase().includes(lower)) {
          add({ type: "content", id: `${kind}:${id}`, title: String(item?.title || id), subtitle: `${kind} · ${item?.rarity || "common"}` });
        }
      }
    }
  }

  await clearStaffWorkflow(user.id, env);
  if (!results.length) {
    await sendTelegramMessage(env, chatId, `<b>🔎 Поиск</b>\n\nПо запросу <code>${escapeHtml(query)}</code> ничего не найдено.`, { inline_keyboard: [[{ text: "🔎 Новый поиск", callback_data: "ops_search" }]] });
    return;
  }
  const typeIcon = { player: "👤", reward: "☕", promo: "🎟", event: "🗓", ticket: "🎫", content: "🎨" };
  const lines = results.map((row, index) => `${index + 1}. ${typeIcon[row.type] || "•"} <b>${escapeHtml(row.title)}</b>\n${escapeHtml(row.subtitle || row.id)}`).join("\n\n");
  const keyboard = results.slice(0, 15).map((row) => {
    if (row.type === "player") return [{ text: `👤 ${String(row.title).slice(0, 32)}`, callback_data: `player_refresh:${row.id}` }];
    if (row.type === "reward") return [{ text: `☕ ${String(row.title).slice(0, 32)}`, callback_data: `ops_search_reward:${row.id}` }];
    if (row.type === "promo") return [{ text: `🎟 ${row.id}`, callback_data: `v57_promo_stats:${row.id}` }];
    if (row.type === "ticket") return [{ text: `🎫 Обращение #${row.id}`, callback_data: `ticket_view:${row.id}` }];
    if (row.type === "event") return [{ text: `🗓 ${String(row.title).slice(0, 32)}`, callback_data: "safe_events" }];
    return [{ text: `🎨 ${String(row.title).slice(0, 32)}`, callback_data: "v57_content" }];
  });
  keyboard.push([{ text: "🔎 Новый поиск", callback_data: "ops_search" }, { text: "🚨 Проблемы", callback_data: "ops_problems" }]);
  await logStaffAction(env, user, access, "universal_search", null, "search", null, null, { query, results: results.length });
  await sendTelegramMessage(env, chatId, `<b>🔎 Результаты поиска</b>\n\nЗапрос: <code>${escapeHtml(query)}</code>\nНайдено: <b>${results.length}</b>\n\n${lines}`, { inline_keyboard: keyboard });
}

async function handleUniversalAdminSearchMessage(message, workflow, env) {
  const query = String(message.text || "").trim();
  if (!query || query.startsWith("/")) {
    await sendTelegramMessage(env, message.chat.id, "Отправьте поисковый запрос обычным сообщением или отмените действие командой <code>/cancel</code>.");
    return true;
  }
  await executeUniversalAdminSearch(message.chat.id, message.from, query, env);
  return true;
}

async function showOperationsStatus(chatId, user, env) {
  const access = await getTeamAccess(user, env);
  if (!access.authorized) {
    await sendTelegramMessage(env, chatId, access.reason === "expired" ? "Сессия истекла. Выполните <code>/staff</code>." : "Доступно только сотрудникам.");
    return;
  }
  let dbStatus = "🟢 доступна";
  let webhookStatus = "🟢 работает";
  let webhookDetails = "";
  let seasonStatus = "не проверен";
  let lowStock = [];
  try { await env.DB.prepare(`SELECT 1 AS ok`).first(); } catch (error) { dbStatus = `🔴 ошибка: ${String(error?.message || error).slice(0, 100)}`; }
  try {
    const info = await telegramApi(env, "getWebhookInfo", {});
    const expected = expectedTelegramWebhookUrl(env);
    const actual = String(info?.url || "");
    const missingRequiredUpdates = telegramWebhookMissingRequiredUpdates(info);
    if (!actual || actual !== expected || missingRequiredUpdates || info?.last_error_message) webhookStatus = "🟡 требует внимания";
    webhookDetails = `URL: ${actual === expected ? "верный" : "не совпадает"} · кнопки: ${missingRequiredUpdates ? "не подключены" : "подключены"} · очередь: ${Number(info?.pending_update_count || 0)}${info?.last_error_message ? ` · ${String(info.last_error_message).slice(0, 120)}` : ""}`;
  } catch (error) {
    webhookStatus = isTransientTelegramApiError(error)
      ? `🟡 Telegram API временно не ответил: ${String(error?.message || error).slice(0, 80)}`
      : `🔴 ошибка: ${String(error?.message || error).slice(0, 100)}`;
  }
  try {
    const season = await ensureSeason(env);
    seasonStatus = `${seasonStatusLabel(season.status)} · до ${formatUtcDate(season.ends_at)}`;
  } catch (error) {
    seasonStatus = `ошибка: ${String(error?.message || error).slice(0, 100)}`;
  }
  try {
    const rows = await readShopStockRows(env);
    lowStock = ["zefir", "americano", "cappuccino"].map((id) => ({ id, availability: shopStockAvailabilityFromRows(rows, "prize", id) }))
      .filter((item) => item.availability.limited && item.availability.remaining <= BOT_LOW_STOCK_THRESHOLD);
  } catch {}
  const heartbeat = await getSystemState(env, "cron:last_success");
  const now = Math.floor(Date.now() / 1000);
  const heartbeatAge = heartbeat?.updatedAt ? now - heartbeat.updatedAt : 0;
  const cronStatus = !heartbeat
    ? "🟡 данных ещё нет"
    : heartbeatAge <= 180 ? `🟢 ${heartbeatAge} сек. назад` : `🔴 ${Math.floor(heartbeatAge / 60)} мин. назад`;
  const stockText = lowStock.length
    ? lowStock.map((item) => `${PRODUCTS[item.id]?.title || item.id}: ${item.availability.remaining}`).join(", ")
    : "остатки выше порога";
  await sendTelegramMessage(env, chatId,
    `<b>🩺 Состояние системы</b>\n\n` +
    `Игра/Worker: 🟢 отвечает · <b>${escapeHtml(GAME_VERSION)}</b>\n` +
    `База данных: ${escapeHtml(dbStatus)}\n` +
    `Telegram webhook: ${escapeHtml(webhookStatus)}\n` +
    `${escapeHtml(webhookDetails)}\n` +
    `Последний Cron: ${escapeHtml(cronStatus)}\n` +
    `Рейтинг: <b>${escapeHtml(seasonStatus)}</b>\n` +
    `Остатки: <b>${escapeHtml(stockText)}</b>`,
    { inline_keyboard: [[
      { text: "🔄 Обновить", callback_data: "status_refresh" },
      { text: "🚨 Проблемы", callback_data: "ops_problems" },
      { text: "📦 Остатки", callback_data: "stock_refresh" }
    ]] }
  );
}

async function notifyOperationalIssue(env, issueKey, messageHtml) {
  const stateKey = `ops-alert:${issueKey}`;
  const existing = await getSystemState(env, stateKey);
  if (existing?.value === "active") return;
  await queueLeaderboardStaffNotification(env, `ops-alert:${issueKey}:${Math.floor(Date.now() / 1000)}`, messageHtml);
  await setSystemState(env, stateKey, "active");
}

async function clearOperationalIssue(env, issueKey) {
  const stateKey = `ops-alert:${issueKey}`;
  const existing = await getSystemState(env, stateKey);
  if (existing?.value === "active") {
    await queueLeaderboardStaffNotification(env, `ops-recovered:${issueKey}:${Math.floor(Date.now() / 1000)}`, `✅ <b>Система восстановлена</b>\n\nПроблема «${escapeHtml(issueKey)}» больше не обнаруживается.`);
    await deleteSystemState(env, stateKey);
  }
}

async function checkLowStockAlerts(env) {
  const rows = await readShopStockRows(env);
  for (const productId of ["zefir", "americano", "cappuccino"]) {
    const availability = shopStockAvailabilityFromRows(rows, "prize", productId);
    const stateKey = `low-stock:${productId}`;
    if (!availability.limited || availability.remaining > BOT_LOW_STOCK_THRESHOLD) {
      await deleteSystemState(env, stateKey);
      continue;
    }
    const existing = await getSystemState(env, stateKey);
    const alertLevel = availability.remaining <= 0 ? "empty" : "low";
    if (existing?.value === alertLevel) continue;
    const title = PRODUCTS[productId]?.title || productId;
    const status = availability.remaining <= 0 ? "Товар закончился." : `Осталось ${availability.remaining} шт.`;
    await queueLeaderboardStaffNotification(env,
      `low-stock:${productId}:${alertLevel}:${Math.floor(Date.now() / 1000)}`,
      `⚠️ <b>${alertLevel === "empty" ? "Товар закончился" : "Низкий остаток"}</b>\n\nТовар: <b>${escapeHtml(title)}</b>\n${escapeHtml(status)}\n\nПополните остаток командой <code>/shop_stock prize ${escapeHtml(productId)} КОЛИЧЕСТВО</code>.`
    );
    await setSystemState(env, stateKey, alertLevel);
  }
}

async function buildDailyStaffReport(env, startAt, dateKey) {
  const [players, runs, openedLevel, openedGranted, rewardsCreated, rewardsUsed, casePurchases, skinPurchases, physicalPurchases, staffActive, staffActors, actionErrors, notificationErrors, broadcastErrors, tickets] = await Promise.all([
    env.DB.prepare(`SELECT COUNT(*) AS count FROM admin_profile_state WHERE created_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS total, SUM(CASE WHEN accepted = 1 THEN 1 ELSE 0 END) AS accepted FROM leaderboard_runs WHERE created_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM level_case_openings WHERE opened_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM granted_cases WHERE opened_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM reward_codes WHERE created_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM reward_codes WHERE status = 'used' AND redeemed_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM granted_cases WHERE granted_by = 'shop' AND created_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM shop_stock_consumptions WHERE category = 'skins' AND created_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM reward_codes WHERE created_at >= ? AND request_id NOT LIKE 'case_reward_%'`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM staff_users WHERE active = 1`).first(),
    env.DB.prepare(`SELECT COUNT(DISTINCT actor_telegram_id) AS count FROM staff_action_log WHERE created_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM staff_action_log WHERE created_at >= ? AND success = 0`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM leaderboard_staff_notifications WHERE status = 'failed' AND updated_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM bot_broadcast_deliveries WHERE status = 'failed' AND attempted_at >= ?`).bind(startAt).first(),
    env.DB.prepare(`SELECT
       SUM(CASE WHEN created_at >= ? THEN 1 ELSE 0 END) AS created,
       SUM(CASE WHEN status IN ('new','working') THEN 1 ELSE 0 END) AS open_count
     FROM support_tickets`).bind(startAt).first()
  ]);
  const stockRows = await readShopStockRows(env);
  const stockLine = ["zefir", "americano", "cappuccino"].map((id) => {
    const availability = shopStockAvailabilityFromRows(stockRows, "prize", id);
    return `${PRODUCTS[id]?.title || id}: ${availability.limited ? availability.remaining : "∞"}`;
  }).join(" · ");
  const openedCases = Number(openedLevel?.count || 0) + Number(openedGranted?.count || 0);
  const purchases = Number(casePurchases?.count || 0) + Number(skinPurchases?.count || 0) + Number(physicalPurchases?.count || 0);
  const errors = Number(actionErrors?.count || 0) + Number(notificationErrors?.count || 0) + Number(broadcastErrors?.count || 0);
  return `<b>📊 Итоги за ${escapeHtml(dateKey)}</b>\n\n` +
    `Новых игроков: <b>${Number(players?.count || 0)}</b>\n` +
    `Забегов: <b>${Number(runs?.total || 0)}</b> · зачтено ${Number(runs?.accepted || 0)}\n` +
    `Открыто кейсов: <b>${openedCases}</b>\n` +
    `Покупок кейсов/скинов/призов: <b>${purchases}</b>\n` +
    `Создано физических наград: <b>${Number(rewardsCreated?.count || 0)}</b>\n` +
    `Погашено кодов: <b>${Number(rewardsUsed?.count || 0)}</b>\n` +
    `Активных сотрудников: <b>${Number(staffActive?.count || 0)}</b> · работали сегодня ${Number(staffActors?.count || 0)}\n` +
    `Новых обращений: <b>${Number(tickets?.created || 0)}</b> · открыто сейчас ${Number(tickets?.open_count || 0)}\n` +
    `Ошибок и недоставок: <b>${errors}</b>\n\n` +
    `<b>Остатки</b>\n${escapeHtml(stockLine)}`;
}

async function showDailyStaffReport(chatId, user, env) {
  const access = await requireTeamPermission(chatId, user, "staff", env);
  if (!access) return;
  await ensureStaffOperationsSchema(env);
  const dateKey = moscowDateKey();
  const report = await buildDailyStaffReport(env, moscowDayStartUnix(), dateKey);
  await logStaffAction(env, user, access, "view_daily_report", null, "system", null, null, { dateKey });
  await sendTelegramMessage(env, chatId, report, {
    inline_keyboard: [[
      { text: "🔄 Обновить", callback_data: "daily_report_refresh" },
      { text: "🩺 Статус", callback_data: "status_refresh" }
    ]]
  });
}

async function maybeSendDailyStaffReport(env) {
  const parts = moscowDateParts();
  const configuredHour = Math.floor(Number(env.BOT_DAILY_REPORT_HOUR));
  const hour = Number.isFinite(configuredHour) && configuredHour >= 0 && configuredHour <= 23
    ? configuredHour
    : BOT_DAILY_REPORT_HOUR;
  if (parts.hour < hour) return { sent: false, reason: "too_early" };
  const dateKey = moscowDateKey();
  const stateKey = `daily-report:${dateKey}`;
  const existing = await getSystemState(env, stateKey);
  if (existing) return { sent: false, reason: "already_sent" };
  const report = await buildDailyStaffReport(env, moscowDayStartUnix(), dateKey);
  await queueLeaderboardStaffNotification(env, stateKey, report);
  await setSystemState(env, stateKey, "sent");
  return { sent: true };
}

function isPlayerNameResetValue(value) {
  return /^(?:off|reset|сброс|сбросить|удалить)$/i.test(String(value || "").trim());
}

async function protectedPlayerControlTarget(telegramId, env) {
  const id = String(telegramId || "");
  if (isBotAdminUser({ id }, env)) return true;
  try {
    const row = await env.DB.prepare(
      `SELECT active FROM staff_users WHERE telegram_id = ? LIMIT 1`
    ).bind(id).first();
    return Number(row?.active || 0) === 1;
  } catch {
    return false;
  }
}

async function beginPlayerNameWorkflow(query, telegramId, env) {
  const chatId = query.message?.chat?.id;
  const access = await requirePlayerControlAccess(chatId, query.from, env);
  if (!access) {
    await answerCallback(env, query.id, "Только владелец или администратор.", true);
    return;
  }
  if (!(await playerProfileExists(telegramId, env))) {
    await answerCallback(env, query.id, "Игрок не найден.", true);
    return;
  }
  const [control, playerName] = await Promise.all([
    getPlayerAdminControl(telegramId, env),
    playerDisplayNameById(telegramId, env)
  ]);
  await setStaffWorkflow(query.from.id, chatId, "player_name", "input", {
    targetId: String(telegramId),
    playerName,
    previousName: control.customName
  }, env);
  await answerCallback(env, query.id, "Введите новое имя.");
  await sendTelegramMessage(env, chatId,
    `<b>Изменение имени игрока</b>\n\nИгрок: <b>${escapeHtml(playerName)}</b> · <code>${escapeHtml(String(telegramId))}</code>\n` +
    `Текущее административное имя: <b>${escapeHtml(control.customName || "не задано")}</b>\n\n` +
    `Отправьте новое имя длиной от 2 до 40 символов. Чтобы вернуть имя из Telegram, отправьте <code>off</code>.`,
    { inline_keyboard: [[{ text: "Отмена", callback_data: "ops_cancel" }]] }
  );
}

async function handlePlayerNameWorkflowMessage(message, workflow, env) {
  const chatId = message.chat.id;
  const access = await requirePlayerControlAccess(chatId, message.from, env);
  if (!access) {
    await clearStaffWorkflow(message.from.id, env);
    return true;
  }
  const targetId = String(workflow.data?.targetId || "");
  if (!targetId || !(await playerProfileExists(targetId, env))) {
    await clearStaffWorkflow(message.from.id, env);
    await sendTelegramMessage(env, chatId, "Игрок больше не найден. Действие отменено.");
    return true;
  }
  const raw = String(message.text || "").trim();
  const customName = isPlayerNameResetValue(raw) ? "" : raw.replace(/\s+/g, " ");
  if (customName && (customName.length < 2 || customName.length > 40)) {
    await sendTelegramMessage(env, chatId, "Имя должно содержать от 2 до 40 символов. Для сброса отправьте <code>off</code>.");
    return true;
  }
  const before = await getPlayerAdminControl(targetId, env);
  const after = await savePlayerAdminControl(targetId, { customName }, message.from.id, env);
  await logStaffAction(env, message.from, access, "player_name_change", targetId, "player", null, null, {
    oldName: before.customName,
    newName: after.customName
  });
  await clearStaffWorkflow(message.from.id, env);
  await sendTelegramMessage(env, chatId,
    after.customName
      ? `✅ Имя игрока изменено на <b>${escapeHtml(after.customName)}</b>. Оно будет использоваться в игре и рейтинге после следующей синхронизации.`
      : "✅ Административное имя сброшено. После следующей синхронизации снова будет использоваться имя из Telegram."
  );
  await showPlayerProfile(chatId, message.from, targetId, env);
  return true;
}

async function beginPlayerBlockWorkflow(query, telegramId, env) {
  const chatId = query.message?.chat?.id;
  const access = await requireSecurityPermission(chatId, query.from, "blockPlayers", env);
  if (!access) {
    await answerCallback(env, query.id, "Только владелец или администратор.", true);
    return;
  }
  if (!access.owner && !access.permissions?.blockPlayers) {
    await answerCallback(env, query.id, "Нет права блокировать игроков.", true);
    return;
  }
  if (!(await playerProfileExists(telegramId, env))) {
    await answerCallback(env, query.id, "Игрок не найден.", true);
    return;
  }
  if (await protectedPlayerControlTarget(telegramId, env)) {
    await answerCallback(env, query.id, "Нельзя заблокировать владельца или активного сотрудника.", true);
    return;
  }
  const control = await getPlayerAdminControl(telegramId, env);
  if (control.blocked) {
    await answerCallback(env, query.id, "Игрок уже заблокирован.", true);
    return;
  }
  const playerName = await playerDisplayNameById(telegramId, env);
  await setStaffWorkflow(query.from.id, chatId, "player_block", "duration", {
    targetId: String(telegramId),
    playerName
  }, env);
  await answerCallback(env, query.id, "Выберите срок блокировки.");
  await sendTelegramMessage(env, chatId,
    `<b>Серьёзная блокировка игрока</b>\n\nИгрок: <b>${escapeHtml(playerName)}</b> · <code>${escapeHtml(String(telegramId))}</code>\n\nВыберите срок. После этого бот запросит причину и покажет финальное подтверждение. Код вводить не требуется.`,
    { inline_keyboard: [
      [{ text: "24 часа", callback_data: `ban_duration:${telegramId}:1d` }, { text: "7 дней", callback_data: `ban_duration:${telegramId}:7d` }],
      [{ text: "30 дней", callback_data: `ban_duration:${telegramId}:30d` }, { text: "Навсегда", callback_data: `ban_duration:${telegramId}:permanent` }],
      [{ text: "Отмена", callback_data: "ops_cancel" }]
    ] }
  );
}

async function handlePlayerBlockWorkflowMessage(message, workflow, env) {
  const chatId = message.chat.id;
  const access = await requireSecurityPermission(chatId, message.from, "blockPlayers", env);
  if (!access) {
    await clearStaffWorkflow(message.from.id, env);
    if (access) await sendTelegramMessage(env, chatId, "Нет права блокировать игроков.");
    return true;
  }
  if (workflow.step !== "reason") {
    await sendTelegramMessage(env, chatId, "Сначала выберите срок блокировки кнопкой в предыдущем сообщении или отмените действие командой <code>/cancel</code>.");
    return true;
  }
  const targetId = String(workflow.data?.targetId || "");
  const reason = String(message.text || "").trim().replace(/\s+/g, " ");
  if (reason.length < 3 || reason.length > 300) {
    await sendTelegramMessage(env, chatId, "Причина должна содержать от 3 до 300 символов.");
    return true;
  }
  if (!targetId || !(await playerProfileExists(targetId, env)) || await protectedPlayerControlTarget(targetId, env)) {
    await clearStaffWorkflow(message.from.id, env);
    await sendTelegramMessage(env, chatId, "Игрок не найден либо его нельзя блокировать. Действие отменено.");
    return true;
  }
  const blockType = String(workflow.data?.blockType || "permanent") === "temporary" ? "temporary" : "permanent";
  const blockedUntil = blockType === "temporary" ? Number(workflow.data?.blockedUntil || 0) : 0;
  if (blockType === "temporary" && blockedUntil <= Math.floor(Date.now() / 1000)) {
    await clearStaffWorkflow(message.from.id, env);
    await sendTelegramMessage(env, chatId, "Срок блокировки устарел. Начните действие заново.");
    return true;
  }
  await updateStaffWorkflow(message.from.id, { step: "confirm", data: { reason, blockType, blockedUntil } }, env);
  const playerName = String(workflow.data?.playerName || await playerDisplayNameById(targetId, env));
  await sendTelegramMessage(env, chatId,
    `<b>Подтвердите блокировку</b>\n\nИгрок: <b>${escapeHtml(playerName)}</b> · <code>${escapeHtml(targetId)}</code>\n` +
    `Срок: <b>${escapeHtml(banDurationLabel(blockType, blockedUntil))}</b>\n` +
    `Причина: <b>${escapeHtml(reason)}</b>\n\nПосле подтверждения доступ будет ограничен, а весь игровой прогресс будет необратимо удалён: баланс, рекорд, кейсы, коллекция, задания, рейтинг и все покупки сезонного пропуска. Разблокировка или окончание временной блокировки не восстановят старые данные. Действие попадёт в журнал модерации.`,
    { inline_keyboard: [[
      { text: "⛔ Заблокировать", callback_data: `player_block_confirm:${targetId}` },
      { text: "Отмена", callback_data: "ops_cancel" }
    ]] }
  );
  return true;
}


function blockedPlayerResetPlan() {
  return {
    points: true,
    treats: true,
    coffee: true,
    personalRecord: true,
    xp: true,
    cases: true,
    collection: true,
    statistics: true,
    ownedSkins: true,
    equippedSkin: true
  };
}

async function blockPlayerAndWipeProgress(env, options) {
  await ensureLiveOpsAdminSchema(env);
  await ensureV78Schema(env);
  await ensureV77Schema(env);
  await ensureSafeControlCenterSchema(env);
  await ensureSeasonPassSchema(env);

  const telegramId = String(options.telegramId || "");
  if (!/^\d{4,20}$/.test(telegramId)) throw new Error("Некорректный Telegram ID игрока.");
  const now = Math.floor(Date.now() / 1000);
  const actorId = String(options.actor?.id || options.updatedBy || "system");
  const actorName = String(options.actorName || telegramDisplayName(options.actor || {})).trim().slice(0, 100);
  const reason = String(options.reason || "").trim().slice(0, 300);
  const blockType = String(options.blockType || "permanent") === "temporary" ? "temporary" : "permanent";
  const blockedUntil = blockType === "temporary" ? Math.max(0, Math.floor(Number(options.blockedUntil) || 0)) : 0;
  const before = options.before || await getPlayerAdminControl(telegramId, env);
  const resetId = `reset_ban_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
  const resetReason = `Блокировка: ${reason}`.slice(0, 300);
  const resetComponents = ["points", "treats", "coffee", "record", "xp", "cases", "collection"];
  const resetJson = JSON.stringify(blockedPlayerResetPlan());
  const campaignSkipReason = `Игрок заблокирован; прогресс сброшен ${resetId}`.slice(0, 500);
  const queueCancelReason = `Отменено при блокировке ${resetId}`.slice(0, 500);

  await env.DB.batch([
    env.DB.prepare(`INSERT OR IGNORE INTO admin_profile_state(
      telegram_id,wallet,best_score,treats,coffee,profile_xp,revision,created_at,updated_at,updated_by
    ) VALUES(?,0,0,0,0,0,1,?,?,?)`).bind(telegramId, now, now, actorId),
    env.DB.prepare(`INSERT OR IGNORE INTO case_player_state(telegram_id,created_at,updated_at) VALUES(?,?,?)`).bind(telegramId, now, now)
  ]);

  await env.DB.batch([
    env.DB.prepare(`INSERT INTO player_admin_controls(
      telegram_id,custom_name,blocked,block_reason,block_type,blocked_until,
      blocked_at,blocked_by_name,appeal_note,last_unblocked_at,last_unblocked_by,
      updated_at,updated_by
    ) VALUES(?,?,1,?,?,?,?,?,?,?,?,?,?)
    ON CONFLICT(telegram_id) DO UPDATE SET
      custom_name=excluded.custom_name,blocked=1,block_reason=excluded.block_reason,
      block_type=excluded.block_type,blocked_until=excluded.blocked_until,
      blocked_at=excluded.blocked_at,blocked_by_name=excluded.blocked_by_name,
      appeal_note=excluded.appeal_note,last_unblocked_at=excluded.last_unblocked_at,
      last_unblocked_by=excluded.last_unblocked_by,updated_at=excluded.updated_at,
      updated_by=excluded.updated_by`).bind(
        telegramId, String(before.customName || ""), reason, blockType, blockedUntil,
        now, actorName, String(before.appealNote || ""), Number(before.lastUnblockedAt || 0),
        String(before.lastUnblockedBy || ""), now, actorId
      ),
    env.DB.prepare(`UPDATE admin_profile_state SET
      wallet=0,best_score=0,treats=0,coffee=0,profile_xp=0,
      pending_wallet=0,pending_treats=0,pending_coffee=0,
      wallet_override=0,treats_override=0,coffee_override=0,
      best_score_override=0,profile_xp_override=0,
      revision=revision+1,updated_at=?,updated_by=?
      WHERE telegram_id=?`).bind(now, actorId, telegramId),
    env.DB.prepare(`UPDATE case_player_state SET
      boosters_points=0,boosters_treats=0,boosters_coffee=0,boosters_extra_json='{}',active_boosters_json='{}',
      active_booster_type='',active_booster_runs=0,
      owned_avatars_json='[]',active_avatar_id='',
      owned_frames_json='[]',active_frame_id='',
      owned_trails_json='[]',active_trail_id='',
      owned_music_json='["cafe_run"]',active_music_id='cafe_run',
      owned_specials_json='[]',owned_skins_json='[]',active_skin_id='',
      mythic_pity_counter=0,legendary_pity_counter=0,revision=revision+1,updated_at=?
      WHERE telegram_id=?`).bind(now, telegramId),
    env.DB.prepare(`DELETE FROM granted_cases WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM level_case_openings WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM case_booster_run_consumptions WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM leaderboard_entries WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM leaderboard_all_time WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM leaderboard_runs WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM leaderboard_rewards WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_claims WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_task_claims WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_task_notifications WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_run_xp WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_activity_runs WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_task_progress WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_entitlements WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_purchases WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_players WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM season_pass_purchase_guards WHERE instr(guard_id,?)>0`).bind(`:${telegramId}:`),
    env.DB.prepare(`DELETE FROM achievement_claims WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM achievement_showcase WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM achievement_showcase_preferences WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM achievement_unlocks WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM achievement_season_history WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM player_task_claims WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM player_task_series_claims WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`DELETE FROM tester_accounts WHERE telegram_id=?`).bind(telegramId),
    env.DB.prepare(`UPDATE reward_delivery_queue SET
      status='cancelled',last_error=?,updated_at=?,lease_token='',lease_until=0
      WHERE telegram_id=? AND status IN ('pending','failed','delivering')`).bind(queueCancelReason, now, telegramId),
    env.DB.prepare(`UPDATE reward_codes SET status='cancelled'
      WHERE owner_telegram_id=? AND status='active'`).bind(telegramId),
    env.DB.prepare(`UPDATE admin_campaign_recipients SET status='skipped',error_text=?,processed_at=?
      WHERE telegram_id=? AND status='pending'`).bind(campaignSkipReason, now, telegramId),
    env.DB.prepare(`INSERT INTO player_reset_directives(
      reset_id,scope,target_telegram_id,reset_json,reason,active,created_at,created_by
    ) VALUES(?,'one',?,?,?,1,?,?)`).bind(resetId, telegramId, resetJson, resetReason, now, actorId),
    env.DB.prepare(`INSERT INTO player_reset_history(
      reset_id,scope,target_telegram_id,components_json,reason,affected_count,
      notification_status,created_by,created_by_name,created_at
    ) VALUES(?,'one',?,?,?,1,'moderation_block',?,?,?)`).bind(
      resetId, telegramId, JSON.stringify(resetComponents), resetReason,
      actorId, actorName, now
    )
  ]);

  return {
    ...(await getPlayerAdminControl(telegramId, env)),
    resetId,
    resetComponents
  };
}

async function confirmPlayerBlock(query, telegramId, env) {
  const chatId = query.message?.chat?.id;
  const access = await requireSecurityPermission(chatId, query.from, "blockPlayers", env);
  if (!access) {
    await answerCallback(env, query.id, "Только владелец или администратор.", true);
    return;
  }
  if (!access.owner && !access.permissions?.blockPlayers) {
    await answerCallback(env, query.id, "Нет права блокировать игроков.", true);
    return;
  }
  const workflow = await getStaffWorkflow(query.from.id, env);
  const targetId = String(telegramId || "");
  if (!workflow || workflow.flow_type !== "player_block" || workflow.step !== "confirm" || String(workflow.data?.targetId || "") !== targetId) {
    await answerCallback(env, query.id, "Подтверждение устарело. Откройте карточку игрока заново.", true);
    return;
  }
  if (await protectedPlayerControlTarget(targetId, env)) {
    await clearStaffWorkflow(query.from.id, env);
    await answerCallback(env, query.id, "Нельзя заблокировать владельца или активного сотрудника.", true);
    return;
  }
  const reason = String(workflow.data?.reason || "").trim();
  const blockType = String(workflow.data?.blockType || "permanent") === "temporary" ? "temporary" : "permanent";
  const blockedUntil = blockType === "temporary" ? Number(workflow.data?.blockedUntil || 0) : 0;
  if (reason.length < 3 || (blockType === "temporary" && blockedUntil <= Math.floor(Date.now() / 1000))) {
    await answerCallback(env, query.id, "Данные блокировки устарели. Начните заново.", true);
    return;
  }
  const now = Math.floor(Date.now() / 1000);
  const before = await getPlayerAdminControl(targetId, env);
  let after;
  try {
    after = await blockPlayerAndWipeProgress(env, {
      telegramId: targetId,
      reason,
      blockType,
      blockedUntil,
      actor: query.from,
      before
    });
  } catch (error) {
    console.error("player block wipe failed", error);
    await answerCallback(env, query.id, "Блокировка не выполнена: не удалось полностью обнулить профиль.", true);
    await sendTelegramMessage(env, chatId, `<b>Блокировка отменена</b>\n\nНе удалось безопасно удалить весь прогресс игрока. Частичная блокировка не считается завершённой.\n\nОшибка: <code>${escapeHtml(String(error?.message || error).slice(0, 300))}</code>`);
    return;
  }
  await writeModerationHistory(env, targetId, "block", after, query.from, reason);
  await logStaffAction(env, query.from, access, "player_block", targetId, "player", before.blocked ? 1 : 0, 1, {
    reason: after.blockReason,
    blockType: after.blockType,
    blockedUntil: after.blockedUntil,
    progressReset: true,
    resetId: after.resetId,
    resetComponents: after.resetComponents
  });
  await notifyPlayerModeration(env, targetId,
    `⛔ <b>Доступ к игре ограничен</b>\n\nСрок: <b>${escapeHtml(banDurationLabel(after.blockType, after.blockedUntil))}</b>\nПричина: <b>${escapeHtml(after.blockReason)}</b>\n\nИгровой прогресс и покупки сезонного пропуска обнулены. Разблокировка не восстановит старые данные.\n\nПо вопросам обратитесь в поддержку игры.`
  );
  await notifySubscribedStaff(env, "player_blocks", `⛔ <b>Игрок заблокирован и обнулён</b>\n\nИгрок: <code>${escapeHtml(targetId)}</code>\nСрок: ${escapeHtml(banDurationLabel(after.blockType, after.blockedUntil))}\nПричина: ${escapeHtml(after.blockReason)}\nСотрудник: ${escapeHtml(telegramDisplayName(query.from))}\nСброс: <code>${escapeHtml(after.resetId)}</code>`);
  await clearStaffWorkflow(query.from.id, env);
  await answerCallback(env, query.id, "Игрок заблокирован и обнулён.");
  await sendTelegramMessage(env, chatId,
    `⛔ Игрок <code>${escapeHtml(targetId)}</code> заблокирован <b>${escapeHtml(banDurationLabel(after.blockType, after.blockedUntil))}</b>.\nПричина: <b>${escapeHtml(after.blockReason)}</b>\n\n✅ Полностью удалены баланс, рекорд, кейсы, коллекция, рейтинг, задания и сезонный пропуск, включая «Элитный» и «Элитный+».\nID сброса: <code>${escapeHtml(after.resetId)}</code>`
  );
  await showPlayerProfile(chatId, query.from, targetId, env);
}

async function beginPlayerUnblockWorkflow(query, telegramId, env) {
  const chatId = query.message?.chat?.id;
  const access = await requireSecurityPermission(chatId, query.from, "unblockPlayers", env);
  if (!access) {
    await answerCallback(env, query.id, "Только владелец или администратор.", true);
    return;
  }
  if (!access.owner && !access.permissions?.unblockPlayers) {
    await answerCallback(env, query.id, "Нет права разблокировать игроков.", true);
    return;
  }
  const control = await getPlayerAdminControl(telegramId, env);
  if (!control.blocked) {
    await answerCallback(env, query.id, "Игрок уже разблокирован.", true);
    return;
  }
  const playerName = await playerDisplayNameById(telegramId, env);
  await setStaffWorkflow(query.from.id, chatId, "player_unblock", "confirm", {
    targetId: String(telegramId),
    playerName,
    previousReason: control.blockReason,
    previousBlockType: control.blockType,
    previousBlockedUntil: control.blockedUntil
  }, env);
  await answerCallback(env, query.id, "Требуется подтверждение.");
  await sendTelegramMessage(env, chatId,
    `<b>Подтвердите разблокировку</b>\n\nИгрок: <b>${escapeHtml(playerName)}</b> · <code>${escapeHtml(String(telegramId))}</code>\n` +
    `Срок блокировки: <b>${escapeHtml(banDurationLabel(control.blockType, control.blockedUntil))}</b>\n` +
    `Причина: <b>${escapeHtml(control.blockReason || "не указана")}</b>\n\nПосле подтверждения доступ будет восстановлен сразу.`,
    { inline_keyboard: [[
      { text: "✅ Разблокировать", callback_data: `player_unblock_confirm:${telegramId}` },
      { text: "Отмена", callback_data: "ops_cancel" }
    ]] }
  );
}

async function confirmPlayerUnblock(query, telegramId, env) {
  const chatId = query.message?.chat?.id;
  const access = await requireSecurityPermission(chatId, query.from, "unblockPlayers", env);
  if (!access) {
    await answerCallback(env, query.id, "Только владелец или администратор.", true);
    return;
  }
  if (!access.owner && !access.permissions?.unblockPlayers) {
    await answerCallback(env, query.id, "Нет права разблокировать игроков.", true);
    return;
  }
  const workflow = await getStaffWorkflow(query.from.id, env);
  const targetId = String(telegramId || "");
  if (!workflow || workflow.flow_type !== "player_unblock" || workflow.step !== "confirm" || String(workflow.data?.targetId || "") !== targetId) {
    await answerCallback(env, query.id, "Подтверждение устарело. Откройте карточку игрока заново.", true);
    return;
  }
  const before = await getPlayerAdminControl(targetId, env);
  if (!before.blocked) {
    await clearStaffWorkflow(query.from.id, env);
    await answerCallback(env, query.id, "Игрок уже разблокирован.", true);
    return;
  }
  const now = Math.floor(Date.now() / 1000);
  const after = await savePlayerAdminControl(targetId, {
    blocked: false,
    blockReason: "",
    lastUnblockedAt: now,
    lastUnblockedBy: telegramDisplayName(query.from)
  }, query.from.id, env);
  await writeModerationHistory(env, targetId, "unblock", {
    blockType: before.blockType,
    blockReason: before.blockReason,
    blockedUntil: before.blockedUntil
  }, query.from, before.blockReason);
  await logStaffAction(env, query.from, access, "player_unblock", targetId, "player", 1, 0, {
    previousReason: before.blockReason,
    previousBlockType: before.blockType,
    previousBlockedUntil: before.blockedUntil
  });
  await notifyPlayerModeration(env, targetId, "✅ <b>Доступ к игре восстановлен</b>\n\nВы снова можете пользоваться игрой и участвовать в рейтинге.");
  await notifySubscribedStaff(env, "player_blocks", `✅ <b>Игрок разблокирован</b>\n\nИгрок: <code>${escapeHtml(targetId)}</code>\nСотрудник: ${escapeHtml(telegramDisplayName(query.from))}`);
  await clearStaffWorkflow(query.from.id, env);
  await answerCallback(env, query.id, "Игрок разблокирован.");
  await sendTelegramMessage(env, chatId, `✅ Игрок <code>${escapeHtml(targetId)}</code> разблокирован и снова может пользоваться игрой.`);
  await showPlayerProfile(chatId, query.from, targetId, env);
}

async function processStaffOperationsCron(env) {
  await ensureStaffOperationsSchema(env);
  await ensureLiveOpsAdminSchema(env);
  const now = Math.floor(Date.now() / 1000);
  await setSystemState(env, "cron:last_start", String(now));
  await env.DB.prepare(`DELETE FROM bot_staff_workflows WHERE expires_at <= ?`).bind(now).run();
  await expireAllTemporaryPlayerBans(env);
  await processPendingAdminCampaign(env);
  await processSafeControlCenterCron(env);
  await processV67Cron(env);
  await processV74PollCron(env);
  await processV77Cron(env);
  const fraudScanState = await getSystemState(env, "fraud:last_scan");
  const lastFraudScan = Number(fraudScanState?.value || 0);
  if (!lastFraudScan || now - lastFraudScan >= 3600) {
    await scanFraudAlerts(env);
    await setSystemState(env, "fraud:last_scan", String(now));
  }
  await checkLowStockAlerts(env);
  try { await syncOperationalProblems(env, { checkWebhook: true, checkCron: false }); } catch (error) { console.error("Operational problems sync failed", error); }
  await maybeSendDailyStaffReport(env);
  await setSystemState(env, "cron:last_success", String(now));
  try { const overview = await buildAdminOverview(env, { syncProblems: false }); await writeCachedAdminOverview(env, overview); } catch (error) { console.error("Admin overview cache refresh failed", error); }
}

async function handleActiveStaffWorkflowMessage(message, env) {
  const workflow = await getStaffWorkflow(message.from.id, env);
  if (!workflow) return false;
  if (String(workflow.chat_id) !== String(message.chat.id)) return false;
  const workflowAccess = await getTeamAccess(message.from, env);
  if (isLimitedAdministratorAccess(workflowAccess) && !LIMITED_ADMINISTRATOR_ALLOWED_WORKFLOWS.has(String(workflow.flow_type || ""))) {
    await clearStaffWorkflow(message.from.id, env);
    await sendTelegramMessage(env, message.chat.id, "Это действие больше недоступно роли <b>Администратор</b>. Откройте админ-панель и выберите разрешённый раздел.");
    return true;
  }
  if (workflow.flow_type === "grant_prefill") {
    await sendTelegramMessage(env, message.chat.id, "Выберите награду кнопкой в предыдущем сообщении или отмените действие командой <code>/cancel</code>.");
    return true;
  }
  if (workflow.flow_type === "grant") return handleGrantWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "redeem") return handleRedeemWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "ticket") return handleTicketWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "season_reward") return handleSeasonRewardWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "season_create") return handleLeaderboardSeasonCreateWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "safe_event") return handleSafeEventWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "compensation") return handleCompensationWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "player_name") return handlePlayerNameWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "player_block_select") return handleBlockSelectMessage(message, workflow, env);
  if (workflow.flow_type === "player_unblock_select") return handleUnblockSelectMessage(message, workflow, env);
  if (workflow.flow_type === "player_block") return handlePlayerBlockWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "campaign") return handleCampaignWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "promo_create") return handlePromoCodeWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "universal_search") return handleUniversalAdminSearchMessage(message, workflow, env);
  if (workflow.flow_type === "automation_create") return handleV67AutomationCreateMessage(message, workflow, env);
  if (workflow.flow_type === "automation_edit") return handleV74AutomationEditMessage(message, workflow, env);
  if (workflow.flow_type === "poll_create") return handleV74PollCreateMessage(message, workflow, env);
  if (workflow.flow_type === "poll_response_comment") return handleV75PollResponseMessage(message, workflow, env);
  if (workflow.flow_type === "v77_diag" || workflow.flow_type === "v77_series_create") return handleV77WorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "player_reset") return handlePlayerResetWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "shop_price_edit") return handleShopPriceEditWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "season_pass_numeric") return handleSeasonPassNumericWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "season_pass_task_create") return handleSeasonPassTaskCreateWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "season_pass_season_create") return handleSeasonPassSeasonCreateWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "release_plan") return handleV67ReleaseWorkflowMessage(message, workflow, env);
  if (workflow.flow_type === "staff_create") return handleStaffCreateWorkflowMessage(message, workflow, env);
  return false;
}

async function handleStaffOperationsCallback(query, env) {
  const data = String(query.data || "");
  const chatId = query.message?.chat?.id;
  if (!chatId) return false;


  if (data === "adm_team") {
    await answerCallback(env, query.id, "Сотрудники обновлены.");
    await showTeamManagement(chatId, query.from, env);
    return true;
  }
  if (data === "adm_staff_create") {
    await startStaffCreateWorkflow(query, env);
    return true;
  }
  if (data === "adm_staff_cancel") {
    await cancelStaffCreate(query, env);
    return true;
  }
  if (data === "adm_staff_create_back") {
    const access = await requireTeamPermission(chatId, query.from, "staff", env);
    if (!access) return true;
    const workflow = await getStaffWorkflow(query.from.id, env);
    if (!workflow || workflow.flow_type !== "staff_create" || !workflow.data?.targetId) {
      await answerCallback(env, query.id, "Создание уже завершено или истекло.", true);
      return true;
    }
    await updateStaffWorkflow(query.from.id, { step: "role", data: { role: "" } }, env);
    await answerCallback(env, query.id, "Выберите роль заново.");
    await showStaffCreateRoleStep(chatId, query.from, String(workflow.data.targetId), { displayName: workflow.data.displayName, username: workflow.data.username }, Boolean(workflow.data.reactivating), access, env);
    return true;
  }
  const createRole = data.match(/^adm_staff_create_role:(cashier|cook|administrator)$/);
  if (createRole) {
    await selectStaffCreateRole(query, createRole[1], env);
    return true;
  }
  if (data === "adm_staff_create_confirm") {
    await confirmStaffCreate(query, env);
    return true;
  }
  const staffCard = data.match(/^adm_staff_card:(\d{4,20})$/);
  if (staffCard) {
    await answerCallback(env, query.id, "Открываю сотрудника.");
    await showStaffMemberCard(chatId, query.from, staffCard[1], env);
    return true;
  }
  const staffRoleMenu = data.match(/^adm_staff_role_menu:(\d{4,20})$/);
  if (staffRoleMenu) {
    await showStaffRoleMenu(query, staffRoleMenu[1], env);
    return true;
  }
  const staffSetRole = data.match(/^adm_staff_set_role:(\d{4,20}):(cashier|cook|administrator)$/);
  if (staffSetRole) {
    await setStaffRoleFromButton(query, staffSetRole[1], staffSetRole[2], env);
    return true;
  }
  const staffToggle = data.match(/^adm_staff_toggle:(\d{4,20}):(on|off)$/);
  if (staffToggle) {
    await toggleStaffFromButton(query, staffToggle[1], staffToggle[2] === "on", env);
    return true;
  }
  const staffDelete = data.match(/^adm_staff_delete:(\d{4,20})$/);
  if (staffDelete) {
    await beginStaffProfileDeletion(query, staffDelete[1], env);
    return true;
  }
  const staffDeleteConfirm = data.match(/^adm_staff_delete_confirm:(\d{4,20})$/);
  if (staffDeleteConfirm) {
    await confirmStaffProfileDeletion(query, staffDeleteConfirm[1], env);
    return true;
  }
  const staffPermissions = data.match(/^adm_staff_permissions:(\d{4,20})$/);
  if (staffPermissions) {
    await answerCallback(env, query.id, "Открываю точные права.");
    await showGranularPermissions(chatId, query.from, staffPermissions[1], env);
    return true;
  }

  const playerNameEdit = data.match(/^player_name:(\d{4,20})$/);
  if (playerNameEdit) {
    await beginPlayerNameWorkflow(query, playerNameEdit[1], env);
    return true;
  }
  const playerBlock = data.match(/^player_block:(\d{4,20})$/);
  if (playerBlock) {
    await beginPlayerBlockWorkflow(query, playerBlock[1], env);
    return true;
  }
  const playerBlockConfirm = data.match(/^player_block_confirm:(\d{4,20})$/);
  if (playerBlockConfirm) {
    await confirmPlayerBlock(query, playerBlockConfirm[1], env);
    return true;
  }
  const playerUnblock = data.match(/^player_unblock:(\d{4,20})$/);
  if (playerUnblock) {
    await beginPlayerUnblockWorkflow(query, playerUnblock[1], env);
    return true;
  }
  const playerUnblockConfirm = data.match(/^player_unblock_confirm:(\d{4,20})$/);
  if (playerUnblockConfirm) {
    await confirmPlayerUnblock(query, playerUnblockConfirm[1], env);
    return true;
  }
  const playerGrant = data.match(/^player_grant:(\d{4,20})$/);
  if (playerGrant) {
    const access = await requireAnySecurityPermission(chatId, query.from, ["grantRewards", "grantLegendaryCases"], env);
    if (!access) { await answerCallback(env, query.id, "Недостаточно прав.", true); return true; }
    if (!(await playerProfileExists(playerGrant[1], env))) {
      await answerCallback(env, query.id, "Игрок не найден.", true);
      return true;
    }
    const playerName = await playerDisplayNameById(playerGrant[1], env);
    await setStaffWorkflow(query.from.id, chatId, "grant_prefill", "choose", { targetId: playerGrant[1], playerName }, env);
    await answerCallback(env, query.id, "Выберите награду.");
    await sendTelegramMessage(env, chatId,
      `<b>Выдача для игрока</b>

Игрок: <b>${escapeHtml(playerName)}</b> · <code>${escapeHtml(playerGrant[1])}</code>

Выберите награду.`,
      grantMainMarkup()
    );
    return true;
  }
  const playerAudit = data.match(/^player_audit:(\d{4,20})$/);
  if (playerAudit) {
    await answerCallback(env, query.id, "Открываю полную историю.");
    await showPlayerTimeline(chatId, query.from, playerAudit[1], env);
    return true;
  }
  if (data === "daily_report_refresh") {
    await answerCallback(env, query.id, "Сводка обновлена.");
    await showDailyStaffReport(chatId, query.from, env);
    return true;
  }

  if (data === "ops_cancel") {
    await clearStaffWorkflow(query.from.id, env);
    await answerCallback(env, query.id, "Действие отменено.");
    await sendTelegramMessage(env, chatId, "Текущее действие отменено.");
    return true;
  }
  if (data === "grant_home") {
    const accessStartedAt = Date.now();
    const access = await requireAnySecurityPermission(
      chatId,
      query.from,
      ["grantRewards", "grantLegendaryCases"],
      env,
      { runtime, perfPrefix: "grant_home:access" }
    );
    sampleAdminPerformancePhase(env, runtime, "grant_home:access", accessStartedAt, Boolean(access));
    if (!access) return true;

    const workflowStartedAt = Date.now();
    const callbackStartedAt = Date.now();
    const telegramStartedAt = Date.now();
    const workflowPromise = clearStaffWorkflow(query.from.id, env, { runtime, perfPrefix: "grant_home:workflow" }).then((value) => {
      sampleAdminPerformancePhase(env, runtime, "grant_home:workflow", workflowStartedAt, true);
      return value;
    }, (error) => {
      sampleAdminPerformancePhase(env, runtime, "grant_home:workflow", workflowStartedAt, false, error?.message || error);
      throw error;
    });
    const callbackPromise = answerCallback(env, query.id, "Выберите награду.").then((value) => {
      sampleAdminPerformancePhase(env, runtime, "grant_home:callback", callbackStartedAt, true);
      return value;
    }, (error) => {
      sampleAdminPerformancePhase(env, runtime, "grant_home:callback", callbackStartedAt, false, error?.message || error);
      throw error;
    });
    const telegramPromise = sendTelegramMessage(env, chatId, "<b>Выдача награды</b>\n\nВыберите тип награды.", grantMainMarkup()).then((value) => {
      sampleAdminPerformancePhase(env, runtime, "grant_home:telegram", telegramStartedAt, true);
      return value;
    }, (error) => {
      sampleAdminPerformancePhase(env, runtime, "grant_home:telegram", telegramStartedAt, false, error?.message || error);
      throw error;
    });

    // V3.3 Performance Candidate: independent cleanup/callback/Telegram work runs in parallel.
    await Promise.all([workflowPromise, callbackPromise, telegramPromise]);
    return true;
  }
  const grantCatalog = data.match(/^grant_catalog:(case|avatar|frame|trail|skin)$/);
  if (grantCatalog) {
    const access = grantCatalog[1] === "case"
      ? await requireAnySecurityPermission(chatId, query.from, ["grantRewards", "grantLegendaryCases"], env)
      : await requireSecurityPermission(chatId, query.from, "grantRewards", env);
    if (!access) return true;
    await answerCallback(env, query.id, "Выберите предмет.");
    await sendTelegramMessage(env, chatId, `<b>${escapeHtml(({ case: "Кейсы", avatar: "Аватарки", frame: "Рамки", trail: "Следы", skin: "Скины" })[grantCatalog[1]])}</b>`, grantCatalogMarkup(grantCatalog[1]));
    return true;
  }
  const grantPick = data.match(/^grant_pick:(points|zefir|coffee|case|avatar|frame|trail|skin):([A-Za-z0-9_-]+)$/);
  if (grantPick) {
    await beginGrantSelection(query, grantPick[1], grantPick[2] === "_" ? "" : grantPick[2], env);
    return true;
  }
  if (data === "grant_confirm") {
    await executeGrantWorkflow(query, env);
    return true;
  }
  if (data === "stock_refresh") {
    await answerCallback(env, query.id, "Остатки обновлены.");
    await showStockDashboard(chatId, query.from, env);
    return true;
  }
  if (data === "status_refresh") {
    await answerCallback(env, query.id, "Статус обновлён.");
    await showOperationsStatus(chatId, query.from, env);
    return true;
  }
  if (data === "season_list") {
    await answerCallback(env, query.id, "Открываю сезоны.");
    await showLeaderboardSeasonsAdmin(chatId, query.from, env);
    return true;
  }
  if (data === "season_new") {
    await startLeaderboardSeasonCreate(query, env);
    return true;
  }
  if (data === "season_create_cancel") {
    await cancelLeaderboardSeasonCreate(query, env);
    return true;
  }
  if (data === "season_create_reward_back") {
    const workflow = await getStaffWorkflow(query.from.id, env);
    if (workflow?.flow_type === "season_create") await updateStaffWorkflow(query.from.id, { step: "reward_type", data: { rewardType: "", itemId: "" } }, env);
    await answerCallback(env, query.id, "Выберите награду.");
    await sendTelegramMessage(env, chatId, "<b>Выберите награду за первое место</b>", seasonCreateRewardTypeKeyboard());
    return true;
  }
  const seasonCreateReward = data.match(/^season_create_reward:(points|treats|coffee|case)$/);
  if (seasonCreateReward) {
    await selectLeaderboardSeasonCreateReward(query, seasonCreateReward[1], "", env);
    return true;
  }
  const seasonCreateCase = data.match(/^season_create_case:(small|sweet|gold|mythic|legendary)$/);
  if (seasonCreateCase) {
    await selectLeaderboardSeasonCreateReward(query, "case", seasonCreateCase[1], env);
    return true;
  }
  if (data === "season_create_save") {
    await finalizeLeaderboardSeasonCreate(query, env);
    return true;
  }
  const seasonView = data.match(/^season_view:([A-Za-z0-9_-]{2,64})$/);
  if (seasonView) {
    await answerCallback(env, query.id, "Открываю сезон.");
    await showLeaderboardSeasonDetails(chatId, query.from, seasonView[1], env);
    return true;
  }
  const seasonRewardFor = data.match(/^season_reward_for:([A-Za-z0-9_-]{2,64})$/);
  if (seasonRewardFor) {
    await startSeasonRewardWorkflow(query, env, seasonRewardFor[1]);
    return true;
  }
  const seasonCancelPreview = data.match(/^season_cancel_preview:([A-Za-z0-9_-]{2,64})$/);
  if (seasonCancelPreview) {
    await cancelScheduledLeaderboardSeason(query, seasonCancelPreview[1], env, false);
    return true;
  }
  const seasonCancelConfirm = data.match(/^season_cancel_confirm:([A-Za-z0-9_-]{2,64})$/);
  if (seasonCancelConfirm) {
    await cancelScheduledLeaderboardSeason(query, seasonCancelConfirm[1], env, true);
    return true;
  }
  if (data === "season_refresh") {
    await answerCallback(env, query.id, "Сезон обновлён.");
    await showSeasonAdminDashboard(chatId, query.from, env);
    return true;
  }
  if (data === "season_top") {
    await answerCallback(env, query.id, "Открываю топ-10.");
    await showSeasonTop10(chatId, query.from, env);
    return true;
  }
  const seasonExtend = data.match(/^season_extend:(1|7)$/);
  if (seasonExtend) {
    await extendSeason(query, Number(seasonExtend[1]), env);
    return true;
  }
  const seasonShorten = data.match(/^season_shorten:(1|7)$/);
  if (seasonShorten) {
    await shortenSeason(query, Number(seasonShorten[1]), env);
    return true;
  }
  if (data === "season_reward") {
    await startSeasonRewardWorkflow(query, env);
    return true;
  }
  const seasonRewardPick = data.match(/^season_reward_pick:(points|treats|coffee|case)$/);
  if (seasonRewardPick) {
    await beginSeasonRewardAmountWorkflow(query, seasonRewardPick[1], "", env);
    return true;
  }
  const seasonRewardCase = data.match(/^season_reward_case:(small|sweet|gold|mythic|legendary)$/);
  if (seasonRewardCase) {
    await beginSeasonRewardAmountWorkflow(query, "case", seasonRewardCase[1], env);
    return true;
  }
  if (data === "season_finish_preview") {
    const access = await requireTeamPermission(chatId, query.from, "staff", env);
    if (!access || !canManageSeason(access)) return true;
    await answerCallback(env, query.id, "Требуется подтверждение.");
    await sendTelegramMessage(env, chatId,
      `<b>Подтвердите досрочное завершение</b>\n\nРейтинг будет закрыт немедленно, победитель и награда будут зафиксированы. Отменить это действие нельзя.`,
      { inline_keyboard: [[
        { text: "⛔ Да, завершить", callback_data: "season_finish_confirm" },
        { text: "Отмена", callback_data: "ops_cancel" }
      ]] }
    );
    return true;
  }
  if (data === "season_finish_confirm") {
    await finishSeasonEarly(query, env);
    return true;
  }
  const ticketCategory = data.match(/^ticket_cat:([a-z_]+)$/);
  if (ticketCategory) {
    await beginTicketCategory(query, ticketCategory[1], env);
    return true;
  }
  const ticketView = data.match(/^ticket_view:(\d{1,9})$/);
  if (ticketView) {
    await answerCallback(env, query.id, "Открываю обращение.");
    await showTicketDetails(chatId, query.from, Number(ticketView[1]), env);
    return true;
  }
  const ticketStatus = data.match(/^ticket_status:(\d{1,9}):(working|resolved|rejected)$/);
  if (ticketStatus) {
    await updateTicketStatus(query, Number(ticketStatus[1]), ticketStatus[2], env);
    return true;
  }
  if (data === "tickets_open") {
    await answerCallback(env, query.id, "Открываю обращения.");
    await showTicketsList(chatId, query.from, "open", env);
    return true;
  }
  return false;
}



