const LIVE_CONTENT_DESTINATIONS = Object.freeze(["native","case","seasonal_case","shop","season_pass","story","event","manual"]);
const LIVE_CONTENT_STATUSES = Object.freeze(["draft","hidden","scheduled","open","archived"]);
const LIVE_CONTENT_RELEASE_CACHE_TTL_MS = 5000;
let liveContentReleaseSchemaPromise = null;
let liveContentReleaseCache = { expiresAt:0, rows:new Map() };

function liveContentReleaseKey(kind,itemId){ return `${String(kind||"")}:${String(itemId||"")}`; }
function liveContentSafeObject(value){ return value&&typeof value==="object"&&!Array.isArray(value)?value:{}; }
function liveContentParseObject(value){ try{return liveContentSafeObject(JSON.parse(String(value||"{}")));}catch{return {};} }
function liveContentStatus(value,fallback="hidden"){
  const status=String(value||"").trim().toLowerCase();
  return LIVE_CONTENT_STATUSES.includes(status)?status:(LIVE_CONTENT_STATUSES.includes(String(fallback||""))?String(fallback):"hidden");
}
function liveContentLegacyRoute(type,id,config){
  const routeType=LIVE_CONTENT_DESTINATIONS.includes(String(type||""))?String(type):"manual",cfg=liveContentSafeObject(config);
  if(routeType==="native"||routeType==="story"||routeType==="event"||routeType==="manual")return {enabled:true};
  if(routeType==="shop")return {enabled:true,points:Math.max(0,Math.floor(Number(cfg.points)||0)),treats:Math.max(0,Math.floor(Number(cfg.treats)||0)),coffee:Math.max(0,Math.floor(Number(cfg.coffee)||0))};
  if(routeType==="case"||routeType==="seasonal_case")return {enabled:true,destinationId:String(id||""),weight:Math.max(.01,Math.min(100000,Number(cfg.weight)||1))};
  if(routeType==="season_pass")return {enabled:true,destinationId:String(id||""),level:Math.max(1,Math.min(50,Math.floor(Number(cfg.level)||1))),lane:String(cfg.lane||"")==="premium"?"premium":"free",...(cfg.previousReward&&typeof cfg.previousReward==="object"?{previousReward:cfg.previousReward}:{})};
  return {enabled:true};
}
function liveContentRoutesFromStorage(raw,legacyType,legacyId,legacyConfig){
  const rawText=String(raw??"").trim(),parsed=liveContentParseObject(raw),out={};
  if(Number(parsed.version||0)===1&&parsed.routes&&typeof parsed.routes==="object"&&!Array.isArray(parsed.routes)){
    for(const type of LIVE_CONTENT_DESTINATIONS){const route=liveContentSafeObject(parsed.routes[type]);if(route.enabled!==true)continue;out[type]={...route,enabled:true};}
    return out;
  }
  if(rawText&&rawText!=="{}")return out;
  const type=LIVE_CONTENT_DESTINATIONS.includes(String(legacyType||""))?String(legacyType):"manual";
  out[type]=liveContentLegacyRoute(type,legacyId,legacyConfig);
  return out;
}
function liveContentRoutesForStorage(routes){const clean={};for(const type of LIVE_CONTENT_DESTINATIONS){const route=liveContentSafeObject(routes?.[type]);if(route.enabled===true)clean[type]={...route,enabled:true};}return JSON.stringify({version:1,routes:clean});}
function liveContentRoute(rule,type,destinationId=""){
  const route=liveContentSafeObject(rule?.routes?.[String(type||"")]);if(route.enabled!==true)return null;
  if(destinationId&&String(route.destinationId||"")!==String(destinationId))return null;
  return route;
}
function liveContentRouteEnabled(rule,type,destinationId=""){return Boolean(liveContentRoute(rule,type,destinationId));}
function liveContentRewardQueueRoute(sourceType){
  const source=String(sourceType||"");
  if(source==="season_story")return "story";
  if(source==="event_participant")return "event";
  return "manual";
}
function liveContentRouteAllowedCached(kind,itemId,type,destinationId=""){
  if(!futureSeasonContentItem(kind,itemId))return true;
  const rule=liveContentReleaseRuleCached(kind,itemId);
  return Boolean(rule?.released&&liveContentRouteEnabled(rule,type,destinationId));
}
async function liveContentRouteAllowed(env,kind,itemId,type,destinationId=""){
  if(!futureSeasonContentItem(kind,itemId))return true;
  const rules=await readLiveContentReleaseRules(env,true);
  const rule=rules.get(liveContentReleaseKey(kind,itemId));
  return Boolean(rule?.released&&liveContentRouteEnabled(rule,type,destinationId));
}
async function assertRolledLiveContentCaseRoutes(env,rolled,routeType,destinationId){
  const rewards=Array.isArray(rolled?.rewards)?rolled.rewards:[];
  const future=[];
  for(const reward of rewards){
    const kind=String(reward?.kind||""),itemId=String(reward?.id||reward?.itemId||"");
    if(!SEASON_PASS_COSMETIC_KINDS.includes(kind)||!futureSeasonContentItem(kind,itemId))continue;
    future.push({kind,itemId});
  }
  if(!future.length)return true;
  const rules=await readLiveContentReleaseRules(env,true);
  for(const item of future){
    const rule=rules.get(liveContentReleaseKey(item.kind,item.itemId));
    if(!rule?.released||!liveContentRouteEnabled(rule,routeType,destinationId))throw new ApiError(409,"Content availability changed. Open the case again.");
  }
  return true;
}
function liveContentPrimaryRoute(routes,preferred=""){
  const pref=String(preferred||"");if(LIVE_CONTENT_DESTINATIONS.includes(pref)&&liveContentSafeObject(routes?.[pref]).enabled===true)return {type:pref,route:routes[pref]};
  for(const type of LIVE_CONTENT_DESTINATIONS){if(liveContentSafeObject(routes?.[type]).enabled===true)return {type,route:routes[type]};}
  return {type:"manual",route:{enabled:false}};
}
function liveContentLegacyRouteConfig(type,route){
  const r=liveContentSafeObject(route);if(type==="shop")return {points:Math.max(0,Math.floor(Number(r.points)||0)),treats:Math.max(0,Math.floor(Number(r.treats)||0)),coffee:Math.max(0,Math.floor(Number(r.coffee)||0))};
  if(type==="case"||type==="seasonal_case")return {weight:Math.max(.01,Math.min(100000,Number(r.weight)||1))};
  if(type==="season_pass")return {level:Math.max(1,Math.min(50,Math.floor(Number(r.level)||1))),lane:String(r.lane||"")==="premium"?"premium":"free",...(r.previousReward&&typeof r.previousReward==="object"?{previousReward:r.previousReward}:{})};
  return {};
}
function liveContentRuleFromRow(row){
  const legacyConfig=liveContentParseObject(row?.destination_config_json);
  const hasRegistry=String(row?.registry_status||"").trim()!=="";let status=hasRegistry?liveContentStatus(row.registry_status,"hidden"):"hidden";
  const releaseAt=Math.max(0,Math.floor(Number(row?.registry_release_at)||0));
  const routes=liveContentRoutesFromStorage(row?.registry_routes_json,row?.destination_type,row?.destination_id,legacyConfig);if(status==="open"&&liveContentRouteCount(routes)<=0)status="hidden";const released=status==="open",primary=liveContentPrimaryRoute(routes,row?.destination_type);
  const destinationType=primary.type,destinationId=String(primary.route?.destinationId||""),destinationConfig=liveContentLegacyRouteConfig(destinationType,primary.route);
  return {
    kind:String(row?.item_kind||""),itemId:String(row?.item_id||""),seasonId:String(row?.content_season_id||""),status,releaseAt,released,everReleased:Number(row?.ever_released||0)===1||released,
    routes,destinationType,destinationId,destinationConfig,
    updatedAt:Math.max(Number(row?.updated_at||0),Number(row?.registry_updated_at||0)),updatedBy:String(row?.registry_updated_by||row?.updated_by||"")
  };
}

async function ensureLiveContentReleaseSchema(env){
  requireDatabase(env);
  if(!liveContentReleaseSchemaPromise){
    liveContentReleaseSchemaPromise=(async()=>{
      await env.DB.batch([
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS live_content_release_rules (
          item_kind TEXT NOT NULL,item_id TEXT NOT NULL,content_season_id TEXT NOT NULL DEFAULT '',released INTEGER NOT NULL DEFAULT 0,ever_released INTEGER NOT NULL DEFAULT 0,
          destination_type TEXT NOT NULL DEFAULT 'native',destination_id TEXT NOT NULL DEFAULT '',destination_config_json TEXT NOT NULL DEFAULT '{}',
          updated_at INTEGER NOT NULL DEFAULT 0,updated_by TEXT NOT NULL DEFAULT '',PRIMARY KEY(item_kind,item_id)
        )`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS live_content_registry_state (
          item_kind TEXT NOT NULL,item_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'hidden',release_at INTEGER NOT NULL DEFAULT 0,routes_json TEXT NOT NULL DEFAULT '{}',
          updated_at INTEGER NOT NULL DEFAULT 0,updated_by TEXT NOT NULL DEFAULT '',PRIMARY KEY(item_kind,item_id)
        )`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_live_content_registry_schedule ON live_content_registry_state(status,release_at)`)
      ]);
      const columns=(await env.DB.prepare(`PRAGMA table_info(live_content_release_rules)`).all()).results||[];
      if(!columns.some(row=>String(row.name)==='content_season_id'))await env.DB.prepare(`ALTER TABLE live_content_release_rules ADD COLUMN content_season_id TEXT NOT NULL DEFAULT ''`).run();
      let boundSeason3Id='',boundSeason2Id='';
      try{boundSeason3Id=String((await env.DB.prepare(`SELECT season_id FROM season_pass_case_presets WHERE preset_id='season3_belkino_case_v1' LIMIT 1`).first())?.season_id||'');}catch{}
      try{boundSeason2Id=String((await env.DB.prepare(`SELECT season_id FROM season_pass_story_presets WHERE preset_id='season2-night-cafe-story-v1' LIMIT 1`).first())?.season_id||'');}catch{}
      const now=Math.floor(Date.now()/1000),statements=[];
      for(const [kind,catalog] of Object.entries(FUTURE_SEASON_CONTENT)){
        for(const [itemId,item] of Object.entries(catalog||{})){
          const seasonKey=String(item?.seasonKey||'season3'),initialSeasonId=seasonKey==='season2'?boundSeason2Id:boundSeason3Id;
          statements.push(env.DB.prepare(`INSERT OR IGNORE INTO live_content_release_rules(item_kind,item_id,content_season_id,released,ever_released,destination_type,destination_id,destination_config_json,updated_at,updated_by) VALUES(?,?,?,0,0,'native','','{}',?,'system')`).bind(kind,itemId,initialSeasonId,now));
          if(initialSeasonId){
            if(seasonKey==='season2'&&boundSeason3Id)statements.push(env.DB.prepare(`UPDATE live_content_release_rules SET content_season_id=? WHERE item_kind=? AND item_id=? AND (content_season_id='' OR content_season_id=?)`).bind(initialSeasonId,kind,itemId,boundSeason3Id));
            else statements.push(env.DB.prepare(`UPDATE live_content_release_rules SET content_season_id=? WHERE item_kind=? AND item_id=? AND content_season_id=''`).bind(initialSeasonId,kind,itemId));
          }
        }
      }
      for(let i=0;i<statements.length;i+=40)await env.DB.batch(statements.slice(i,i+40));
      await env.DB.prepare(`INSERT OR IGNORE INTO live_content_registry_state(item_kind,item_id,status,release_at,routes_json,updated_at,updated_by)
        SELECT item_kind,item_id,CASE WHEN released=1 THEN 'open' ELSE 'hidden' END,0,'{}',updated_at,updated_by FROM live_content_release_rules`).run();
    })().catch(error=>{liveContentReleaseSchemaPromise=null;throw error;});
  }
  await liveContentReleaseSchemaPromise;
}

async function readLiveContentReleaseRules(env,force=false){
  const now=Date.now();
  if(!force&&liveContentReleaseCache.expiresAt>now&&liveContentReleaseCache.rows.size)return liveContentReleaseCache.rows;
  const readRows=()=>env.DB.prepare(`SELECT r.*,s.status AS registry_status,s.release_at AS registry_release_at,s.routes_json AS registry_routes_json,s.updated_at AS registry_updated_at,s.updated_by AS registry_updated_by
    FROM live_content_release_rules r LEFT JOIN live_content_registry_state s ON s.item_kind=r.item_kind AND s.item_id=r.item_id ORDER BY r.item_kind,r.item_id`).all();
  let result;try{result=await readRows();}catch(error){if(!isMissingRuntimeDatabaseSchemaError(error))throw error;await ensureLiveContentReleaseSchema(env);result=await readRows();}
  const rows=new Map();for(const row of result.results||[]){const rule=liveContentRuleFromRow(row);rows.set(liveContentReleaseKey(rule.kind,rule.itemId),rule);}
  liveContentReleaseCache={expiresAt:Date.now()+LIVE_CONTENT_RELEASE_CACHE_TTL_MS,rows};
  return rows;
}

function liveContentReleaseRuleCached(kind,itemId){ return liveContentReleaseCache.rows.get(liveContentReleaseKey(kind,itemId))||null; }
function isFutureContentReleasedCached(kind,itemId){ return Boolean(liveContentReleaseRuleCached(kind,itemId)?.released); }
function invalidateLiveContentReleaseCache(){ liveContentReleaseCache={expiresAt:0,rows:new Map()}; invalidateLiveOpsConfigCache(); }
async function bindFutureContentCatalogToSeason(env,seasonId){
  const id=String(seasonId||'').trim();if(!id)return {ok:false,bound:0};
  await ensureLiveContentReleaseSchema(env);const statements=[];
  for(const [kind,catalog] of Object.entries(FUTURE_SEASON_CONTENT))for(const itemId of Object.keys(catalog||{})){
    if(!futureSeasonContentMatchesSeasonKey(kind,itemId,'season3'))continue;
    statements.push(env.DB.prepare(`UPDATE live_content_release_rules SET content_season_id=? WHERE item_kind=? AND item_id=? AND (content_season_id='' OR content_season_id=?)`).bind(id,kind,itemId,id));
  }
  for(let i=0;i<statements.length;i+=40)await env.DB.batch(statements.slice(i,i+40));
  invalidateLiveContentReleaseCache();return {ok:true,bound:statements.length,seasonId:id,scope:'season3_only'};
}
async function bindSeason2ContentCatalogToSeason(env,seasonId){
  const id=String(seasonId||'').trim();if(!id)return {ok:false,bound:0};
  await ensureLiveContentReleaseSchema(env);let season3Id='';
  try{season3Id=String((await env.DB.prepare(`SELECT season_id FROM season_pass_case_presets WHERE preset_id='season3_belkino_case_v1' LIMIT 1`).first())?.season_id||'');}catch{}
  const statements=[];
  for(const [kind,catalog] of Object.entries(FUTURE_SEASON_CONTENT))for(const itemId of Object.keys(catalog||{})){
    if(!futureSeasonContentMatchesSeasonKey(kind,itemId,'season2'))continue;
    if(season3Id)statements.push(env.DB.prepare(`UPDATE live_content_release_rules SET content_season_id=? WHERE item_kind=? AND item_id=? AND (content_season_id='' OR content_season_id=?)`).bind(id,kind,itemId,season3Id));
    else statements.push(env.DB.prepare(`UPDATE live_content_release_rules SET content_season_id=? WHERE item_kind=? AND item_id=? AND content_season_id=''`).bind(id,kind,itemId));
  }
  for(let i=0;i<statements.length;i+=40)await env.DB.batch(statements.slice(i,i+40));
  invalidateLiveContentReleaseCache();return {ok:true,bound:statements.length,seasonId:id,scope:'season2_only'};
}

async function readLiveContentShopCatalog(env){
  const rules=await readLiveContentReleaseRules(env);const items=[];
  for(const rule of rules.values()){
    const route=liveContentRoute(rule,"shop");if(!rule.released||!route)continue;
    const item=futureSeasonContentItem(rule.kind,rule.itemId);if(!item)continue;
    items.push({kind:rule.kind,itemId:rule.itemId,title:String(item.title||rule.itemId),rarity:String(item.rarity||"common"),imageUrl:String(item.imageUrl||""),audioUrl:String(item.audioUrl||item.src||""),price:{points:Math.max(0,Math.floor(Number(route.points)||0)),treats:Math.max(0,Math.floor(Number(route.treats)||0)),coffee:Math.max(0,Math.floor(Number(route.coffee)||0))},seasonId:String(rule.seasonId||""),seasonLabel:futureSeasonContentLabel(rule.kind,rule.itemId)});
  }
  return items.sort((a,b)=>String(a.kind).localeCompare(String(b.kind))||String(a.title).localeCompare(String(b.title),"ru"));
}

let seasonPassCaseSpecialItemsSchemaPromise=null;
async function ensureSeasonPassCaseSpecialItemsSchema(env){
  requireDatabase(env);
  if(!seasonPassCaseSpecialItemsSchemaPromise){
    seasonPassCaseSpecialItemsSchemaPromise=env.DB.batch([
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS season_pass_case_special_items (
        case_id TEXT NOT NULL,item_key TEXT NOT NULL,reward_kind TEXT NOT NULL CHECK(reward_kind IN ('showcase_style')),
        item_id TEXT NOT NULL,weight REAL NOT NULL DEFAULT 1 CHECK(weight>0),rarity TEXT NOT NULL DEFAULT 'seasonal',title TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)),
        PRIMARY KEY(case_id,item_key)
      )`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_season_pass_case_special_items_enabled ON season_pass_case_special_items(case_id,enabled,reward_kind)`)
    ]).catch((error)=>{seasonPassCaseSpecialItemsSchemaPromise=null;throw error;});
  }
  await seasonPassCaseSpecialItemsSchemaPromise;
}

async function seasonPassEffectiveCaseItems(env,caseIdValue,baseRows=null){
  const caseId=String(caseIdValue||"").trim();if(!caseId)return [];
  const caseDefinition=await env.DB.prepare(`SELECT season_id FROM season_pass_case_definitions WHERE case_id=? LIMIT 1`).bind(caseId).first(),caseSeasonId=String(caseDefinition?.season_id||"");
  let rows;
  if(Array.isArray(baseRows))rows=baseRows.slice();
  else{
    await ensureSeasonPassCaseSpecialItemsSchema(env);
    const [cosmetics,resources,specials]=await Promise.all([
      env.DB.prepare(`SELECT item_key,reward_kind,item_id,1 AS amount,weight,rarity,title,image_url,enabled FROM season_pass_case_items WHERE case_id=? AND enabled=1 AND weight>0 ORDER BY item_key`).bind(caseId).all(),
      env.DB.prepare(`SELECT item_key,reward_kind,item_id,amount,weight,rarity,title,image_url,enabled FROM season_pass_case_resource_items WHERE case_id=? AND enabled=1 AND weight>0 ORDER BY item_key`).bind(caseId).all(),
      env.DB.prepare(`SELECT item_key,reward_kind,item_id,1 AS amount,weight,rarity,title,image_url,enabled FROM season_pass_case_special_items WHERE case_id=? AND enabled=1 AND weight>0 ORDER BY item_key`).bind(caseId).all()
    ]);
    rows=[...(cosmetics.results||[]),...(resources.results||[]),...(specials.results||[])];
  }
  const known=new Set(rows.map(row=>`${String(row.reward_kind)}:${String(row.item_id)}:${String(row.item_key||"")}`));const rules=await readLiveContentReleaseRules(env);
  for(const rule of rules.values()){
    const seasonalRoute=liveContentRoute(rule,"seasonal_case",caseId);if(!rule.released||!seasonalRoute||!caseSeasonId||String(rule.seasonId||"")!==caseSeasonId)continue;
    const item=futureSeasonContentItem(rule.kind,rule.itemId);if(!item)continue;const key=`${rule.kind}:${rule.itemId}`;if(rows.some(row=>String(row.reward_kind)===rule.kind&&String(row.item_id)===rule.itemId))continue;
    const weight=Math.max(.01,Math.min(100000,Number(seasonalRoute.weight)||1));
    rows.push({item_key:`live:${key}`,reward_kind:rule.kind,item_id:rule.itemId,amount:1,weight,rarity:String(item.rarity||"epic"),title:String(item.title||rule.itemId),image_url:String(item.imageUrl||""),enabled:1,live_content:1});
  }
  return rows;
}

let liveOpsAdminSchemaPromise = null;
async function ensureLiveOpsAdminSchema(env) {
  if (!liveOpsAdminSchemaPromise) {
    liveOpsAdminSchemaPromise = (async () => {
      await ensureLiveContentReleaseSchema(env);
      await env.DB.batch([
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS player_moderation_history (id INTEGER PRIMARY KEY AUTOINCREMENT, telegram_id TEXT NOT NULL, action TEXT NOT NULL, block_type TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', blocked_until INTEGER NOT NULL DEFAULT 0, actor_telegram_id TEXT NOT NULL DEFAULT '', actor_name TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL)`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS player_notes (id INTEGER PRIMARY KEY AUTOINCREMENT, telegram_id TEXT NOT NULL, note_text TEXT NOT NULL, created_by TEXT NOT NULL, created_by_name TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL, deleted_at INTEGER NOT NULL DEFAULT 0, deleted_by TEXT NOT NULL DEFAULT '')`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS liveops_content_items (item_kind TEXT NOT NULL, item_id TEXT NOT NULL, title TEXT NOT NULL, rarity TEXT NOT NULL DEFAULT 'common', weight REAL NOT NULL DEFAULT 1, enabled INTEGER NOT NULL DEFAULT 1, is_new INTEGER NOT NULL DEFAULT 0, legendary_only INTEGER NOT NULL DEFAULT 0, image_url TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL, updated_by TEXT NOT NULL DEFAULT '', PRIMARY KEY(item_kind, item_id))`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS liveops_case_configs (case_id TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 1, title TEXT NOT NULL, guarantee_count INTEGER NOT NULL DEFAULT 0, chances_json TEXT NOT NULL DEFAULT '{}', ranges_json TEXT NOT NULL DEFAULT '{}', updated_at INTEGER NOT NULL, updated_by TEXT NOT NULL DEFAULT '')`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS liveops_config_history (id INTEGER PRIMARY KEY AUTOINCREMENT, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, old_json TEXT NOT NULL DEFAULT '{}', new_json TEXT NOT NULL DEFAULT '{}', reason TEXT NOT NULL DEFAULT '', actor_telegram_id TEXT NOT NULL, actor_name TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL)`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS admin_campaigns (campaign_id TEXT PRIMARY KEY, title TEXT NOT NULL, segment_key TEXT NOT NULL, reward_kind TEXT NOT NULL, reward_id TEXT NOT NULL DEFAULT '', amount INTEGER NOT NULL DEFAULT 1, reason TEXT NOT NULL, message_text TEXT NOT NULL DEFAULT '', reward_bundle_json TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'pending', created_by TEXT NOT NULL, created_by_name TEXT NOT NULL DEFAULT '', report_chat_id TEXT NOT NULL, total_count INTEGER NOT NULL DEFAULT 0, processed_count INTEGER NOT NULL DEFAULT 0, failed_count INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, started_at INTEGER NOT NULL DEFAULT 0, completed_at INTEGER NOT NULL DEFAULT 0, updated_at INTEGER NOT NULL, lease_token TEXT NOT NULL DEFAULT '', lease_until INTEGER NOT NULL DEFAULT 0)`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS admin_campaign_recipients (campaign_id TEXT NOT NULL, telegram_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', error_text TEXT NOT NULL DEFAULT '', processed_at INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(campaign_id, telegram_id))`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS admin_campaign_mail_config (campaign_id TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0, preview_text TEXT NOT NULL DEFAULT '')`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS fraud_alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, telegram_id TEXT NOT NULL, alert_type TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'medium', title TEXT NOT NULL, details_json TEXT NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'open', assigned_to TEXT NOT NULL DEFAULT '', resolution TEXT NOT NULL DEFAULT '', fingerprint TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS staff_work_context (telegram_id TEXT PRIMARY KEY, location_name TEXT NOT NULL DEFAULT 'Основное кафе', shift_name TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL)`),
        env.DB.prepare(`CREATE TABLE IF NOT EXISTS physical_redemption_context (reward_code TEXT PRIMARY KEY, employee_telegram_id TEXT NOT NULL, employee_name TEXT NOT NULL DEFAULT '', location_name TEXT NOT NULL DEFAULT 'Основное кафе', shift_name TEXT NOT NULL DEFAULT '', redeemed_at INTEGER NOT NULL)`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_player_notes_player ON player_notes(telegram_id, deleted_at, created_at DESC)`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_admin_campaigns_pending ON admin_campaigns(status, lease_until, created_at)`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_admin_campaign_recipients_pending ON admin_campaign_recipients(campaign_id, status, telegram_id)`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_fraud_alerts_status_severity ON fraud_alerts(status, severity, created_at DESC)`),
        env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_liveops_config_history_recent ON liveops_config_history(created_at DESC, id DESC)`)
      ]);
      const campaignInfo = await env.DB.prepare(`PRAGMA table_info(admin_campaigns)`).all();
      const campaignColumns = new Set((campaignInfo.results || []).map((column) => String(column.name || '')));
      const campaignUpgrades = [
        ['scheduled_at', `INTEGER NOT NULL DEFAULT 0`],
        ['image_url', `TEXT NOT NULL DEFAULT ''`],
        ['button_text', `TEXT NOT NULL DEFAULT ''`],
        ['button_url', `TEXT NOT NULL DEFAULT ''`],
        ['reward_bundle_json', `TEXT NOT NULL DEFAULT '[]'`]
      ];
      for (const [column, definition] of campaignUpgrades) {
        if (!campaignColumns.has(column)) await env.DB.prepare(`ALTER TABLE admin_campaigns ADD COLUMN ${column} ${definition}`).run();
      }
      const recipientInfo = await env.DB.prepare(`PRAGMA table_info(admin_campaign_recipients)`).all();
      const recipientColumns = new Set((recipientInfo.results || []).map((column) => String(column.name || '')));
      if (!recipientColumns.has('delivered_at')) {
        await env.DB.prepare(`ALTER TABLE admin_campaign_recipients ADD COLUMN delivered_at INTEGER NOT NULL DEFAULT 0`).run();
        await env.DB.prepare(`UPDATE admin_campaign_recipients SET delivered_at=processed_at WHERE status='processed' AND processed_at>0`).run();
      }
      if (!recipientColumns.has('delivery_error')) {
        await env.DB.prepare(`ALTER TABLE admin_campaign_recipients ADD COLUMN delivery_error TEXT NOT NULL DEFAULT ''`).run();
        await env.DB.prepare(`UPDATE admin_campaign_recipients SET delivery_error=error_text WHERE status='failed' AND error_text<>''`).run();
      }
      const now = Math.floor(Date.now() / 1000);
      const contentStatements = [];
      for (const [kind, catalog] of Object.entries({ avatar: CASE_AVATARS, frame: CASE_FRAMES, trail: CASE_TRAILS, skin: CASE_SKINS })) {
        for (const [itemId, item] of Object.entries(catalog)) {
          const imageUrl = String(LIVEOPS_CONTENT_IMAGES[kind]?.[itemId] || "");
          contentStatements.push(env.DB.prepare(
            `INSERT OR IGNORE INTO liveops_content_items (item_kind, item_id, title, rarity, weight, enabled, is_new, legendary_only, image_url, updated_at, updated_by)
             VALUES (?, ?, ?, ?, ?, 1, ?, ?, ?, ?, 'system')`
          ).bind(kind, itemId, String(item.title || itemId), String(item.rarity || "common"), Math.max(0, Number(item.weight || 1)), item.isNew ? 1 : 0, item.legendaryOnly ? 1 : 0, imageUrl, now));
          if (imageUrl) contentStatements.push(env.DB.prepare(
            `UPDATE liveops_content_items SET image_url = ?, updated_at = ?, updated_by = 'asset-backfill-v0.56'
             WHERE item_kind = ? AND item_id = ? AND image_url = ''`
          ).bind(imageUrl, now, kind, itemId));
        }
      }
      if (contentStatements.length) await env.DB.batch(contentStatements);
      const caseStatements = LIVEOPS_CASE_IDS.map((caseId) => {
        const item = LIVEOPS_CASE_DEFAULTS[caseId];
        return env.DB.prepare(
          `INSERT OR IGNORE INTO liveops_case_configs (case_id, enabled, title, guarantee_count, chances_json, ranges_json, updated_at, updated_by)
           VALUES (?, ?, ?, ?, ?, ?, ?, 'system')`
        ).bind(caseId, item.enabled ? 1 : 0, item.title, item.guaranteeCount, JSON.stringify(item.chances), JSON.stringify(item.ranges), now);
      });
      await env.DB.batch(caseStatements);
      invalidateLiveOpsConfigCache();
    })().catch((error) => {
      liveOpsAdminSchemaPromise = null;
      throw error;
    });
  }
  await liveOpsAdminSchemaPromise;
}

function liveOpsCaseConfigFromRow(row) {
  const caseId = String(row?.case_id || "");
  const fallback = LIVEOPS_CASE_DEFAULTS[caseId] || LIVEOPS_CASE_DEFAULTS.small;
  const storedChances = parseJsonObject(row?.chances_json, {});
  const chances = { ...fallback.chances, ...storedChances };
  if (caseId === "legendary" && !Object.prototype.hasOwnProperty.call(storedChances, "music")) {
    chances.music = 0.45;
    chances.points = Math.max(0, Number(chances.points || 0) - 0.45);
  }
  const ranges = { ...fallback.ranges, ...parseJsonObject(row?.ranges_json, {}) };
  return {
    id: caseId,
    enabled: Number(row?.enabled || 0) === 1,
    title: String(row?.title || fallback.title),
    guaranteeCount: Math.max(0, Math.floor(Number(row?.guarantee_count ?? fallback.guaranteeCount))),
    chances,
    ranges,
    updatedAt: Number(row?.updated_at || 0),
    updatedBy: String(row?.updated_by || "")
  };
}

const LIVEOPS_CONFIG_CACHE_TTL_MS = 15 * 1000;
let liveOpsConfigMemory = { value: null, expiresAt: 0, promise: null, generation: 0 };
function invalidateLiveOpsConfigCache() {
  liveOpsConfigMemory.value = null;
  liveOpsConfigMemory.expiresAt = 0;
  liveOpsConfigMemory.promise = null;
  liveOpsConfigMemory.generation += 1;
}
async function readLiveOpsConfig(env, force = false) {
  const nowMs = Date.now();
  if (!force && liveOpsConfigMemory.value && liveOpsConfigMemory.expiresAt > nowMs) return liveOpsConfigMemory.value;
  if (!force && liveOpsConfigMemory.promise) return liveOpsConfigMemory.promise;
  const generation = liveOpsConfigMemory.generation;
  const promise = (async () => {
  const readRows = () => Promise.all([
    env.DB.prepare(`SELECT * FROM liveops_content_items ORDER BY item_kind, title`).all(),
    env.DB.prepare(`SELECT * FROM liveops_case_configs ORDER BY CASE case_id WHEN 'small' THEN 1 WHEN 'sweet' THEN 2 WHEN 'gold' THEN 3 WHEN 'mythic' THEN 4 ELSE 5 END`).all(),
    readLiveContentReleaseRules(env)
  ]);
  let contentResult, caseResult, releaseRules;
  try { [contentResult, caseResult, releaseRules] = await readRows(); }
  catch (error) { if (!isMissingRuntimeDatabaseSchemaError(error)) throw error; await ensureLiveOpsAdminSchema(env); [contentResult, caseResult, releaseRules] = await readRows(); }
  const content = { avatar: {}, frame: {}, trail: {}, skin: {}, music: {} };
  for (const row of contentResult.results || []) {
    const kind = String(row.item_kind || "");
    if (!content[kind]) continue;
    content[kind][String(row.item_id)] = {
      title: String(row.title || row.item_id),
      rarity: String(row.rarity || "common"),
      weight: Math.max(0, Number(row.weight || 0)),
      enabled: Number(row.enabled || 0) === 1,
      isNew: Number(row.is_new || 0) === 1,
      legendaryOnly: Number(row.legendary_only || 0) === 1,
      imageUrl: String(row.image_url || "")
    };
  }
  for(const rule of releaseRules.values()){
    if(!rule.released&&!rule.everReleased)continue;
    const item=futureSeasonContentItem(rule.kind,rule.itemId);if(!item||!content[rule.kind])continue;
    content[rule.kind][rule.itemId]={
      title:String(item.title||rule.itemId),rarity:String(item.rarity||"common"),weight:Math.max(0,Number((liveContentRoute(rule,"case")||liveContentRoute(rule,"seasonal_case")||{}).weight)||1),
      enabled:Boolean(rule.released),isNew:true,legendaryOnly:false,imageUrl:String(item.imageUrl||""),audioUrl:String(item.audioUrl||item.src||""),
      future:true,released:Boolean(rule.released),everReleased:Boolean(rule.everReleased),status:String(rule.status||"hidden"),releaseAt:Number(rule.releaseAt||0),routes:rule.routes||{},seasonId:String(rule.seasonId||""),destinationType:rule.destinationType,destinationId:rule.destinationId,destinationConfig:rule.destinationConfig||{},seasonLabel:futureSeasonContentLabel(rule.kind,rule.itemId)
    };
  }
  const cases = {};
  for (const row of caseResult.results || []) cases[String(row.case_id)] = liveOpsCaseConfigFromRow(row);
  for (const caseId of LIVEOPS_CASE_IDS) if (!cases[caseId]) cases[caseId] = { id: caseId, ...LIVEOPS_CASE_DEFAULTS[caseId] };
  const revision = Math.max(0,
    ...Array.from(contentResult.results || [], row => Number(row.updated_at || 0)),
    ...Array.from(caseResult.results || [], row => Number(row.updated_at || 0)),
    ...Array.from(releaseRules.values(), row => Number(row.updatedAt || 0))
  );
  const value = { content, cases, version: 3, revision };
  if (generation === liveOpsConfigMemory.generation) {
    liveOpsConfigMemory.value = value;
    liveOpsConfigMemory.expiresAt = Date.now() + LIVEOPS_CONFIG_CACHE_TTL_MS;
  }
  return value;
  })();
  liveOpsConfigMemory.promise = promise;
  try { return await promise; }
  finally { if (liveOpsConfigMemory.promise === promise) liveOpsConfigMemory.promise = null; }
}

function runtimeCaseCatalog(kind, baseCatalog, liveops, caseType = "") {
  const overrides = liveops?.content?.[kind] || {};
  const result = {};
  for (const [id, item] of Object.entries(baseCatalog || {})) {
    if (caseType && item?.achievementOnly === true) continue;
    const override = overrides[id];
    if (override && override.enabled === false) continue;
    result[id] = {
      ...item,
      title: String(override?.title || item.title || id),
      rarity: String(override?.rarity || item.rarity || "common"),
      weight: Math.max(0, Number(override?.weight ?? item.weight ?? 1)),
      isNew: override?.isNew == null ? Boolean(item.isNew) : Boolean(override.isNew),
      legendaryOnly: override?.legendaryOnly == null ? Boolean(item.legendaryOnly) : Boolean(override.legendaryOnly),
      achievementOnly:Boolean(item.achievementOnly),
      imageUrl:String(override?.imageUrl||item.imageUrl||""),audioUrl:String(override?.audioUrl||item.audioUrl||item.src||"")
    };
  }
  for(const [id,override] of Object.entries(overrides)){
    if(Object.prototype.hasOwnProperty.call(baseCatalog||{},id)||override?.enabled===false)continue;
    if(caseType&&!liveContentRouteEnabled(override,"case",String(caseType)))continue;
    result[id]={id,title:String(override?.title||id),rarity:String(override?.rarity||"common"),weight:Math.max(0,Number(override?.weight)||1),isNew:Boolean(override?.isNew),legendaryOnly:Boolean(override?.legendaryOnly),imageUrl:String(override?.imageUrl||""),src:kind==="music"?String(override?.audioUrl||""):String(override?.imageUrl||""),audioUrl:String(override?.audioUrl||""),future:Boolean(override?.future)};
  }
  return result;
}

function liveOpsCaseConfig(liveops, caseType) {
  if (String(caseType || "") === "alex") return ALEX_CASE_DEFINITION;
  return liveops?.cases?.[caseType] || { id: caseType, ...LIVEOPS_CASE_DEFAULTS[caseType] };
}

async function logLiveOpsConfigChange(env, user, entityType, entityId, action, oldValue, newValue, reason = "") {
  await ensureLiveOpsAdminSchema(env);
  const now = Math.floor(Date.now() / 1000);
  await env.DB.prepare(
    `INSERT INTO liveops_config_history (entity_type, entity_id, action, old_json, new_json, reason, actor_telegram_id, actor_name, created_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).bind(entityType, entityId, action, JSON.stringify(oldValue || {}), JSON.stringify(newValue || {}), String(reason || "").slice(0, 300), String(user?.id || ""), telegramDisplayName(user), now).run();
}

