async function handleSafeEventWorkflowMessage(message, workflow, env) {
  const chatId = message.chat.id;
  const user = message.from;
  const access = await requireSecurityPermission(chatId, user, "manageSeasons", env);
  if (!access) return true;
  const text = String(message.text || "").trim();
  const data = workflow.data || {};
  if (workflow.step === "title") {
    if (text.length < 3 || text.length > 100) return sendTelegramMessage(env, chatId, "Название должно содержать от 3 до 100 символов."), true;
    await updateStaffWorkflow(user.id, { step: "start", data: { title: text } }, env);
    await sendTelegramMessage(env, chatId, "<b>Шаг 2 из 6</b>\n\nВведите начало по Москве: <code>01.08.2026 10:00</code>.");
    return true;
  }
  if (workflow.step === "start") {
    const startsAt = parseMoscowDateTime(text);
    if (!startsAt) return sendTelegramMessage(env, chatId, "Дата не распознана. Формат: <code>ДД.ММ.ГГГГ ЧЧ:ММ</code>."), true;
    await updateStaffWorkflow(user.id, { step: "end", data: { startsAt } }, env);
    await sendTelegramMessage(env, chatId, "<b>Шаг 3 из 6</b>\n\nВведите завершение по Москве: <code>14.08.2026 22:00</code>.");
    return true;
  }
  if (workflow.step === "end") {
    const endsAt = parseMoscowDateTime(text);
    if (!endsAt || endsAt <= Number(data.startsAt || 0)) return sendTelegramMessage(env, chatId, "Завершение должно быть позже начала."), true;
    await updateStaffWorkflow(user.id, { step: "winner", data: { endsAt } }, env);
    await sendTelegramMessage(env, chatId, "<b>Шаг 4 из 6</b>\n\nНаграда за первое место. Примеры:\n<code>case legendary 1</code>\n<code>points 3000</code>\n<code>coffee 50 | 50 кофе</code>");
    return true;
  }
  if (workflow.step === "winner") {
    const winnerReward = parseSafeReward(text, false);
    if (!winnerReward) return sendTelegramMessage(env, chatId, "Награда не распознана. Пример: <code>case legendary 1</code>."), true;
    await updateStaffWorkflow(user.id, { step: "participant", data: { winnerReward } }, env);
    await sendTelegramMessage(env, chatId, "<b>Шаг 5 из 6</b>\n\nПодарок участникам. Пример: <code>case sweet 1</code>.\nБез подарка: <code>нет</code>.");
    return true;
  }
  if (workflow.step === "participant") {
    const participantReward = parseSafeReward(text, true);
    if (!participantReward) return sendTelegramMessage(env, chatId, "Подарок не распознан. Пример: <code>case sweet 1</code> или <code>нет</code>."), true;
    await updateStaffWorkflow(user.id, { step: "image", data: { participantReward } }, env);
    await sendTelegramMessage(env, chatId, "<b>Шаг 6 из 6</b>\n\nОтправьте HTTPS-ссылку или путь к изображению награды.\nАвтоматическая картинка по типу награды: <code>авто</code>.");
    return true;
  }
  if (workflow.step === "image") {
    const rawImage = text.trim();
    const imageUrl = /^(авто|auto|нет|none)$/i.test(rawImage) ? "" : rawImage;
    if (imageUrl && !/^(https:\/\/|\/assets\/)/i.test(imageUrl)) return sendTelegramMessage(env, chatId, "Укажите HTTPS-ссылку, путь <code>/assets/...</code> или <code>авто</code>."), true;
    const now = Math.floor(Date.now() / 1000);
    const eventId = safeEventId();
    const winnerReward = { ...(data.winnerReward || {}), imageUrl };
    const payload = {
      title: data.title,
      startsAt: Number(data.startsAt),
      endsAt: Number(data.endsAt),
      winnerReward,
      participantReward: data.participantReward,
      shop: { products: {}, discounts: {} },
      broadcasts: {
        start: `🏁 Событие «${data.title}» началось! Участвуйте в рейтинге до ${formatUtcDate(Number(data.endsAt))}.`,
        end: `🏆 Событие «${data.title}» завершено. Проверьте результаты и награды.`
      }
    };
    await env.DB.prepare(`INSERT INTO liveops_events (event_id,title,starts_at,ends_at,status,draft_json,published_json,runtime_snapshot_json,created_by,created_by_name,created_at,updated_at) VALUES (?,?,?,?,'draft',?,'{}','{}',?,?,?,?)`)
      .bind(eventId, data.title, Number(data.startsAt), Number(data.endsAt), JSON.stringify(payload), String(user.id), telegramDisplayName(user), now, now).run();
    await clearStaffWorkflow(user.id, env);
    await showSafeEventDetails(chatId, user, eventId, env);
    return true;
  }
  return true;
}

async function showSafeEventDetails(chatId, user, eventId, env) {
  const access = await requireSecurityPermission(chatId, user, "manageSeasons", env);
  if (!access) return;
  await ensureSafeControlCenterSchema(env);
  const row = await env.DB.prepare(`SELECT * FROM liveops_events WHERE event_id = ? LIMIT 1`).bind(eventId).first();
  if (!row) return sendTelegramMessage(env, chatId, "Событие не найдено.");
  const payload = safeJson(row.status === "draft" ? row.draft_json : row.published_json, {});
  const products = Object.entries(payload.shop?.products || {}).map(([id, item]) => `• ${id}: ${item.points} очк. / ${item.treats} зеф. / ${item.coffee} кофе`);
  const discounts = Object.entries(payload.shop?.discounts || {}).map(([id, percent]) => `• ${id}: −${percent}%`);
  const buttons = [[{ text: "👁 Предпросмотр", callback_data: `safe_event_preview:${row.event_id}` }]];
  if (row.status === "draft") buttons.push([{ text: "✅ Опубликовать", callback_data: `safe_event_publish:${row.event_id}` }, { text: "🗑 Отменить", callback_data: `safe_event_cancel:${row.event_id}` }]);
  if (["scheduled", "active"].includes(row.status)) buttons.push([{ text: "⛔ Отменить событие", callback_data: `safe_event_cancel:${row.event_id}` }]);
  buttons.push([{ text: "⬅️ События", callback_data: "safe_events" }]);
  await sendTelegramMessage(env, chatId,
    `<b>🗓 ${escapeHtml(row.title)}</b>\n\nID: <code>${escapeHtml(row.event_id)}</code>\nСтатус: <b>${escapeHtml(row.status)}</b>\nНачало: <b>${escapeHtml(formatUtcDate(row.starts_at))}</b>\nЗавершение: <b>${escapeHtml(formatUtcDate(row.ends_at))}</b>\n\nПервое место: <b>${escapeHtml(safeRewardDescription(payload.winnerReward))}</b>\nИзображение: ${payload.winnerReward?.imageUrl ? `<code>${escapeHtml(payload.winnerReward.imageUrl)}</code>` : "автоматическое"}\nУчастникам: <b>${escapeHtml(safeRewardDescription(payload.participantReward))}</b>\n\n<b>Временные товары</b>\n${products.join("\n") || "Не настроены."}\n\n<b>Скидки</b>\n${discounts.join("\n") || "Не настроены."}\n\nКоманды расширения:\n<code>/event_shop ${escapeHtml(row.event_id)} PRODUCT POINTS TREATS COFFEE</code>\n<code>/event_discount ${escapeHtml(row.event_id)} PRODUCT PERCENT</code>\n<code>/event_image ${escapeHtml(row.event_id)} URL_ИЛИ_АВТО</code>\n<code>/event_broadcast ${escapeHtml(row.event_id)} start ТЕКСТ</code>`,
    { inline_keyboard: buttons }
  );
}

async function patchSafeEventPayload(chatId, user, eventId, mutate, env) {
  const access = await requireSecurityPermission(chatId, user, "manageSeasons", env);
  if (!access) return;
  await ensureSafeControlCenterSchema(env);
  const row = await env.DB.prepare(`SELECT * FROM liveops_events WHERE event_id = ? AND status = 'draft' LIMIT 1`).bind(eventId).first();
  if (!row) return sendTelegramMessage(env, chatId, "Можно менять только неопубликованный черновик события.");
  const payload = safeJson(row.draft_json, {});
  mutate(payload);
  await env.DB.prepare(`UPDATE liveops_events SET draft_json = ?, updated_at = ? WHERE event_id = ?`).bind(JSON.stringify(payload), Math.floor(Date.now() / 1000), eventId).run();
  await showSafeEventDetails(chatId, user, eventId, env);
}

async function patchSafeEventShop(chatId, user, eventId, productId, points, treats, coffee, env) {
  if (!SHOP_ASSORTMENT_PRODUCTS[productId]) return sendTelegramMessage(env, chatId, "Неизвестный товар.");
  return patchSafeEventPayload(chatId, user, eventId, (payload) => {
    payload.shop ||= { products: {}, discounts: {} };
    payload.shop.products ||= {};
    payload.shop.products[productId] = { points: Math.max(0, Number(points)), treats: Math.max(0, Number(treats)), coffee: Math.max(0, Number(coffee)), enabled: true };
  }, env);
}

async function patchSafeEventDiscount(chatId, user, eventId, productId, percent, env) {
  if (!SHOP_ASSORTMENT_PRODUCTS[productId]) return sendTelegramMessage(env, chatId, "Неизвестный товар.");
  const discount = Math.max(1, Math.min(90, Number(percent || 0)));
  return patchSafeEventPayload(chatId, user, eventId, (payload) => {
    payload.shop ||= { products: {}, discounts: {} };
    payload.shop.discounts ||= {};
    payload.shop.discounts[productId] = discount;
  }, env);
}

async function patchSafeEventBroadcast(chatId, user, eventId, phase, text, env) {
  return patchSafeEventPayload(chatId, user, eventId, (payload) => {
    payload.broadcasts ||= {};
    payload.broadcasts[phase] = String(text || "").slice(0, 3500);
  }, env);
}

async function patchSafeEventImage(chatId, user, eventId, rawImage, env) {
  const value = String(rawImage || "").trim();
  const imageUrl = /^(авто|auto|нет|none)$/i.test(value) ? "" : value;
  if (imageUrl && !/^(https:\/\/|\/assets\/)/i.test(imageUrl)) return sendTelegramMessage(env, chatId, "Укажите HTTPS-ссылку, путь <code>/assets/...</code> или <code>авто</code>.");
  return patchSafeEventPayload(chatId, user, eventId, (payload) => {
    payload.winnerReward ||= {};
    payload.winnerReward.imageUrl = imageUrl;
  }, env);
}

async function previewSafeEvent(chatId, user, eventId, env) {
  const access = await requireSecurityPermission(chatId, user, "manageSeasons", env);
  if (!access) return;
  const row = await env.DB.prepare(`SELECT * FROM liveops_events WHERE event_id = ? LIMIT 1`).bind(eventId).first();
  if (!row) return sendTelegramMessage(env, chatId, "Событие не найдено.");
  const payload = safeJson(row.status === "draft" ? row.draft_json : row.published_json, {});
  await sendTelegramMessage(env, chatId,
    `<b>👁 Как событие увидит игрок</b>\n\n🏁 <b>${escapeHtml(row.title)}</b>\n${escapeHtml(formatUtcDate(row.starts_at))} — ${escapeHtml(formatUtcDate(row.ends_at))}\n\n🏆 Первое место: <b>${escapeHtml(safeRewardDescription(payload.winnerReward))}</b>\n🖼 Изображение: ${payload.winnerReward?.imageUrl ? `<code>${escapeHtml(payload.winnerReward.imageUrl)}</code>` : "автоматическое"}\n🎁 Участникам: <b>${escapeHtml(safeRewardDescription(payload.participantReward))}</b>\n\nСообщение о старте:\n${escapeHtml(payload.broadcasts?.start || "не задано")}\n\nСообщение о завершении:\n${escapeHtml(payload.broadcasts?.end || "не задано")}`,
    { inline_keyboard: [[{ text: "⬅️ К событию", callback_data: `safe_event:${row.event_id}` }]] }
  );
}

async function publishSafeEvent(query, eventId, env) {
  const chatId = query.message?.chat?.id;
  const access = await requireSecurityPermission(chatId, query.from, "manageSeasons", env);
  if (!access) return;
  const row = await env.DB.prepare(`SELECT * FROM liveops_events WHERE event_id = ? AND status = 'draft' LIMIT 1`).bind(eventId).first();
  if (!row) return answerCallback(env, query.id, "Событие не найдено или уже опубликовано.", true);
  const payload = safeJson(row.draft_json, {});
  const fakeDraft = { entity_type: "event", draft_json: JSON.stringify(payload) };
  const validation = await validateSafeDraftRow(fakeDraft, env);
  if (!validation.ok) return answerCallback(env, query.id, "Событие не прошло проверку.", true);
  const overlap = await env.DB.prepare(`SELECT event_id,title FROM liveops_events WHERE event_id <> ? AND status IN ('scheduled','active') AND starts_at < ? AND ends_at > ? LIMIT 1`).bind(eventId, row.ends_at, row.starts_at).first();
  if (overlap) return answerCallback(env, query.id, `Пересекается с событием «${overlap.title}».`, true);
  const now = Math.floor(Date.now() / 1000);
  await env.DB.prepare(`UPDATE liveops_events SET status = 'scheduled', published_json = draft_json, published_at = ?, updated_at = ?, last_error = '' WHERE event_id = ?`).bind(now, now, eventId).run();
  await answerCallback(env, query.id, "Событие опубликовано и поставлено в расписание.");
  await showSafeEventDetails(chatId, query.from, eventId, env);
}

async function cancelSafeEvent(query, eventId, env) {
  const chatId = query.message?.chat?.id;
  const access = await requireSecurityPermission(chatId, query.from, "manageSeasons", env);
  if (!access) return;
  const row = await env.DB.prepare(`SELECT * FROM liveops_events WHERE event_id = ? LIMIT 1`).bind(eventId).first();
  if (!row) return answerCallback(env, query.id, "Событие не найдено.", true);
  if (row.status === "active") await finishSafeEvent(row, env, true);
  await env.DB.prepare(`UPDATE liveops_events SET status = 'cancelled', updated_at = ?, completed_at = CASE WHEN completed_at = 0 THEN ? ELSE completed_at END WHERE event_id = ?`).bind(Math.floor(Date.now() / 1000), Math.floor(Date.now() / 1000), eventId).run();
  await answerCallback(env, query.id, "Событие отменено.");
  await showSafeEventsDashboard(chatId, query.from, env);
}

async function queueSystemBroadcast(env, text, reportChatId = "", dedupeKey = "") {
  const messageText = String(text || "").trim();
  if (!messageText) return null;
  await ensureBotBroadcastSchema(env);
  const totalRow = await env.DB.prepare(`SELECT COUNT(*) AS total FROM bot_subscribers WHERE active = 1`).first();
  const total = Number(totalRow?.total || 0);
  if (!total) return null;
  const now = Math.floor(Date.now() / 1000);
  const normalizedKey = String(dedupeKey || "").trim().replace(/[^A-Za-z0-9_-]/g, "_").slice(0, 96);
  const id = normalizedKey ? `system_${normalizedKey}` : caseGrantId("event_post");
  await env.DB.batch([
    env.DB.prepare(`INSERT OR IGNORE INTO bot_broadcasts (broadcast_id,message_text,created_by,report_chat_id,created_at,status,total_count,sent_count,failed_count,updated_at,completed_at,completion_notified,lease_token,lease_until) VALUES (?,?, 'system', ?, ?, 'pending', ?,0,0,?,0,0,'',0)`).bind(id, messageText, String(reportChatId || ""), now, total, now),
    env.DB.prepare(`INSERT OR IGNORE INTO bot_broadcast_deliveries (broadcast_id,subscriber_id,telegram_id,status,attempts,error_text,attempted_at) SELECT ?,id,telegram_id,'pending',0,'',0 FROM bot_subscribers WHERE active = 1`).bind(id)
  ]);
  return id;
}

const SEASON_START_BROADCAST_SCAN_STATE_KEY = "season_start_broadcast:last_scan_v1";

function ratingSeasonStartBroadcastText(season) {
  const reward = leaderboardRewardPresentation(season?.reward_type, season?.reward_amount, season?.reward_item_id, season?.reward_title, season?.reward_image_url);
  return [
    "🏆 Новый сезон рейтинга стартовал!",
    "",
    `«${String(season?.title || "Новый сезон") }» уже идёт в «Сладком Забеге».`,
    `Награда за 1 место: ${reward.title}.`,
    `Сезон завершится ${formatUtcDate(Number(season?.ends_at || 0))}.`,
    "",
    "Заходи в игру и поборись за первое место!"
  ].join("\n");
}

function seasonPassStartBroadcastText(row) {
  return [
    "🎟 Новый сезон сезонного пропуска стартовал!",
    "",
    `«${String(row?.title || "Новый сезон") }» уже открыт в «Сладком Забеге».`,
    "Выполняй задания, получай XP и забирай награды бесплатной и Элитной линий.",
    `Сезон завершится ${formatUtcDate(Number(row?.ends_at || 0))}.`,
    "",
    "Открой сезонный пропуск в профиле игры."
  ].join("\n");
}

async function queueRatingSeasonStartBroadcast(env, season) {
  if (!season?.id) return null;
  return queueSystemBroadcast(env, ratingSeasonStartBroadcastText(season), "", `rating_season_start_${String(season.id)}`);
}

async function queueSeasonPassStartBroadcast(env, row) {
  if (!row?.season_id) return null;
  return queueSystemBroadcast(env, seasonPassStartBroadcastText(row), "", `season_pass_start_${String(row.season_id)}`);
}

async function processSeasonStartBroadcasts(env) {
  const now = Math.floor(Date.now() / 1000);
  const state = await getSystemState(env, SEASON_START_BROADCAST_SCAN_STATE_KEY);
  const previous = Math.max(0, Number(state?.value || 0));
  const since = previous > 0 ? Math.min(previous, now) : Math.max(0, now - 10 * 60);
  await reconcileLeaderboardSeasonTimeline(env, now);
  await ensureSeasonPassSchema(env);
  const [ratingsResult, passResult] = await Promise.all([
    env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE status='active' AND finalized_at IS NULL AND starts_at>=? AND starts_at<=? AND ends_at>? ORDER BY starts_at,id`).bind(since, now, now).all(),
    env.DB.prepare(`SELECT * FROM season_pass_seasons WHERE manual_status!='ended' AND starts_at>=? AND starts_at<=? AND ends_at>? ORDER BY starts_at,season_id`).bind(since, now, now).all()
  ]);
  let ratingQueued = 0;
  let passQueued = 0;
  for (const season of ratingsResult.results || []) {
    const id = await queueRatingSeasonStartBroadcast(env, season);
    if (id) ratingQueued += 1;
  }
  for (const row of passResult.results || []) {
    const season = seasonPassSeasonFromRow(row, configuredSeasonPassState(env, now * 1000), now * 1000);
    if (season.status !== "active") continue;
    const closure = await getSeasonPassForcedClosure(env, now * 1000);
    if (closure && closure.nextSeasonId !== String(row.season_id || "")) continue;
    const id = await queueSeasonPassStartBroadcast(env, row);
    if (id) passQueued += 1;
  }
  await setSystemState(env, SEASON_START_BROADCAST_SCAN_STATE_KEY, String(now));
  return { since, now, ratingQueued, passQueued };
}

async function restoreSafeEventShop(row, env, reason = "event_restore") {
  const snapshot = safeJson(row?.runtime_snapshot_json, {});
  if (!snapshot.shop) return;
  await ensureShopAssortmentSchema(env);
  const now = Math.floor(Date.now() / 1000);
  for (const [productId, item] of Object.entries(snapshot.shop)) {
    await env.DB.prepare(`UPDATE shop_assortment SET enabled=?,points=?,treats=?,coffee=?,updated_at=?,updated_by=? WHERE product_id=?`)
      .bind(item.enabled ? 1 : 0, Number(item.points || 0), Number(item.treats || 0), Number(item.coffee || 0), now, `${reason}:${row.event_id}`, productId).run();
  }
}

async function startSafeEvent(row, env) {
  const payload = safeJson(row.published_json, {});
  const now = Math.floor(Date.now() / 1000);
  await ensureShopAssortmentSchema(env);
  const savedSnapshot = safeJson(row.runtime_snapshot_json, {});
  const currentShop = savedSnapshot.shop || await readShopAssortment(env);
  const snapshot = savedSnapshot.shop ? savedSnapshot : { shop: currentShop };
  if (!savedSnapshot.shop) {
    await env.DB.prepare(`UPDATE liveops_events SET runtime_snapshot_json = ?, updated_at = ? WHERE event_id = ?`)
      .bind(JSON.stringify(snapshot), now, row.event_id).run();
  }
  const productChanges = payload.shop?.products || {};
  const discounts = payload.shop?.discounts || {};
  for (const [productId, current] of Object.entries(currentShop)) {
    const override = productChanges[productId] || {};
    const discount = Math.max(0, Math.min(90, Number(discounts[productId] || 0)));
    const base = { ...current, ...override };
    const factor = (100 - discount) / 100;
    await env.DB.prepare(`UPDATE shop_assortment SET enabled = ?, points = ?, treats = ?, coffee = ?, updated_at = ?, updated_by = ? WHERE product_id = ?`)
      .bind(base.enabled === false ? 0 : 1, Math.floor(Number(base.points || 0) * factor), Math.floor(Number(base.treats || 0) * factor), Math.floor(Number(base.coffee || 0) * factor), now, `event:${row.event_id}`, productId).run();
  }
  const winner = payload.winnerReward || { kind: "case", id: "legendary", amount: 1 };
  const presentation = leaderboardRewardPresentation(winner.kind === "zefir" ? "treats" : winner.kind, winner.amount, winner.id, winner.title, winner.imageUrl || "");
  const seasonId = `event_${row.event_id}`;
  await env.DB.prepare(`INSERT INTO leaderboard_seasons (id,title,starts_at,ends_at,status,reward_type,reward_amount,reward_claim_days,reset_plan_json,close_reason,created_at,updated_at,finalized_at,manual_override,reward_title,reward_image_url,reward_item_id) VALUES (?,?,?,?,'active',?, ?,30,?,'',?,?,NULL,1,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,starts_at=excluded.starts_at,ends_at=excluded.ends_at,status='active',reward_type=excluded.reward_type,reward_amount=excluded.reward_amount,reward_title=excluded.reward_title,reward_image_url=excluded.reward_image_url,reward_item_id=excluded.reward_item_id,manual_override=1,updated_at=excluded.updated_at`)
    .bind(seasonId, row.title, row.starts_at, row.ends_at, presentation.type, presentation.amount, JSON.stringify(DEFAULT_SEASON_RESET_PLAN), now, now, presentation.title, presentation.imageUrl, presentation.itemId).run();
  await env.DB.prepare(`UPDATE liveops_events SET status='active',runtime_snapshot_json=?,started_at=CASE WHEN started_at=0 THEN ? ELSE started_at END,updated_at=?,start_notified=0,last_error='',lease_token='',lease_until=0 WHERE event_id=?`).bind(JSON.stringify(snapshot), now, now, row.event_id).run();
  invalidateActiveRunLiveOpsCache();
  await queueSystemBroadcast(env, payload.broadcasts?.start || `🏁 Событие «${row.title}» началось!`, "", `event_${row.event_id}_start`);
  await env.DB.prepare(`UPDATE liveops_events SET start_notified=1,updated_at=? WHERE event_id=?`).bind(now,row.event_id).run();
}

async function enqueueRewardDelivery(env, telegramId, sourceType, sourceId, reward, reason, reportChatId = "") {
  await ensureSafeControlCenterSchema(env);
  if (!reward || reward.kind === "none") return 0;
  const now = Math.floor(Date.now() / 1000);
  const result = await env.DB.prepare(`INSERT OR IGNORE INTO reward_delivery_queue (telegram_id,source_type,source_id,reward_kind,reward_id,amount,reason,payload_json,status,attempts,last_error,available_at,created_at,updated_at,notify_after,report_chat_id,lease_token,lease_until) VALUES (?,?,?,?,?,?,?,'{}','pending',0,'',?,?,?, ?,?,'',0)`)
    .bind(String(telegramId), String(sourceType), String(sourceId), String(reward.kind), String(reward.id || ""), Math.max(1, Number(reward.amount || 1)), String(reason || "").slice(0, 300), now, now, now, now + 900, String(reportChatId || "")).run();
  return Number(result.meta?.last_row_id || 0);
}

async function finishSafeEvent(row, env, cancelled = false) {
  const payload = safeJson(row.published_json, {});
  const snapshot = safeJson(row.runtime_snapshot_json, {});
  const now = Math.floor(Date.now() / 1000);
  await restoreSafeEventShop(row, env, "event_restore");
  const seasonId = `event_${row.event_id}`;
  const season = await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id = ? LIMIT 1`).bind(seasonId).first();
  if (season && !season.finalized_at) {
    await env.DB.prepare(`UPDATE leaderboard_seasons SET ends_at=?,status='ended',updated_at=? WHERE id=?`).bind(now, now, seasonId).run();
    const updated = await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();
    await finalizeSeason(env, updated, now);
  }
  if (!cancelled && payload.participantReward?.kind && payload.participantReward.kind !== "none") {
    const participants = await env.DB.prepare(`SELECT telegram_id FROM leaderboard_entries WHERE season_id = ? AND hidden = 0`).bind(seasonId).all();
    for (const participant of participants.results || []) {
      await enqueueRewardDelivery(env, participant.telegram_id, "event_participant", row.event_id, payload.participantReward, `Участие в событии «${row.title}»`);
    }
  }
  await env.DB.prepare(`UPDATE liveops_events SET status=?,completed_at=CASE WHEN completed_at=0 THEN ? ELSE completed_at END,updated_at=?,end_notified=0,last_error='',lease_token='',lease_until=0 WHERE event_id=?`).bind(cancelled ? "cancelled" : "completed", now, now, row.event_id).run();
  invalidateActiveRunLiveOpsCache();
  await queueSystemBroadcast(env, cancelled ? `⛔ Событие «${row.title}» отменено.` : (payload.broadcasts?.end || `🏆 Событие «${row.title}» завершено.`), "", `event_${row.event_id}_${cancelled ? "cancel" : "end"}`);
  await env.DB.prepare(`UPDATE liveops_events SET end_notified=1,updated_at=? WHERE event_id=?`).bind(now,row.event_id).run();
}

async function deliverQueuedReward(env, row, leaseToken) {
  await ensurePlayerAccountRevisionAvailable(env);
  const amount = Math.max(1, Math.floor(Number(row.amount || 1)));
  const telegramId = String(row.telegram_id);
  const queueId = Math.max(1, Math.floor(Number(row.id || 0)));
  const token = String(leaseToken || "");
  if (!queueId || !token) throw new Error("Некорректная блокировка очереди наград");
  const now = Math.floor(Date.now() / 1000);

  // Wallet-like rewards need admin_profile_state before the atomic fold.
  // Pure case grants do not: granted_cases is authoritative on its own. Skipping
  // the profile bootstrap for case-only gifts removes a costly DB fold from the
  // player's synchronous claim path without changing the economic transaction.
  const rewardKind = String(row.reward_kind || "");
  if (["points", "zefir", "coffee"].includes(rewardKind)) {
    await ensureAuthoritativeProfileRow(env, telegramId, `queue-profile:${queueId}`);
  }

  let cosmeticDuplicate = false;
  let cosmeticId = "";
  let cosmeticColumn = "";
  let seasonPassDelivery = null;
  if (rewardKind === "season_pass_xp_grant" || rewardKind === "season_pass_tier") {
    await ensureSeasonPassSchema(env);
    let seasonId = "";
    let requestedTier = "";
    if (rewardKind === "season_pass_tier") {
      const rawId = String(row.reward_id || "").trim();
      const divider = rawId.lastIndexOf("|");
      seasonId = divider > 0 ? rawId.slice(0, divider) : "";
      requestedTier = divider > 0 ? rawId.slice(divider + 1) : "";
      if (!/^[A-Za-z0-9_-]{1,120}$/.test(seasonId) || !["elite", "elite_plus"].includes(requestedTier)) throw new Error("Некорректный тариф сезонного пропуска");
    } else {
      seasonId = String(row.reward_id || "").trim();
      if (!/^[A-Za-z0-9_-]{1,120}$/.test(seasonId)) throw new Error("Некорректный сезон для XP сезонного пропуска");
    }
    const season = await loadSeasonPassSeasonById(env, seasonId);
    if (!season) throw new Error("Сезон сезонного пропуска не найден");
    if (String(season.status || "") === "scheduled") throw new Error("Сезон сезонного пропуска ещё не начался");
    if (String(season.status || "") === "ended" && !season.claimWindowOpen) throw new Error("Сезон сезонного пропуска уже завершён");
    const player = await ensureSeasonPassPlayer(env, season, telegramId);
    if (rewardKind === "season_pass_tier") {
      const currentTier = ["elite", "elite_plus"].includes(String(player?.premium_tier)) ? String(player.premium_tier) : "none";
      const duplicate = currentTier === requestedTier || (currentTier === "elite_plus" && requestedTier === "elite");
      let plan = null;
      let compensation = null;
      if (duplicate) {
        await ensureAuthoritativeProfileRow(env, telegramId, `queue-pass-comp:${queueId}`);
        compensation = ownerPanelSeasonPassPrice(season, requestedTier);
      } else if (requestedTier === "elite_plus") {
        plan = await elitePlusBenefitPlan(env, { season, telegramId, player }, player, now, {
          source:`queue-season-pass:${queueId}`,
          bonusAlreadyGranted:Boolean(Number(player?.elite_plus_bonus_granted || 0))
        });
      }
      seasonPassDelivery = { kind:rewardKind, season, player, requestedTier, currentTier, duplicate, compensation, plan };
    } else {
      seasonPassDelivery = { kind:rewardKind, season, player };
    }
  }
  let runBoosterReward = null;
  if (rewardKind === "booster") {
    runBoosterReward = runBoosterDefinition(row.reward_id);
    if (!runBoosterReward) throw new Error("Неизвестный усилитель");
    if (amount > 999) throw new Error("Количество усилителей превышает безопасный лимит");
    await ensureCasePlayerState(env, telegramId, {});
  }
  let showcaseStyleReward=null;
  if(rewardKind==="showcase_style"){
    await ensureAchievementConfigSchema(env);
    showcaseStyleReward=achievementShowcaseRewardStyleDefinition(row.reward_id);
    if(!showcaseStyleReward){
      const directStyle=achievementShowcaseDirectGrantStyleDefinition(row.reward_id);
      if(directStyle?.manualOnly===true&&String(row.source_type||"")==="gift_inbox"){
        const giftId=String(row.source_id||"").replace(/_\d+$/,"");
        const gift=giftId?await env.DB.prepare(`SELECT gift_kind FROM player_gift_inbox WHERE telegram_id=? AND gift_id=? LIMIT 1`).bind(telegramId,giftId).first():null;
        if(String(gift?.gift_kind||"")==="compensation")showcaseStyleReward=directStyle;
      }
    }
    if(!showcaseStyleReward)throw new Error("Неизвестное оформление витрины");
    const current=await env.DB.prepare(`SELECT 1 AS ok FROM achievement_showcase_style_ownership WHERE telegram_id=? AND style_id=? LIMIT 1`).bind(telegramId,String(showcaseStyleReward.id)).first();cosmeticDuplicate=Boolean(current);cosmeticId=String(showcaseStyleReward.id);
  } else if (["avatar", "frame", "trail", "skin", "music"].includes(row.reward_kind)) {
    await ensureCasePlayerState(env, telegramId, {});
    if (row.reward_kind === "skin") {
      cosmeticId = String(row.reward_id || "").trim().toLowerCase();
      if (!(SKINS[cosmeticId] || futureSeasonContentItem("skin",cosmeticId)) || cosmeticId === "default") throw new Error("Неизвестный косметический предмет");
      cosmeticColumn = "owned_skins_json";
    } else if (row.reward_kind === "music") {
      cosmeticId = String(row.reward_id || "").trim();
      const music=seasonPassAnyCosmeticCatalog("music")?.[cosmeticId];
      if (!music) throw new Error("Неизвестный музыкальный трек");
      cosmeticColumn = "owned_music_json";
    } else {
      cosmeticId = normalizeCaseCosmeticId(row.reward_kind, row.reward_id);
      if (!cosmeticId) throw new Error("Неизвестный косметический предмет");
      cosmeticColumn = ({ avatar:"owned_avatars_json", frame:"owned_frames_json", trail:"owned_trails_json" })[row.reward_kind];
    }
    if(futureSeasonContentItem(row.reward_kind,cosmeticId)){
      const routeType=liveContentRewardQueueRoute(row.source_type);
      if(routeType==='story'){
        const rules=await readLiveContentReleaseRules(env,true),rule=rules.get(liveContentReleaseKey(row.reward_kind,cosmeticId)),storyEvent=await env.DB.prepare(`SELECT season_id FROM season_pass_story_events WHERE event_id=? LIMIT 1`).bind(String(row.source_id||'')).first();
        if(!rule?.released||!storyEvent?.season_id||String(rule.seasonId||'')!==String(storyEvent.season_id)||!liveContentRouteEnabled(rule,'story'))throw new Error('Косметический предмет недоступен через сюжет этого сезона');
      }else if(!(await liveContentRouteAllowed(env,row.reward_kind,cosmeticId,routeType)))throw new Error(`Косметический предмет недоступен через канал ${routeType}`);
    }
    const current = await env.DB.prepare(`SELECT ${cosmeticColumn} AS owned FROM case_player_state WHERE telegram_id=? LIMIT 1`).bind(telegramId).first();
    let owned = [];
    try { owned = JSON.parse(String(current?.owned || "[]")); } catch {}
    cosmeticDuplicate = Array.isArray(owned) && owned.map((value) => String(value || "").toLowerCase()).includes(cosmeticId.toLowerCase());
  } else if (row.reward_kind === "seasonal_case") {
    await ensureSeasonPassSchema(env);
    const caseId=String(row.reward_id||'').trim();
    const definition=await env.DB.prepare(`SELECT case_id,season_id,title,description,closed_image_url,open_image_url,slots,duplicate_points,reward_groups_json,enabled,release_at FROM season_pass_case_definitions WHERE case_id=? LIMIT 1`).bind(caseId).first();
    if(!definition||!Number(definition.enabled||0))throw new Error("Сезонный кейс отключён");
    if(Number(definition.release_at||0)>now)throw new Error("Сезонный кейс ещё не выпущен");
    const caseItems=await seasonPassEffectiveCaseItems(env,caseId);
    if(!caseItems.length)throw new Error("В сезонном кейсе пока нет наград");
    row.__seasonalCase={definition,caseItems};
  } else if (row.reward_kind === "physical_restore") {
    throw new Error("Требуется ручная проверка и восстановление физического кода");
  } else if (!["points", "zefir", "coffee", "case", "booster", "season_pass_tier", "season_pass_xp_grant", "showcase_style"].includes(row.reward_kind)) {
    throw new Error("Неизвестный тип награды");
  }

  const statements = [
    env.DB.prepare(
      `INSERT OR IGNORE INTO reward_delivery_effects(queue_id,telegram_id,reward_kind,reward_id,apply_token,applied_at)
       SELECT ?,?,?,?,?,? WHERE EXISTS(
         SELECT 1 FROM reward_delivery_queue WHERE id=? AND status='delivering' AND lease_token=?
       )`
    ).bind(queueId, telegramId, String(row.reward_kind), String(row.reward_id || ""), token, now, queueId, token)
  ];

  if (["points", "zefir", "coffee"].includes(row.reward_kind)) {
    const field = ({ points: "pending_wallet", zefir: "pending_treats", coffee: "pending_coffee" })[row.reward_kind];
    statements.push(env.DB.prepare(
      `UPDATE admin_profile_state SET ${field}=${field}+?,revision=revision+1,updated_at=?,updated_by=?
       WHERE telegram_id=? AND EXISTS(
         SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?
       )`
    ).bind(amount, now, `queue:${queueId}`, telegramId, queueId, token));
  } else if (row.reward_kind === "case") {
    const caseType = normalizeCaseType(row.reward_id);
    if (!caseType) throw new Error("Неизвестный тип кейса");
    const quantity = Math.max(1, Math.min(20, amount));
    for (let index = 0; index < quantity; index += 1) {
      const grantId = `queuecase_${queueId}_${index + 1}`;
      statements.push(env.DB.prepare(
        `INSERT OR IGNORE INTO granted_cases(id,telegram_id,case_type,status,granted_by,reason,created_at)
         SELECT ?,?,?,'pending',?,?,? WHERE EXISTS(
           SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?
         )`
      ).bind(grantId, telegramId, caseType, `queue:${queueId}`, String(row.reason || "").slice(0,300), now, queueId, token));
    }
  } else if (row.reward_kind === "booster") {
    if (!runBoosterReward) throw new Error("Неизвестный усилитель");
    const boosterId = runBoosterReward.id;
    if (CASE_REWARD_BOOSTER_TYPES.includes(boosterId)) {
      const column = boosterId === "points" ? "boosters_points" : boosterId === "treats" ? "boosters_treats" : "boosters_coffee";
      statements.push(env.DB.prepare(
        `UPDATE case_player_state SET ${column}=MAX(0,${column})+?,revision=revision+1,updated_at=?
         WHERE telegram_id=? AND EXISTS(SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?)`
      ).bind(amount,now,telegramId,queueId,token));
    } else {
      const jsonPath = `$.${boosterId}`;
      statements.push(env.DB.prepare(
        `UPDATE case_player_state SET boosters_extra_json=json_set(CASE WHEN json_valid(boosters_extra_json) THEN boosters_extra_json ELSE '{}' END,'${jsonPath}',MAX(0,CAST(COALESCE(json_extract(CASE WHEN json_valid(boosters_extra_json) THEN boosters_extra_json ELSE '{}' END,'${jsonPath}'),0) AS INTEGER))+?),revision=revision+1,updated_at=?
         WHERE telegram_id=? AND EXISTS(SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?)`
      ).bind(amount,now,telegramId,queueId,token));
    }
  } else if (row.reward_kind === "seasonal_case") {
    const definition=row.__seasonalCase?.definition,caseItems=row.__seasonalCase?.caseItems||[];
    if(!definition||!caseItems.length)throw new Error("Сезонный кейс недоступен");
    const caseId=String(definition.case_id),caseSnapshot=JSON.stringify({title:String(definition.title||'Сезонный кейс'),description:String(definition.description||''),imageUrl:String(definition.closed_image_url||''),openImageUrl:String(definition.open_image_url||''),slots:Math.max(1,Math.min(5,Number(definition.slots)||1)),duplicatePoints:Math.max(0,Number(definition.duplicate_points)||0),groupChances:seasonPassSeasonalCaseGroupChances(definition.reward_groups_json),items:caseItems.map(item=>({key:String(item.item_key),kind:String(item.reward_kind),itemId:String(item.item_id),amount:Math.max(1,Number(item.amount||1)),weight:Number(item.weight||1),rarity:String(item.rarity||'seasonal'),title:String(item.title||''),imageUrl:String(item.image_url||'')}))});
    const quantity=Math.max(1,Math.min(20,amount));
    for(let index=0;index<quantity;index+=1){const grantId=`queue_spcase_${queueId}_${index+1}`.slice(0,190);statements.push(env.DB.prepare(`INSERT OR IGNORE INTO season_pass_case_grants(grant_id,case_id,source_season_id,telegram_id,status,rewards_json,snapshot_json,granted_by,created_at) SELECT ?,?,?,?,'pending','[]',?,?,? WHERE EXISTS(SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?)`).bind(grantId,caseId,String(definition.season_id||''),telegramId,caseSnapshot,`queue:${queueId}`,now,queueId,token));}
  } else if (row.reward_kind === "showcase_style") {
    statements.push(env.DB.prepare(`INSERT OR IGNORE INTO achievement_showcase_style_ownership(telegram_id,style_id,source_type,source_id,unlocked_at,updated_at) SELECT ?,?,?,?,?,? WHERE EXISTS(SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?)`).bind(telegramId,String(showcaseStyleReward.id),String(row.source_type||"queue"),String(row.source_id||queueId),now,now,queueId,token));
  } else if (["avatar", "frame", "trail", "skin", "music"].includes(row.reward_kind)) {
    statements.push(env.DB.prepare(
      `UPDATE case_player_state SET ${cosmeticColumn}=CASE
         WHEN EXISTS(
           SELECT 1 FROM json_each(CASE WHEN json_valid(${cosmeticColumn}) THEN ${cosmeticColumn} ELSE '[]' END)
           WHERE lower(CAST(value AS TEXT))=lower(?)
         ) THEN CASE WHEN json_valid(${cosmeticColumn}) THEN ${cosmeticColumn} ELSE '[]' END
         ELSE json_insert(CASE WHEN json_valid(${cosmeticColumn}) THEN ${cosmeticColumn} ELSE '[]' END,'$[#]',?)
       END,revision=revision+1,updated_at=?
       WHERE telegram_id=? AND EXISTS(
         SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?
       )`
    ).bind(cosmeticId, cosmeticId, now, telegramId, queueId, token));
  } else if (row.reward_kind === "season_pass_xp_grant") {
    if (!seasonPassDelivery?.season) throw new Error("Сезонный пропуск недоступен");
    statements.push(env.DB.prepare(
      `UPDATE season_pass_players SET xp=xp+?,revision=revision+1,updated_at=?
       WHERE season_id=? AND telegram_id=? AND EXISTS(
         SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?
       )`
    ).bind(amount, now, seasonPassDelivery.season.id, telegramId, queueId, token));
  } else if (row.reward_kind === "season_pass_tier") {
    if (!seasonPassDelivery?.season) throw new Error("Сезонный пропуск недоступен");
    if (seasonPassDelivery.duplicate) {
      const compensation = seasonPassDelivery.compensation || { points:0, treats:0, coffee:0 };
      statements.push(env.DB.prepare(
        `UPDATE admin_profile_state SET pending_wallet=pending_wallet+?,pending_treats=pending_treats+?,pending_coffee=pending_coffee+?,revision=revision+1,updated_at=?,updated_by=?
         WHERE telegram_id=? AND EXISTS(SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?)`
      ).bind(compensation.points, compensation.treats, compensation.coffee, now, `queue-pass-comp:${queueId}`, telegramId, queueId, token));
    } else if (seasonPassDelivery.requestedTier === "elite") {
      statements.push(env.DB.prepare(
        `UPDATE season_pass_players SET premium_tier=CASE WHEN premium_tier='elite_plus' THEN 'elite_plus' ELSE 'elite' END,revision=revision+1,updated_at=?
         WHERE season_id=? AND telegram_id=? AND EXISTS(SELECT 1 FROM reward_delivery_effects WHERE queue_id=? AND apply_token=?)`
      ).bind(now, seasonPassDelivery.season.id, telegramId, queueId, token));
    } else {
      const plan = seasonPassDelivery.plan;
      if (!plan?.statements?.length) throw new Error("Не удалось подготовить выдачу тарифа Элитный+");
      statements.push(...plan.statements);
    }
  }

  // Every successful queued economic delivery advances one global account revision.
  // Table triggers cover direct/legacy mutations; this explicit bump also covers
  // pending-wallet writes that are folded into the visible profile later.
  statements.push(bumpPlayerAccountRevisionStatement(env, telegramId, now));

  statements.push(env.DB.prepare(
    `UPDATE reward_delivery_queue
     SET status='delivered',attempts=attempts+1,last_error='',delivered_at=?,updated_at=?,lease_token='',lease_until=0
     WHERE id=? AND lease_token=? AND EXISTS(SELECT 1 FROM reward_delivery_effects WHERE queue_id=?)`
  ).bind(now, now, queueId, token, queueId));

  const results = await env.DB.batch(statements);
  if (Number(results?.[results.length - 1]?.meta?.changes || 0) !== 1) {
    throw new Error("Не удалось атомарно завершить доставку награды");
  }

  // A gift can be delivered by the dedicated claim worker, startup maintenance,
  // or cron. Whichever worker commits the final queue row also closes the inbox
  // item immediately. This removes the race where the reward is already on the
  // account but the player still sees "Получаем…" / a second "Забрать".
  if (String(row.source_type || "") === "gift_inbox") {
    try {
      const inboxFinalize = await env.DB.prepare(`UPDATE player_gift_inbox
        SET status='claimed',claimed_at=CASE WHEN claimed_at>0 THEN claimed_at ELSE ? END,updated_at=?
        WHERE telegram_id=? AND status IN ('pending','claiming') AND ? GLOB (gift_id || '_*')
          AND NOT EXISTS(
            SELECT 1 FROM reward_delivery_queue q
            WHERE q.telegram_id=? AND q.source_type='gift_inbox'
              AND q.source_id GLOB (player_gift_inbox.gift_id || '_*') AND q.status<>'delivered'
          )`).bind(now,now,telegramId,String(row.source_id || ""),telegramId).run();
      if (Number(inboxFinalize?.meta?.changes || 0) > 0) {
        await bumpPlayerAccountRevisionStatement(env,telegramId,now).run();
      }
    } catch (error) {
      // Economic delivery has already committed. Inbox self-heal in
      // maintainPlayerGiftInboxState will finish the presentation state later.
      console.error("gift inbox finalization after delivery failed", error);
    }
  }

  // Everything below is non-economic side effect. A notification/timeline
  // failure must never make the atomic reward transaction retry.
  if (row.reward_kind === "season_pass_tier" && seasonPassDelivery?.season && !seasonPassDelivery.duplicate) {
    let updatedPlayer = await env.DB.prepare(`SELECT * FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(seasonPassDelivery.season.id, telegramId).first().catch(()=>null);
    if (seasonPassDelivery.requestedTier === "elite_plus" && updatedPlayer) {
      try { updatedPlayer = await reconcileElitePlusTaskXpBoost(env, seasonPassDelivery.season, telegramId, updatedPlayer); } catch (error) { console.error("queued elite plus task xp reconcile failed", error); }
    }
    const premiumTier = String(updatedPlayer?.premium_tier || seasonPassDelivery.requestedTier);
    try {
      await queueSeasonPassTierActivationNotice(env,{
        season:seasonPassDelivery.season, telegramId, previousTier:seasonPassDelivery.currentTier, newTier:premiumTier,
        source:"compensation_gift", sourceKey:`queue:${queueId}`, activatedAt:now,
        payload:seasonPassDelivery.requestedTier === "elite_plus" ? (seasonPassDelivery.plan?.activation || {}) : {fromLevel:seasonPassLevelFromXp(seasonPassDelivery.player?.xp),toLevel:seasonPassLevelFromXp(seasonPassDelivery.player?.xp),bonusLevels:0}
      });
    } catch (error) { console.error("queued season pass activation notice failed", error); }
  }
  const rewardDescription = safeRewardDescription({ kind: row.reward_kind, id: row.reward_id, amount });
  // gift_inbox already writes one consolidated gift_claim timeline entry after
  // all rewards are committed. Avoid a duplicate synchronous timeline write for
  // every reward in the same gift.
  if (String(row.source_type || "") !== "gift_inbox") {
    try {
      await recordPlayerTimeline(env, telegramId, "reward_delivery", cosmeticDuplicate ? `получил дубликат: ${rewardDescription}` : `получил ${rewardDescription}`, { queueId, sourceType: row.source_type, sourceId: row.source_id, reason: row.reason, duplicate: cosmeticDuplicate }, `queue_${queueId}`, null);
    } catch (error) { console.error("reward delivery timeline failed", error); }
  }
  if (["avatar", "frame", "trail", "skin", "music"].includes(row.reward_kind)) {
    try { await recordContentAnalyticsEvent(env, telegramId, row.reward_kind, cosmeticId || row.reward_id, cosmeticDuplicate ? "duplicate" : "acquired", row.source_type, row.source_id); } catch (error) { console.error("reward delivery analytics failed", error); }
  }
  if (!["gift_inbox", "leaderboard", "season_story", "album_milestone", "achievement"].includes(String(row.source_type || ""))) {
    try {
      const subscriber = await env.DB.prepare(`SELECT chat_id FROM bot_subscribers WHERE telegram_id=? AND active=1 LIMIT 1`).bind(telegramId).first();
      if (subscriber?.chat_id) await sendTelegramMessage(env, subscriber.chat_id, `<b>🎁 Награда доставлена</b>\n\n${escapeHtml(rewardDescription)}\nПричина: ${escapeHtml(row.reason || "Системная выдача")}\n\nНаграда уже записана в профиль. Откройте игру или обновите раздел с кейсами.`, { inline_keyboard: [[{ text: "🎮 Открыть игру", web_app: { url: configuredGameUrl(env) } }], [{ text: "📋 Задания", callback_data: "menu:tasks" }]] });
    } catch (error) { console.error("reward delivery notification failed", error); }
  }
  return { cosmeticDuplicate };
}

async function reconcileRewardDeliveryQueue(env, telegramId = "") {
  await ensureSafeControlCenterSchema(env);
  const now = Math.floor(Date.now()/1000);
  const player = String(telegramId || "");
  const suffix = player ? " AND telegram_id=?" : "";
  const bind = (statement, ...values) => player ? statement.bind(...values, player) : statement.bind(...values);
  // A crashed isolate must not leave a reward visually stuck in `delivering`.
  // Expired leases are safe to return to pending because the economic effect is
  // protected by reward_delivery_effects / source idempotency.
  await bind(env.DB.prepare(`UPDATE reward_delivery_queue
    SET status='pending',lease_token='',lease_until=0,updated_at=?
    WHERE status='delivering' AND lease_until>0 AND lease_until<? AND attempts<5${suffix}`), now, now).run();
  // Terminal rows must never keep a stale lease after delivery/claim/cancel.
  await bind(env.DB.prepare(`UPDATE reward_delivery_queue
    SET lease_token='',lease_until=0,updated_at=CASE WHEN updated_at>0 THEN updated_at ELSE ? END
    WHERE status IN ('delivered','claimed','cancelled') AND (lease_token<>'' OR lease_until<>0)${suffix}`), now).run();
}

async function processRewardDeliveryQueue(env, limit = 25) {
  await ensureSafeControlCenterSchema(env);
  await reconcileRewardDeliveryQueue(env);
  const now = Math.floor(Date.now() / 1000);
  const max = Math.max(1, Math.min(100, Math.floor(Number(limit) || 25)));
  const rows = await env.DB.prepare(
    `SELECT id,telegram_id,source_type,source_id,reward_kind,reward_id,amount,reason,attempts
     FROM reward_delivery_queue
     WHERE status IN ('pending','failed','delivering') AND available_at<=? AND attempts<5
       AND (lease_until=0 OR lease_until<?)
     ORDER BY available_at ASC,created_at ASC,id ASC
     LIMIT ?`
  ).bind(now, now, max).all();
  let delivered = 0;
  let failed = 0;
  let skipped = 0;
  for (const row of rows.results || []) {
    const token = caseGrantId("reward_lock");
    const claimAt = Math.floor(Date.now() / 1000);
    const lock = await env.DB.prepare(
      `UPDATE reward_delivery_queue
       SET status='delivering',lease_token=?,lease_until=?,updated_at=?
       WHERE id=? AND status IN ('pending','failed','delivering') AND attempts<5 AND available_at<=?
         AND (lease_until=0 OR lease_until<?)`
    ).bind(token, claimAt + SERVER_NOTIFICATION_LEASE_SECONDS, claimAt, row.id, claimAt, claimAt).run();
    if (Number(lock.meta?.changes || 0) < 1) { skipped += 1; continue; }
    try {
      await deliverQueuedReward(env, row, token);
      delivered += 1;
    } catch (error) {
      const finishedAt = Math.floor(Date.now() / 1000);
      const attempts = Math.max(1, Number(row.attempts || 0) + 1);
      const delay = Math.min(3600, 60 * (2 ** Math.max(0, attempts - 1)));
      await env.DB.prepare(
        `UPDATE reward_delivery_queue
         SET status='failed',attempts=?,last_error=?,updated_at=?,lease_token='',lease_until=0,available_at=?
         WHERE id=? AND lease_token=?`
      ).bind(attempts, String(error?.message || error).slice(0, 500), finishedAt, finishedAt + delay, row.id, token).run();
      failed += 1;
    }
  }
  return { delivered, failed, skipped, processed: delivered + failed };
}

async function processPlayerRewardDeliveryQueue(env, telegramId, limit = 10) {
  await ensureSafeControlCenterSchema(env);
  await reconcileRewardDeliveryQueue(env, telegramId);
  const now = Math.floor(Date.now() / 1000);
  const max = Math.max(1, Math.min(25, Number(limit) || 10));
  const rows = await env.DB.prepare(
    `SELECT id,telegram_id,source_type,source_id,reward_kind,reward_id,amount,reason,attempts
     FROM reward_delivery_queue
     WHERE telegram_id=? AND status IN ('pending','failed','delivering') AND available_at<=? AND attempts<5
       AND (lease_until=0 OR lease_until<?)
     ORDER BY available_at ASC,created_at ASC,id ASC
     LIMIT ?`
  ).bind(String(telegramId), now, now, max).all();
  let delivered = 0;
  let failed = 0;
  for (const row of rows.results || []) {
    const token = caseGrantId("reward_player_lock");
    const claimAt = Math.floor(Date.now() / 1000);
    const lock = await env.DB.prepare(
      `UPDATE reward_delivery_queue SET status='delivering',lease_token=?,lease_until=?,updated_at=?
       WHERE id=? AND status IN ('pending','failed','delivering') AND attempts<5 AND available_at<=?
         AND (lease_until=0 OR lease_until<?)`
    ).bind(token, claimAt + SERVER_NOTIFICATION_LEASE_SECONDS, claimAt, row.id, claimAt, claimAt).run();
    if (Number(lock.meta?.changes || 0) < 1) continue;
    try {
      await deliverQueuedReward(env, row, token);
      delivered += 1;
    } catch (error) {
      const finishedAt = Math.floor(Date.now() / 1000);
      const attempts = Math.max(1, Number(row.attempts || 0) + 1);
      const delay = Math.min(3600, 60 * (2 ** Math.max(0, attempts - 1)));
      await env.DB.prepare(
        `UPDATE reward_delivery_queue SET status='failed',attempts=?,last_error=?,updated_at=?,lease_token='',lease_until=0,available_at=? WHERE id=? AND lease_token=?`
      ).bind(attempts, String(error?.message || error).slice(0, 500), finishedAt, finishedAt + delay, row.id, token).run();
      failed += 1;
    }
  }
  return { delivered, failed, processed: delivered + failed };
}

async function showRewardQueueDashboard(chatId, user, env) {
  const access = await requireSecurityPermission(chatId, user, "grantRewards", env);
  if (!access) return;
  await ensureSafeControlCenterSchema(env);
  const [queueResult, staleCases, leaderboardPending, physicalPending] = await Promise.all([
    env.DB.prepare(`SELECT * FROM reward_delivery_queue WHERE status IN ('pending','failed','delivering') ORDER BY CASE status WHEN 'failed' THEN 0 ELSE 1 END, created_at ASC LIMIT 30`).all(),
    env.DB.prepare(`SELECT id,telegram_id,case_type,created_at FROM granted_cases WHERE status='opening' AND created_at < ? LIMIT 10`).bind(Math.floor(Date.now()/1000)-900).all(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM leaderboard_rewards WHERE status='pending'`).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM reward_codes WHERE status='active' AND expires_at > ?`).bind(Math.floor(Date.now()/1000)).first()
  ]);
  const rows = queueResult.results || [];
  const lines = rows.map((row) => `${row.status === "failed" ? "❌" : row.status === "delivering" ? "🔄" : "⏳"} <b>#${row.id} ${escapeHtml(safeRewardDescription({ kind: row.reward_kind, id: row.reward_id, amount: row.amount }))}</b>\n  Игрок: <code>${escapeHtml(row.telegram_id)}</code> · попыток ${row.attempts}${row.last_error ? `\n  ${escapeHtml(row.last_error)}` : ""}`);
  const buttons = rows.slice(0, 12).flatMap((row) => [
    [{ text: `🔁 #${row.id}`, callback_data: `safe_queue_retry:${row.id}` }, { text: "👤 Игрок", callback_data: `player_refresh:${row.telegram_id}` }],
    [{ text: "🎁 Компенсация", callback_data: `safe_queue_comp:${row.id}` }, { text: "✖️ Отменить", callback_data: `safe_queue_cancel:${row.id}` }]
  ]);
  buttons.push([{ text: "🔄 Обновить", callback_data: "safe_queue" }, { text: "🧰 Компенсация", callback_data: "safe_comp" }]);
  buttons.push([{ text: "⬅️ Админ-панель", callback_data: "adm_home" }]);
  await sendTelegramMessage(env, chatId,
    `<b>📬 Центр недоставленных наград</b>\n\n${lines.join("\n\n") || "Системная очередь пуста."}\n\nОжидают получения в рейтинге: <b>${Number(leaderboardPending?.count || 0)}</b>\nАктивные физические коды: <b>${Number(physicalPending?.count || 0)}</b>\nЗависшие открытия кейсов: <b>${(staleCases.results || []).length}</b>`,
    { inline_keyboard: buttons }
  );
}

async function retryQueuedReward(query, id, env) {
  const access = await requireSecurityPermission(query.message?.chat?.id, query.from, "grantRewards", env);
  if (!access) return;
  await env.DB.prepare(`UPDATE reward_delivery_queue SET status='pending',attempts=0,available_at=?,lease_token='',lease_until=0,last_error='',notify_after=?,updated_at=? WHERE id=? AND status IN ('failed','delivering','pending')`).bind(Math.floor(Date.now()/1000), Math.floor(Date.now()/1000)+900, Math.floor(Date.now()/1000), Number(id)).run();
  await answerCallback(env, query.id, "Награда поставлена на повторную выдачу.");
  await showRewardQueueDashboard(query.message.chat.id, query.from, env);
}

async function cancelQueuedReward(query, id, env) {
  const access = await requireSecurityPermission(query.message?.chat?.id, query.from, "grantRewards", env);
  if (!access) return;
  await env.DB.prepare(`UPDATE reward_delivery_queue SET status='cancelled',updated_at=?,lease_token='',lease_until=0 WHERE id=? AND status NOT IN ('delivered','claimed','cancelled')`).bind(Math.floor(Date.now()/1000), Number(id)).run();
  await answerCallback(env, query.id, "Награда отменена.");
  await showRewardQueueDashboard(query.message.chat.id, query.from, env);
}

