async function processSeasonPassTeaserNotifications(env){
  await ensureSeasonPassSchema(env);const now=Math.floor(Date.now()/1000);
  const teaser=await env.DB.prepare(`SELECT t.*,s.title AS season_title FROM season_pass_teasers t JOIN season_pass_seasons s ON s.season_id=t.season_id WHERE t.enabled=1 AND s.starts_at<=? AND s.ends_at>? AND s.manual_status!='ended' ORDER BY s.starts_at DESC LIMIT 1`).bind(now,now).first();
  if(!teaser)return {active:false};const threshold=seasonPassXpForLevel(Math.max(1,Math.min(50,Number(teaser.unlock_level)||50)));
  await env.DB.prepare(`INSERT OR IGNORE INTO season_pass_teaser_deliveries(season_id,telegram_id,unlocked_at,notified_at,opened_at) SELECT ?,p.telegram_id,?,0,0 FROM season_pass_players p WHERE p.season_id=? AND p.xp>=?`).bind(teaser.season_id,now,teaser.season_id,threshold).run();
  const rows=(await env.DB.prepare(`SELECT d.telegram_id,b.chat_id FROM season_pass_teaser_deliveries d JOIN bot_subscribers b ON b.telegram_id=d.telegram_id AND b.active=1 WHERE d.season_id=? AND d.notified_at=0 AND TRIM(COALESCE(b.chat_id,''))<>'' ORDER BY d.unlocked_at,d.telegram_id LIMIT 40`).bind(teaser.season_id).all()).results||[];
  let processed=0;for(const row of rows){try{const text=String(teaser.push_text||'').trim()||'Вы дошли до финала сезонного пропуска. Для вас появилось письмо со спойлером следующего сезона.';const url=new URL(configuredSeasonPassTasksUrl(env));url.searchParams.delete('view');url.searchParams.set('letter','1');url.searchParams.set('letterSeason',String(teaser.season_id));await v77DeliverPlayerNotification(env,String(row.telegram_id),String(row.chat_id),'season_pass_letter',`<b>💌 ${escapeHtml(String(teaser.envelope_title||'Вам письмо'))}</b>\n\n${escapeHtml(text)}`,{inline_keyboard:[[{text:'💌 Открыть письмо',web_app:{url:url.toString()}}]]});await env.DB.prepare(`UPDATE season_pass_teaser_deliveries SET notified_at=? WHERE season_id=? AND telegram_id=? AND notified_at=0`).bind(now,teaser.season_id,String(row.telegram_id)).run();processed+=1;}catch(error){console.error('season pass teaser notification failed',row.telegram_id,error);}}
  return {active:true,processed};
}

function seasonPassStoryUnlockXpCase(alias='e'){
  const safeAlias=/^[A-Za-z_][A-Za-z0-9_]*$/.test(String(alias))?String(alias):'e';
  const parts=[];for(let level=1;level<=50;level+=1)parts.push(`WHEN ${level} THEN ${seasonPassXpForLevel(level)}`);
  return `(CASE ${safeAlias}.unlock_level ${parts.join(' ')} ELSE 0 END)`;
}

async function processSeasonPassStoryNotifications(env,options={}){
  await ensureSeasonPassSchema(env);const now=Math.floor(Date.now()/1000),onlyEventId=String(options?.eventId||'').trim();
  const season=await env.DB.prepare(`SELECT season_id,title FROM season_pass_seasons WHERE starts_at<=? AND ends_at>? AND manual_status!='ended' ORDER BY starts_at DESC LIMIT 1`).bind(now,now).first();
  if(!season)return {active:false,processed:0};
  const eventXp=seasonPassStoryUnlockXpCase('e');
  const sql=`SELECT e.event_id,e.title,e.push_text,p.telegram_id,b.chat_id
    FROM season_pass_story_events e
    JOIN season_pass_players p ON p.season_id=e.season_id
    JOIN bot_subscribers b ON b.telegram_id=p.telegram_id AND b.active=1 AND TRIM(COALESCE(b.chat_id,''))<>''
    LEFT JOIN season_pass_story_progress sp ON sp.event_id=e.event_id AND sp.telegram_id=p.telegram_id
    LEFT JOIN season_pass_story_manual_unlocks mu ON mu.event_id=e.event_id AND mu.telegram_id=p.telegram_id
    WHERE e.season_id=? AND e.enabled=1 AND e.push_enabled=1
      ${onlyEventId?'AND e.event_id=?':''}
      AND ((p.xp>=${eventXp} AND (e.unlock_at<=0 OR e.unlock_at<=${now})) OR COALESCE(mu.unlocked_at,0)>0)
      AND COALESCE(sp.completed_at,0)=0 AND COALESCE(sp.notified_at,0)=0
      AND NOT EXISTS (
        SELECT 1 FROM season_pass_story_events prev
        LEFT JOIN season_pass_story_progress pp ON pp.event_id=prev.event_id AND pp.telegram_id=p.telegram_id
        WHERE prev.season_id=e.season_id AND prev.enabled=1 AND COALESCE(pp.completed_at,0)=0
          AND (prev.unlock_level<e.unlock_level
            OR (prev.unlock_level=e.unlock_level AND prev.sort_order<e.sort_order)
            OR (prev.unlock_level=e.unlock_level AND prev.sort_order=e.sort_order AND prev.created_at<e.created_at)
            OR (prev.unlock_level=e.unlock_level AND prev.sort_order=e.sort_order AND prev.created_at=e.created_at AND prev.event_id<e.event_id))
      )
    ORDER BY e.unlock_level,e.sort_order,e.created_at,e.event_id,p.telegram_id LIMIT 40`;
  const stmt=env.DB.prepare(sql),rows=(await (onlyEventId?stmt.bind(String(season.season_id),onlyEventId).all():stmt.bind(String(season.season_id)).all())).results||[];let processed=0;
  for(const row of rows){
    try{
      const text=String(row.push_text||'').trim()||'Открылась новая часть истории сезона.';const url=new URL(configuredSeasonPassTasksUrl(env));url.searchParams.delete('view');url.searchParams.set('story','1');
      await v77DeliverPlayerNotification(env,String(row.telegram_id),String(row.chat_id),'season_pass_story',`<b>📖 ${escapeHtml(String(row.title||'Новая глава'))}</b>

${escapeHtml(text)}`,{inline_keyboard:[[{text:'📖 Читать',web_app:{url:url.toString()}}]]});
      await env.DB.prepare(`INSERT INTO season_pass_story_progress(event_id,season_id,telegram_id,seen_at,completed_at,notified_at) VALUES(?,?,?,0,0,?)
        ON CONFLICT(event_id,telegram_id) DO UPDATE SET notified_at=CASE WHEN season_pass_story_progress.notified_at=0 THEN excluded.notified_at ELSE season_pass_story_progress.notified_at END`)
        .bind(String(row.event_id),String(season.season_id),String(row.telegram_id),now).run();processed+=1;
    }catch(error){console.error('season pass story notification failed',row.telegram_id,row.event_id,error);}
  }
  return {active:true,processed};
}

let seasonPassTierActivationNoticeSchemaPromise = null;
async function ensureSeasonPassTierActivationNoticeSchema(env) {
  requireDatabase(env);
  if (!seasonPassTierActivationNoticeSchemaPromise) {
    seasonPassTierActivationNoticeSchemaPromise = env.DB.batch([
      env.DB.prepare(`CREATE TABLE IF NOT EXISTS season_pass_tier_activation_notices (
        notice_id TEXT PRIMARY KEY,
        season_id TEXT NOT NULL,
        telegram_id TEXT NOT NULL,
        previous_tier TEXT NOT NULL DEFAULT 'none' CHECK(previous_tier IN ('none','elite','elite_plus')),
        new_tier TEXT NOT NULL CHECK(new_tier IN ('elite','elite_plus')),
        source TEXT NOT NULL DEFAULT '',
        source_key TEXT NOT NULL,
        payload_json TEXT NOT NULL DEFAULT '{}',
        activated_at INTEGER NOT NULL,
        claimed_at INTEGER NOT NULL DEFAULT 0,
        claimed_surface TEXT NOT NULL DEFAULT ''
      )`),
      env.DB.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS idx_season_pass_tier_activation_source ON season_pass_tier_activation_notices(season_id,telegram_id,source_key)`),
      env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_season_pass_tier_activation_pending ON season_pass_tier_activation_notices(telegram_id,season_id,claimed_at,activated_at)`)
    ]).catch((error)=>{ seasonPassTierActivationNoticeSchemaPromise=null; throw error; });
  }
  return seasonPassTierActivationNoticeSchemaPromise;
}

function seasonPassTierActivationSourceKey(value) {
  const raw=String(value||'').trim().replace(/[^A-Za-z0-9:_-]/g,'_');
  return raw.slice(0,160)||`tier_${Date.now().toString(36)}`;
}

function seasonPassTierActivationBenefits(season,newTier,payload={}) {
  if(newTier==='elite') return [
    {key:'premium_rewards',title:'Премиальная линия из 50 наград',imageUrl:'/assets/season-pass/season.png?v=07939'},
    {key:'premium_tasks',title:'Премиальные задания',imageUrl:'/assets/season-pass/quest.png?v=07939'},
    {key:'rating_badge',title:'Значок «Элитный» в рейтинге',imageUrl:'/assets/ui/icon_player_elit.png',symbol:''},
    {key:'legendary_case',title:'Легендарный кейс на 50 уровне',imageUrl:'/assets/cases/legendary_closed.png'}
  ];
  const settings=seasonPassPublicTierSettings(season)?.elitePlus||{};
  const benefits=[
    {key:'elite_all',title:'Все преимущества «Элитного»',imageUrl:'/assets/season-pass/elite.png?v=07939'},
    {key:'rating_badge',title:'Значок «Элитный+» в рейтинге',imageUrl:'/assets/ui/icon_player_elit+.png',symbol:''}
  ];
  if(settings.xpBoost!==false){
    benefits.push({key:'season_xp_x2',title:'×2 XP сезона',imageUrl:'/assets/season-pass/xp_x2.png?v=07939'});
    benefits.push({key:'profile_xp_x2',title:'×2 XP профиля',imageUrl:'/assets/season-pass/xp_x2.png?v=07939'});
  }
  const bonusLevels=Math.max(0,Number(payload.bonusLevels??settings.bonusLevels)||0);
  if(bonusLevels>0)benefits.push({key:'bonus_levels',title:`+${bonusLevels} уровней пропуска`,imageUrl:'/assets/season-pass/levels_5.png?v=07939'});
  for(const cosmetic of Array.isArray(settings.cosmetics)?settings.cosmetics:[]){
    if(!cosmetic||cosmetic.kind==='secret')continue;
    benefits.push({key:`cosmetic_${String(cosmetic.kind||'item')}`,title:String(cosmetic.title||'Эксклюзивная награда'),imageUrl:String(cosmetic.imageUrl||'/assets/season-pass/season.png?v=07939')});
  }
  if(settings.case)benefits.push({key:'bonus_case',title:String(settings.case.title||'Золотой кейс'),imageUrl:String(settings.case.imageUrl||'/assets/cases/gold_closed.png')});
  return benefits;
}

function seasonPassTierActivationNoticeView(row,season) {
  if(!row)return null;
  let payload={};try{payload=JSON.parse(String(row.payload_json||'{}'))||{};}catch{}
  const previousTier=['elite','elite_plus'].includes(String(row.previous_tier))?String(row.previous_tier):'none';
  const newTier=String(row.new_tier)==='elite_plus'?'elite_plus':'elite';
  const fromLevel=Math.max(0,Number(payload.fromLevel)||0),toLevel=Math.max(0,Number(payload.toLevel)||0);
  const bonusLevels=Math.max(0,Number(payload.bonusLevels)||Math.max(0,toLevel-fromLevel));
  return {
    id:String(row.notice_id||''),seasonId:String(row.season_id||''),seasonTitle:String(season?.title||payload.seasonTitle||''),
    previousTier,newTier,isUpgrade:previousTier==='elite'&&newTier==='elite_plus',source:String(row.source||''),activatedAt:Number(row.activated_at||0),
    fromLevel,toLevel,bonusLevels,benefits:seasonPassTierActivationBenefits(season,newTier,{...payload,bonusLevels})
  };
}

async function queueSeasonPassTierActivationNotice(env,{season,telegramId,previousTier='none',newTier='',source='',sourceKey='',activatedAt=0,payload={}}={}) {
  const id=String(telegramId||'').trim(),sid=String(season?.id||'').trim();
  const before=['elite','elite_plus'].includes(String(previousTier))?String(previousTier):'none';
  const after=String(newTier)==='elite_plus'?'elite_plus':String(newTier)==='elite'?'elite':'';
  if(!id||!sid||!after||before===after||(before==='elite_plus'&&after==='elite'))return null;
  await ensureSeasonPassTierActivationNoticeSchema(env);
  const key=seasonPassTierActivationSourceKey(sourceKey||`${source}:${after}:${activatedAt||Date.now()}`);
  const noticeId=`sp_tier_${sid}_${id}_${key}`.replace(/[^A-Za-z0-9:_-]/g,'_').slice(0,190);
  const now=Math.max(1,Math.floor(Number(activatedAt)||Date.now()/1000));
  const safePayload={...(payload&&typeof payload==='object'?payload:{}),seasonTitle:String(season?.title||payload?.seasonTitle||'')};
  // If a player went from no tier to Elite and then to Elite+ before ever seeing
  // the first celebration, the newer maximum-tier notice supersedes the stale
  // Elite presentation. Already-viewed notices are never rewritten.
  if(after==='elite_plus')await env.DB.prepare(`UPDATE season_pass_tier_activation_notices SET claimed_at=?,claimed_surface='superseded' WHERE season_id=? AND telegram_id=? AND new_tier='elite' AND claimed_at=0`).bind(now,sid,id).run();
  await env.DB.prepare(`INSERT OR IGNORE INTO season_pass_tier_activation_notices(notice_id,season_id,telegram_id,previous_tier,new_tier,source,source_key,payload_json,activated_at,claimed_at,claimed_surface) VALUES(?,?,?,?,?,?,?,?,?,0,'')`)
    .bind(noticeId,sid,id,before,after,String(source||'').slice(0,80),key,JSON.stringify(safePayload),now).run();
  const row=await env.DB.prepare(`SELECT * FROM season_pass_tier_activation_notices WHERE season_id=? AND telegram_id=? AND source_key=? LIMIT 1`).bind(sid,id,key).first();
  return row&&Number(row.claimed_at||0)===0?seasonPassTierActivationNoticeView(row,season):null;
}

async function pendingSeasonPassTierActivationNotice(env,telegramId,season) {
  const id=String(telegramId||'').trim(),sid=String(season?.id||'').trim();
  if(!id||!sid)return null;
  await ensureSeasonPassTierActivationNoticeSchema(env);
  const row=await env.DB.prepare(`SELECT * FROM season_pass_tier_activation_notices WHERE telegram_id=? AND season_id=? AND claimed_at=0 ORDER BY activated_at ASC,notice_id ASC LIMIT 1`).bind(id,sid).first();
  return seasonPassTierActivationNoticeView(row,season);
}

async function claimSeasonPassTierActivationNotice(request,env) {
  try{
    requireDatabase(env);requireBotToken(env);await ensureSeasonPassTierActivationNoticeSchema(env);
    const body=await readJson(request),auth=await validateTelegramInitData(String(body.initData||body.init_data||''),env),telegramId=String(auth.user.id);
    const noticeId=String(body.noticeId||body.notice_id||'').trim();if(!noticeId||noticeId.length>190)throw new ApiError(400,'Некорректное уведомление активации.');
    const surface=['index','battle_pass'].includes(String(body.surface||''))?String(body.surface):'unknown';
    const now=Math.floor(Date.now()/1000);
    const changed=await env.DB.prepare(`UPDATE season_pass_tier_activation_notices SET claimed_at=?,claimed_surface=? WHERE notice_id=? AND telegram_id=? AND claimed_at=0`).bind(now,surface,noticeId,telegramId).run();
    if(Number(changed?.meta?.changes||0)<1)return jsonResponse({ok:true,claimed:false,notice:null});
    const row=await env.DB.prepare(`SELECT * FROM season_pass_tier_activation_notices WHERE notice_id=? AND telegram_id=? LIMIT 1`).bind(noticeId,telegramId).first();
    const season=row?await loadSeasonPassSeasonById(env,String(row.season_id||'')):null;
    return jsonResponse({ok:true,claimed:true,notice:seasonPassTierActivationNoticeView(row,season)});
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('claimSeasonPassTierActivationNotice failed',error);return jsonResponse({ok:false,error:'Не удалось открыть уведомление активации.'},500);}
}

async function buildSeasonPassPayload(env,season,telegramId,player=null){
  const current=player||await ensureSeasonPassPlayer(env,season,telegramId);
  const [rewardsResult,claimsResult,entitlementsResult,profileRow,tasksPayload,summary]=await Promise.all([
    env.DB.prepare(`SELECT level,lane,reward_type,amount,item_id,title,image_url,enabled FROM season_pass_rewards WHERE season_id=? ORDER BY level,lane`).bind(season.id).all(),
    env.DB.prepare(`SELECT level,lane,status FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND status='delivered' ORDER BY level,lane`).bind(season.id,telegramId).all(),
    env.DB.prepare(`SELECT item_id,source,granted_at FROM season_pass_entitlements WHERE season_id=? AND telegram_id=? ORDER BY granted_at,item_id`).bind(season.id,telegramId).all(),
    env.DB.prepare(`SELECT wallet,treats,coffee,pending_wallet,pending_treats,pending_coffee,wallet_override,treats_override,coffee_override FROM admin_profile_state WHERE telegram_id=? LIMIT 1`).bind(telegramId).first(),
    buildSeasonPassTasksPayload(env,season,telegramId,current?.premium_tier),
    buildSeasonPassSummary(env,season,telegramId)
  ]);
  const xp=Math.max(0,Number(current?.xp)||0);const level=seasonPassLevelFromXp(xp);const required=SEASON_PASS_LEVEL_XP[level-1]||0;const start=seasonPassXpForLevel(level);
  const deliveredClaims=claimsResult.results||[];
  const overflowClaimed=deliveredClaims.filter(row=>String(row.lane)==='overflow').length;
  const overflow=seasonPassOverflowView(xp,overflowClaimed);
  const [letter,seasonalCases,story,tierActivationNotice]=await Promise.all([seasonPassTeaserForPlayer(env,season,telegramId,current),seasonPassSeasonalCaseInventory(env,telegramId),seasonPassStoryForPlayer(env,season,telegramId,current),pendingSeasonPassTierActivationNotice(env,telegramId,season)]);
  const catchUp=seasonPassCatchUpView(season,current);
  const finale=await seasonPassFinaleForPlayer(env,season,telegramId,current,summary,story,letter);
  const availablePoints=(profileRow?.wallet_override==null?Number(profileRow?.wallet||0):Number(profileRow?.wallet_override||0))+Number(profileRow?.pending_wallet||0);
  const availableTreats=(profileRow?.treats_override==null?Number(profileRow?.treats||0):Number(profileRow?.treats_override||0))+Number(profileRow?.pending_treats||0);
  const availableCoffee=(profileRow?.coffee_override==null?Number(profileRow?.coffee||0):Number(profileRow?.coffee_override||0))+Number(profileRow?.pending_coffee||0);
  return {ok:true,season:{...season,progression:seasonPassProgressionView(),tierSettings:seasonPassPublicTierSettings(season),capabilities:seasonPassCapabilities(season)},player:seasonPassPlayerView(current),overflow,catchUp,finale,letter,seasonalCases,story,tierActivationNotice,
    rewards:(rewardsResult.results||[]).map(seasonPassPlayerRewardView),
    claimed:deliveredClaims.filter(row=>String(row.lane)==='free'||String(row.lane)==='premium').map(row=>`${Number(row.level)}:${String(row.lane)}`),entitlements:(entitlementsResult.results||[]).map(row=>String(row.item_id)).filter(item=>!item.startsWith('__system:')),tasks:tasksPayload.tasks,taskPeriods:tasksPayload.periods,taskClaimableCount:seasonPassCapabilities(season).canClaimTasks?tasksPayload.claimableCount:0,summary,
    balance:{points:availablePoints,treats:availableTreats,coffee:availableCoffee}};
}


function seasonPassPlayerView(current){
  const xp=Math.max(0,Number(current?.xp)||0);const level=seasonPassLevelFromXp(xp);
  const overflow=seasonPassOverflowView(xp,0);
  const start=seasonPassXpForLevel(level);
  const required=overflow.unlocked?SEASON_PASS_OVERFLOW_LEVEL_XP:(SEASON_PASS_LEVEL_XP[level-1]||0);
  const within=overflow.unlocked?overflow.xpWithin:Math.max(0,Math.min(required,xp-start));
  return {xp,level,displayLevel:overflow.unlocked?'50+':String(level),xpWithin:within,xpRequired:required,premiumTier:String(current?.premium_tier||'none'),elitePlusBonusGranted:Number(current?.elite_plus_bonus_granted||0)===1,revision:Number(current?.revision||0)};
}

function seasonPassCapabilities(season){
  const active=season.status==='active';
  const canClaimRewards=active||Boolean(season.claimWindowOpen);
  return {canEarnXp:active,canPurchase:active,canClaimRewards,canClaimTasks:active};
}

function seasonPassPublicTierSettings(season) {
  const fallback=seasonPassElitePlusBenefitsView(defaultSeasonPassElitePlusBenefits());
  const source=season?.tierSettings?.elitePlus || fallback;
  return {
    elitePlus:{
      xpBoost:source.xpBoost !== false,
      bonusLevels:Math.max(0,Number(source.bonusLevels)||0),
      case:source.case ? {...source.case} : null,
      cosmetics:(Array.isArray(source.cosmetics)?source.cosmetics:[]).map((item)=>item?.future&&!item?.released
        ? {kind:"secret",itemId:"",title:"Секретная награда сезона",imageUrl:"/assets/season-pass/season.png?v=07939",future:true,released:false}
        : {...item})
    }
  };
}

function assertSeasonPassTaskClaimsOpen(season){
  if(!seasonPassCapabilities(season).canClaimTasks){
    throw new ApiError(409,'Сезон завершён, задания отключены. Можно забрать только уже открытые награды.');
  }
}

async function buildSeasonPassMutationPayload(env,season,telegramId,options={}){
  const playerPromise=env.DB.prepare(`SELECT * FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(season.id,String(telegramId)).first();
  const profilePromise=env.DB.prepare(`SELECT wallet,treats,coffee,wallet_override,treats_override,coffee_override,pending_wallet,pending_treats,pending_coffee FROM admin_profile_state WHERE telegram_id=? LIMIT 1`).bind(String(telegramId)).first();
  const claimsPromise=options.includeClaims?env.DB.prepare(`SELECT level,lane FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND status='delivered' ORDER BY level,lane`).bind(season.id,String(telegramId)).all():Promise.resolve(null);
  const entitlementsPromise=options.includeEntitlements?env.DB.prepare(`SELECT item_id FROM season_pass_entitlements WHERE season_id=? AND telegram_id=? ORDER BY item_id`).bind(season.id,String(telegramId)).all():Promise.resolve(null);
  const tasksPromise=options.includeTasks?buildSeasonPassTasksPayload(env,season,String(telegramId),options.premiumTier):Promise.resolve(null);
  const [player,profileRow,claimsResult,entitlementsResult,tasksPayload]=await Promise.all([playerPromise,profilePromise,claimsPromise,entitlementsPromise,tasksPromise]);
  const payload={ok:true,season:{id:season.id,title:season.title,status:season.status,startsAt:season.startsAt,endsAt:season.endsAt,claimGraceEndsAt:season.claimGraceEndsAt,claimWindowOpen:season.claimWindowOpen,baseRunXp:season.baseRunXp,levelPricePoints:season.levelPricePoints,prices:season.prices,progression:seasonPassProgressionView(),tierSettings:seasonPassPublicTierSettings(season),capabilities:seasonPassCapabilities(season)},player:seasonPassPlayerView(player),balance:{
    points:(profileRow?.wallet_override==null?Number(profileRow?.wallet||0):Number(profileRow?.wallet_override||0))+Number(profileRow?.pending_wallet||0),
    treats:(profileRow?.treats_override==null?Number(profileRow?.treats||0):Number(profileRow?.treats_override||0))+Number(profileRow?.pending_treats||0),
    coffee:(profileRow?.coffee_override==null?Number(profileRow?.coffee||0):Number(profileRow?.coffee_override||0))+Number(profileRow?.pending_coffee||0)
  }};
  if(options.includeClaims){const rows=claimsResult?.results||[];payload.claimed=rows.filter(row=>String(row.lane)==='free'||String(row.lane)==='premium').map(row=>`${Number(row.level)}:${String(row.lane)}`);payload.overflow=seasonPassOverflowView(player?.xp,rows.filter(row=>String(row.lane)==='overflow').length);}
  if(options.includeEntitlements)payload.entitlements=(entitlementsResult?.results||[]).map(row=>String(row.item_id)).filter(item=>!item.startsWith('__system:'));
  if(options.includeTasks&&tasksPayload){payload.tasks=tasksPayload.tasks;payload.taskPeriods=tasksPayload.periods;payload.taskClaimableCount=seasonPassCapabilities(season).canClaimTasks?tasksPayload.claimableCount:0;}
  const [story,tierActivationNotice]=await Promise.all([seasonPassStoryForPlayer(env,season,String(telegramId),player),pendingSeasonPassTierActivationNotice(env,String(telegramId),season)]);
  payload.story=story;
  payload.tierActivationNotice=tierActivationNotice;
  payload.catchUp=seasonPassCatchUpView(season,player);
  if(Math.max(0,Number(player?.xp)||0)>=SEASON_PASS_LEVEL_50_COMPLETE_XP)payload.finale=await seasonPassFinaleForPlayer(env,season,String(telegramId),player,null,payload.story,null);
  else payload.finale={unlocked:false,level:seasonPassLevelFromXp(Math.max(0,Number(player?.xp)||0)),displayLevel:String(seasonPassLevelFromXp(Math.max(0,Number(player?.xp)||0))),xp:Math.max(0,Number(player?.xp)||0),rewardsClaimed:0,tasksClaimed:0,runs:0,bestScore:0,storyCompleted:0,storyTotal:0,nextSeason:null,teaser:null};
  return payload;
}

async function seasonPassAttentionForPlayer(env,season,telegramId,player=null){
  const id=String(telegramId||'').trim();
  const current=player||await ensureSeasonPassPlayer(env,season,id);
  const capabilities=seasonPassCapabilities(season);
  if(!capabilities.canClaimRewards&&!capabilities.canClaimTasks)return {claimableCount:0,rewardCount:0,taskCount:0,overflowCount:0};
  const level=seasonPassLevelFromXp(Math.max(0,Number(current?.xp)||0));
  const premiumTier=String(current?.premium_tier||'none');
  const rewardPromise=capabilities.canClaimRewards
    ? env.DB.prepare(`SELECT r.level,r.lane,r.reward_type,r.amount,r.item_id,r.title,r.image_url,r.enabled
        FROM season_pass_rewards r
        WHERE r.season_id=? AND r.enabled=1 AND r.level<=?
          AND (r.lane='free' OR (?<>'none' AND r.lane='premium'))
          AND NOT EXISTS(
            SELECT 1 FROM season_pass_claims c
            WHERE c.season_id=r.season_id AND c.telegram_id=? AND c.level=r.level AND c.lane=r.lane AND c.status='delivered'
          )
        ORDER BY r.level,r.lane`).bind(String(season.id),level,premiumTier,id).all()
    : Promise.resolve({results:[]});
  const overflowPromise=capabilities.canClaimRewards
    ? env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND lane='overflow' AND status='delivered'`).bind(String(season.id),id).first()
    : Promise.resolve({count:0});
  const dailyKey=seasonPassMoscowPeriod('daily').key;
  const weeklyKey=seasonPassMoscowPeriod('weekly').key;
  const tasksPromise=capabilities.canClaimTasks
    ? env.DB.prepare(`SELECT COUNT(*) AS count
        FROM season_pass_task_notifications n
        WHERE n.season_id=? AND n.telegram_id=? AND n.period_key IN (?,?)
          AND NOT EXISTS(
            SELECT 1 FROM season_pass_task_claims c
            WHERE c.season_id=n.season_id AND c.telegram_id=n.telegram_id AND c.task_id=n.task_id AND c.period_key=n.period_key AND c.status='delivered'
          )`).bind(String(season.id),id,dailyKey,weeklyKey).first()
    : Promise.resolve({count:0});
  const seasonalCasesPromise=env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_case_grants g JOIN season_pass_case_definitions d ON d.case_id=g.case_id WHERE g.telegram_id=? AND g.status IN ('pending','opening') AND d.enabled=1 AND d.release_at<=?`).bind(id,Math.floor(Date.now()/1000)).first();
  const [rewardRows,overflowRow,taskRow,seasonalCaseRow]=await Promise.all([rewardPromise,overflowPromise,tasksPromise,seasonalCasesPromise]);
  const rewardCount=(rewardRows.results||[]).filter((row)=>seasonPassPlayerRewardView(row).enabled!==false).length;
  const overflowCount=capabilities.canClaimRewards?Math.max(0,Number(seasonPassOverflowView(current?.xp,Number(overflowRow?.count||0))?.available||0)):0;
  const taskCount=capabilities.canClaimTasks?Math.max(0,Number(taskRow?.count||0)):0;const seasonalCaseCount=Math.max(0,Number(seasonalCaseRow?.count||0));
  return {claimableCount:rewardCount+taskCount+overflowCount+seasonalCaseCount,rewardCount,taskCount,overflowCount,seasonalCaseCount};
}

async function getSeasonPassProfileBonusForUser(env,telegramId){
  const forcedClosure=await getSeasonPassForcedClosure(env);
  if(forcedClosure){
    return {ok:true,active:false,multiplier:1,premiumTier:'none',seasonId:forcedClosure.nextSeasonId||'',status:'upcoming',startsAt:forcedClosure.startsAt,endsAt:forcedClosure.endsAt,claimWindowOpen:false,forceClosed:true,claimableCount:0,rewardClaimableCount:0,taskClaimableCount:0,overflowClaimableCount:0,seasonalCaseClaimableCount:0};
  }
  const season=await loadSeasonPassSeason(env);
  if(season.status==='ended'){
    const player=season.claimWindowOpen?await ensureSeasonPassPlayer(env,season,String(telegramId)):null;
    const [attention,tierActivationNotice]=player?await Promise.all([seasonPassAttentionForPlayer(env,season,String(telegramId),player),pendingSeasonPassTierActivationNotice(env,String(telegramId),season)]):[{claimableCount:0,rewardCount:0,taskCount:0,overflowCount:0},null];
    return {ok:true,active:false,multiplier:1,premiumTier:String(player?.premium_tier||'none'),seasonId:season.id,status:season.status,endsAt:season.endsAt,claimWindowOpen:Boolean(season.claimWindowOpen),tierActivationNotice,claimableCount:attention.claimableCount,rewardClaimableCount:attention.rewardCount,taskClaimableCount:attention.taskCount,overflowClaimableCount:attention.overflowCount,seasonalCaseClaimableCount:attention.seasonalCaseCount||0};
  }
  const player=await ensureSeasonPassPlayer(env,season,String(telegramId));
  const [active,attention,tierActivationNotice]=await Promise.all([
    season.status==='active'?seasonPassHasXpX2(env,season.id,String(telegramId),player):Promise.resolve(false),
    seasonPassAttentionForPlayer(env,season,String(telegramId),player),
    pendingSeasonPassTierActivationNotice(env,String(telegramId),season)
  ]);
  return {ok:true,active,multiplier:active?2:1,premiumTier:String(player?.premium_tier||'none'),seasonId:season.id,status:season.status,endsAt:season.endsAt,claimWindowOpen:false,tierActivationNotice,claimableCount:attention.claimableCount,rewardClaimableCount:attention.rewardCount,taskClaimableCount:attention.taskCount,overflowClaimableCount:attention.overflowCount,seasonalCaseClaimableCount:attention.seasonalCaseCount||0};
}

async function getSeasonPassProfileBonus(request,env){
  try{requireBotToken(env);const body=await readJson(request);const initData=String(body.initData||body.init_data||'');if(!initData)throw new ApiError(401,'Откройте игру через Telegram.');const auth=await validateTelegramInitData(initData,env);return jsonResponse(await getSeasonPassProfileBonusForUser(env,String(auth.user.id)));}
  catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('getSeasonPassProfileBonus failed',error);return jsonResponse({ok:false,error:'Не удалось проверить бонус XP.'},500);}
}

async function getSeasonPassState(request,env){
  try{const ctx=await seasonPassRequestContext(request,env);return jsonResponse(await buildSeasonPassPayload(env,ctx.season,ctx.telegramId,ctx.player));}
  catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('getSeasonPassState failed',error);return jsonResponse({ok:false,error:'Не удалось загрузить сезонный пропуск.'},500);}
}

function seasonPassBackgroundWork(executionCtx,promise,label='season pass background work'){
  if(executionCtx?.waitUntil)executionCtx.waitUntil(Promise.resolve(promise).catch(error=>console.error(label,error)));
  else void Promise.resolve(promise).catch(error=>console.error(label,error));
}

function seasonPassRewardMutationEnvelope(ctx,extra={}){
  return {
    ok:true,
    season:{
      id:ctx.season.id,
      status:ctx.season.status,
      claimWindowOpen:ctx.season.claimWindowOpen,
      progression:seasonPassProgressionView(),
      capabilities:seasonPassCapabilities(ctx.season)
    },
    player:seasonPassPlayerView(ctx.player),
    ...extra
  };
}

async function grantSeasonPassReward(env,ctx,reward,executionCtx=null){
  await assertSeasonPassNotForceClosed(env);
  const showcaseStyleReward=seasonPassShowcaseStyleRewardDefinition(reward);
  let cosmeticReward=seasonPassCosmeticRewardDefinition(reward);
  if(cosmeticReward?.future){await readLiveContentReleaseRules(env,true);cosmeticReward=seasonPassCosmeticRewardDefinition(reward);}
  const boostReward=seasonPassBoostRewardDefinition(reward);
  if(showcaseStyleReward)await ensureAchievementConfigSchema(env);
  if(cosmeticReward?.future&&!cosmeticReward?.released) throw new ApiError(409,'Эта награда относится к скрытому контенту и пока не разрешена для этого слота Season Pass.');
  const now=Math.floor(Date.now()/1000);const level=Number(reward.level);const lane=String(reward.lane);const key=[ctx.season.id,ctx.telegramId,level,lane];
  let caseEnsured=null;
  if(cosmeticReward || (boostReward&&CASE_BOOSTER_TYPES.includes(boostReward.kind))){
    caseEnsured=await ensureCasePlayerState(env,ctx.telegramId,{});
    if(cosmeticReward)seasonPassApplyCosmeticToState(caseEnsured.state,cosmeticReward);
  }
  const statements=[
    env.DB.prepare(`INSERT OR IGNORE INTO season_pass_claims(season_id,telegram_id,level,lane,status,reward_json,claimed_at) VALUES(?,?,?,?,'pending',?,?)`).bind(...key,JSON.stringify(reward),now),
    env.DB.prepare(`UPDATE season_pass_claims SET status='pending',reward_json=?,claimed_at=?,error_text='' WHERE season_id=? AND telegram_id=? AND level=? AND lane=? AND status='failed'`).bind(JSON.stringify(reward),now,...key)
  ];
  const entitlementsAdded=[];
  if(showcaseStyleReward){
    statements.push(env.DB.prepare(`INSERT OR IGNORE INTO achievement_showcase_style_ownership(telegram_id,style_id,source_type,source_id,unlocked_at,updated_at) SELECT ?,?,'season_pass',?,?,? WHERE EXISTS(SELECT 1 FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND level=? AND lane=? AND status='pending')`).bind(ctx.telegramId,showcaseStyleReward.styleId,`${ctx.season.id}:${level}:${lane}`,now,now,...key));
    entitlementsAdded.push(`${SEASON_PASS_SHOWCASE_STYLE_PREFIX}${showcaseStyleReward.styleId}`);
  }else if(cosmeticReward){
    // Cosmetic ownership is idempotent. Keeping it in the same D1 batch as the
    // claim finalization avoids the old multi-round-trip reward path.
    statements.push(caseStateUpdateStatement(env,ctx.telegramId,caseEnsured.state,now));
  }else if(boostReward?.kind==='xp'){
    statements.push(env.DB.prepare(`INSERT OR IGNORE INTO season_pass_entitlements(season_id,telegram_id,item_id,source,granted_at) SELECT ?,?,?,?,? WHERE EXISTS(SELECT 1 FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND level=? AND lane=? AND status='pending')`).bind(ctx.season.id,ctx.telegramId,SEASON_PASS_SPECIAL_XP_X2,`reward:${level}:${lane}`,now,...key));
    entitlementsAdded.push(SEASON_PASS_SPECIAL_XP_X2);
  }else if(boostReward&&CASE_REWARD_BOOSTER_TYPES.includes(boostReward.kind)){
    const column=boostReward.kind==='points'?'boosters_points':boostReward.kind==='treats'?'boosters_treats':'boosters_coffee';
    statements.push(env.DB.prepare(`UPDATE case_player_state SET ${column}=${column}+?,revision=revision+1,updated_at=? WHERE telegram_id=? AND EXISTS(SELECT 1 FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND level=? AND lane=? AND status='pending')`).bind(Math.max(1,Number(reward.amount)||1),now,ctx.telegramId,...key));
  }else if(boostReward&&['shield','second_chance','pause'].includes(boostReward.kind)){
    const jsonPath=`$.${boostReward.kind}`;
    const amount=Math.max(1,Number(reward.amount)||1);
    statements.push(env.DB.prepare(`UPDATE case_player_state SET boosters_extra_json=json_set(CASE WHEN json_valid(boosters_extra_json) THEN boosters_extra_json ELSE '{}' END,'${jsonPath}',MIN(999,MAX(0,CAST(COALESCE(json_extract(CASE WHEN json_valid(boosters_extra_json) THEN boosters_extra_json ELSE '{}' END,'${jsonPath}'),0) AS INTEGER))+?)),revision=revision+1,updated_at=? WHERE telegram_id=? AND EXISTS(SELECT 1 FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND level=? AND lane=? AND status='pending')`).bind(amount,now,ctx.telegramId,...key));
  }else if(['points','treats','coffee'].includes(String(reward.reward_type))){
    const field=reward.reward_type==='points'?'pending_wallet':reward.reward_type==='treats'?'pending_treats':'pending_coffee';
    statements.push(env.DB.prepare(`UPDATE admin_profile_state SET ${field}=${field}+?,revision=revision+1,updated_at=?,updated_by=? WHERE telegram_id=? AND EXISTS(SELECT 1 FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND level=? AND lane=? AND status='pending')`).bind(Math.max(0,Number(reward.amount)||0),now,`season-pass:${ctx.season.id}`,ctx.telegramId,...key));
  }else if(String(reward.reward_type)==='case'){
    const seasonalCase=seasonPassSeasonalCaseRewardDefinition(reward);
    if(seasonalCase){
      const definition=await env.DB.prepare(`SELECT case_id,title,description,closed_image_url,open_image_url,slots,duplicate_points,reward_groups_json,enabled,release_at FROM season_pass_case_definitions WHERE case_id=? LIMIT 1`).bind(seasonalCase.caseId).first();
      if(!definition||!Number(definition.enabled||0))throw new ApiError(409,'Этот сезонный кейс отключён.');
      if(Number(definition.release_at||0)>now)throw new ApiError(409,'Этот сезонный кейс ещё не выпущен.');
      const caseItems=await seasonPassEffectiveCaseItems(env,seasonalCase.caseId);
      if(!caseItems.length)throw new ApiError(409,'В сезонном кейсе пока нет наград.');
      const caseSnapshot=JSON.stringify({title:String(definition.title||'Сезонный кейс'),description:String(definition.description||''),imageUrl:String(definition.closed_image_url||''),openImageUrl:String(definition.open_image_url||''),slots:Math.max(1,Math.min(5,Number(definition.slots)||1)),duplicatePoints:Math.max(0,Number(definition.duplicate_points)||0),groupChances:seasonPassSeasonalCaseGroupChances(definition.reward_groups_json),items:caseItems.map(item=>({key:String(item.item_key),kind:String(item.reward_kind),itemId:String(item.item_id),amount:Math.max(1,Number(item.amount||1)),weight:Number(item.weight||1),rarity:String(item.rarity||'seasonal'),title:String(item.title||''),imageUrl:String(item.image_url||'')}))});
      const amount=Math.max(1,Math.min(20,Number(reward.amount)||1));
      for(let index=0;index<amount;index+=1){const grantId=`spcase:${ctx.season.id}:${ctx.telegramId}:${level}:${lane}:${index}`.slice(0,190);statements.push(env.DB.prepare(`INSERT OR IGNORE INTO season_pass_case_grants(grant_id,case_id,source_season_id,telegram_id,status,rewards_json,snapshot_json,granted_by,created_at) SELECT ?,?,?,?,'pending','[]',?,?,? WHERE EXISTS(SELECT 1 FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND level=? AND lane=? AND status='pending')`).bind(grantId,seasonalCase.caseId,ctx.season.id,ctx.telegramId,caseSnapshot,`season-pass:${ctx.season.id}`,now,...key));}
    }else{
      // The grant id is deterministic, so a repeated/concurrent request cannot
      // create a second case. It also repairs an old delivered claim missing its grant.
      statements.push(seasonPassCaseGrantStatement(env,{seasonId:ctx.season.id,telegramId:ctx.telegramId,level,lane,caseType:reward.item_id,seasonTitle:ctx.season.title,rewardTitle:`${ctx.season.title}: уровень ${level}`,now}));
    }
  }else throw new ApiError(400,'Неизвестный тип награды сезонного пропуска.');
  statements.push(env.DB.prepare(`UPDATE season_pass_claims SET status='delivered',delivered_at=?,error_text='' WHERE season_id=? AND telegram_id=? AND level=? AND lane=? AND status='pending'`).bind(now,...key));
  // D1 batch is one transaction. All reward mutations are guarded by the pending
  // claim, so a concurrent request cannot award currency/boosters twice.
  const batch=await env.DB.batch(statements);
  const finalized=Number(batch?.[batch.length-1]?.meta?.changes||0)>0;
  if(finalized)seasonPassBackgroundWork(executionCtx,recordPlayerTimeline(env,ctx.telegramId,'season_pass_reward',`получил награду сезонного пропуска «${String(reward.title||'Награда')}»`,{seasonId:ctx.season.id,level,lane,rewardType:seasonPassPublicRewardType(reward),amount:reward.amount,itemId:seasonPassPublicRewardItemId(reward)},`season_pass_${ctx.season.id}_${level}_${lane}`,ctx.auth.user,now),'season pass reward timeline failed');
  return {repeated:!finalized,reward,entitlementsAdded};
}

async function claimSeasonPassReward(request,env,executionCtx=null){
  try{
    const ctx=await seasonPassRequestContext(request,env);if(ctx.season.status!=='active'&&!ctx.season.claimWindowOpen)throw new ApiError(409,'Период получения наград завершён.');
    const rawLevel=Number(ctx.body.level);if(!Number.isInteger(rawLevel)||rawLevel<1||rawLevel>50)throw new ApiError(400,'Некорректный уровень награды.');const level=rawLevel;
    const lane=String(ctx.body.lane||'');if(lane!=='free'&&lane!=='premium')throw new ApiError(400,'Некорректная линия награды.');
    const playerLevel=seasonPassLevelFromXp(ctx.player.xp);if(level>playerLevel)throw new ApiError(409,'Этот уровень ещё не открыт.');
    if(lane==='premium'&&String(ctx.player.premium_tier||'none')==='none')throw new ApiError(403,'Нужен тариф «Элитный» или «Элитный+».');
    const reward=await env.DB.prepare(`SELECT * FROM season_pass_rewards WHERE season_id=? AND level=? AND lane=? AND enabled=1 LIMIT 1`).bind(ctx.season.id,level,lane).first();if(!reward)throw new ApiError(404,'Награда не найдена.');
    const result=await grantSeasonPassReward(env,ctx,reward,executionCtx);
    const id=`${level}:${lane}`;const seasonalCases=seasonPassSeasonalCaseRewardDefinition(reward)?await seasonPassSeasonalCaseInventory(env,ctx.telegramId):null;
    return jsonResponse(seasonPassRewardMutationEnvelope(ctx,{
      claimedAdded:[id],
      entitlementsAdded:result.entitlementsAdded,
      received:[{level,lane,title:reward.title,rewardType:seasonPassPublicRewardType(reward),amount:reward.amount,itemId:seasonPassPublicRewardItemId(reward),imageUrl:seasonPassRewardImage(reward)}],
      ...(seasonalCases?{seasonalCases}:{}),
      repeated:result.repeated
    }));
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('claimSeasonPassReward failed',error);return jsonResponse({ok:false,error:'Не удалось начислить награду.'},500);}
}

async function claimAllSeasonPassRewards(request,env,executionCtx=null){
  try{
    const ctx=await seasonPassRequestContext(request,env);await assertSeasonPassNotForceClosed(env);if(ctx.season.status!=='active'&&!ctx.season.claimWindowOpen)throw new ApiError(409,'Период получения наград завершён.');
    const level=seasonPassLevelFromXp(ctx.player.xp);const premium=String(ctx.player.premium_tier||'none')!=='none';const now=Math.floor(Date.now()/1000);
    const rows=(await env.DB.prepare(`SELECT r.* FROM season_pass_rewards r LEFT JOIN season_pass_claims c ON c.season_id=r.season_id AND c.telegram_id=? AND c.level=r.level AND c.lane=r.lane WHERE r.season_id=? AND r.enabled=1 AND r.level<=? AND (r.lane='free' OR ?=1) AND (c.status IS NULL OR c.status!='delivered') ORDER BY r.level,r.lane`).bind(ctx.telegramId,ctx.season.id,level,premium?1:0).all()).results||[];
    if(!rows.length){
      const delivered=(await env.DB.prepare(`SELECT level,lane FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND status='delivered' AND level<=? AND (lane='free' OR ?=1) ORDER BY level,lane`).bind(ctx.season.id,ctx.telegramId,level,premium?1:0).all()).results||[];
      return jsonResponse(seasonPassRewardMutationEnvelope(ctx,{claimed:delivered.map(row=>`${Number(row.level)}:${String(row.lane)}`),received:[],failedRewards:[],stale:true}));
    }
    if(rows.some(reward=>{const cosmetic=seasonPassCosmeticRewardDefinition(reward);return cosmetic?.future&&!cosmetic?.released;}))throw new ApiError(409,'Среди наград есть контент, который не открыт для своих слотов Season Pass. Проверьте «Контент → Управление контентом».');

    // Bulk claim intentionally reuses the exact same idempotent grant path as a
    // successful single claim. The previous giant SQL batch was fast in theory,
    // but one malformed/unsupported aggregate statement caused the whole request
    // to fail while individual claims still worked. Small bounded batches keep the
    // request fast and make every reward independently recoverable/idempotent.
    const stateTouching=[];const parallelSafe=[];
    for(const reward of rows){
      const cosmetic=seasonPassCosmeticRewardDefinition(reward);const boost=seasonPassBoostRewardDefinition(reward);
      if(cosmetic||(boost&&CASE_BOOSTER_TYPES.includes(boost.kind)))stateTouching.push(reward);
      else parallelSafe.push(reward);
    }

    const results=[];
    const grantOne=async reward=>{
      try{
        const result=await grantSeasonPassReward(env,ctx,reward,executionCtx);
        return {ok:true,reward,result};
      }catch(error){
        console.error('bulk season pass reward item failed',{seasonId:ctx.season.id,telegramId:ctx.telegramId,level:Number(reward?.level||0),lane:String(reward?.lane||''),error});
        return {ok:false,reward,error};
      }
    };

    // Cosmetics and run boosters share case_player_state. Process them one by one
    // so a cosmetic full-state write can never race a booster increment.
    for(const reward of stateTouching)results.push(await grantOne(reward));

    // Currency, cases and XP entitlement are independent/idempotent. A small
    // concurrency window avoids both the old timeout and a write burst to D1.
    const BULK_REWARD_CONCURRENCY=6;
    for(let offset=0;offset<parallelSafe.length;offset+=BULK_REWARD_CONCURRENCY){
      const chunk=parallelSafe.slice(offset,offset+BULK_REWARD_CONCURRENCY);
      results.push(...await Promise.all(chunk.map(grantOne)));
    }

    const claimedAdded=[];const received=[];const entitlements=new Set();const failedRewards=[];
    for(const entry of results){
      const reward=entry.reward||{};const levelValue=Number(reward.level);const lane=String(reward.lane||'free');
      if(!entry.ok){failedRewards.push({level:levelValue,lane,title:String(reward.title||'Награда')});continue;}
      claimedAdded.push(`${levelValue}:${lane}`);
      for(const item of entry.result?.entitlementsAdded||[])entitlements.add(String(item));
      if(entry.result?.repeated)continue;
      received.push({level:levelValue,lane,title:String(reward.title||'Награда'),rewardType:seasonPassPublicRewardType(reward),amount:Number(reward.amount),itemId:seasonPassPublicRewardItemId(reward),imageUrl:seasonPassRewardImage(reward)});
    }

    if(received.length)seasonPassBackgroundWork(executionCtx,recordPlayerTimeline(env,ctx.telegramId,'season_pass_reward_bulk',`получил ${received.length} наград сезонного пропуска`,{seasonId:ctx.season.id,count:received.length,failed:failedRewards.length},`season_pass_bulk_${ctx.season.id}_${now}`,ctx.auth.user,now),'season pass bulk timeline failed');
    const seasonalCases=received.some(item=>item.rewardType==='seasonal_case')?await seasonPassSeasonalCaseInventory(env,ctx.telegramId):null;
    return jsonResponse(seasonPassRewardMutationEnvelope(ctx,{claimedAdded,entitlementsAdded:[...entitlements],received,failedRewards,...(seasonalCases?{seasonalCases}:{}),partial:failedRewards.length>0,repeated:received.length<=0&&failedRewards.length<=0}));
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('claimAllSeasonPassRewards failed',error);return jsonResponse({ok:false,error:'Не удалось начислить награды.'},500);}
}

async function seasonPassTaskProgressForClaim(env,season,telegramId,row){
  const period=String(row?.period)==='weekly'?'weekly':'daily';
  const metric=String(row?.metric||'runs');
  const bounds=seasonPassMoscowPeriod(period);
  const seasonStart=Math.floor(Date.parse(String(season?.startsAt||''))/1000);
  const seasonEnd=Math.floor(Date.parse(String(season?.endsAt||''))/1000);
  const startAt=Number.isFinite(seasonStart)?Math.max(bounds.startAt,seasonStart):bounds.startAt;
  const endAt=Number.isFinite(seasonEnd)?Math.max(startAt,Math.min(bounds.endAt,seasonEnd)):bounds.endAt;
  const id=String(telegramId),seasonId=String(season?.id||DEFAULT_SEASON_PASS_ID);
  if(metric==='cases_opened'){
    const [levelCases,grantedCases,seasonalCases]=await Promise.all([
      env.DB.prepare(`SELECT COUNT(*) AS value FROM level_case_openings WHERE telegram_id=? AND opened_at>=? AND opened_at<?`).bind(id,startAt,endAt).first(),
      env.DB.prepare(`SELECT COUNT(*) AS value FROM granted_cases WHERE telegram_id=? AND status='opened' AND opened_at>=? AND opened_at<?`).bind(id,startAt,endAt).first(),
      env.DB.prepare(`SELECT COUNT(*) AS value FROM season_pass_case_grants WHERE telegram_id=? AND status='opened' AND opened_at>=? AND opened_at<?`).bind(id,startAt,endAt).first()
    ]);
    return {value:Number(levelCases?.value||0)+Number(grantedCases?.value||0)+Number(seasonalCases?.value||0),periodKey:bounds.key,resetAt:bounds.resetAt};
  }
  const column=metric==='score'?'score':metric==='treats'?'run_treats':metric==='coffee'?'run_coffee':null;
  const aggregate=column
    ? await env.DB.prepare(`SELECT COALESCE(SUM(${column}),0) AS value FROM season_pass_activity_runs WHERE season_id=? AND telegram_id=? AND created_at>=? AND created_at<?`).bind(seasonId,id,startAt,endAt).first()
    : await env.DB.prepare(`SELECT COUNT(*) AS value FROM season_pass_activity_runs WHERE season_id=? AND telegram_id=? AND created_at>=? AND created_at<?`).bind(seasonId,id,startAt,endAt).first();
  return {value:Number(aggregate?.value||0),periodKey:bounds.key,resetAt:bounds.resetAt};
}

async function seasonPassTaskForClaim(env,season,telegramId,premiumTier,taskId){
  const row=await env.DB.prepare(`SELECT task_id,period,premium,metric,target,xp_reward,title,description FROM season_pass_tasks WHERE season_id=? AND task_id=? AND enabled=1 LIMIT 1`).bind(season.id,String(taskId)).first();
  if(!row)return null;
  const progressState=await seasonPassTaskProgressForClaim(env,season,telegramId,row);
  const target=Math.max(1,Number(row.target)||1);const rawProgress=Math.max(0,Number(progressState.value)||0);
  const premium=Number(row.premium||0)===1;
  return {id:String(row.task_id),period:String(row.period)==='weekly'?'weekly':'daily',premium,metric:String(row.metric||'runs'),target,xp:Math.max(1,Number(row.xp_reward)||1),title:String(row.title||''),description:String(row.description||''),progress:Math.min(rawProgress,target),rawProgress,complete:rawProgress>=target,claimed:false,locked:premium&&String(premiumTier||'none')==='none',periodKey:progressState.periodKey,resetAt:progressState.resetAt};
}

function seasonPassTaskTimelineLater(executionCtx,promise){
  if(executionCtx?.waitUntil)executionCtx.waitUntil(promise.catch(error=>console.error('season pass task timeline failed',error)));
  else void promise.catch(error=>console.error('season pass task timeline failed',error));
}

async function claimSeasonPassTaskGiftReward(env, telegramId, reward, executionCtx = null) {
  const id = String(telegramId || "").trim();
  const seasonId = String(reward?.seasonId || "").trim();
  const taskId = String(reward?.taskId || "").trim();
  const periodKey = String(reward?.periodKey || "").trim();
  if (!/^\d{4,20}$/.test(id) || !/^[A-Za-z0-9_-]{1,120}$/.test(seasonId) || !/^[A-Za-z0-9_-]{2,80}$/.test(taskId) || !/^[DW]:\d{4}-\d{2}-\d{2}$/.test(periodKey)) throw new ApiError(400,"Некорректная награда сезонного задания.");
  await ensureSeasonPassSchema(env);
  const [season,notification,taskRow] = await Promise.all([
    loadSeasonPassSeasonById(env,seasonId),
    env.DB.prepare(`SELECT task_title,xp_reward FROM season_pass_task_notifications WHERE season_id=? AND telegram_id=? AND task_id=? AND period_key=? LIMIT 1`).bind(seasonId,id,taskId,periodKey).first(),
    env.DB.prepare(`SELECT task_id,xp_reward,title FROM season_pass_tasks WHERE season_id=? AND task_id=? LIMIT 1`).bind(seasonId,taskId).first()
  ]);
  if (!season) throw new ApiError(404,"Сезон для этой награды не найден.");
  assertSeasonPassTaskClaimsOpen(season);
  if (!notification) throw new ApiError(404,"Выполненное задание не найдено.");
  if (!taskRow) throw new ApiError(404,"Задание сезонного пропуска больше недоступно.");
  const player = await ensureSeasonPassPlayer(env,season,id);
  const task = { id:taskId, periodKey, xp:Math.max(1,Number(taskRow.xp_reward)||1), title:String(notification.task_title || taskRow.title || "Задание") };
  return grantSeasonPassTaskXp(env,{season,telegramId:id,player,auth:{user:null}},task,executionCtx);
}

async function grantSeasonPassTaskXp(env,ctx,task,executionCtx=null){
  const now=Math.floor(Date.now()/1000);const key=[ctx.season.id,ctx.telegramId,String(task.id),String(task.periodKey)];
  const premiumMultiplier=await seasonPassHasXpX2(env,ctx.season.id,ctx.telegramId,ctx.player)?2:seasonPassTaskXpMultiplierForPlayer(ctx.season,ctx.player);
  const earnedMultiplier=seasonPassEarnedXpMultiplierView(ctx.season,ctx.player,premiumMultiplier,now*1000);
  const multiplier=earnedMultiplier.multiplier;
  const taskXp=Math.max(1,Number(task.xp)||1)*multiplier;
  // Keep the whole idempotent claim in one D1 transaction/round-trip. A concurrent
  // second request sees the row already delivered and cannot add XP twice.
  const batchResult=await env.DB.batch([
    env.DB.prepare(`INSERT OR IGNORE INTO season_pass_task_claims(season_id,telegram_id,task_id,period_key,status,xp_awarded,claimed_at) VALUES(?,?,?,?,'pending',?,?)`).bind(...key,taskXp,now),
    env.DB.prepare(`UPDATE season_pass_task_claims SET status='pending',xp_awarded=?,claimed_at=?,error_text='' WHERE season_id=? AND telegram_id=? AND task_id=? AND period_key=? AND status='failed'`).bind(taskXp,now,...key),
    env.DB.prepare(`UPDATE season_pass_players SET xp=xp+?,revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=? AND EXISTS(SELECT 1 FROM season_pass_task_claims WHERE season_id=? AND telegram_id=? AND task_id=? AND period_key=? AND status='pending')`).bind(taskXp,now,ctx.season.id,ctx.telegramId,...key),
    env.DB.prepare(`UPDATE season_pass_task_claims SET status='delivered',delivered_at=?,error_text='' WHERE season_id=? AND telegram_id=? AND task_id=? AND period_key=? AND status='pending'`).bind(now,...key),
    env.DB.prepare(`UPDATE season_pass_task_notifications SET bot_notified_at=CASE WHEN bot_notified_at<=0 THEN ? ELSE bot_notified_at END WHERE season_id=? AND telegram_id=? AND task_id=? AND period_key=?`).bind(now,...key)
  ]);
  const awarded=Number(batchResult?.[2]?.meta?.changes||0)>0;
  let mailChanged=false;
  try {
    await ensurePlayerGiftInboxSchema(env);
    const giftId=seasonPassTaskMailGiftId(ctx.season.id,task.id,task.periodKey);
    const mailResults=await env.DB.batch([
      env.DB.prepare(`UPDATE player_gift_inbox SET status='claimed',claimed_at=CASE WHEN claimed_at>0 THEN claimed_at ELSE ? END,updated_at=? WHERE telegram_id=? AND gift_id=? AND status IN ('pending','claiming')`).bind(now,now,ctx.telegramId,giftId),
      env.DB.prepare(`UPDATE player_mail_metadata SET read_at=CASE WHEN read_at>0 THEN read_at ELSE ? END WHERE telegram_id=? AND gift_id=?`).bind(now,ctx.telegramId,giftId)
    ]);
    mailChanged=mailResults.some((result)=>Number(result?.meta?.changes||0)>0);
  } catch (mailError) { console.error('season pass task mail finalize failed',mailError); }
  if(awarded||mailChanged){
    await ensurePlayerAccountRevisionAvailable(env);
    await bumpPlayerAccountRevisionStatement(env,ctx.telegramId,now).run();
  }
  if(awarded)seasonPassTaskTimelineLater(executionCtx,recordPlayerTimeline(env,ctx.telegramId,'season_pass_task',`получил ${taskXp.toLocaleString('ru-RU')} XP за задание «${String(task.title||'Задание')}»`,{seasonId:ctx.season.id,taskId:task.id,periodKey:task.periodKey,xp:taskXp,multiplier},`season_pass_task_${ctx.season.id}_${task.id}_${task.periodKey}`,ctx.auth.user,now));
  return {repeated:!awarded,xp:awarded?taskXp:0,multiplier};
}

async function seasonPassTaskFastMutationState(env,season,telegramId){
  const [player,overflowClaims]=await Promise.all([
    env.DB.prepare(`SELECT * FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(season.id,String(telegramId)).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND lane='overflow' AND status='delivered'`).bind(season.id,String(telegramId)).first()
  ]);
  const catchUp=seasonPassCatchUpView(season,player);
  const finale=Math.max(0,Number(player?.xp)||0)>=SEASON_PASS_LEVEL_50_COMPLETE_XP?await seasonPassFinaleForPlayer(env,season,String(telegramId),player):null;
  return {player:seasonPassPlayerView(player),overflow:seasonPassOverflowView(player?.xp,Number(overflowClaims?.count||0)),catchUp,...(finale?{finale}: {})};
}

async function claimSeasonPassTask(request,env,executionCtx=null){
  try{
    const ctx=await seasonPassRequestContext(request,env);assertSeasonPassTaskClaimsOpen(ctx.season);
    const taskId=String(ctx.body.taskId||ctx.body.task_id||'').trim();if(!/^[A-Za-z0-9_-]{2,80}$/.test(taskId))throw new ApiError(400,'Некорректное задание.');
    const task=await seasonPassTaskForClaim(env,ctx.season,ctx.telegramId,ctx.player.premium_tier,taskId);if(!task)throw new ApiError(404,'Задание не найдено.');
    if(task.locked)throw new ApiError(403,'Для этого задания нужен платный тариф.');if(!task.complete)throw new ApiError(409,'Задание ещё не выполнено.');
    const result=await grantSeasonPassTaskXp(env,ctx,task,executionCtx);
    // Season-task pushes are realtime now. Any legacy delayed message for this
    // player is stale as soon as XP has been collected and must never arrive later.
    await cancelQueuedSeasonPassTaskNotifications(env,ctx.telegramId,'season-task-claimed');
    const fastState=await seasonPassTaskFastMutationState(env,ctx.season,ctx.telegramId);
    return jsonResponse({
      ok:true,
      season:{id:ctx.season.id,status:ctx.season.status,claimWindowOpen:ctx.season.claimWindowOpen,progression:seasonPassProgressionView(),capabilities:seasonPassCapabilities(ctx.season)},
      player:fastState.player,overflow:fastState.overflow,catchUp:fastState.catchUp,...(fastState.finale?{finale:fastState.finale}:{}),
      taskUpdate:{id:task.id,periodKey:task.periodKey,claimed:true,complete:true,progress:Math.max(Number(task.progress)||0,Number(task.target)||1)},
      taskClaimableDelta:-1,
      receivedTask:{id:task.id,title:task.title,xp:result.xp},
      repeated:result.repeated
    });
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('claimSeasonPassTask failed',error);return jsonResponse({ok:false,error:'Не удалось получить XP за задание.'},500);}
}

async function claimAllSeasonPassTasks(request,env,executionCtx=null){
  try{
    const ctx=await seasonPassRequestContext(request,env);assertSeasonPassTaskClaimsOpen(ctx.season);
    const tasksPayload=await buildSeasonPassTasksPayload(env,ctx.season,ctx.telegramId,ctx.player.premium_tier);const ready=tasksPayload.tasks.filter(task=>task.complete&&!task.claimed&&!task.locked);const now=Math.floor(Date.now()/1000);
    const taskPremiumMultiplier=await seasonPassHasXpX2(env,ctx.season.id,ctx.telegramId,ctx.player)?2:seasonPassTaskXpMultiplierForPlayer(ctx.season,ctx.player);
    const taskXpMultiplier=seasonPassEarnedXpMultiplierView(ctx.season,ctx.player,taskPremiumMultiplier,now*1000).multiplier;
    if(!ready.length){await cancelQueuedSeasonPassTaskNotifications(env,ctx.telegramId,'season-task-already-claimed');const fastState=await seasonPassTaskFastMutationState(env,ctx.season,ctx.telegramId);return jsonResponse({ok:true,season:{id:ctx.season.id,status:ctx.season.status,claimWindowOpen:ctx.season.claimWindowOpen,progression:seasonPassProgressionView(),capabilities:seasonPassCapabilities(ctx.season)},player:fastState.player,overflow:fastState.overflow,catchUp:fastState.catchUp,...(fastState.finale?{finale:fastState.finale}:{}),receivedTasks:[],taskUpdates:[],taskClaimableDelta:0,totalXp:0,stale:true});}
    const predicates=ready.map(()=>`(task_id=? AND period_key=?)`).join(' OR ');const pairBinds=ready.flatMap(task=>[String(task.id),String(task.periodKey)]);
    const valueSql=ready.map(()=>`(?,?,?,?,?,'pending',?)`).join(',');
    const valueBinds=ready.flatMap(task=>[ctx.season.id,ctx.telegramId,String(task.id),String(task.periodKey),Math.max(1,Number(task.xp)||1)*taskXpMultiplier,now]);
    const batch=await env.DB.batch([
      env.DB.prepare(`INSERT OR IGNORE INTO season_pass_task_claims(season_id,telegram_id,task_id,period_key,xp_awarded,status,claimed_at) VALUES ${valueSql}`).bind(...valueBinds),
      env.DB.prepare(`UPDATE season_pass_task_claims SET status='pending',claimed_at=?,error_text='' WHERE season_id=? AND telegram_id=? AND status='failed' AND (${predicates})`).bind(now,ctx.season.id,ctx.telegramId,...pairBinds),
      env.DB.prepare(`SELECT COALESCE(SUM(xp_awarded),0) AS total FROM season_pass_task_claims WHERE season_id=? AND telegram_id=? AND status='pending' AND (${predicates})`).bind(ctx.season.id,ctx.telegramId,...pairBinds),
      env.DB.prepare(`UPDATE season_pass_players SET xp=xp+COALESCE((SELECT SUM(xp_awarded) FROM season_pass_task_claims WHERE season_id=? AND telegram_id=? AND status='pending' AND (${predicates})),0),revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=? AND EXISTS(SELECT 1 FROM season_pass_task_claims WHERE season_id=? AND telegram_id=? AND status='pending' AND (${predicates}))`).bind(ctx.season.id,ctx.telegramId,...pairBinds,now,ctx.season.id,ctx.telegramId,ctx.season.id,ctx.telegramId,...pairBinds),
      env.DB.prepare(`UPDATE season_pass_task_claims SET status='delivered',delivered_at=?,error_text='' WHERE season_id=? AND telegram_id=? AND status='pending' AND (${predicates})`).bind(now,ctx.season.id,ctx.telegramId,...pairBinds),
      env.DB.prepare(`UPDATE season_pass_task_notifications SET bot_notified_at=CASE WHEN bot_notified_at<=0 THEN ? ELSE bot_notified_at END WHERE season_id=? AND telegram_id=? AND (${predicates})`).bind(now,ctx.season.id,ctx.telegramId,...pairBinds)
    ]);
    const awardedXp=Math.max(0,Number(batch?.[2]?.results?.[0]?.total||batch?.[2]?.results?.[0]?.TOTAL||0));
    const awarded=Number(batch?.[3]?.meta?.changes||0)>0&&awardedXp>0;
    if(awarded){
      try{
        await ensurePlayerGiftInboxSchema(env);
        const mailStatements=[];
        for(const task of ready){
          const giftId=seasonPassTaskMailGiftId(ctx.season.id,task.id,task.periodKey);
          mailStatements.push(
            env.DB.prepare(`UPDATE player_gift_inbox SET status='claimed',claimed_at=CASE WHEN claimed_at>0 THEN claimed_at ELSE ? END,updated_at=? WHERE telegram_id=? AND gift_id=? AND status IN ('pending','claiming')`).bind(now,now,ctx.telegramId,giftId),
            env.DB.prepare(`UPDATE player_mail_metadata SET read_at=CASE WHEN read_at>0 THEN read_at ELSE ? END WHERE telegram_id=? AND gift_id=?`).bind(now,ctx.telegramId,giftId)
          );
        }
        for(let index=0;index<mailStatements.length;index+=40)await env.DB.batch(mailStatements.slice(index,index+40));
      }catch(mailError){console.error('season pass bulk task mail finalize failed',mailError);}
      await ensurePlayerAccountRevisionAvailable(env);
      await bumpPlayerAccountRevisionStatement(env,ctx.telegramId,now).run();
    }
    await cancelQueuedSeasonPassTaskNotifications(env,ctx.telegramId,'season-task-claimed-all');
    const receivedTasks=awarded?ready.map(task=>({id:task.id,periodKey:task.periodKey,title:task.title,xp:Math.max(1,Number(task.xp)||1)*taskXpMultiplier})):[];
    if(awarded)seasonPassTaskTimelineLater(executionCtx,recordPlayerTimeline(env,ctx.telegramId,'season_pass_task_bulk',`получил ${awardedXp.toLocaleString('ru-RU')} XP за задания`,{seasonId:ctx.season.id,count:receivedTasks.length,xp:awardedXp},`season_pass_tasks_bulk_${ctx.season.id}_${now}`,ctx.auth.user,now));
    const fastState=await seasonPassTaskFastMutationState(env,ctx.season,ctx.telegramId);
    return jsonResponse({
      ok:true,
      season:{id:ctx.season.id,status:ctx.season.status,claimWindowOpen:ctx.season.claimWindowOpen,progression:seasonPassProgressionView(),capabilities:seasonPassCapabilities(ctx.season)},
      player:fastState.player,overflow:fastState.overflow,catchUp:fastState.catchUp,...(fastState.finale?{finale:fastState.finale}:{}),
      receivedTasks,
      taskUpdates:ready.map(task=>({id:task.id,periodKey:task.periodKey,claimed:true,complete:true})),
      taskClaimableDelta:-ready.length,
      totalXp:awarded?awardedXp:0
    });
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('claimAllSeasonPassTasks failed',error);return jsonResponse({ok:false,error:'Не удалось получить XP за задания.'},500);}
}

async function claimSeasonPassOverflow(request,env){
  try{
    const ctx=await seasonPassRequestContext(request,env);
    const capabilities=seasonPassCapabilities(ctx.season);
    if(!capabilities.canClaimRewards)throw new ApiError(409,'Получение бонусных наград сейчас недоступно.');
    // 50+ is intentionally universal: Free, Elite and Elite+ all use the same overflow reward lane.
    // Premium tiers only change XP earning speed and premium task/reward access.
    const player=await env.DB.prepare(`SELECT * FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId).first()||ctx.player;
    const claimedRow=await env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND lane='overflow' AND status='delivered'`).bind(ctx.season.id,ctx.telegramId).first();
    const overflow=seasonPassOverflowView(player?.xp,Number(claimedRow?.count||0));
    if(!overflow.unlocked||overflow.available<=0)throw new ApiError(409,'Бонусный золотой кейс ещё не открыт.');
    const requestedAll=ctx.body?.all!==false;
    const take=Math.max(1,Math.min(requestedAll?overflow.available:1,50));
    const now=Math.floor(Date.now()/1000);
    const received=[];
    let busyCount=0;
    for(let offset=1;offset<=take;offset+=1){
      const index=overflow.claimed+offset;
      const level=SEASON_PASS_MAX_LEVEL+index;
      const reward={level,lane:'overflow',rewardType:'case',amount:1,itemId:'gold',title:`Золотой кейс · 50+${index}`,imageUrl:'/assets/cases/gold_closed.png'};
      const grantId=`sp_overflow_${ctx.season.id}_${ctx.telegramId}_${index}`.replace(/[^A-Za-z0-9_-]/g,'_').slice(0,120);
      const reserved=await env.DB.prepare(`INSERT OR IGNORE INTO season_pass_claims(season_id,telegram_id,level,lane,status,reward_json,claimed_at,delivered_at,error_text) VALUES(?,?,?,'overflow','pending',?,?,0,'')`).bind(ctx.season.id,ctx.telegramId,level,JSON.stringify(reward),now).run();
      if(Number(reserved?.meta?.changes||0)<1){
        const existing=await env.DB.prepare(`SELECT status,claimed_at FROM season_pass_claims WHERE season_id=? AND telegram_id=? AND level=? AND lane='overflow' LIMIT 1`).bind(ctx.season.id,ctx.telegramId,level).first();
        const status=String(existing?.status||'');
        const stale=(status==='pending'&&now-Number(existing?.claimed_at||now)>=24)||status==='failed';
        if(stale){
          const recovered=await env.DB.prepare(`UPDATE season_pass_claims SET status='pending',reward_json=?,claimed_at=?,delivered_at=0,error_text='' WHERE season_id=? AND telegram_id=? AND level=? AND lane='overflow' AND (status='failed' OR (status='pending' AND claimed_at<=?))`).bind(JSON.stringify(reward),now,ctx.season.id,ctx.telegramId,level,now-24).run();
          if(Number(recovered?.meta?.changes||0)<1){busyCount+=1;continue;}
        }else{busyCount+=1;continue;}
      }
      try{
        await env.DB.batch([
          env.DB.prepare(`INSERT OR IGNORE INTO granted_cases(id,telegram_id,case_type,status,granted_by,reason,rewards_json,created_at) VALUES(?,?,'gold','pending','season-pass',?,'[]',?)`).bind(grantId,ctx.telegramId,`${ctx.season.title}: бонусный уровень 50+${index}`,now),
          env.DB.prepare(`UPDATE season_pass_claims SET status='delivered',delivered_at=?,error_text='' WHERE season_id=? AND telegram_id=? AND level=? AND lane='overflow' AND status='pending'`).bind(now,ctx.season.id,ctx.telegramId,level)
        ]);
        received.push(reward);
      }catch(deliveryError){
        await env.DB.prepare(`UPDATE season_pass_claims SET status='failed',error_text=? WHERE season_id=? AND telegram_id=? AND level=? AND lane='overflow' AND status='pending'`).bind(String(deliveryError?.message||deliveryError).slice(0,500),ctx.season.id,ctx.telegramId,level).run().catch(()=>{});
        throw deliveryError;
      }
    }
    const deliveredCount=received.length;
    if(!deliveredCount){
      if(busyCount>0)throw new ApiError(409,'Бонусная награда уже обрабатывается. Повторите через несколько секунд.');
      throw new ApiError(409,'Бонусный золотой кейс уже получен.');
    }
    try{await recordPlayerTimeline(env,ctx.telegramId,'season_pass_overflow',`получил ${deliveredCount} бонусн${deliveredCount===1?'ый':'ых'} золот${deliveredCount===1?'ой кейс':'ых кейса'} после 50 уровня`,{seasonId:ctx.season.id,count:deliveredCount,levels:received.map(item=>item.level)},`season_pass_overflow_${ctx.season.id}_${ctx.telegramId}_${received[0]?.level}_${received[received.length-1]?.level}`,ctx.auth.user,now);}catch(error){console.error('season pass overflow timeline failed',error);}
    const payload=await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId,{includeClaims:true});
    return jsonResponse({...payload,overflowReceived:deliveredCount,received:[{level:'50+',lane:'overflow',rewardType:'case',amount:deliveredCount,itemId:'gold',title:deliveredCount===1?'Золотой кейс':`Золотой кейс ×${deliveredCount}`,imageUrl:'/assets/cases/gold_closed.png'}]});
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('claimSeasonPassOverflow failed',error);return jsonResponse({ok:false,error:'Не удалось получить бонусный золотой кейс.'},500);}
}

function seasonPassInteger(value, fallback = 0) {
  const normalized = typeof value === "string"
    ? value.replace(/[\s\u00A0\u202F]/g, "").replace(",", ".")
    : value;
  const number = Number(normalized);
  if (!Number.isFinite(number)) return Math.max(0, Math.floor(Number(fallback) || 0));
  return Math.max(0, Math.min(999999999, Math.floor(number)));
}

function seasonPassTierCharge(season,tier,currentTier) {
  const price = season?.prices?.[tier] || {};
  const base = currentTier === 'elite' && tier === 'elite_plus' ? (season?.prices?.elite || {}) : {};
  return {
    points:Math.max(0,seasonPassInteger(price.points)-seasonPassInteger(base.points)),
    treats:Math.max(0,seasonPassInteger(price.treats)-seasonPassInteger(base.treats)),
    coffee:Math.max(0,seasonPassInteger(price.coffee)-seasonPassInteger(base.coffee))
  };
}

async function seasonPassAccountBalance(env,telegramId){
  await ensureCasePlayerState(env,telegramId,{});
  const row=await env.DB.prepare(`SELECT wallet,treats,coffee,wallet_override,treats_override,coffee_override,pending_wallet,pending_treats,pending_coffee FROM admin_profile_state WHERE telegram_id=? LIMIT 1`).bind(telegramId).first();
  return {
    row,
    points:(row?.wallet_override==null?Number(row?.wallet||0):Number(row?.wallet_override||0))+Number(row?.pending_wallet||0),
    treats:(row?.treats_override==null?Number(row?.treats||0):Number(row?.treats_override||0))+Number(row?.pending_treats||0),
    coffee:(row?.coffee_override==null?Number(row?.coffee||0):Number(row?.coffee_override||0))+Number(row?.pending_coffee||0)
  };
}

function seasonPassBalanceGuardStatement(env,guardId,telegramId,price){
  return env.DB.prepare(`INSERT INTO season_pass_purchase_guards(guard_id,ok) VALUES(?,COALESCE((
    SELECT CASE WHEN
      ((CASE WHEN wallet_override IS NULL THEN wallet ELSE wallet_override END)+pending_wallet)>=? AND
      ((CASE WHEN treats_override IS NULL THEN treats ELSE treats_override END)+pending_treats)>=? AND
      ((CASE WHEN coffee_override IS NULL THEN coffee ELSE coffee_override END)+pending_coffee)>=?
    THEN 1 ELSE 0 END FROM admin_profile_state WHERE telegram_id=? LIMIT 1
  ),0))`).bind(String(guardId),seasonPassInteger(price.points),seasonPassInteger(price.treats),seasonPassInteger(price.coffee),String(telegramId));
}

// The tier price is calculated from the tier seen at request start. Guard that
// exact state inside the same D1 transaction so concurrent Elite / Elite+
// purchases cannot both charge a stale "none" (or stale "elite") price.
function seasonPassTierStateGuardStatement(env,guardId,seasonId,telegramId,expectedTier){
  return env.DB.prepare(`INSERT INTO season_pass_purchase_guards(guard_id,ok) VALUES(?,COALESCE((
    SELECT CASE WHEN premium_tier=? THEN 1 ELSE 0 END
    FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1
  ),0))`).bind(String(guardId),String(expectedTier),String(seasonId),String(telegramId));
}

function seasonPassChargeStatement(env,telegramId,price,now,source){
  const points=seasonPassInteger(price.points);const treats=seasonPassInteger(price.treats);const coffee=seasonPassInteger(price.coffee);
  return env.DB.prepare(`UPDATE admin_profile_state SET
    wallet=((CASE WHEN wallet_override IS NULL THEN wallet ELSE wallet_override END)+pending_wallet)-?,
    wallet_override=((CASE WHEN wallet_override IS NULL THEN wallet ELSE wallet_override END)+pending_wallet)-?,
    treats=((CASE WHEN treats_override IS NULL THEN treats ELSE treats_override END)+pending_treats)-?,
    treats_override=((CASE WHEN treats_override IS NULL THEN treats ELSE treats_override END)+pending_treats)-?,
    coffee=((CASE WHEN coffee_override IS NULL THEN coffee ELSE coffee_override END)+pending_coffee)-?,
    coffee_override=((CASE WHEN coffee_override IS NULL THEN coffee ELSE coffee_override END)+pending_coffee)-?,
    pending_wallet=0,pending_treats=0,pending_coffee=0,revision=revision+1,updated_at=?,updated_by=?
    WHERE telegram_id=?`).bind(points,points,treats,treats,coffee,coffee,now,String(source),String(telegramId));
}

async function elitePlusBenefitPlan(env,ctx,player,now,options={}){
  const benefits=ctx.season?.tierSettings?.elitePlus || seasonPassElitePlusBenefitsView(defaultSeasonPassElitePlusBenefits());
  const benefitCosmetics=Array.isArray(benefits.cosmetics)?benefits.cosmetics:[];
  const hasFutureCosmetics=benefitCosmetics.some((item)=>item?.future&&item?.kind&&item?.itemId);
  const freshLiveRules=hasFutureCosmetics?await readLiveContentReleaseRules(env,true):null;
  const hidden=benefitCosmetics.find((item)=>{if(!item?.future)return false;const rule=freshLiveRules?.get(liveContentReleaseKey(item.kind,item.itemId));return !rule?.released||!liveContentRouteEnabled(rule,'manual');});
  if(hidden)throw new ApiError(409,'Эксклюзивная награда тарифа относится к скрытому будущему контенту. Откройте контент релизным обновлением перед продажей тарифа.');
  const bonusAlreadyGranted=Boolean(options.bonusAlreadyGranted);
  const source=String(options.source||'elite_plus');
  const state=(await ensureCasePlayerState(env,ctx.telegramId,{})).state;
  state.ownedSpecials=Array.isArray(state.ownedSpecials)?state.ownedSpecials:[];
  if(benefits.xpBoost&&!state.ownedSpecials.includes(SEASON_PASS_SPECIAL_XP_X2))state.ownedSpecials.push(SEASON_PASS_SPECIAL_XP_X2);
  const cosmetics=(Array.isArray(benefits.cosmetics)?benefits.cosmetics:[]).filter((item)=>item?.kind&&item?.itemId);
  for(const cosmetic of cosmetics)seasonPassApplyCosmeticToState(state,cosmetic);
  const currentLevel=seasonPassLevelFromXp(player.xp);
  const bonusLevels=bonusAlreadyGranted?0:Math.max(0,Math.min(25,Number(benefits.bonusLevels)||0));
  const targetLevel=Math.min(50,currentLevel+bonusLevels);
  const grantedBonusLevels=Math.max(0,targetLevel-currentLevel);
  const targetXp=grantedBonusLevels>0?Math.max(Number(player.xp)||0,seasonPassXpForLevel(targetLevel)):Math.max(0,Number(player.xp)||0);
  const statements=[
    env.DB.prepare(`UPDATE season_pass_players SET xp=?,premium_tier='elite_plus',elite_plus_bonus_granted=1,revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=?`).bind(targetXp,now,ctx.season.id,ctx.telegramId)
  ];
  if(benefits.xpBoost){
    statements.push(env.DB.prepare(`INSERT OR IGNORE INTO season_pass_entitlements(season_id,telegram_id,item_id,source,granted_at) VALUES(?,?,?,?,?)`).bind(ctx.season.id,ctx.telegramId,SEASON_PASS_SPECIAL_XP_X2,source,now));
  }
  for(const cosmetic of cosmetics){
    statements.push(env.DB.prepare(`INSERT OR IGNORE INTO season_pass_entitlements(season_id,telegram_id,item_id,source,granted_at) VALUES(?,?,?,?,?)`).bind(ctx.season.id,ctx.telegramId,`${SEASON_PASS_COSMETIC_PREFIX}${cosmetic.kind}:${cosmetic.itemId}`,source,now));
  }
  const caseType=benefits.case?.type?normalizeCaseType(benefits.case.type):"";
  const caseCount=!bonusAlreadyGranted&&caseType?Math.max(0,Math.min(10,Number(benefits.case?.count)||0)):0;
  for(let index=0;index<caseCount;index+=1){
    const grantId=`sp_elite_plus_case_${ctx.season.id}_${ctx.telegramId}_${index+1}`.replace(/[^A-Za-z0-9_-]/g,'_').slice(0,120);
    statements.push(env.DB.prepare(`INSERT OR IGNORE INTO granted_cases(id,telegram_id,case_type,status,granted_by,reason,rewards_json,created_at) VALUES(?,? ,?,'pending','season-pass',?,'[]',?)`).bind(grantId,ctx.telegramId,caseType,`${ctx.season.title}: бонус Элитный+`,now));
  }
  statements.push(caseStateUpdateStatement(env,ctx.telegramId,state,now));
  const received=[];
  if(benefits.xpBoost)received.push({title:'×2 XP сезонного пропуска',itemId:SEASON_PASS_SPECIAL_XP_X2,imageUrl:'/assets/season-pass/xp_x2.png'});
  if(grantedBonusLevels>0)received.push({title:`+${grantedBonusLevels} уровней`,itemId:`levels_${grantedBonusLevels}`,imageUrl:'/assets/season-pass/levels_5.png'});
  for(const cosmetic of cosmetics)received.push({title:String(cosmetic.title||'Эксклюзивная награда'),itemId:String(cosmetic.itemId),imageUrl:String(cosmetic.imageUrl||'/assets/season-pass/season.png')});
  if(caseCount>0)received.push({title:`${String(benefits.case?.title||'Кейс')}${caseCount>1?` ×${caseCount}`:''}`,itemId:`${caseType}_case`,imageUrl:String(benefits.case?.imageUrl||ownerPanelCaseAsset(caseType))});
  return {statements,received,activation:{fromLevel:currentLevel,toLevel:targetLevel,bonusLevels:grantedBonusLevels,caseCount,caseType}};
}

async function reconcileDeliveredSeasonPassTier(env,ctx,effectiveTier,now){
  if(effectiveTier!=='elite_plus'){
    await env.DB.prepare(`UPDATE season_pass_players SET premium_tier=CASE WHEN premium_tier='elite_plus' THEN 'elite_plus' ELSE 'elite' END,revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=?`).bind(now,ctx.season.id,ctx.telegramId).run();
    return 'elite';
  }
  const currentPlayer=await env.DB.prepare(`SELECT xp,elite_plus_bonus_granted FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId).first();
  const bonusAlreadyGranted=Number(currentPlayer?.elite_plus_bonus_granted||0)===1;
  const plan=await elitePlusBenefitPlan(env,ctx,{...ctx.player,xp:Math.max(0,Number(currentPlayer?.xp)||0)},now,{source:'elite_plus-reconcile',bonusAlreadyGranted});
  await env.DB.batch(plan.statements);
  const upgradedPlayer=await env.DB.prepare(`SELECT * FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId).first();
  await reconcileElitePlusTaskXpBoost(env,ctx.season,ctx.telegramId,upgradedPlayer);
  return 'elite_plus';
}

async function purchaseSeasonPassTier(request,env){
  try{
    const ctx=await seasonPassRequestContext(request,env);
    await assertSeasonPassNotForceClosed(env);
    if(ctx.season.status!=='active'){
      const message=ctx.season.status==='ended'
        ? 'Сезон завершён. Покупка «Элитного» и «Элитного+» недоступна.'
        : 'Сезон ещё не начался. Покупка тарифов недоступна.';
      throw new ApiError(409,message);
    }
    const tier=String(ctx.body.tier||'');if(tier!=='elite'&&tier!=='elite_plus')throw new ApiError(400,'Некорректный тариф сезонного пропуска.');
    let current=String(ctx.player.premium_tier||'none');
    const now=Math.floor(Date.now()/1000);const purchaseKey=tier;
    const existing=await env.DB.prepare(`SELECT status,created_at FROM season_pass_purchases WHERE season_id=? AND telegram_id=? AND purchase_key=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId,purchaseKey).first();

    // Самовосстановление старого состояния: покупка уже записана, а карточка тарифа осталась неактивной.
    if(String(existing?.status)==='delivered'){
      const effectiveTier=tier==='elite_plus'?'elite_plus':(current==='elite_plus'?'elite_plus':'elite');
      if(current!==effectiveTier){
        current=await reconcileDeliveredSeasonPassTier(env,ctx,effectiveTier,now);
      }
      return jsonResponse({...await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId,{includeEntitlements:true,includeTasks:true,premiumTier:current}),received:[],repeated:true,purchasedTier:current});
    }
    if(current==='elite_plus'||current===tier){
      return jsonResponse({...await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId,{includeEntitlements:true,includeTasks:true,premiumTier:current}),received:[],repeated:true,purchasedTier:current});
    }
    if(String(existing?.status)==='pending'){
      if(now-Number(existing.created_at||now)<120)throw new ApiError(409,'Покупка уже обрабатывается. Повторите через несколько секунд.');
      await env.DB.prepare(`DELETE FROM season_pass_purchases WHERE season_id=? AND telegram_id=? AND purchase_key=? AND status='pending'`).bind(ctx.season.id,ctx.telegramId,purchaseKey).run();
    }

    const price=seasonPassTierCharge(ctx.season,tier,current);
    const balance=await seasonPassAccountBalance(env,ctx.telegramId);
    if(balance.points<price.points||balance.treats<price.treats||balance.coffee<price.coffee)throw new ApiError(409,'Недостаточно игровой валюты для покупки тарифа.');
    const guardId=`tier:${ctx.season.id}:${ctx.telegramId}:${purchaseKey}:${now}`.slice(0,180);
    const tierStateGuardId=`tier-state:${ctx.season.id}:${ctx.telegramId}:${tier}:${current}:${now}`.slice(0,180);
    const statements=[
      env.DB.prepare(`INSERT INTO season_pass_purchases(season_id,telegram_id,purchase_key,status,price_points,price_treats,price_coffee,created_at) VALUES(?,?,?,'pending',?,?,?,?)`).bind(ctx.season.id,ctx.telegramId,purchaseKey,price.points,price.treats,price.coffee,now),
      seasonPassTierStateGuardStatement(env,tierStateGuardId,ctx.season.id,ctx.telegramId,current),
      seasonPassBalanceGuardStatement(env,guardId,ctx.telegramId,price),
      seasonPassChargeStatement(env,ctx.telegramId,price,now,`season-pass:${ctx.season.id}:${tier}`)
    ];
    let elitePlusPlan=null;
    if(tier==='elite_plus'){
      elitePlusPlan=await elitePlusBenefitPlan(env,ctx,ctx.player,now,{source:'elite_plus',bonusAlreadyGranted:Boolean(ctx.player?.elite_plus_bonus_granted)});
      statements.push(...elitePlusPlan.statements);
    } else statements.push(env.DB.prepare(`UPDATE season_pass_players SET premium_tier='elite',revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=?`).bind(now,ctx.season.id,ctx.telegramId));
    statements.push(
      env.DB.prepare(`UPDATE season_pass_purchases SET status='delivered',completed_at=? WHERE season_id=? AND telegram_id=? AND purchase_key=? AND status='pending'`).bind(now,ctx.season.id,ctx.telegramId,purchaseKey),
      env.DB.prepare(`DELETE FROM season_pass_purchase_guards WHERE guard_id IN (?,?)`).bind(guardId,tierStateGuardId)
    );
    try{await env.DB.batch(statements);}catch(batchError){
      const after=await env.DB.prepare(`SELECT status FROM season_pass_purchases WHERE season_id=? AND telegram_id=? AND purchase_key=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId,purchaseKey).first();
      if(String(after?.status)==='delivered')return jsonResponse({...await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId,{includeEntitlements:true,includeTasks:true,premiumTier:tier}),received:[],repeated:true,purchasedTier:tier});
      const text=String(batchError?.message||batchError).toLowerCase();
      if(text.includes('check constraint')||text.includes('season_pass_purchase_guards')){
        const actualTier=String((await env.DB.prepare(`SELECT premium_tier FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId).first())?.premium_tier||'none');
        if(actualTier!==current)throw new ApiError(409,'Тариф уже изменился. Обновите сезонный пропуск и повторите покупку по актуальной цене.');
        throw new ApiError(409,'Баланс изменился. Проверьте валюту и повторите покупку.');
      }
      if(text.includes('unique')||text.includes('primary key'))throw new ApiError(409,'Покупка уже обрабатывается. Повторите через несколько секунд.');
      throw batchError;
    }
    if(tier==='elite_plus'){
      const upgradedPlayer=await env.DB.prepare(`SELECT * FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId).first();
      await reconcileElitePlusTaskXpBoost(env,ctx.season,ctx.telegramId,upgradedPlayer);
    }
    try{await recordPlayerTimeline(env,ctx.telegramId,'season_pass_purchase',`активировал тариф «${tier==='elite_plus'?'Элитный+':'Элитный'}»`,{seasonId:ctx.season.id,tier,price},`season_pass_purchase_${ctx.season.id}_${tier}`,ctx.auth.user,now);}catch(error){console.error('season pass purchase timeline failed',error);}
    try{await queueSeasonPassTierActivationNotice(env,{season:ctx.season,telegramId:ctx.telegramId,previousTier:current,newTier:tier,source:'battle_pass_purchase',sourceKey:`purchase:${tier}`,activatedAt:now,payload:elitePlusPlan?.activation||{fromLevel:seasonPassLevelFromXp(ctx.player?.xp),toLevel:seasonPassLevelFromXp(ctx.player?.xp),bonusLevels:0}});}catch(error){console.error('season pass purchase activation notice failed',error);}
    try{await refreshReferralProgressForInvitee(env,ctx.telegramId,{source:'season_tier',seasonId:ctx.season.id,tier});}catch(error){console.error('referral season tier refresh failed',error);}
    const received=tier==='elite_plus'?(elitePlusPlan?.received||[]):[];
    return jsonResponse({...await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId,{includeEntitlements:true,includeTasks:true,premiumTier:tier}),received,pricePaid:price,repeated:false,purchasedTier:tier});
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('purchaseSeasonPassTier failed',error);return jsonResponse({ok:false,error:'Не удалось активировать тариф.'},500);}
}

async function purchaseSeasonPassLevel(request,env){
  try{
    const ctx=await seasonPassRequestContext(request,env);
    await assertSeasonPassNotForceClosed(env);
    if(ctx.season.status!=='active')throw new ApiError(409,ctx.season.status==='ended'?'Сезон завершён. Покупка уровней недоступна.':'Сезон ещё не начался. Покупка уровней недоступна.');
    if(String(ctx.player.premium_tier||'none')==='none')throw new ApiError(403,'Покупка уровней доступна только платному тарифу.');
    const currentLevel=seasonPassLevelFromXp(ctx.player.xp);if(currentLevel>=50)throw new ApiError(409,'Уже достигнут максимальный уровень.');
    const targetLevel=Math.max(2,Math.min(50,Math.floor(Number(ctx.body.targetLevel||ctx.body.target_level||currentLevel+1))));
    if(targetLevel<=currentLevel)return jsonResponse({...await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId),purchasedLevel:currentLevel,pricePoints:0,repeated:true});
    if(targetLevel!==currentLevel+1)throw new ApiError(409,'Уровень изменился. Откройте подтверждение покупки ещё раз.');

    const price=seasonPassInteger(ctx.season.levelPricePoints,DEFAULT_SEASON_PASS_LEVEL_PRICE_POINTS);const now=Math.floor(Date.now()/1000);const purchaseKey=`level:${targetLevel}`;
    const existing=await env.DB.prepare(`SELECT status,created_at FROM season_pass_purchases WHERE season_id=? AND telegram_id=? AND purchase_key=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId,purchaseKey).first();
    if(String(existing?.status)==='delivered'){
      const targetXp=seasonPassXpForLevel(targetLevel);
      await env.DB.prepare(`UPDATE season_pass_players SET xp=MAX(xp,?),revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=?`).bind(targetXp,now,ctx.season.id,ctx.telegramId).run();
      return jsonResponse({...await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId),purchasedLevel:targetLevel,pricePoints:price,repeated:true});
    }
    if(String(existing?.status)==='pending'){
      if(now-Number(existing.created_at||now)<120)throw new ApiError(409,'Покупка уровня уже обрабатывается.');
      await env.DB.prepare(`DELETE FROM season_pass_purchases WHERE season_id=? AND telegram_id=? AND purchase_key=? AND status='pending'`).bind(ctx.season.id,ctx.telegramId,purchaseKey).run();
    }

    const balance=await seasonPassAccountBalance(env,ctx.telegramId);if(balance.points<price)throw new ApiError(409,`Недостаточно очков. Требуется ${price.toLocaleString('ru-RU')}.`);
    const targetXp=seasonPassXpForLevel(targetLevel);const guardId=`level:${ctx.season.id}:${ctx.telegramId}:${targetLevel}:${now}`.slice(0,180);
    const priceObject={points:price,treats:0,coffee:0};
    try{await env.DB.batch([
      env.DB.prepare(`INSERT INTO season_pass_purchases(season_id,telegram_id,purchase_key,status,price_points,price_treats,price_coffee,created_at) VALUES(?,?,?,'pending',?,0,0,?)`).bind(ctx.season.id,ctx.telegramId,purchaseKey,price,now),
      seasonPassBalanceGuardStatement(env,guardId,ctx.telegramId,priceObject),
      seasonPassChargeStatement(env,ctx.telegramId,priceObject,now,`season-pass:${ctx.season.id}:level-${targetLevel}`),
      env.DB.prepare(`UPDATE season_pass_players SET xp=MAX(xp,?),revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=?`).bind(targetXp,now,ctx.season.id,ctx.telegramId),
      env.DB.prepare(`UPDATE season_pass_purchases SET status='delivered',completed_at=? WHERE season_id=? AND telegram_id=? AND purchase_key=? AND status='pending'`).bind(now,ctx.season.id,ctx.telegramId,purchaseKey),
      env.DB.prepare(`DELETE FROM season_pass_purchase_guards WHERE guard_id=?`).bind(guardId)
    ]);}catch(batchError){
      const after=await env.DB.prepare(`SELECT status FROM season_pass_purchases WHERE season_id=? AND telegram_id=? AND purchase_key=? LIMIT 1`).bind(ctx.season.id,ctx.telegramId,purchaseKey).first();
      if(String(after?.status)==='delivered')return jsonResponse({...await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId),purchasedLevel:targetLevel,pricePoints:price,repeated:true});
      const text=String(batchError?.message||batchError).toLowerCase();
      if(text.includes('check constraint')||text.includes('season_pass_purchase_guards'))throw new ApiError(409,'Баланс изменился. Проверьте количество очков и повторите покупку.');
      if(text.includes('unique')||text.includes('primary key'))throw new ApiError(409,'Покупка уровня уже обрабатывается.');
      throw batchError;
    }
    try{await recordPlayerTimeline(env,ctx.telegramId,'season_pass_level_purchase',`купил ${targetLevel} уровень сезонного пропуска`,{seasonId:ctx.season.id,targetLevel,pricePoints:price},`season_pass_level_${ctx.season.id}_${targetLevel}`,ctx.auth.user,now);}catch(error){console.error('season pass level timeline failed',error);}
    return jsonResponse({...await buildSeasonPassMutationPayload(env,ctx.season,ctx.telegramId),purchasedLevel:targetLevel,pricePoints:price,repeated:false});
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('purchaseSeasonPassLevel failed',error);return jsonResponse({ok:false,error:'Не удалось купить уровень.'},500);}
}

async function recordSeasonPassRunActivity(env,telegramId,input={},seasonValue=null,options={}){
  await ensureSeasonPassSchema(env);
  const flag=await getFeatureFlag(env,'battle_pass');const access=await battlePassAudienceAccess(env,String(telegramId),flag);
  if(!access.allowed)return {accepted:false,ignored:true,reason:'not_allowed',xpAwarded:0,multiplier:1};
  const now=Math.floor(Date.now()/1000);
  const runCreatedAt=Math.max(1,Math.floor(Number(options?.runCreatedAt||now))||now);
  const forcedClosure=await getSeasonPassForcedClosure(env,runCreatedAt*1000);
  if(forcedClosure)return {accepted:false,ignored:true,reason:'forced_closed',xpAwarded:0,multiplier:1};
  const season=seasonValue||await loadSeasonPassSeason(env,runCreatedAt*1000);
  if(season.status!=='active')return {accepted:false,ignored:true,reason:season.status,xpAwarded:0,multiplier:1};
  const runId=String(input.runId||input.run_id||'').trim();if(!/^[A-Za-z0-9_-]{12,96}$/.test(runId))throw new ApiError(400,'Некорректный идентификатор забега.');
  const score=Math.max(0,Math.floor(Number(input.score)||0));const durationMs=Math.max(0,Math.floor(Number(input.durationMs||input.duration_ms)||0));
  const runTreats=Math.max(0,Math.min(10000,Math.floor(Number(input.runTreats||input.run_treats)||0)));const runCoffee=Math.max(0,Math.min(10000,Math.floor(Number(input.runCoffee||input.run_coffee)||0)));
  const newRecord=Boolean(input.newRecord||input.new_record)?1:0;const minSeconds=positiveInt(env.LEADERBOARD_MIN_RUN_SECONDS,DEFAULT_LEADERBOARD_MIN_RUN_SECONDS);const minScore=positiveInt(env.LEADERBOARD_MIN_SCORE,DEFAULT_LEADERBOARD_MIN_SCORE);const durationSeconds=durationMs/1000;
  if(!Number.isFinite(durationSeconds)||durationSeconds<minSeconds||score<minScore)throw new ApiError(400,`Забег должен длиться от ${minSeconds} секунд и набрать от ${minScore} очков.`);
  // Public callers cannot bypass validation: submitSeasonPassRun below only
  // reaches this function with a matching authoritative run-ledger row.
  if(options?.serverValidated!==true&&score>Math.floor(durationSeconds*90+6000))throw new ApiError(400,'Забег не прошёл серверную проверку.');
  const seasonStart=Math.floor(Date.parse(season.startsAt)/1000);const seasonEnd=Math.floor(Date.parse(season.endsAt)/1000);if(runCreatedAt<seasonStart||runCreatedAt>=seasonEnd)return {accepted:false,ignored:true,reason:'outside_season',xpAwarded:0,multiplier:1};

  const id=String(telegramId);
  const sameActivity=(row)=>row&&String(row.season_id)===String(season.id)&&String(row.telegram_id)===id&&Number(row.score)===score&&Number(row.duration_ms)===durationMs&&Number(row.run_treats)===runTreats&&Number(row.run_coffee)===runCoffee&&Number(row.new_record)===newRecord;
  let repeated=false;
  let activityCreatedAt=runCreatedAt;
  let taskEvent=null;
  const existingBefore=await env.DB.prepare(`SELECT season_id,telegram_id,score,duration_ms,run_treats,run_coffee,new_record,created_at FROM season_pass_activity_runs WHERE run_id=? LIMIT 1`).bind(runId).first();
  if(existingBefore){
    if(!sameActivity(existingBefore))throw new ApiError(409,'Этот идентификатор забега уже использован.');
    repeated=true;
    activityCreatedAt=Math.max(1,Number(existingBefore.created_at||runCreatedAt));
  }else{
    // Prepare task crossings before the run is inserted so the lazy backfill sees
    // only historical activity. The insert + counters + notification rows are
    // committed atomically below, so a repeated run cannot increment progress twice.
    taskEvent=await prepareSeasonPassTaskProgressEvent(env,id,{runs:1,score,treats:runTreats,coffee:runCoffee},runCreatedAt,{season});
    const statements=[
      env.DB.prepare(`INSERT INTO season_pass_activity_runs(run_id,season_id,telegram_id,score,duration_ms,run_treats,run_coffee,new_record,created_at) VALUES(?,?,?,?,?,?,?,?,?)`).bind(runId,season.id,id,score,durationMs,runTreats,runCoffee,newRecord,runCreatedAt),
      ...(taskEvent?.progressStatements||[]),
      ...(taskEvent?.notificationStatements||[])
    ];
    try{
      await env.DB.batch(statements);
    }catch(error){
      const text=String(error?.message||error).toLowerCase();
      if(text.includes('unique')||text.includes('primary key')){
        const raced=await env.DB.prepare(`SELECT season_id,telegram_id,score,duration_ms,run_treats,run_coffee,new_record,created_at FROM season_pass_activity_runs WHERE run_id=? LIMIT 1`).bind(runId).first();
        if(!sameActivity(raced))throw new ApiError(409,'Этот идентификатор забега уже использован.');
        repeated=true;
        activityCreatedAt=Math.max(1,Number(raced?.created_at||runCreatedAt));
        taskEvent=null;
      }else throw error;
    }
  }

  const award=await awardSeasonPassRunXp(env,id,runId,activityCreatedAt);
  const taskNotice=!repeated&&taskEvent?.taskRows?.length?seasonPassTaskNoticePublic(taskEvent.taskRows,season):null;
  if(!repeated&&taskEvent?.taskRows?.length){
    scheduleRunSettlementBackground(null,deliverSeasonPassTaskNotificationsForRows(env,id,season,taskEvent.taskRows),'season pass fallback notification failed');
  }
  return {accepted:true,repeated,xpAwarded:Number(award?.xpAwarded||0),multiplier:Number(award?.multiplier||1),profileXpMultiplier:Number(award?.premiumMultiplier||1),catchUp:Boolean(award?.catchUpActive),taskNotice};
}

async function submitSeasonPassRun(request,env){
  try{
    requireDatabase(env);requireBotToken(env);await ensureAuthoritativeEconomySchema(env);await ensureSeasonPassSchema(env);
    const body=await readJson(request);const auth=await validateTelegramInitData(String(body.initData||body.init_data||''),env);const telegramId=String(auth.user.id);
    const runId=String(body.runId||body.run_id||'').trim();if(!/^[A-Za-z0-9_-]{12,96}$/.test(runId))throw new ApiError(400,'Некорректный идентификатор забега.');
    const ledger=await env.DB.prepare(`SELECT * FROM player_economy_run_ledger WHERE run_id=? AND telegram_id=? LIMIT 1`).bind(runId,telegramId).first();
    if(!ledger)throw new ApiError(409,'Сначала завершите и подтвердите забег через защищённую игровую сессию.');
    const result=await recordSeasonPassRunActivity(env,telegramId,{
      runId,
      score:Number(ledger.raw_score||0),
      durationMs:Number(ledger.duration_ms||0),
      runTreats:Number(ledger.raw_treats||0),
      runCoffee:Number(ledger.raw_coffee||0),
      newRecord:Number(ledger.new_record||0)===1
    },null,{serverValidated:true,runCreatedAt:Number(ledger.created_at||Math.floor(Date.now()/1000))});
    return jsonResponse({ok:true,...result});
  }catch(error){if(error instanceof ApiError)return jsonResponse({ok:false,error:error.message},error.status);console.error('submitSeasonPassRun failed',error);return jsonResponse({ok:false,error:'Не удалось сохранить прогресс сезонного пропуска.'},500);}
}

async function awardSeasonPassRunXp(env,telegramId,runId,createdAt){
  try{await assertSeasonPassNotForceClosed(env);const runAt=Math.max(0,Number(createdAt||Math.floor(Date.now()/1000)))*1000;const forcedClosure=await getSeasonPassForcedClosure(env,runAt);if(forcedClosure)return null;const season=await loadSeasonPassSeason(env,runAt);if(season.status!=='active')return null;const startsAt=Date.parse(String(season.startsAt||''));const endsAt=Date.parse(String(season.endsAt||''));if((Number.isFinite(startsAt)&&runAt<startsAt)||(Number.isFinite(endsAt)&&runAt>=endsAt))return null;const player=await ensureSeasonPassPlayer(env,season,String(telegramId));const premiumMultiplier=await seasonPassHasXpX2(env,season.id,String(telegramId),player)?2:1;const earnedMultiplier=seasonPassEarnedXpMultiplierView(season,player,premiumMultiplier,runAt);const multiplier=earnedMultiplier.multiplier;const base=Math.max(1,Number(season.baseRunXp)||100);const awarded=base*multiplier;const now=Math.floor(Date.now()/1000);const id=String(telegramId),rid=String(runId),sid=String(season.id);
    const results=await env.DB.batch([
      env.DB.prepare(`INSERT OR IGNORE INTO season_pass_run_xp(run_id,season_id,telegram_id,base_xp,multiplier,xp_awarded,created_at,applied_at) VALUES(?,?,?,?,?,?,?,0)`).bind(rid,sid,id,base,multiplier,awarded,Number(createdAt)||now),
      env.DB.prepare(`UPDATE season_pass_players SET xp=xp+COALESCE((SELECT xp_awarded FROM season_pass_run_xp WHERE run_id=? AND season_id=? AND telegram_id=? AND applied_at=0),0),revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=? AND EXISTS(SELECT 1 FROM season_pass_run_xp WHERE run_id=? AND season_id=? AND telegram_id=? AND applied_at=0)`).bind(rid,sid,id,now,sid,id,rid,sid,id),
      env.DB.prepare(`UPDATE season_pass_run_xp SET applied_at=? WHERE run_id=? AND season_id=? AND telegram_id=? AND applied_at=0`).bind(now,rid,sid,id)
    ]);
    const applied=Number(results?.[2]?.meta?.changes||0)>0;return {xpAwarded:applied?awarded:0,multiplier,premiumMultiplier,catchUpActive:earnedMultiplier.catchUp.active};
  }catch(error){console.error('awardSeasonPassRunXp failed',error);return null;}
}

const SEASON_PASS_ADMIN_SELECTION_PREFIX='season-pass-admin-selection:';
const SEASON_PASS_CUSTOM_TASK_PREFIX='custom_';

function seasonPassAdminSelectionKey(userId){return `${SEASON_PASS_ADMIN_SELECTION_PREFIX}${String(userId||'')}`;}
function seasonPassStatusLabel(season){return season.status==='active'?'🟢 идёт':season.claimWindowOpen?'🟠 завершён · выдача наград':season.status==='ended'?'⚫ завершён':'🕒 ожидает старта';}
function seasonPassWorkflowCancelKeyboard(){return {inline_keyboard:[[{text:'❌ Отмена',callback_data:'sp_workflow_cancel'}]]};}

async function setSeasonPassAdminSelection(env,userId,seasonId){
  await setSystemState(env,seasonPassAdminSelectionKey(userId),String(seasonId||''));
}

async function resolveSeasonPassAdminSeason(env,user,nowMs=Date.now()){
  await ensureSeasonPassSchema(env);
  const state=await getSystemState(env,seasonPassAdminSelectionKey(user?.id));
  if(state?.value){
    const selected=await loadSeasonPassSeasonById(env,state.value,nowMs);
    if(selected)return selected;
  }
  const current=await loadSeasonPassSeason(env,nowMs);
  await setSeasonPassAdminSelection(env,user?.id,current.id);
  return current;
}

async function showSeasonPassAdminDashboard(chatId,user,env){
  const access=await requireAnySecurityPermission(chatId,user,['manageSeasons','manageMaintenance'],env);if(!access)return;
  const season=await resolveSeasonPassAdminSeason(env,user);const status=seasonPassStatusLabel(season);const elite=season.prices.elite;const plus=season.prices.elite_plus;
  const forcedClosure=await getSeasonPassForcedClosure(env);
  const forcedLine=forcedClosure
    ? `включено до ${escapeHtml(formatUtcDate(forcedClosure.unlockAt))} · откроется ${escapeHtml(forcedClosure.nextSeasonTitle || 'новый сезон')}`
    : 'выключено';
  const keyboard=[
    [{text:'🗓 Все сезоны',callback_data:'sp_seasons'},{text:'➕ Новый сезон',callback_data:'sp_season_new'}],
    [{text:'🎁 Награды уровней',callback_data:'sp_rewards:0'},{text:'📋 Задания',callback_data:'sp_tasks:0'}],
    [{text:'💳 Цены и XP',callback_data:'sp_settings'},{text:'📊 Статистика',callback_data:'sp_stats'}],
    [{text:'▶️ Начать сейчас',callback_data:`sp_start_now:${season.id}`},{text:'⏹ Завершить сейчас',callback_data:`sp_end_now:${season.id}`}]
  ];
  if(forcedClosure)keyboard.push([{text:`🔒 Закрыто до ${formatUtcDate(forcedClosure.unlockAt)}`,callback_data:'sp_noop'}]);
  else if(season.status==='active'||season.claimWindowOpen)keyboard.push([{text:'🔒 Принудительно закрыть до нового сезона',callback_data:`sp_force_close_confirm:${season.id}`}]);
  const lockedNextSeason=forcedClosure&&forcedClosure.nextSeasonId===season.id;
  const seasonStartsAtMs=Date.parse(String(season.startsAt||''));
  if(!lockedNextSeason&&season.id!==DEFAULT_SEASON_PASS_ID&&Number.isFinite(seasonStartsAtMs)&&seasonStartsAtMs>Date.now())keyboard.push([{text:'🗑 Удалить запланированный сезон',callback_data:`sp_season_delete_confirm:${season.id}`}]);
  keyboard.push([{text:'♻️ Сбросить прогресс и покупки всех',callback_data:`sp_reset_all_confirm:${season.id}`}],[{text:'👁 Настройки видимости',callback_data:'v65_feature:battle_pass'}],[{text:'⬅️ Админ-панель',callback_data:'adm_home'}]);
  await sendTelegramMessage(env,chatId,`<b>🎟 Сезонный пропуск</b>

Управляемый сезон: <b>${escapeHtml(season.title)}</b>
ID: <code>${escapeHtml(season.id)}</code>
Статус: <b>${status}</b>
Начало: <b>${escapeHtml(formatUtcDate(Math.floor(Date.parse(season.startsAt)/1000)))}</b>
Окончание: <b>${escapeHtml(formatUtcDate(Math.floor(Date.parse(season.endsAt)/1000)))}</b>
Получение наград до: <b>${escapeHtml(formatUtcDate(Math.floor(Date.parse(season.claimGraceEndsAt)/1000)))}</b>
Принудительное закрытие: <b>${forcedLine}</b>

<b>Тарифы</b>
Элитный: ${elite.points.toLocaleString('ru-RU')} очков · ${elite.treats} зефира · ${elite.coffee} кофе
Элитный+: ${plus.points.toLocaleString('ru-RU')} очков · ${plus.treats} зефира · ${plus.coffee} кофе
Уровень: ${season.levelPricePoints.toLocaleString('ru-RU')} очков`,{inline_keyboard:keyboard});
}

async function showSeasonPassSeasonsAdmin(chatId,user,env){
  const access=await requireAnySecurityPermission(chatId,user,['manageSeasons','manageMaintenance'],env);if(!access)return;await ensureSeasonPassSchema(env);
  const selected=await resolveSeasonPassAdminSeason(env,user);const nowMs=Date.now();
  const forcedClosure=await getSeasonPassForcedClosure(env,nowMs);
  const rows=(await env.DB.prepare(`SELECT * FROM season_pass_seasons ORDER BY starts_at DESC,updated_at DESC LIMIT 24`).all()).results||[];
  const items=rows.map(row=>({row,item:seasonPassSeasonFromRow(row,configuredSeasonPassState(env,nowMs),nowMs)}));
  const buttons=items.map(({item})=>{
    const mark=item.id===selected.id?'✅ ':'';
    const lockedNextSeason=Boolean(forcedClosure&&forcedClosure.nextSeasonId===item.id);
    const startsAtMs=Date.parse(String(item.startsAt||''));
    const canDelete=item.id!==DEFAULT_SEASON_PASS_ID&&!lockedNextSeason&&Number.isFinite(startsAtMs)&&startsAtMs>nowMs;
    const selectButton={text:`${mark}${seasonPassStatusLabel(item).split(' ')[0]} ${String(item.title).slice(0,canDelete?25:30)}`,callback_data:`sp_season_pick:${item.id}`};
    return canDelete?[selectButton,{text:'🗑',callback_data:`sp_season_delete_confirm:${item.id}`}]:[selectButton];
  });
  buttons.push([{text:'➕ Создать новый сезон',callback_data:'sp_season_new'}],[{text:'⬅️ Текущий сезон',callback_data:'sp_admin'}]);
  const lines=items.map(({row,item})=>{const lockedNextSeason=Boolean(forcedClosure&&forcedClosure.nextSeasonId===item.id);const note=lockedNextSeason?' · 🔒 выбран для таймера':'';return `${item.id===selected.id?'✅':'•'} <b>${escapeHtml(item.title)}</b> · ${seasonPassStatusLabel(item)}${note}\n${escapeHtml(formatUtcDate(Number(row.starts_at)))} — ${escapeHtml(formatUtcDate(Number(row.ends_at)))}`;});
  await sendTelegramMessage(env,chatId,`<b>🗓 Сезоны пропуска</b>\n\n${lines.join('\n\n')||'Сезонов пока нет.'}\n\nВыберите сезон, чтобы редактировать его. Любой сезон с будущей датой начала и без данных игроков можно удалить кнопкой 🗑, даже если его случайно завершили раньше старта. Сезон с отметкой 🔒 защищён, пока используется таймером.`,{inline_keyboard:buttons});
}

async function selectSeasonPassAdminSeason(query,seasonId,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;
  const season=await loadSeasonPassSeasonById(env,seasonId);if(!season){await answerCallback(env,query.id,'Сезон не найден.',true);return;}
  await setSeasonPassAdminSelection(env,query.from.id,season.id);await answerCallback(env,query.id,'Сезон выбран.');await showSeasonPassAdminDashboard(chatId,query.from,env);
}

function seasonPassSeasonCreateDateLabel(timestamp){return formatUtcDate(Math.floor(Number(timestamp)||0));}
async function seasonPassSeasonOverlap(env,startsAt,endsAt,excludeId=''){
  return env.DB.prepare(`SELECT season_id,title,starts_at,ends_at,claim_grace_ends_at FROM season_pass_seasons WHERE season_id!=? AND starts_at<? AND MAX(ends_at,claim_grace_ends_at)>? ORDER BY starts_at LIMIT 1`).bind(String(excludeId||''),Number(endsAt),Number(startsAt)).first();
}

async function startSeasonPassSeasonCreate(query,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;
  const source=await resolveSeasonPassAdminSeason(env,query.from);
  await setStaffWorkflow(query.from.id,chatId,'season_pass_season_create','title',{sourceSeasonId:source.id},env);
  await answerCallback(env,query.id,'Создаём новый сезон.');
  await sendTelegramMessage(env,chatId,`<b>➕ Новый сезон</b>\n\nОтправьте название сезона одним сообщением.\n\nПример: <code>Сезон II: Сладкое лето</code>`,seasonPassWorkflowCancelKeyboard());
}

async function handleSeasonPassSeasonCreateWorkflowMessage(message,workflow,env){
  const chatId=message.chat?.id;const access=await requireAnySecurityPermission(chatId,message.from,['manageSeasons','manageMaintenance'],env);if(!access){await clearStaffWorkflow(message.from.id,env);return true;}
  const text=String(message.text||'').trim();if(text==='/cancel'){await clearStaffWorkflow(message.from.id,env);await sendTelegramMessage(env,chatId,'Создание сезона отменено.');return true;}
  const data=workflow.data||{};
  if(workflow.step==='title'){
    if(text.length<3||text.length>80){await sendTelegramMessage(env,chatId,'Название должно содержать от 3 до 80 символов.');return true;}
    await updateStaffWorkflow(message.from.id,{step:'starts_at',data:{...data,title:text}},env);
    await sendTelegramMessage(env,chatId,`Введите <b>дату и время начала</b> по Москве.\n\nФормат: <code>10.09.2026 00:00</code>`,seasonPassWorkflowCancelKeyboard());return true;
  }
  if(workflow.step==='starts_at'){
    const startsAt=parseMoscowDateTime(text);const now=Math.floor(Date.now()/1000);
    if(!startsAt){await sendTelegramMessage(env,chatId,'Не удалось распознать дату. Пример: <code>10.09.2026 00:00</code>');return true;}
    if(startsAt<now){await sendTelegramMessage(env,chatId,'Для нового сезона дата начала должна быть в будущем. Для текущего сезона используйте «Начать сейчас».');return true;}
    await updateStaffWorkflow(message.from.id,{step:'ends_at',data:{...data,startsAt}},env);
    await sendTelegramMessage(env,chatId,`Начало: <b>${escapeHtml(seasonPassSeasonCreateDateLabel(startsAt))}</b>\n\nТеперь введите <b>дату и время окончания</b> по Москве.\n\nПример: <code>10.10.2026 23:59</code>`,seasonPassWorkflowCancelKeyboard());return true;
  }
  if(workflow.step==='ends_at'){
    const endsAt=parseMoscowDateTime(text);const startsAt=Number(data.startsAt||0);
    if(!endsAt){await sendTelegramMessage(env,chatId,'Не удалось распознать дату окончания. Пример: <code>10.10.2026 23:59</code>');return true;}
    if(endsAt<=startsAt+3600){await sendTelegramMessage(env,chatId,'Окончание должно быть минимум на 1 час позже начала.');return true;}
    const overlap=await seasonPassSeasonOverlap(env,startsAt,endsAt);
    if(overlap){await sendTelegramMessage(env,chatId,`Период пересекается с сезоном <b>${escapeHtml(overlap.title)}</b> или его окном выдачи наград (${escapeHtml(formatUtcDate(Number(overlap.starts_at)))} — ${escapeHtml(formatUtcDate(Math.max(Number(overlap.ends_at)||0,Number(overlap.claim_grace_ends_at)||0)))}). Введите другую дату окончания или отмените создание.`);return true;}
    await updateStaffWorkflow(message.from.id,{step:'confirm',data:{...data,endsAt}},env);
    const graceEndsAt=endsAt+SEASON_PASS_MANUAL_CLAIM_GRACE_SECONDS;
    await sendTelegramMessage(env,chatId,`<b>Проверьте новый сезон</b>\n\nНазвание: <b>${escapeHtml(data.title)}</b>\nНачало: <b>${escapeHtml(seasonPassSeasonCreateDateLabel(startsAt))}</b>\nОкончание: <b>${escapeHtml(seasonPassSeasonCreateDateLabel(endsAt))}</b>\nНаграды можно забрать до: <b>${escapeHtml(seasonPassSeasonCreateDateLabel(graceEndsAt))}</b>\n\nНаграды уровней, задания, цены и XP будут скопированы из выбранного сейчас сезона. После создания их можно изменить отдельно.`,{inline_keyboard:[[{text:'✅ Создать сезон',callback_data:'sp_season_create_save'}],[{text:'❌ Отмена',callback_data:'sp_workflow_cancel'}]]});return true;
  }
  await sendTelegramMessage(env,chatId,'Используйте кнопки в предыдущем сообщении или /cancel.');return true;
}

async function uniqueSeasonPassSeasonId(env,startsAt){
  const local=new Date(Number(startsAt)*1000+3*3600*1000);const date=`${local.getUTCFullYear()}${String(local.getUTCMonth()+1).padStart(2,'0')}${String(local.getUTCDate()).padStart(2,'0')}`;
  for(let attempt=0;attempt<20;attempt+=1){const suffix=Math.random().toString(36).slice(2,7);const id=`season-${date}-${suffix}`;const row=await env.DB.prepare(`SELECT 1 AS ok FROM season_pass_seasons WHERE season_id=? LIMIT 1`).bind(id).first();if(!row)return id;}
  throw new Error('Не удалось создать уникальный ID сезона.');
}

async function finalizeSeasonPassSeasonCreate(query,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;
  const workflow=await getStaffWorkflow(query.from.id,env);if(!workflow||workflow.flow_type!=='season_pass_season_create'||workflow.step!=='confirm'){await answerCallback(env,query.id,'Мастер создания устарел. Начните заново.',true);return;}
  const data=workflow.data||{};const startsAt=Number(data.startsAt||0);const endsAt=Number(data.endsAt||0);const title=String(data.title||'').trim();
  if(title.length<3||title.length>80||!Number.isFinite(startsAt)||!Number.isFinite(endsAt)||endsAt<=startsAt+3600){await answerCallback(env,query.id,'Данные сезона повреждены. Начните создание заново.',true);await clearStaffWorkflow(query.from.id,env);return;}
  const overlap=await seasonPassSeasonOverlap(env,startsAt,endsAt);if(overlap){await answerCallback(env,query.id,'Период уже занят другим сезоном.',true);await sendTelegramMessage(env,chatId,`Сезон пересекается с <b>${escapeHtml(overlap.title)}</b>. Создание остановлено.`);return;}
  const sourceId=String(data.sourceSeasonId||DEFAULT_SEASON_PASS_ID);const source=await env.DB.prepare(`SELECT * FROM season_pass_seasons WHERE season_id=? LIMIT 1`).bind(sourceId).first();const now=Math.floor(Date.now()/1000);const actor=String(query.from.id);const seasonId=await uniqueSeasonPassSeasonId(env,startsAt);const graceEndsAt=endsAt+SEASON_PASS_MANUAL_CLAIM_GRACE_SECONDS;
  const cfg=source||{base_run_xp:100,level_price_points:DEFAULT_SEASON_PASS_LEVEL_PRICE_POINTS,elite_price_points:DEFAULT_SEASON_PASS_ELITE_PRICE.points,elite_price_treats:DEFAULT_SEASON_PASS_ELITE_PRICE.treats,elite_price_coffee:DEFAULT_SEASON_PASS_ELITE_PRICE.coffee,elite_plus_price_points:DEFAULT_SEASON_PASS_ELITE_PLUS_PRICE.points,elite_plus_price_treats:DEFAULT_SEASON_PASS_ELITE_PLUS_PRICE.treats,elite_plus_price_coffee:DEFAULT_SEASON_PASS_ELITE_PLUS_PRICE.coffee,elite_plus_benefits_json:JSON.stringify(defaultSeasonPassElitePlusBenefits())};
  const cfgInt=(value,fallback=0)=>Number.isFinite(Number(value))?Math.max(0,Math.floor(Number(value))):fallback;
  await env.DB.batch([
    env.DB.prepare(`INSERT INTO season_pass_seasons(season_id,title,starts_at,ends_at,claim_grace_ends_at,manual_status,base_run_xp,level_price_points,elite_price_points,elite_price_treats,elite_price_coffee,elite_plus_price_points,elite_plus_price_treats,elite_plus_price_coffee,elite_plus_benefits_json,updated_at,updated_by) VALUES(?,?,?,?,?,'',?,?,?,?,?,?,?,?,?,?,?)`).bind(seasonId,title,startsAt,endsAt,graceEndsAt,Math.max(1,cfgInt(cfg.base_run_xp,100)),cfgInt(cfg.level_price_points,DEFAULT_SEASON_PASS_LEVEL_PRICE_POINTS),cfgInt(cfg.elite_price_points,DEFAULT_SEASON_PASS_ELITE_PRICE.points),cfgInt(cfg.elite_price_treats,DEFAULT_SEASON_PASS_ELITE_PRICE.treats),cfgInt(cfg.elite_price_coffee,DEFAULT_SEASON_PASS_ELITE_PRICE.coffee),cfgInt(cfg.elite_plus_price_points,DEFAULT_SEASON_PASS_ELITE_PLUS_PRICE.points),cfgInt(cfg.elite_plus_price_treats,DEFAULT_SEASON_PASS_ELITE_PLUS_PRICE.treats),cfgInt(cfg.elite_plus_price_coffee,DEFAULT_SEASON_PASS_ELITE_PLUS_PRICE.coffee),String(cfg.elite_plus_benefits_json||JSON.stringify(defaultSeasonPassElitePlusBenefits())),now,actor),
    env.DB.prepare(`INSERT INTO season_pass_rewards(season_id,level,lane,reward_type,amount,item_id,title,image_url,enabled,updated_at,updated_by) SELECT ?,level,lane,reward_type,amount,item_id,title,image_url,enabled,?,? FROM season_pass_rewards WHERE season_id=?`).bind(seasonId,now,actor,sourceId),
    env.DB.prepare(`INSERT INTO season_pass_tasks(season_id,task_id,period,premium,metric,target,xp_reward,title,description,enabled,sort_order,updated_at,updated_by) SELECT ?,task_id,period,premium,metric,target,xp_reward,title,description,enabled,sort_order,?,? FROM season_pass_tasks WHERE season_id=?`).bind(seasonId,now,actor,sourceId)
  ]);
  await bindSeason3DraftCasePresetToSeason(env,seasonId,title,actor);
  const rewardCount=Number((await env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_rewards WHERE season_id=?`).bind(seasonId).first())?.count||0);
  if(!rewardCount){const seed=[];for(let level=1;level<=SEASON_PASS_MAX_LEVEL;level+=1){for(const lane of ['free','premium']){const reward=defaultSeasonPassReward(level,lane);seed.push(env.DB.prepare(`INSERT INTO season_pass_rewards(season_id,level,lane,reward_type,amount,item_id,title,image_url,enabled,updated_at,updated_by) VALUES(?,?,?,?,?,?,?,?,1,?,?)`).bind(seasonId,level,lane,reward.rewardType,reward.amount,reward.itemId,reward.title,reward.imageUrl,now,actor));}}for(let i=0;i<seed.length;i+=25)await env.DB.batch(seed.slice(i,i+25));}
  const taskCount=Number((await env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_tasks WHERE season_id=?`).bind(seasonId).first())?.count||0);
  if(!taskCount){const tasks=defaultSeasonPassTasks().map((task,index)=>env.DB.prepare(`INSERT INTO season_pass_tasks(season_id,task_id,period,premium,metric,target,xp_reward,title,description,enabled,sort_order,updated_at,updated_by) VALUES(?,?,?,?,?,?,?,?,?,1,?,?,?)`).bind(seasonId,task.id,task.period,task.premium?1:0,task.metric,task.target,task.xp,task.title,task.description,(index+1)*10,now,actor));if(tasks.length)await env.DB.batch(tasks);}
  await setSeasonPassAdminSelection(env,query.from.id,seasonId);await clearStaffWorkflow(query.from.id,env);
  try{await logStaffAction(env,query.from,access,'season_pass_create',null,'season_pass',null,null,{seasonId,title,startsAt,endsAt,sourceSeasonId:sourceId});}catch(error){console.error('season pass create audit failed',error);}
  await answerCallback(env,query.id,'Новый сезон создан.');await showSeasonPassAdminDashboard(chatId,query.from,env);
}

async function showSeasonPassDeleteConfirmation(query,env,seasonId=''){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;const season=seasonId?await loadSeasonPassSeasonById(env,seasonId):await resolveSeasonPassAdminSeason(env,query.from);if(!season){await answerCallback(env,query.id,'Сезон не найден.',true);return;}const now=Math.floor(Date.now()/1000);
  const forcedClosure=await getSeasonPassForcedClosure(env);if(forcedClosure?.nextSeasonId===season.id){await answerCallback(env,query.id,'Этот сезон используется таймером принудительного закрытия и не может быть удалён до старта.',true);return;}
  if(season.id===DEFAULT_SEASON_PASS_ID||Math.floor(Date.parse(season.startsAt)/1000)<=now){await answerCallback(env,query.id,'Удалять можно только сезон с будущей датой начала.',true);return;}
  await answerCallback(env,query.id,'Требуется подтверждение.');await sendTelegramMessage(env,chatId,`<b>Удалить запланированный сезон?</b>\n\n<b>${escapeHtml(season.title)}</b>\n${escapeHtml(formatUtcDate(Math.floor(Date.parse(season.startsAt)/1000)))} — ${escapeHtml(formatUtcDate(Math.floor(Date.parse(season.endsAt)/1000)))}\n\nБудут удалены настройки, награды и задания этого сезона. Удаление разрешено, потому что его дата начала ещё не наступила.`,{inline_keyboard:[[{text:'🗑 Да, удалить',callback_data:`sp_season_delete_execute:${season.id}`}],[{text:'❌ Отмена',callback_data:'sp_seasons'}]]});
}

async function deleteSeasonPassScheduledSeason(query,env,seasonId=''){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;const season=seasonId?await loadSeasonPassSeasonById(env,seasonId):await resolveSeasonPassAdminSeason(env,query.from);if(!season){await answerCallback(env,query.id,'Сезон не найден.',true);return;}const now=Math.floor(Date.now()/1000);
  const forcedClosure=await getSeasonPassForcedClosure(env);if(forcedClosure?.nextSeasonId===season.id){await answerCallback(env,query.id,'Этот сезон используется таймером принудительного закрытия и не может быть удалён до старта.',true);return;}
  if(season.id===DEFAULT_SEASON_PASS_ID||Math.floor(Date.parse(season.startsAt)/1000)<=now){await answerCallback(env,query.id,'Этот сезон уже нельзя удалить: дата его начала наступила.',true);return;}
  const counts=await Promise.all([
    env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_players WHERE season_id=?`).bind(season.id).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_claims WHERE season_id=?`).bind(season.id).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_task_claims WHERE season_id=?`).bind(season.id).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_run_xp WHERE season_id=?`).bind(season.id).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_activity_runs WHERE season_id=?`).bind(season.id).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_entitlements WHERE season_id=?`).bind(season.id).first(),
    env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_purchases WHERE season_id=?`).bind(season.id).first()
  ]);
  if(counts.some(row=>Number(row?.count||0)>0)){await answerCallback(env,query.id,'У сезона уже есть данные игроков, удаление запрещено.',true);return;}
  await env.DB.batch([
    env.DB.prepare(`DELETE FROM season_pass_rewards WHERE season_id=?`).bind(season.id),
    env.DB.prepare(`DELETE FROM season_pass_tasks WHERE season_id=?`).bind(season.id),
    env.DB.prepare(`DELETE FROM season_pass_seasons WHERE season_id=?`).bind(season.id)
  ]);
  try{await logStaffAction(env,query.from,access,'season_pass_delete',null,'season_pass',season.id,null,{title:season.title,startsAt:season.startsAt,endsAt:season.endsAt});}catch(error){console.error('season pass delete audit failed',error);}
  await deleteSystemState(env,seasonPassAdminSelectionKey(query.from.id));await answerCallback(env,query.id,'Запланированный сезон удалён.');await showSeasonPassSeasonsAdmin(chatId,query.from,env);
}

async function showSeasonPassSettings(chatId,user,env){
  const access=await requireAnySecurityPermission(chatId,user,['manageSeasons','manageMaintenance'],env);if(!access)return;const season=await resolveSeasonPassAdminSeason(env,user);const elite=season.prices.elite;const plus=season.prices.elite_plus;
  await sendTelegramMessage(env,chatId,`<b>💳 Цены и XP сезонного пропуска</b>\n\nСезон: <b>${escapeHtml(season.title)}</b>\n\nЭлитный: <b>${elite.points.toLocaleString('ru-RU')}</b> очков · <b>${elite.treats}</b> зефира · <b>${elite.coffee}</b> кофе\nЭлитный+: <b>${plus.points.toLocaleString('ru-RU')}</b> очков · <b>${plus.treats}</b> зефира · <b>${plus.coffee}</b> кофе\nПокупка уровня: <b>${season.levelPricePoints.toLocaleString('ru-RU')}</b> очков\nXP за забег: <b>${season.baseRunXp}</b>`,{inline_keyboard:[
    [{text:'✅ Цены запуска',callback_data:'sp_prices_launch'}],
    [{text:'✏️ Элитный · очки',callback_data:'sp_input:elite_points'},{text:'✏️ зефир',callback_data:'sp_input:elite_treats'},{text:'✏️ кофе',callback_data:'sp_input:elite_coffee'}],
    [{text:'✏️ Элитный+ · очки',callback_data:'sp_input:plus_points'},{text:'✏️ зефир',callback_data:'sp_input:plus_treats'},{text:'✏️ кофе',callback_data:'sp_input:plus_coffee'}],
    [{text:'✏️ Стоимость уровня',callback_data:'sp_input:level_price'},{text:'✏️ XP за забег',callback_data:'sp_input:run_xp'}],
    [{text:'Уровень 5 000',callback_data:'sp_level_price:5000'},{text:'10 000',callback_data:'sp_level_price:10000'},{text:'15 000',callback_data:'sp_level_price:15000'}],
    [{text:'XP 100',callback_data:'sp_run_xp:100'},{text:'XP 150',callback_data:'sp_run_xp:150'},{text:'XP 200',callback_data:'sp_run_xp:200'}],
    [{text:'⬅️ Сезонный пропуск',callback_data:'sp_admin'}]
  ]});
}

async function setSeasonPassSettingsAction(query,kind,value,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;const season=await resolveSeasonPassAdminSeason(env,query.from);const now=Math.floor(Date.now()/1000);const actor=String(query.from.id);
  if(kind==='launch'){await env.DB.prepare(`UPDATE season_pass_seasons SET elite_price_points=25000,elite_price_treats=450,elite_price_coffee=450,elite_plus_price_points=50000,elite_plus_price_treats=650,elite_plus_price_coffee=650,level_price_points=10000,updated_at=?,updated_by=? WHERE season_id=?`).bind(now,actor,season.id).run();invalidateSeasonPassConfigCache();}
  else if(kind==='level_price'){await env.DB.prepare(`UPDATE season_pass_seasons SET level_price_points=?,updated_at=?,updated_by=? WHERE season_id=?`).bind(Math.max(0,Math.min(1000000,Number(value)||0)),now,actor,season.id).run();invalidateSeasonPassConfigCache();}
  else if(kind==='run_xp'){await env.DB.prepare(`UPDATE season_pass_seasons SET base_run_xp=?,updated_at=?,updated_by=? WHERE season_id=?`).bind(Math.max(1,Math.min(10000,Number(value)||100)),now,actor,season.id).run();invalidateSeasonPassConfigCache();}
  await answerCallback(env,query.id,'Настройки сезонного пропуска сохранены.');await showSeasonPassSettings(chatId,query.from,env);
}

const SEASON_PASS_NUMERIC_FIELDS=Object.freeze({
  elite_points:{column:'elite_price_points',label:'стоимость «Элитного» в очках',min:0,max:999999999},elite_treats:{column:'elite_price_treats',label:'стоимость «Элитного» в зефире',min:0,max:999999999},elite_coffee:{column:'elite_price_coffee',label:'стоимость «Элитного» в кофе',min:0,max:999999999},
  plus_points:{column:'elite_plus_price_points',label:'стоимость «Элитного+» в очках',min:0,max:999999999},plus_treats:{column:'elite_plus_price_treats',label:'стоимость «Элитного+» в зефире',min:0,max:999999999},plus_coffee:{column:'elite_plus_price_coffee',label:'стоимость «Элитного+» в кофе',min:0,max:999999999},
  level_price:{column:'level_price_points',label:'стоимость одного уровня в очках',min:0,max:999999999},run_xp:{column:'base_run_xp',label:'XP за один зачтённый забег',min:1,max:999999999}
});

async function startSeasonPassNumericInput(query,field,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;const config=SEASON_PASS_NUMERIC_FIELDS[field];if(!config){await answerCallback(env,query.id,'Неизвестное поле.',true);return;}const season=await resolveSeasonPassAdminSeason(env,query.from);
  await setStaffWorkflow(query.from.id,chatId,'season_pass_numeric','value',{mode:'setting',field,seasonId:season.id},env);await answerCallback(env,query.id,'Введите число сообщением.');await sendTelegramMessage(env,chatId,`Сезон: <b>${escapeHtml(season.title)}</b>\nВведите <b>${escapeHtml(config.label)}</b> целым числом от ${config.min.toLocaleString('ru-RU')} до ${config.max.toLocaleString('ru-RU')}.\n\nОтмена: /cancel`);
}

async function startSeasonPassTaskNumericInput(query,taskId,field,page,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;if(!['target','xp'].includes(field))return;const season=await resolveSeasonPassAdminSeason(env,query.from);const row=await env.DB.prepare(`SELECT title FROM season_pass_tasks WHERE season_id=? AND task_id=? LIMIT 1`).bind(season.id,String(taskId)).first();if(!row){await answerCallback(env,query.id,'Задание не найдено.',true);return;}
  await setStaffWorkflow(query.from.id,chatId,'season_pass_numeric','value',{mode:'task',seasonId:season.id,taskId:String(taskId),field,page:Number(page)||0},env);await answerCallback(env,query.id,'Введите число сообщением.');await sendTelegramMessage(env,chatId,`Задание: <b>${escapeHtml(row.title)}</b>\nВведите ${field==='xp'?'<b>XP за выполнение</b>':'<b>точную цель</b>'} целым числом от 1 до 999 999 999.\n\nОтмена: /cancel`);
}

async function handleSeasonPassNumericWorkflowMessage(message,workflow,env){
  const chatId=message.chat?.id;const access=await requireAnySecurityPermission(chatId,message.from,['manageSeasons','manageMaintenance'],env);if(!access){await clearStaffWorkflow(message.from.id,env);return true;}const raw=String(message.text||'').trim();if(raw==='/cancel'){await clearStaffWorkflow(message.from.id,env);await sendTelegramMessage(env,chatId,'Изменение отменено.');return true;}
  const normalized=raw.replace(/[\s\u00A0\u202F]/g,'');if(!/^\d+$/.test(normalized)){await sendTelegramMessage(env,chatId,'Нужно отправить одно целое неотрицательное число без текста. Попробуйте ещё раз или /cancel.');return true;}const value=Number(normalized);if(!Number.isSafeInteger(value)||value>999999999){await sendTelegramMessage(env,chatId,'Значение должно быть целым числом от 0 до 999 999 999.');return true;}const now=Math.floor(Date.now()/1000);const data=workflow.data||{};const seasonId=String(data.seasonId||DEFAULT_SEASON_PASS_ID);
  if(data.mode==='setting'){
    const config=SEASON_PASS_NUMERIC_FIELDS[String(data.field||'')];if(!config){await clearStaffWorkflow(message.from.id,env);await sendTelegramMessage(env,chatId,'Поле настройки больше недоступно.');return true;}if(value<config.min||value>config.max){await sendTelegramMessage(env,chatId,`Допустимый диапазон: ${config.min.toLocaleString('ru-RU')}–${config.max.toLocaleString('ru-RU')}.`);return true;}
    await env.DB.prepare(`UPDATE season_pass_seasons SET ${config.column}=?,updated_at=?,updated_by=? WHERE season_id=?`).bind(value,now,String(message.from.id),seasonId).run();await clearStaffWorkflow(message.from.id,env);await sendTelegramMessage(env,chatId,`✅ Сохранено: ${escapeHtml(config.label)} — <b>${value.toLocaleString('ru-RU')}</b>.`);await showSeasonPassSettings(chatId,message.from,env);return true;
  }
  if(data.mode==='task'){
    if(value<1){await sendTelegramMessage(env,chatId,'Для задания значение должно быть не меньше 1.');return true;}const field=String(data.field)==='xp'?'xp_reward':'target';await env.DB.prepare(`UPDATE season_pass_tasks SET ${field}=?,updated_at=?,updated_by=? WHERE season_id=? AND task_id=?`).bind(value,now,String(message.from.id),seasonId,String(data.taskId)).run();await clearStaffWorkflow(message.from.id,env);await sendTelegramMessage(env,chatId,`✅ Значение задания сохранено: <b>${value.toLocaleString('ru-RU')}</b>.`);await showSeasonPassTaskEditor(chatId,message.from,String(data.taskId),Number(data.page)||0,env);return true;
  }
  await clearStaffWorkflow(message.from.id,env);return true;
}

async function showSeasonPassTasksAdmin(chatId,user,env,pageValue=0){
  const access=await requireAnySecurityPermission(chatId,user,['manageSeasons','manageMaintenance'],env);if(!access)return;await ensureSeasonPassSchema(env);const season=await resolveSeasonPassAdminSeason(env,user);const rows=(await env.DB.prepare(`SELECT task_id,period,premium,title,target,xp_reward,enabled FROM season_pass_tasks WHERE season_id=? ORDER BY sort_order,task_id`).bind(season.id).all()).results||[];const totalPages=Math.max(1,Math.ceil(rows.length/6));const page=Math.max(0,Math.min(totalPages-1,Number(pageValue)||0));const slice=rows.slice(page*6,page*6+6);const buttons=slice.map(row=>[{text:`${Number(row.enabled)?'🟢':'🔴'} ${String(row.title).slice(0,25)}`,callback_data:`sp_task_edit:${row.task_id}:${page}`}]);buttons.push([{text:'➕ Создать своё задание',callback_data:'sp_task_new'}],[{text:'◀️',callback_data:`sp_tasks:${Math.max(0,page-1)}`},{text:`${page+1}/${totalPages}`,callback_data:'sp_noop'},{text:'▶️',callback_data:`sp_tasks:${Math.min(totalPages-1,page+1)}`}],[{text:'♻️ Восстановить стандартные',callback_data:'sp_tasks_reset'}],[{text:'⬅️ Сезонный пропуск',callback_data:'sp_admin'}]);const lines=slice.map(row=>`• ${Number(row.enabled)?'🟢':'🔴'} <b>${escapeHtml(row.title)}</b> — ${Number(row.target).toLocaleString('ru-RU')} · +${Number(row.xp_reward).toLocaleString('ru-RU')} XP${Number(row.premium)?' · Элитный':''}`);await sendTelegramMessage(env,chatId,`<b>📋 Задания сезонного пропуска</b>\n\nСезон: <b>${escapeHtml(season.title)}</b>\n\n${lines.join('\n')||'Нет заданий.'}\n\nМожно создавать собственные ежедневные и еженедельные задания.`,{inline_keyboard:buttons});
}

async function startSeasonPassTaskCreate(query,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;const season=await resolveSeasonPassAdminSeason(env,query.from);
  await setStaffWorkflow(query.from.id,chatId,'season_pass_task_create','title',{seasonId:season.id},env);await answerCallback(env,query.id,'Создаём задание.');await sendTelegramMessage(env,chatId,`<b>➕ Новое задание</b>\n\nСезон: <b>${escapeHtml(season.title)}</b>\n\nОтправьте короткое название задания.\nПример: <code>Собери 100 зефирок</code>`,seasonPassWorkflowCancelKeyboard());
}

async function handleSeasonPassTaskCreateWorkflowMessage(message,workflow,env){
  const chatId=message.chat?.id;const access=await requireAnySecurityPermission(chatId,message.from,['manageSeasons','manageMaintenance'],env);if(!access){await clearStaffWorkflow(message.from.id,env);return true;}const text=String(message.text||'').trim();if(text==='/cancel'){await clearStaffWorkflow(message.from.id,env);await sendTelegramMessage(env,chatId,'Создание задания отменено.');return true;}const data=workflow.data||{};
  if(workflow.step==='title'){
    if(text.length<3||text.length>80){await sendTelegramMessage(env,chatId,'Название должно содержать от 3 до 80 символов.');return true;}
    await updateStaffWorkflow(message.from.id,{step:'period',data:{...data,title:text}},env);await sendTelegramMessage(env,chatId,'Как часто обновляется задание?',{inline_keyboard:[[{text:'☀️ Ежедневно',callback_data:'sp_tc_period:daily'},{text:'📅 Еженедельно',callback_data:'sp_tc_period:weekly'}],[{text:'❌ Отмена',callback_data:'sp_workflow_cancel'}]]});return true;
  }
  if(workflow.step==='target'){
    const normalized=text.replace(/[\s\u00A0\u202F]/g,'');if(!/^\d+$/.test(normalized)||Number(normalized)<1||Number(normalized)>999999999){await sendTelegramMessage(env,chatId,'Введите цель целым числом от 1 до 999 999 999.');return true;}
    await updateStaffWorkflow(message.from.id,{step:'xp',data:{...data,target:Number(normalized)}},env);await sendTelegramMessage(env,chatId,'Сколько XP выдавать за выполнение? Введите число от 1 до 100 000.',seasonPassWorkflowCancelKeyboard());return true;
  }
  if(workflow.step==='xp'){
    const normalized=text.replace(/[\s\u00A0\u202F]/g,'');if(!/^\d+$/.test(normalized)||Number(normalized)<1||Number(normalized)>100000){await sendTelegramMessage(env,chatId,'Введите XP целым числом от 1 до 100 000.');return true;}
    await updateStaffWorkflow(message.from.id,{step:'description',data:{...data,xp:Number(normalized)}},env);await sendTelegramMessage(env,chatId,'Отправьте описание задания. Чтобы оставить его пустым, отправьте <code>-</code>.',seasonPassWorkflowCancelKeyboard());return true;
  }
  if(workflow.step==='description'){
    const description=text==='-'?'':text;if(description.length>240){await sendTelegramMessage(env,chatId,'Описание должно быть не длиннее 240 символов.');return true;}
    await updateStaffWorkflow(message.from.id,{step:'confirm',data:{...data,description}},env);await showSeasonPassTaskCreateConfirmation(chatId,message.from,env);return true;
  }
  await sendTelegramMessage(env,chatId,'Используйте кнопки в предыдущем сообщении или /cancel.');return true;
}

async function setSeasonPassTaskCreateChoice(query,field,value,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;const workflow=await getStaffWorkflow(query.from.id,env);if(!workflow||workflow.flow_type!=='season_pass_task_create'){await answerCallback(env,query.id,'Мастер создания устарел. Начните заново.',true);return;}
  const data=workflow.data||{};
  if(field==='period'&&['daily','weekly'].includes(value)){
    await updateStaffWorkflow(query.from.id,{step:'lane',data:{...data,period:value}},env);await answerCallback(env,query.id,'Период выбран.');await sendTelegramMessage(env,chatId,'Для какой линии доступно задание?',{inline_keyboard:[[{text:'🆓 Бесплатная',callback_data:'sp_tc_lane:free'},{text:'⭐ Только Элитная',callback_data:'sp_tc_lane:premium'}],[{text:'❌ Отмена',callback_data:'sp_workflow_cancel'}]]});return;
  }
  if(field==='lane'&&['free','premium'].includes(value)){
    await updateStaffWorkflow(query.from.id,{step:'metric',data:{...data,premium:value==='premium'}},env);await answerCallback(env,query.id,'Линия выбрана.');await sendTelegramMessage(env,chatId,'Что должен сделать игрок?',{inline_keyboard:[[{text:'🏃 Завершить забеги',callback_data:'sp_tc_metric:runs'}],[{text:'🍥 Собрать зефир',callback_data:'sp_tc_metric:treats'},{text:'☕ Собрать кофе',callback_data:'sp_tc_metric:coffee'}],[{text:'⭐ Набрать очки',callback_data:'sp_tc_metric:score'},{text:'📦 Открыть кейсы',callback_data:'sp_tc_metric:cases_opened'}],[{text:'❌ Отмена',callback_data:'sp_workflow_cancel'}]]});return;
  }
  if(field==='metric'&&['runs','treats','coffee','score','cases_opened'].includes(value)){
    await updateStaffWorkflow(query.from.id,{step:'target',data:{...data,metric:value}},env);await answerCallback(env,query.id,'Условие выбрано.');await sendTelegramMessage(env,chatId,'Введите числом цель задания. Например: <code>10</code>.',seasonPassWorkflowCancelKeyboard());return;
  }
  await answerCallback(env,query.id,'Некорректный выбор.',true);
}

async function showSeasonPassTaskCreateConfirmation(chatId,user,env){
  const workflow=await getStaffWorkflow(user.id,env);if(!workflow||workflow.flow_type!=='season_pass_task_create'||workflow.step!=='confirm')return;const d=workflow.data||{};const metricLabel={runs:'завершённые забеги',treats:'собранный зефир',coffee:'собранный кофе',score:'набранные очки',cases_opened:'открытые кейсы'}[d.metric]||d.metric;
  await sendTelegramMessage(env,chatId,`<b>Проверьте задание</b>\n\nНазвание: <b>${escapeHtml(d.title)}</b>\nПериод: <b>${d.period==='weekly'?'еженедельное':'ежедневное'}</b>\nЛиния: <b>${d.premium?'только Элитная':'бесплатная'}</b>\nУсловие: <b>${escapeHtml(metricLabel)}</b>\nЦель: <b>${Number(d.target||0).toLocaleString('ru-RU')}</b>\nНаграда: <b>${Number(d.xp||0).toLocaleString('ru-RU')} XP</b>\nОписание: ${d.description?escapeHtml(d.description):'—'}`,{inline_keyboard:[[{text:'✅ Создать задание',callback_data:'sp_tc_save'}],[{text:'❌ Отмена',callback_data:'sp_workflow_cancel'}]]});
}

async function finalizeSeasonPassTaskCreate(query,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;const workflow=await getStaffWorkflow(query.from.id,env);if(!workflow||workflow.flow_type!=='season_pass_task_create'||workflow.step!=='confirm'){await answerCallback(env,query.id,'Мастер создания устарел.',true);return;}const d=workflow.data||{};const seasonId=String(d.seasonId||'');const season=await loadSeasonPassSeasonById(env,seasonId);if(!season){await answerCallback(env,query.id,'Сезон больше не существует.',true);return;}const now=Math.floor(Date.now()/1000);const taskId=`${SEASON_PASS_CUSTOM_TASK_PREFIX}${Date.now().toString(36)}_${Math.random().toString(36).slice(2,6)}`;const maxRow=await env.DB.prepare(`SELECT COALESCE(MAX(sort_order),0) AS value FROM season_pass_tasks WHERE season_id=?`).bind(seasonId).first();const sortOrder=Number(maxRow?.value||0)+10;
  await env.DB.prepare(`INSERT INTO season_pass_tasks(season_id,task_id,period,premium,metric,target,xp_reward,title,description,enabled,sort_order,updated_at,updated_by) VALUES(?,?,?,?,?,?,?,?,?,1,?,?,?)`).bind(seasonId,taskId,d.period,d.premium?1:0,d.metric,Number(d.target),Number(d.xp),String(d.title),String(d.description||''),sortOrder,now,String(query.from.id)).run();const taskCount=Number((await env.DB.prepare(`SELECT COUNT(*) AS count FROM season_pass_tasks WHERE season_id=?`).bind(seasonId).first())?.count||1);await clearStaffWorkflow(query.from.id,env);try{await logStaffAction(env,query.from,access,'season_pass_task_create',null,'season_pass_task',null,null,{seasonId,taskId,title:d.title,period:d.period,metric:d.metric,target:d.target,xp:d.xp,premium:Boolean(d.premium)});}catch(error){console.error('season pass task create audit failed',error);}await answerCallback(env,query.id,'Задание создано.');await showSeasonPassTasksAdmin(chatId,query.from,env,Math.max(0,Math.ceil(taskCount/6)-1));
}

async function toggleSeasonPassTask(query,taskId,page,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;const season=await resolveSeasonPassAdminSeason(env,query.from);const now=Math.floor(Date.now()/1000);await env.DB.prepare(`UPDATE season_pass_tasks SET enabled=CASE enabled WHEN 1 THEN 0 ELSE 1 END,updated_at=?,updated_by=? WHERE season_id=? AND task_id=?`).bind(now,String(query.from.id),season.id,String(taskId)).run();await answerCallback(env,query.id,'Статус задания изменён.');await showSeasonPassTaskEditor(chatId,query.from,taskId,page,env);
}

function seasonPassTaskTargetStep(metric){const value=String(metric||'runs');if(value==='score')return 500;if(value==='treats')return 10;if(value==='coffee')return 1;return 1;}

async function showSeasonPassTaskEditor(chatId,user,taskId,pageValue,env){
  const access=await requireAnySecurityPermission(chatId,user,['manageSeasons','manageMaintenance'],env);if(!access)return;await ensureSeasonPassSchema(env);const season=await resolveSeasonPassAdminSeason(env,user);
  const row=await env.DB.prepare(`SELECT task_id,period,premium,metric,target,xp_reward,title,description,enabled FROM season_pass_tasks WHERE season_id=? AND task_id=? LIMIT 1`).bind(season.id,String(taskId)).first();if(!row)return sendTelegramMessage(env,chatId,'Задание не найдено.');const page=Math.max(0,Number(pageValue)||0);const step=seasonPassTaskTargetStep(row.metric);const xpStep=50;const keyboard=[
    [{text:`Цель −${step}`,callback_data:`sp_task_target:${row.task_id}:dec:${page}`},{text:`Цель +${step}`,callback_data:`sp_task_target:${row.task_id}:inc:${page}`}],
    [{text:'✏️ Ввести цель',callback_data:`sp_task_input:${row.task_id}:target:${page}`}],
    [{text:`XP −${xpStep}`,callback_data:`sp_task_xp:${row.task_id}:dec:${page}`},{text:`XP +${xpStep}`,callback_data:`sp_task_xp:${row.task_id}:inc:${page}`}],
    [{text:'✏️ Ввести XP',callback_data:`sp_task_input:${row.task_id}:xp:${page}`}],
    [{text:Number(row.enabled)?'🔴 Отключить':'🟢 Включить',callback_data:`sp_task_toggle:${row.task_id}:${page}`}]
  ];if(String(row.task_id).startsWith(SEASON_PASS_CUSTOM_TASK_PREFIX))keyboard.push([{text:'🗑 Удалить своё задание',callback_data:`sp_task_delete_confirm:${row.task_id}:${page}`}]);keyboard.push([{text:'⬅️ К списку заданий',callback_data:`sp_tasks:${page}`}]);
  await sendTelegramMessage(env,chatId,`<b>📋 ${escapeHtml(row.title)}</b>\n\n${escapeHtml(row.description||'')}\n\nСезон: <b>${escapeHtml(season.title)}</b>\nПериод: <b>${row.period==='weekly'?'недельное':'ежедневное'}</b>\nЛиния: <b>${Number(row.premium)?'Элитная':'Бесплатная'}</b>\nМетрика: <code>${escapeHtml(row.metric)}</code>\nЦель: <b>${Number(row.target).toLocaleString('ru-RU')}</b>\nНаграда: <b>${Number(row.xp_reward).toLocaleString('ru-RU')} XP</b>\nСтатус: <b>${Number(row.enabled)?'включено':'отключено'}</b>`,{inline_keyboard:keyboard});
}

async function updateSeasonPassTaskValue(query,taskId,field,direction,page,env){
  const chatId=query.message?.chat?.id;const access=await requireAnySecurityPermission(chatId,query.from,['manageSeasons','manageMaintenance'],env);if(!access)return;await ensureSeasonPassSchema(env);const season=await resolveSeasonPassAdminSeason(env,query.from);const row=await env.DB.prepare(`SELECT metric,target,xp_reward FROM season_pass_tasks WHERE season_id=? AND task_id=? LIMIT 1`).bind(season.id,String(taskId)).first();if(!row){await answerCallback(env,query.id,'Задание не найдено.');return;}const now=Math.floor(Date.now()/1000);const sign=direction==='dec'?-1:1;
  if(field==='target'){const step=seasonPassTaskTargetStep(row.metric);const value=Math.max(1,Math.min(10000000,Number(row.target||1)+sign*step));await env.DB.prepare(`UPDATE season_pass_tasks SET target=?,updated_at=?,updated_by=? WHERE season_id=? AND task_id=?`).bind(value,now,String(query.from.id),season.id,String(taskId)).run();}
  else{const value=Math.max(1,Math.min(100000,Number(row.xp_reward||1)+sign*50));await env.DB.prepare(`UPDATE season_pass_tasks SET xp_reward=?,updated_at=?,updated_by=? WHERE season_id=? AND task_id=?`).bind(value,now,String(query.from.id),season.id,String(taskId)).run();}
  await answerCallback(env,query.id,'Задание обновлено.');await showSeasonPassTaskEditor(chatId,query.from,taskId,page,env);
}

