  const spSeasonDeleteExecute=data.match(/^sp_season_delete_execute:([A-Za-z0-9_-]{2,48})$/);if(spSeasonDeleteExecute){await deleteSeasonPassScheduledSeason(query,env,spSeasonDeleteExecute[1]);return true;}
