  const body=ownerPanelSessionBase64Encode(JSON.stringify(payload));const key=encoder.encode(`owner-panel:${String(env.TELEGRAM_BOT_TOKEN||"")}`);const sig=bytesToHex(await hmacSha256(key,body));return `${body}.${sig}`;
