async function ownerV85CreateCampaignForIds(env, actor, ids, spec={}) {
  await ensureLiveOpsAdminSchema(env);
  const cleanIds=[...new Set((ids||[]).map(x=>String(x||"").trim()).filter(Boolean))];
  if(!cleanIds.length) throw new ApiError(409,"Нет получателей.");
  const now=Math.floor(Date.now()/1000),campaignId=caseGrantId("campaign");
  const rewardBundle=normalizePlayerGiftRewards(spec.rewardBundle||[]);
  await env.DB.prepare(`INSERT INTO admin_campaigns(campaign_id,title,segment_key,reward_kind,reward_id,amount,reason,message_text,reward_bundle_json,image_url,button_text,button_url,scheduled_at,status,created_by,created_by_name,report_chat_id,total_count,processed_count,failed_count,created_at,started_at,completed_at,updated_at,lease_token,lease_until) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?, 'pending',?,?,?,?,0,0,?,0,0,?,'',0)`).bind(
    campaignId,String(spec.title||"Компенсация").slice(0,120),String(spec.segmentKey||"direct").slice(0,120),String(spec.rewardKind||"none"),String(spec.rewardId||""),Math.max(1,Math.floor(Number(spec.amount||1))),String(spec.reason||"").slice(0,300),String(spec.message||"").slice(0,2500),JSON.stringify(rewardBundle),String(spec.imageUrl||"").slice(0,1000),String(spec.buttonText||"").slice(0,60),String(spec.buttonUrl||"").slice(0,1000),Math.max(0,Math.floor(Number(spec.scheduledAt||0))),String(actor?.id||"owner"),telegramDisplayName(actor||{}),String(spec.reportChatId||actor?.id||""),cleanIds.length,now,now
  ).run();
  await env.DB.prepare(`INSERT OR REPLACE INTO admin_campaign_mail_config(campaign_id,enabled,preview_text) VALUES(?,?,?)`).bind(campaignId,spec.inboxEnabled===true?1:0,playerMailPreviewText(spec.preview,spec.message||spec.title||"")).run();
  const statements=cleanIds.map(id=>env.DB.prepare(`INSERT OR IGNORE INTO admin_campaign_recipients(campaign_id,telegram_id) VALUES(?,?)`).bind(campaignId,id));
  for(let i=0;i<statements.length;i+=80) await env.DB.batch(statements.slice(i,i+80));
  return campaignId;
}

async function ownerV85QueueCompensationCampaigns(env, actor, ids, data={}) {
  const rawRewards=Array.isArray(data.rewards)?data.rewards:[];
  if(rawRewards.some((reward)=>String(reward?.kind)==="physical_restore")) throw new ApiError(409,"Шаблон восстановления физической награды требует ручной проверки и не может быть выдан массово.");
  const rewards=normalizePlayerGiftRewards(rawRewards);
  if(!rewards.length){
    const campaignId=await ownerV85CreateCampaignForIds(env,actor,ids,{title:`Компенсация: ${String(data.templateTitle||"Без шаблона").slice(0,90)}`,segmentKey:data.segmentKey||"direct",rewardKind:"none",reason:data.reason||"Компенсация",message:String(data.message||""),reportChatId:data.reportChatId||actor?.id||"",inboxEnabled:true});
    return [campaignId];
  }
  const campaignId=await ownerV85CreateCampaignForIds(env,actor,ids,{
    title:`Компенсация: ${String(data.templateTitle||"Без шаблона").slice(0,90)}`,
    segmentKey:data.segmentKey||"direct",rewardKind:"gift_bundle",rewardId:String(data.templateId||""),amount:1,
    rewardBundle:rewards,reason:data.reason||"Компенсация",message:String(data.message||""),reportChatId:data.reportChatId||actor?.id||"",inboxEnabled:true
  });
  return [campaignId];
}

async function ownerV85AllPlayerIds(env, createdBefore = 0) {
  await ensureControlCenterV85Schema(env);
  const cutoff = Math.max(0, Math.floor(Number(createdBefore || 0)));
  const ids = [], pageSize = 1000;
  let cursorCreatedAt = -1, cursorTelegramId = "";
  for (;;) {
    let stmt = cutoff > 0
      ? env.DB.prepare(`SELECT telegram_id,created_at FROM admin_profile_state WHERE created_at<=? AND (created_at>? OR (created_at=? AND telegram_id>?)) ORDER BY created_at ASC,telegram_id ASC LIMIT ?`).bind(cutoff,cursorCreatedAt,cursorCreatedAt,cursorTelegramId,pageSize)
      : env.DB.prepare(`SELECT telegram_id,created_at FROM admin_profile_state WHERE created_at>? OR (created_at=? AND telegram_id>?) ORDER BY created_at ASC,telegram_id ASC LIMIT ?`).bind(cursorCreatedAt,cursorCreatedAt,cursorTelegramId,pageSize);
    const result = await stmt.all();
    const rows = result.results || [];
    for (const row of rows) {
      const id = String(row.telegram_id || "").trim();
      if (id) ids.push(id);
    }
    if (rows.length < pageSize) break;
    const last = rows[rows.length - 1];
    cursorCreatedAt = Number(last.created_at || 0);
    cursorTelegramId = String(last.telegram_id || "");
  }
  return [...new Set(ids)];
}

async function ownerV85AllPlayerPreview(env) {
  await ensureControlCenterV85Schema(env);
  const [countRow, sample] = await Promise.all([
    env.DB.prepare(`SELECT COUNT(*) AS count FROM admin_profile_state`).first(),
    env.DB.prepare(`SELECT p.telegram_id,COALESCE(NULLIF(b.display_name,''),NULLIF(a.display_name,''),p.telegram_id) AS display_name,COALESCE(b.username,a.username,'') AS username,COALESCE(a.photo_url,'') AS photo_url,COALESCE(a.best_score,p.best_score,0) AS best_score FROM admin_profile_state p LEFT JOIN bot_subscribers b ON b.telegram_id=p.telegram_id LEFT JOIN leaderboard_all_time a ON a.telegram_id=p.telegram_id ORDER BY p.created_at ASC,p.telegram_id ASC LIMIT 30`).all()
  ]);
  return {
    ok: true,
    key: "all_players",
    title: "Все игроки",
    count: Number(countRow?.count || 0),
    players: (sample.results || []).map((r) => ({
      telegramId: String(r.telegram_id || ""),
      name: String(r.display_name || r.telegram_id || "Игрок"),
      username: String(r.username || ""),
      photoUrl: String(r.photo_url || ""),
      bestScore: Number(r.best_score || 0)
    }))
  };
}

const OWNER_V85_SELECTED_PLAYERS_MAX = 500;
function ownerV85SelectedPlayerIds(input){
  if(!Array.isArray(input))throw new ApiError(400,"Передайте список выбранных игроков.");
  const ids=[...new Set(input.map(value=>String(value||"").trim()).filter(Boolean))];
  if(!ids.length)throw new ApiError(400,"Выберите хотя бы одного игрока.");
  if(ids.length>OWNER_V85_SELECTED_PLAYERS_MAX)throw new ApiError(400,`За одну ручную выборку можно выбрать максимум ${OWNER_V85_SELECTED_PLAYERS_MAX} игроков.`);
  if(ids.some(id=>!/^\d{4,20}$/.test(id)))throw new ApiError(400,"В списке выбранных игроков есть некорректный Telegram ID.");
  return ids;
}
async function ownerV85SelectedPlayerAudience(env,input){
  await ensureControlCenterV85Schema(env);
  const ids=ownerV85SelectedPlayerIds(input),found=new Map();
  for(let offset=0;offset<ids.length;offset+=80){
    const chunk=ids.slice(offset,offset+80),placeholders=chunk.map(()=>"?").join(",");
    const result=await env.DB.prepare(`SELECT p.telegram_id,COALESCE(NULLIF(a.display_name,''),NULLIF(b.display_name,''),p.telegram_id) AS display_name,COALESCE(NULLIF(a.username,''),NULLIF(b.username,''),'') AS username,COALESCE(a.photo_url,'') AS photo_url,COALESCE(a.best_score,p.best_score,0) AS best_score FROM admin_profile_state p LEFT JOIN leaderboard_all_time a ON a.telegram_id=p.telegram_id LEFT JOIN bot_subscribers b ON b.telegram_id=p.telegram_id WHERE p.telegram_id IN (${placeholders})`).bind(...chunk).all();
    for(const row of result.results||[])found.set(String(row.telegram_id||""),{telegramId:String(row.telegram_id||""),name:String(row.display_name||row.telegram_id||"Игрок"),username:String(row.username||""),photoUrl:String(row.photo_url||""),bestScore:Number(row.best_score||0)});
  }
  const missing=ids.filter(id=>!found.has(id));
  if(missing.length)throw new ApiError(404,`Не найдены игроки: ${missing.slice(0,5).join(", ")}${missing.length>5?` и ещё ${missing.length-5}`:""}. Обновите выбор и повторите.`);
  return {ids,players:ids.map(id=>found.get(id))};
}

let ownerV85CompConfirmationSchemaPromise = null;
async function ensureOwnerV85CompConfirmationSchema(env){
  if(!ownerV85CompConfirmationSchemaPromise){
    ownerV85CompConfirmationSchemaPromise=env.DB.prepare(`CREATE TABLE IF NOT EXISTS owner_compensation_confirmation_words (
      owner_telegram_id TEXT PRIMARY KEY,
      word_salt TEXT NOT NULL,
      word_hash TEXT NOT NULL,
      updated_at INTEGER NOT NULL,
      updated_by TEXT NOT NULL DEFAULT ''
    )`).run().catch((error)=>{ownerV85CompConfirmationSchemaPromise=null;throw error;});
  }
  return ownerV85CompConfirmationSchemaPromise;
}
function ownerV85NormalizeCompConfirmationWord(value){
  const raw=String(value??'');
  const normalized=typeof raw.normalize==='function'?raw.normalize('NFKC'):raw;
  return normalized.trim().replace(/\s+/g,' ').toLocaleUpperCase('ru-RU');
}
async function ownerV85CompConfirmationHash(ownerId,salt,word){
  return legalSha256Hex(`owner-compensation-confirmation-v1\n${String(ownerId||'')}\n${String(salt||'')}\n${ownerV85NormalizeCompConfirmationWord(word)}`);
}
async function ownerV85CompConfirmationStatus(env,ownerId){
  await ensureOwnerV85CompConfirmationSchema(env);
  const row=await env.DB.prepare(`SELECT updated_at FROM owner_compensation_confirmation_words WHERE owner_telegram_id=? LIMIT 1`).bind(String(ownerId)).first();
  return {configured:Boolean(row),mode:row?'owner_word_plus_count':'system_phrase',updatedAt:Number(row?.updated_at||0)};
}
async function ownerPanelV85CompensationConfirmationWord(env,ctx){
  await ensureOwnerV85CompConfirmationSchema(env);
  if(!ctx.access?.owner||String(ctx.access?.role||'')!=='owner')throw new ApiError(403,'Контрольное слово может менять только владелец проекта.');
  const ownerId=String(ctx.user.id),action=String(ctx.body?.action||'save').trim().toLowerCase();
  if(action==='reset'){
    await env.DB.prepare(`DELETE FROM owner_compensation_confirmation_words WHERE owner_telegram_id=?`).bind(ownerId).run();
    await logStaffAction(env,ctx.user,ctx.access,'owner_compensation_confirmation_word_reset',null,'compensation',null,null,{configured:false});
    return {ok:true,confirmationWord:{configured:false,mode:'system_phrase',updatedAt:Math.floor(Date.now()/1000)}};
  }
  const word=ownerV85NormalizeCompConfirmationWord(ctx.body?.word),repeat=ownerV85NormalizeCompConfirmationWord(ctx.body?.repeatWord);
  if(word.length<4||word.length>64)throw new ApiError(400,'Контрольное слово должно содержать от 4 до 64 символов.');
  if(word!==repeat)throw new ApiError(400,'Повтор контрольного слова не совпадает.');
  if(/[\r\n\t]/.test(word))throw new ApiError(400,'Контрольное слово должно быть в одной строке.');
  const bytes=new Uint8Array(18);crypto.getRandomValues(bytes);const salt=bytesToHex(bytes),hash=await ownerV85CompConfirmationHash(ownerId,salt,word),now=Math.floor(Date.now()/1000);
  await env.DB.prepare(`INSERT INTO owner_compensation_confirmation_words(owner_telegram_id,word_salt,word_hash,updated_at,updated_by) VALUES(?,?,?,?,?) ON CONFLICT(owner_telegram_id) DO UPDATE SET word_salt=excluded.word_salt,word_hash=excluded.word_hash,updated_at=excluded.updated_at,updated_by=excluded.updated_by`).bind(ownerId,salt,hash,now,ownerId).run();
  await logStaffAction(env,ctx.user,ctx.access,'owner_compensation_confirmation_word_set',null,'compensation',null,null,{configured:true});
  return {ok:true,confirmationWord:{configured:true,mode:'owner_word_plus_count',updatedAt:now}};
}
async function ownerV85VerifyCompensationConfirmation(env,ownerId,rawConfirmation,count){
  await ensureOwnerV85CompConfirmationSchema(env);
  const expectedCount=Math.max(1,Math.floor(Number(count)||0)),confirmation=String(rawConfirmation||'').trim();
  const row=await env.DB.prepare(`SELECT word_salt,word_hash FROM owner_compensation_confirmation_words WHERE owner_telegram_id=? LIMIT 1`).bind(String(ownerId)).first();
  if(!row){
    if(confirmation!==`ВЫДАТЬ ${expectedCount}`)throw new ApiError(400,`Введите подтверждение: ВЫДАТЬ ${expectedCount}`);
    return true;
  }
  const match=confirmation.match(/^([\s\S]*\S)\s+(\d+)$/);
  if(!match||Number(match[2])!==expectedCount)throw new ApiError(400,`Введите своё контрольное слово и точное число получателей: СЛОВО ${expectedCount}`);
  const candidate=ownerV85NormalizeCompConfirmationWord(match[1]);
  if(candidate.length<4||candidate.length>64)throw new ApiError(400,'Неверное контрольное слово.');
  const candidateHash=await ownerV85CompConfirmationHash(ownerId,String(row.word_salt||''),candidate);
  if(!timingSafeEqualString(candidateHash,String(row.word_hash||'')))throw new ApiError(400,'Неверное контрольное слово владельца.');
  return true;
}

function ownerV85CompensationRewardCatalog(){
  return {
    cases: grantCatalogItems("case").map(item=>({id:String(item.id),title:String(item.title)})),
    skins: grantCatalogItems("skin").map(item=>({id:String(item.id),title:String(item.title)})),
    avatars: grantCatalogItems("avatar").map(item=>({id:String(item.id),title:String(item.title)})),
    frames: grantCatalogItems("frame").map(item=>({id:String(item.id),title:String(item.title)})),
    trails: grantCatalogItems("trail").map(item=>({id:String(item.id),title:String(item.title)})),
    showcases: ACHIEVEMENT_SHOWCASE_STYLES.filter(item=>item?.rewardable===true).map(item=>({id:String(item.id),title:`${String(item.title||item.id)}${item.manualOnly===true?" · особая":""}${item.hidden===true?" · скрытая":""}`,manualOnly:Boolean(item.manualOnly),hidden:Boolean(item.hidden)})),
    boosters: runBoosterCatalogItems().map(item=>({id:String(item.id),title:String(item.title)}))
  };
}
async function ownerV85NormalizeCustomCompensationRewards(env,input){
  const raw=Array.isArray(input)?input:[];
  if(raw.length>8)throw new ApiError(400,"В своей компенсации можно указать максимум 8 строк наград.");
  const catalog={
    case:new Set(grantCatalogItems("case").map(item=>String(item.id))),
    skin:new Set(grantCatalogItems("skin").map(item=>String(item.id))),
    avatar:new Set(grantCatalogItems("avatar").map(item=>String(item.id))),
    frame:new Set(grantCatalogItems("frame").map(item=>String(item.id))),
    trail:new Set(grantCatalogItems("trail").map(item=>String(item.id))),
    showcase_style:new Set(ACHIEVEMENT_SHOWCASE_STYLES.filter(item=>item?.rewardable===true).map(item=>String(item.id))),
    booster:new Set(runBoosterCatalogItems().map(item=>String(item.id)))
  };
  const checked=[];
  let boundSeason=null;
  const activeSeason=async()=>{
    if(boundSeason)return boundSeason;
    await ensureSeasonPassSchema(env);
    await assertSeasonPassNotForceClosed(env);
    const season=await loadSeasonPassSeason(env);
    if(!season||String(season.status)!=='active')throw new ApiError(409,'Элитный, Элитный+ и EXP можно выдавать только для активного сезона сезонного пропуска.');
    boundSeason=season;
    return season;
  };
  for(const item of raw){
    if(!item||typeof item!=="object")throw new ApiError(400,"Некорректная строка награды.");
    let kind=String(item.kind||"").trim().toLowerCase();
    if(kind==="treats"||kind==="marshmallow")kind="zefir";
    const id=String(item.id||item.rewardId||"").trim();
    let amount=Math.floor(Number(item.amount||1));
    if(["points","zefir","coffee"].includes(kind)){
      if(!Number.isFinite(amount)||amount<1||amount>5000000)throw new ApiError(400,`Количество для «${grantRewardTitle(kind)}» должно быть от 1 до 5 000 000.`);
      checked.push({kind,id:"",amount});
      continue;
    }
    if(kind==="case"){
      if(!catalog.case.has(id))throw new ApiError(400,"Выбран неизвестный кейс.");
      if(!Number.isFinite(amount)||amount<1||amount>20)throw new ApiError(400,"За одну компенсацию можно выдать от 1 до 20 кейсов одного типа.");
      checked.push({kind,id,amount});
      continue;
    }
    if(kind==="booster"){
      if(!catalog.booster.has(id))throw new ApiError(400,"Выбран неизвестный усилитель.");
      if(!Number.isFinite(amount)||amount<1||amount>999)throw new ApiError(400,"За одну компенсацию можно выдать от 1 до 999 усилителей одного типа.");
      checked.push({kind,id,amount});
      continue;
    }
    if(["skin","avatar","frame","trail"].includes(kind)){
      if(!catalog[kind].has(id))throw new ApiError(400,`Выбран неизвестный предмет категории «${kind}».`);
      checked.push({kind,id,amount:1});
      continue;
    }
    if(kind==="showcase_style"){
      const style=achievementShowcaseDirectGrantStyleDefinition(id);
      if(!catalog.showcase_style.has(id)||!style)throw new ApiError(400,"Выбрана неизвестная витрина достижений.");
      checked.push({kind,id:String(style.id),amount:1});
      continue;
    }
    if(kind==="season_pass_tier"){
      const tier=id==="elite_plus"?"elite_plus":id==="elite"?"elite":"";
      if(!tier)throw new ApiError(400,"Выберите тариф Элитный или Элитный+.");
      const season=await activeSeason();
      checked.push({kind,id:`${season.id}|${tier}`,amount:1});
      continue;
    }
    if(kind==="season_pass_xp_grant"){
      if(!Number.isFinite(amount)||amount<1||amount>5000000)throw new ApiError(400,"EXP сезонного пропуска должен быть от 1 до 5 000 000.");
      const season=await activeSeason();
      checked.push({kind,id:String(season.id),amount});
      continue;
    }
    throw new ApiError(400,"В своей компенсации указан неподдерживаемый тип награды.");
  }
  return normalizePlayerGiftRewards(checked);
}

async function ownerPanelV85Compensations(env,ctx){
  await ensureControlCenterV85Schema(env);const [templates,segments,queue,campaigns,notifyQueue,confirmationWord]=await Promise.all([
    env.DB.prepare(`SELECT * FROM compensation_templates WHERE enabled=1 ORDER BY template_id`).all(),ownerV85SegmentCatalog(env,false),
    env.DB.prepare(`SELECT status,COUNT(*) AS count FROM reward_delivery_queue WHERE source_type IN ('compensation','campaign') AND created_at>=? GROUP BY status`).bind(Math.floor(Date.now()/1000)-7*86400).all(),
    env.DB.prepare(`SELECT campaign_id,title,status,total_count,processed_count,failed_count,created_at,completed_at FROM admin_campaigns WHERE title LIKE 'Компенсация:%' ORDER BY created_at DESC LIMIT 24`).all(),
    env.DB.prepare(`SELECT status,COUNT(*) AS count FROM player_notification_queue GROUP BY status`).all().catch(()=>({results:[]})),
    ownerV85CompConfirmationStatus(env,ctx.user.id)
  ]);
  const mappedTemplates=(templates.results||[]).filter(r=>!ownerV8SafeJson(r.rewards_json,[]).some(x=>String(x?.kind)==='physical_restore')).map(r=>({id:String(r.template_id),title:String(r.title),description:String(r.description||""),rewards:ownerV8SafeJson(r.rewards_json,[])}));
  mappedTemplates.unshift({id:"__message__",title:"Только уведомление",description:"Сообщение без игровой награды",rewards:[]});
  mappedTemplates.splice(1,0,{id:"__custom__",title:"Своя компенсация",description:"Набор наград задаётся вручную перед отправкой",rewards:[]});
  return {ok:true,templates:mappedTemplates,rewardCatalog:ownerV85CompensationRewardCatalog(),confirmationWord,segments,queue:(queue.results||[]).map(r=>({status:String(r.status),count:Number(r.count||0)})),notificationQueue:(notifyQueue.results||[]).map(r=>({status:String(r.status),count:Number(r.count||0)})),recent:(campaigns.results||[]).map(r=>({id:String(r.campaign_id),title:String(r.title||""),status:String(r.status||""),total:Number(r.total_count||0),processed:Number(r.processed_count||0),failed:Number(r.failed_count||0),createdAt:Number(r.created_at||0),completedAt:Number(r.completed_at||0)}))};
}
async function ownerPanelV85CompensationPreview(env,ctx){const target=String(ctx.body?.target||"segment");if(target==="player"){const id=String(ctx.body?.telegramId||"").trim();if(!/^\d{4,20}$/.test(id)||!(await playerProfileExists(id,env)))throw new ApiError(404,"Игрок не найден.");return {ok:true,count:1,players:[{telegramId:id,name:await playerDisplayNameById(id,env)}]};}if(target==="players"){const audience=await ownerV85SelectedPlayerAudience(env,ctx.body?.telegramIds);return {ok:true,key:"selected_players",title:"Выбранные игроки",count:audience.ids.length,players:audience.players.slice(0,30)};}if(target==="all")return ownerV85AllPlayerPreview(env);return ownerPanelV85SegmentPreview(env,ctx);}
async function ownerPanelV85CompensationSend(env,ctx){
  await ensureControlCenterV85Schema(env);const templateId=String(ctx.body?.templateId||"").trim();let template=null,rewards=[];
  if(templateId==="__message__"){
    template={template_id:"__message__",title:"Уведомление"};rewards=[];
  }else if(templateId==="__custom__"){
    const title=String(ctx.body?.customTitle||"").trim().slice(0,120);
    if(title.length<3)throw new ApiError(400,"Укажите название своей компенсации.");
    template={template_id:"__custom__",title};
    rewards=await ownerV85NormalizeCustomCompensationRewards(env,ctx.body?.customRewards);
  }else{
    template=await env.DB.prepare(`SELECT * FROM compensation_templates WHERE template_id=? AND enabled=1 LIMIT 1`).bind(templateId).first();if(!template)throw new ApiError(404,"Шаблон компенсации не найден.");rewards=ownerV8SafeJson(template.rewards_json,[]);if(!Array.isArray(rewards)||!rewards.length)throw new ApiError(409,"В шаблоне нет наград.");if(rewards.some(r=>String(r?.kind)==='physical_restore'))throw new ApiError(409,"Этот шаблон требует ручной проверки физической награды.");
  }
  const reason=String(ctx.body?.reason||template.title||"Компенсация").trim().slice(0,300);if(reason.length<3)throw new ApiError(400,"Укажите причину.");const message=String(ctx.body?.message||"").trim().slice(0,2500);if(!rewards.length&&!message)throw new ApiError(400,"Для уведомления укажите текст сообщения.");
  const target=String(ctx.body?.target||"segment");let ids=[],segmentKey="",audienceSnapshotAt=0;if(target==="player"){const id=String(ctx.body?.telegramId||"").trim();if(!/^\d{4,20}$/.test(id)||!(await playerProfileExists(id,env)))throw new ApiError(404,"Игрок не найден.");ids=[id];segmentKey=`player_${id}`;}else if(target==="players"){const audience=await ownerV85SelectedPlayerAudience(env,ctx.body?.telegramIds);ids=audience.ids;segmentKey="selected_players";}else if(target==="all"){audienceSnapshotAt=Math.floor(Date.now()/1000);segmentKey="all_players";ids=await ownerV85AllPlayerIds(env,audienceSnapshotAt);}else{segmentKey=String(ctx.body?.segmentKey||"").trim();if(!(await ownerV85SegmentTitle(env,segmentKey)))throw new ApiError(404,"Сегмент не найден.");ids=await segmentPlayerIds(env,segmentKey,10000);}
  ids=[...new Set(ids)];if(!ids.length)throw new ApiError(409,"Нет получателей.");await ownerV85VerifyCompensationConfirmation(env,ctx.user.id,ctx.body?.confirmation,ids.length);
  const hasLegendary=rewards.some(r=>String(r?.kind)==="case"&&String(r?.id)==="legendary");
  const customHighImpact=templateId==="__custom__"&&rewards.some(r=>{
    const kind=String(r?.kind||""),id=String(r?.id||""),amount=Math.max(1,Number(r?.amount||1));
    return kind==="skin"||kind==="showcase_style"||kind==="season_pass_tier"||(kind==="season_pass_xp_grant"&&amount>=1000)||(kind==="case"&&["mythic","legendary"].includes(id))||(kind==="points"&&amount>=1000000)||(["zefir","coffee"].includes(kind)&&amount>=1000);
  });
  const payload={templateId,templateTitle:String(template.title||"Уведомление"),rewards,reason,message,segmentKey,targetMode:target,audienceSnapshotAt,targetCount:ids.length,targetIds:target==="all"?[]:ids.slice(0,10000),reportChatId:String(ctx.user.id)};
  if(hasLegendary||ids.length>250||(customHighImpact&&ids.length>1)){
    // The owner is the final authority for Control Center compensations. The
    // owner's own typed confirmation above is sufficient; a second staff
    // member is required only for non-owner administrators.
    if(ctx.access?.owner){
      const campaignIds=await ownerV85QueueCompensationCampaigns(env,ctx.user,ids,payload);
      await logStaffAction(env,ctx.user,ctx.access,"owner_panel_bulk_compensation",null,"compensation",null,ids.length,{campaignIds,templateId,count:ids.length,segmentKey,target,reason,ownerDirect:true,highImpact:true,hasLegendary,customHighImpact});
      ownerV85CacheInvalidate("compensations");
      return {ok:true,count:ids.length,campaignIds,ownerDirect:true};
    }
    const approvalId=await requestDangerousAction(env,ctx.user,"bulk_compensation",`${rewards.length?'Компенсация':'Уведомление'} «${template.title}» · ${ids.length} игроков`,payload);
    await logStaffAction(env,ctx.user,ctx.access,"owner_panel_bulk_compensation_request",null,"compensation",null,ids.length,{templateId,segmentKey,target,approvalId,customHighImpact});
    return {ok:true,approvalRequired:true,approvalId,count:ids.length};
  }
  const campaignIds=await ownerV85QueueCompensationCampaigns(env,ctx.user,ids,payload);await logStaffAction(env,ctx.user,ctx.access,"owner_panel_bulk_compensation",null,"compensation",null,ids.length,{campaignIds,templateId,count:ids.length,segmentKey,target,reason});ownerV85CacheInvalidate("compensations");return {ok:true,count:ids.length,campaignIds};
}

async function ownerV85MonitorConfig(env){const state=await getSystemState(env,V85_MONITOR_STATE_KEY);const raw=state?ownerV8SafeJson(state.value,{}):{};if(raw.rewardStale&&!raw.rewardStaleMinutes)raw.rewardStaleMinutes=Math.max(5,Number(raw.rewardStale)||15);return {...V85_MONITOR_DEFAULTS,...raw};}
async function ownerPanelV85Monitoring(env,ctx){
  await ensureControlCenterV85Schema(env);
  return ownerV85Cached("monitoring",10000,async()=>{
    const now=Math.floor(Date.now()/1000),since=now-24*3600,config=await ownerV85MonitorConfig(env);
    try{await scanV77SmartAlerts(env);}catch(error){console.error("Monitoring Smart Alerts refresh failed",error);}
    const [rewards,playerNotifications,staffNotifications,cron,perf,alerts,hourly]=await Promise.all([
      env.DB.prepare(`SELECT
        SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS pending,
        SUM(CASE WHEN status='delivering' THEN 1 ELSE 0 END) AS active,
        SUM(CASE WHEN status='failed' AND attempts<5 THEN 1 ELSE 0 END) AS retrying,
        SUM(CASE WHEN status='failed' AND attempts>=5 THEN 1 ELSE 0 END) AS terminal,
        MAX(CASE WHEN status='pending' THEN ?-created_at ELSE 0 END) AS pending_max_age,
        MAX(CASE WHEN status='failed' AND attempts<5 THEN ?-created_at ELSE 0 END) AS retry_max_age
        FROM reward_delivery_queue WHERE status IN ('pending','delivering','failed')`).bind(now,now).first(),
      env.DB.prepare(`SELECT
        SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS pending,
        SUM(CASE WHEN status='failed' AND attempts<5 THEN 1 ELSE 0 END) AS retrying,
        SUM(CASE WHEN status='failed' AND attempts>=5 AND updated_at>=? AND NOT (LOWER(COALESCE(last_error,'')) LIKE '%bot was blocked%' OR LOWER(COALESCE(last_error,'')) LIKE '%chat not found%' OR LOWER(COALESCE(last_error,'')) LIKE '%user is deactivated%' OR LOWER(COALESCE(last_error,'')) LIKE '%forbidden%' OR LOWER(COALESCE(last_error,'')) LIKE '%cannot initiate%' OR LOWER(COALESCE(last_error,'')) LIKE '%can''t initiate%') THEN 1 ELSE 0 END) AS terminal,
        SUM(CASE WHEN status='failed' AND attempts>=5 AND updated_at>=? AND (LOWER(COALESCE(last_error,'')) LIKE '%bot was blocked%' OR LOWER(COALESCE(last_error,'')) LIKE '%chat not found%' OR LOWER(COALESCE(last_error,'')) LIKE '%user is deactivated%' OR LOWER(COALESCE(last_error,'')) LIKE '%forbidden%' OR LOWER(COALESCE(last_error,'')) LIKE '%cannot initiate%' OR LOWER(COALESCE(last_error,'')) LIKE '%can''t initiate%') THEN 1 ELSE 0 END) AS unreachable,
        MAX(CASE WHEN status='pending' THEN ?-created_at ELSE 0 END) AS pending_max_age,
        MAX(CASE WHEN status='failed' AND attempts<5 THEN ?-created_at ELSE 0 END) AS retry_max_age
        FROM player_notification_queue WHERE status IN ('pending','failed')`).bind(since,since,now,now).first(),
      env.DB.prepare(`SELECT
        SUM(CASE WHEN status='pending' THEN 1 ELSE 0 END) AS pending,
        SUM(CASE WHEN status='failed' AND attempts<5 THEN 1 ELSE 0 END) AS retrying,
        SUM(CASE WHEN status='failed' AND attempts>=5 AND updated_at>=? AND NOT (LOWER(COALESCE(last_error,'')) LIKE '%bot was blocked%' OR LOWER(COALESCE(last_error,'')) LIKE '%chat not found%' OR LOWER(COALESCE(last_error,'')) LIKE '%user is deactivated%' OR LOWER(COALESCE(last_error,'')) LIKE '%forbidden%' OR LOWER(COALESCE(last_error,'')) LIKE '%cannot initiate%' OR LOWER(COALESCE(last_error,'')) LIKE '%can''t initiate%') THEN 1 ELSE 0 END) AS terminal,
        SUM(CASE WHEN status='failed' AND attempts>=5 AND updated_at>=? AND (LOWER(COALESCE(last_error,'')) LIKE '%bot was blocked%' OR LOWER(COALESCE(last_error,'')) LIKE '%chat not found%' OR LOWER(COALESCE(last_error,'')) LIKE '%user is deactivated%' OR LOWER(COALESCE(last_error,'')) LIKE '%forbidden%' OR LOWER(COALESCE(last_error,'')) LIKE '%cannot initiate%' OR LOWER(COALESCE(last_error,'')) LIKE '%can''t initiate%') THEN 1 ELSE 0 END) AS unreachable,
        MAX(CASE WHEN status='pending' THEN ?-created_at ELSE 0 END) AS pending_max_age,
        MAX(CASE WHEN status='failed' AND attempts<5 THEN ?-created_at ELSE 0 END) AS retry_max_age
        FROM leaderboard_staff_notifications WHERE status IN ('pending','failed')`).bind(since,since,now,now).first(),
      env.DB.prepare(`SELECT * FROM server_cron_jobs ORDER BY priority,job_key`).all(),
      env.DB.prepare(`SELECT area,COUNT(*) AS samples,ROUND(AVG(duration_ms),1) AS avg_ms,MAX(duration_ms) AS max_ms,SUM(CASE WHEN success=0 THEN 1 ELSE 0 END) AS errors FROM admin_performance_samples WHERE created_at>=? GROUP BY area ORDER BY avg_ms DESC LIMIT 30`).bind(since).all(),
      env.DB.prepare(`SELECT * FROM smart_alert_events WHERE status='open' ORDER BY CASE severity WHEN 'critical' THEN 0 ELSE 1 END,last_seen_at DESC LIMIT 40`).all(),
      env.DB.prepare(`SELECT * FROM server_analytics_hourly WHERE bucket_at>=? ORDER BY bucket_at ASC LIMIT 48`).bind(now-48*3600).all()
    ]);
    const queueStats=(row)=>({
      pending:{count:Number(row?.pending||0),maxAge:Number(row?.pending_max_age||0)},
      active:{count:Number(row?.active||0)},
      retrying:{count:Number(row?.retrying||0),maxAge:Number(row?.retry_max_age||0)},
      terminal:{count:Number(row?.terminal||0)},
      unreachable:{count:Number(row?.unreachable||0)},
      failed:{count:Number(row?.terminal||0)}
    });
    const rQ=queueStats(rewards),pQ=queueStats(playerNotifications),sQ=queueStats(staffNotifications);
    const notificationSummary={pending:{count:pQ.pending.count+sQ.pending.count},retrying:{count:pQ.retrying.count+sQ.retrying.count},terminal:{count:pQ.terminal.count+sQ.terminal.count},unreachable:{count:pQ.unreachable.count+sQ.unreachable.count}};
    const cronRows=(cron.results||[]).map(r=>({key:String(r.job_key),enabled:Boolean(r.enabled),interval:Number(r.interval_seconds||0),lastSuccessAt:Number(r.last_success_at||0),lastFinishedAt:Number(r.last_finished_at||0),nextRunAt:Number(r.next_run_at||0),status:String(r.last_status||"never"),duration:Number(r.last_duration_ms||0),error:String(r.last_error||""),failures:Number(r.failures_total||0)}));
    const cronFailures24=(hourly.results||[]).reduce((sum,r)=>sum+Number(r.cron_failures||0),0);
    const slowAreaRows=(perf.results||[]).filter(r=>Number(r.avg_ms||0)>=Number(config.slowMs||1200));const slowAreas=slowAreaRows.length;
    const failedCron=cronRows.filter(r=>r.enabled&&r.status==='failed');
    const staleCron=cronRows.filter(r=>r.enabled&&r.lastSuccessAt&&now-r.lastSuccessAt>Math.max(r.interval*3,Number(config.cronStaleMinutes||20)*60));
    const staleReward=(rQ.pending.maxAge||0)>Number(config.rewardStaleMinutes||15)*60||(rQ.retrying.maxAge||0)>Number(config.rewardStaleMinutes||15)*60;
    const reasons=[];
    if(rQ.terminal.count>=Number(config.rewardFailed||1))reasons.push({level:'critical',text:`не доставлено наград: ${rQ.terminal.count}`});
    if(failedCron.length)reasons.push({level:'critical',text:`Cron с ошибкой: ${failedCron.map(r=>r.key).join(', ')}`});
    if(notificationSummary.terminal.count>=Number(config.notificationFailed||3))reasons.push({level:'warning',text:`не доставлено уведомлений за 24ч: ${notificationSummary.terminal.count}`});
    if(staleReward)reasons.push({level:'warning',text:`награды ждут дольше ${Number(config.rewardStaleMinutes||15)} мин.`});
    if(staleCron.length)reasons.push({level:'warning',text:`Cron давно без успеха: ${staleCron.map(r=>r.key).join(', ')}`});
    if(cronFailures24>=Number(config.cronFailures||1))reasons.push({level:'warning',text:`ошибок Cron за 24ч: ${cronFailures24}`});
    if(slowAreas>0){const labels=slowAreaRows.slice(0,2).map(r=>`${String(r.area)} ${Math.round(Number(r.avg_ms||0))} мс`);reasons.push({level:'warning',text:`медленно: ${labels.join(', ')}${slowAreas>2?` и ещё ${slowAreas-2}`:''}`});}
    const critical=reasons.some(r=>r.level==='critical'),warning=reasons.some(r=>r.level==='warning');
    return {ok:true,generatedAt:now,status:critical?'critical':warning?'warning':'healthy',healthReasons:reasons,config,queues:{rewards:rQ,playerNotifications:pQ,staffNotifications:sQ,notifications:notificationSummary},cron:cronRows,cronFailures24,performance:(perf.results||[]).map(r=>({area:String(r.area),samples:Number(r.samples||0),avgMs:Number(r.avg_ms||0),maxMs:Number(r.max_ms||0),errors:Number(r.errors||0)})),alerts:(alerts.results||[]).map(r=>({key:String(r.alert_key),type:String(r.alert_type||""),severity:String(r.severity||""),title:String(r.title||""),details:String(r.details||""),firstSeenAt:Number(r.first_seen_at||0),lastSeenAt:Number(r.last_seen_at||0)})),hourly:(hourly.results||[]).map(r=>({at:Number(r.bucket_at||0),active:Number(r.active_players||0),runs:Number(r.runs_total||0),rewardErrors:Number(r.rewards_failed||0),staffErrors:Number(r.staff_notifications_failed||0),playerErrors:Number(r.player_notifications_failed||0),cronFailures:Number(r.cron_failures||0),cronMs:Number(r.cron_duration_ms||0)}))};
  });
}
async function ownerPanelV85MonitoringConfig(env,ctx){await ensureControlCenterV85Schema(env);const c={rewardFailed:ownerPanelInteger(ctx.body?.rewardFailed,1,1000)||1,rewardStaleMinutes:ownerPanelInteger(ctx.body?.rewardStaleMinutes,5,1440)||15,notificationFailed:ownerPanelInteger(ctx.body?.notificationFailed,1,1000)||3,cronFailures:ownerPanelInteger(ctx.body?.cronFailures,1,100)||1,cronStaleMinutes:ownerPanelInteger(ctx.body?.cronStaleMinutes,5,1440)||20,slowMs:ownerPanelInteger(ctx.body?.slowMs,100,60000)||1200};await setSystemState(env,V85_MONITOR_STATE_KEY,JSON.stringify(c));ownerV85CacheInvalidate("monitoring");await logStaffAction(env,ctx.user,ctx.access,"owner_panel_monitor_config",null,"system",null,null,c);return {ok:true,config:c};}

function ownerV85ExperimentMetricLabel(key){return ({runs:"Забеги/игрока",avg_score:"Средний результат",purchase_rate:"Доля покупателей",cases:"Кейсы/игрока"})[key]||key;}
async function ownerV85ExperimentMetrics(env,row){const start=Math.max(0,Number(row.starts_at||0));if(!start)return {control:{players:0},variant:{players:0}};const end=String(row.status)==='completed'&&Number(row.completed_at||0)>0?Number(row.completed_at):Math.floor(Date.now()/1000);const [runs,purchases,cases]=await Promise.all([
  env.DB.prepare(`SELECT telegram_id,COUNT(*) AS runs,AVG(score) AS avg_score FROM leaderboard_runs WHERE accepted=1 AND created_at>=? AND created_at<=? GROUP BY telegram_id LIMIT 10000`).bind(start,end).all(),
  env.DB.prepare(`SELECT telegram_id,SUM(ops) AS ops FROM (SELECT telegram_id,COUNT(*) AS ops FROM granted_cases WHERE granted_by='shop' AND created_at>=? AND created_at<=? GROUP BY telegram_id UNION ALL SELECT telegram_id,COUNT(*) AS ops FROM shop_stock_consumptions WHERE category='skins' AND created_at>=? AND created_at<=? GROUP BY telegram_id) GROUP BY telegram_id LIMIT 10000`).bind(start,end,start,end).all(),
  env.DB.prepare(`SELECT telegram_id,SUM(opened) AS opened FROM (SELECT telegram_id,COUNT(*) AS opened FROM level_case_openings WHERE opened_at>=? AND opened_at<=? GROUP BY telegram_id UNION ALL SELECT telegram_id,COUNT(*) AS opened FROM granted_cases WHERE status='opened' AND opened_at>=? AND opened_at<=? GROUP BY telegram_id) GROUP BY telegram_id LIMIT 10000`).bind(start,end,start,end).all()
]);const map=new Map();for(const r of runs.results||[])map.set(String(r.telegram_id),{runs:Number(r.runs||0),avgScore:Number(r.avg_score||0),purchases:0,cases:0});for(const r of purchases.results||[]){const id=String(r.telegram_id),x=map.get(id)||{runs:0,avgScore:0,purchases:0,cases:0};x.purchases=Number(r.ops||0);map.set(id,x);}for(const r of cases.results||[]){const id=String(r.telegram_id),x=map.get(id)||{runs:0,avgScore:0,purchases:0,cases:0};x.cases=Number(r.opened||0);map.set(id,x);}const group=()=>({players:0,runs:0,scoreWeighted:0,purchases:0,buyers:0,cases:0});const control=group(),variant=group();for(const [id,x] of map){const g=stableRolloutBucket(`${row.flag_key}:${id}`)<Number(row.variant_percent||50)?variant:control;g.players++;g.runs+=x.runs;g.scoreWeighted+=x.avgScore*x.runs;g.purchases+=x.purchases;if(x.purchases>0)g.buyers++;g.cases+=x.cases;}for(const g of [control,variant]){g.runsPerPlayer=g.players?g.runs/g.players:0;g.avgScore=g.runs?g.scoreWeighted/g.runs:0;g.purchaseRate=g.players?g.buyers*100/g.players:0;g.casesPerPlayer=g.players?g.cases/g.players:0;delete g.scoreWeighted;}return {control,variant};}
async function ownerPanelV85Experiments(env,ctx){
  await ensureControlCenterV85Schema(env);
  return ownerV85Cached("experiments",15000,async()=>{
    const [rows,flags]=await Promise.all([env.DB.prepare(`SELECT * FROM ab_experiments ORDER BY updated_at DESC LIMIT 20`).all(),loadFeatureFlagRows(env)]);
    const source=rows.results||[],experiments=[];
    for(let i=0;i<source.length;i+=3){
      const chunk=source.slice(i,i+3);
      const mapped=await Promise.all(chunk.map(async(row)=>{
        let metrics={control:{players:0},variant:{players:0}};
        if(Number(row.starts_at||0)>0)metrics=await ownerV85Cached(`experiment-metrics:${String(row.experiment_key)}`,20000,()=>ownerV85ExperimentMetrics(env,row));
        return {key:String(row.experiment_key),title:String(row.title),description:String(row.description||""),flagKey:String(row.flag_key),variantPercent:Number(row.variant_percent||50),metric:String(row.primary_metric||"runs"),metricTitle:ownerV85ExperimentMetricLabel(row.primary_metric),status:String(row.status||"draft"),startsAt:Number(row.starts_at||0),endsAt:Number(row.ends_at||0),winner:String(row.winner||""),updatedAt:Number(row.updated_at||0),metrics};
      }));
      experiments.push(...mapped);
    }
    return {ok:true,flags:flags.map(r=>({key:String(r.flag_key),title:String(r.title||r.flag_key),mode:String(r.mode||"all"),rollout:Number(r.rollout_percent||0)})),experiments};
  });
}
