function normalizeSeasonPassAssetKey(value,{required=false}={}){
  const key=String(value||'').trim().toLowerCase();
  if(!key){if(required)throw new ApiError(400,'Выберите папку ассетов сезона.');return '';}
  if(!/^[a-z0-9][a-z0-9_-]{0,63}$/.test(key))throw new ApiError(400,'Папка ассетов: используйте только a-z, 0-9, дефис и подчёркивание, например s3.');
  return key;
}

