  const afterEnd=Number.isFinite(end)?end+60000:NaN,duringGrace=hasGrace?Math.min(grace-60000,end+Math.max(60000,Math.floor((grace-end)/2))):NaN,afterGrace=(hasGrace?grace:end)+60000;
