function ownerPanelSeasonPassTierLabel(tier) {
  return String(tier) === "elite_plus" ? "Элитный+" : "Элитный";
}

function ownerPanelSeasonPassPrice(season, tier) {
  const raw = season?.prices?.[tier] || {};
  return {
    points: seasonPassInteger(raw.points),
    treats: seasonPassInteger(raw.treats),
    coffee: seasonPassInteger(raw.coffee)
  };
}

function ownerPanelSeasonPassPriceText(price) {
  const parts = [];
  const points = seasonPassInteger(price?.points);
  const treats = seasonPassInteger(price?.treats);
  const coffee = seasonPassInteger(price?.coffee);
  if (points > 0) parts.push(`${points.toLocaleString("ru-RU")} очков`);
  if (treats > 0) parts.push(`${treats.toLocaleString("ru-RU")} зефира`);
  if (coffee > 0) parts.push(`${coffee.toLocaleString("ru-RU")} кофе`);
  return parts.length ? parts.join(" · ") : "0";
}

async function ownerPanelNotifySeasonPassGrant(env, telegramId, payload = {}) {
  try {
    const subscriber = await env.DB.prepare(`SELECT chat_id FROM bot_subscribers WHERE telegram_id=? AND active=1 LIMIT 1`).bind(String(telegramId)).first();
    if (!subscriber?.chat_id) return false;
    const tierLabel = ownerPanelSeasonPassTierLabel(payload.tier);
    const compensation = payload.compensation || null;
    const title = compensation ? "♻️ Компенсация за сезонный пропуск" : "🎟 Вам выдан сезонный пропуск";
    const body = compensation
      ? `Повторная выдача тарифа <b>«${escapeHtml(tierLabel)}»</b> заменена компенсацией по его стоимости: <b>${escapeHtml(ownerPanelSeasonPassPriceText(compensation))}</b>.\nВаш текущий более высокий тариф, если он был, сохранён.`
      : `На текущий сезон вам активирован тариф <b>«${escapeHtml(tierLabel)}»</b>.\nПремиальные награды и задания уже доступны в игре.`;
    await sendTelegramMessage(env, subscriber.chat_id, `<b>${title}</b>\n\n${body}${payload.reason ? `\n\nПричина: ${escapeHtml(payload.reason)}` : ""}`, {
      inline_keyboard: [[{ text: "🎮 Открыть игру", web_app: { url: configuredGameUrl(env) } }]]
    });
    return true;
  } catch (error) {
    console.error("owner panel season pass grant notification failed", error);
    return false;
  }
}

async function ownerPanelGrantSeasonPassTier(env, ctx, telegramId, tier, reason) {
  await ensurePlayerAccountRevisionAvailable(env);
  await ensureSeasonPassSchema(env);
  await assertSeasonPassNotForceClosed(env);
  const season = await loadSeasonPassSeason(env);
  if (!season || String(season.status) !== "active") throw new ApiError(409, "Выдать тариф можно только для активного сезона сезонного пропуска.");
  const normalizedTier = String(tier) === "elite_plus" ? "elite_plus" : String(tier) === "elite" ? "elite" : "";
  if (!normalizedTier) throw new ApiError(400, "Некорректный тариф сезонного пропуска.");
  const player = await ensureSeasonPassPlayer(env, season, telegramId);
  const currentTier = ["elite", "elite_plus"].includes(String(player?.premium_tier)) ? String(player.premium_tier) : "none";
  const now = Math.floor(Date.now() / 1000);
  const sourceId = `owner_pass_${season.id}_${telegramId}_${now}_${crypto.randomUUID().replaceAll("-", "").slice(0, 8)}`;
  const duplicate = currentTier === normalizedTier || (currentTier === "elite_plus" && normalizedTier === "elite");

  if (duplicate) {
    const compensation = ownerPanelSeasonPassPrice(season, normalizedTier);
    const duplicateResults = await env.DB.batch([
      env.DB.prepare(`UPDATE admin_profile_state SET
        pending_wallet=pending_wallet+?,pending_treats=pending_treats+?,pending_coffee=pending_coffee+?,
        revision=revision+1,updated_at=?,updated_by=? WHERE telegram_id=?`).bind(
          compensation.points, compensation.treats, compensation.coffee, now, `owner-pass-comp:${sourceId}`, telegramId
        ),
      bumpPlayerAccountRevisionStatement(env, telegramId, now)
    ]);
    if (Number(duplicateResults?.[0]?.meta?.changes || 0) < 1) throw new ApiError(404, "Профиль игрока не найден.");
    try {
      await recordPlayerTimeline(env, telegramId, "season_pass_compensation", `получил компенсацию за повторную выдачу «${ownerPanelSeasonPassTierLabel(normalizedTier)}»: ${ownerPanelSeasonPassPriceText(compensation)}`, {
        seasonId: season.id, requestedTier: normalizedTier, currentTier, compensation, sourceId, reason
      }, sourceId, ctx.user, now);
    } catch (error) { console.error("owner season pass compensation timeline failed", error); }
    await logStaffAction(env, ctx.user, ctx.access, "owner_panel_season_pass_compensation", telegramId, "season_pass", null, null, {
      seasonId: season.id, requestedTier: normalizedTier, currentTier, compensation, reason, sourceId
    });
    const notifyPromise = ownerPanelNotifySeasonPassGrant(env, telegramId, { tier: normalizedTier, compensation, reason });
    if (ctx.executionCtx?.waitUntil) ctx.executionCtx.waitUntil(notifyPromise); else await notifyPromise;
    return {
      ok: true,
      grantType: "season_pass",
      seasonId: String(season.id),
      seasonTitle: String(season.title || ""),
      requestedTier: normalizedTier,
      premiumTier: currentTier,
      compensated: true,
      compensation,
      message: `Тариф уже доступен игроку. Начислена компенсация: ${ownerPanelSeasonPassPriceText(compensation)}.`
    };
  }

  let received = [];
  let plan = null;
  if (normalizedTier === "elite") {
    await env.DB.batch([
      env.DB.prepare(`UPDATE season_pass_players SET premium_tier='elite',revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=? AND premium_tier='none'`).bind(now, season.id, telegramId),
      bumpPlayerAccountRevisionStatement(env, telegramId, now)
    ]);
  } else {
    plan = await elitePlusBenefitPlan(env, { season, telegramId, player }, player, now, {
      source: `owner_grant:${sourceId}`,
      bonusAlreadyGranted: Boolean(Number(player?.elite_plus_bonus_granted || 0))
    });
    await env.DB.batch([...plan.statements,bumpPlayerAccountRevisionStatement(env, telegramId, now)]);
    received = Array.isArray(plan.received) ? plan.received : [];
  }
  let updated = await env.DB.prepare(`SELECT * FROM season_pass_players WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(season.id, telegramId).first();
  if(normalizedTier==='elite_plus'){
    updated=await reconcileElitePlusTaskXpBoost(env,season,telegramId,updated);
  }
  const premiumTier = String(updated?.premium_tier || normalizedTier);
  try { await queueSeasonPassTierActivationNotice(env,{season,telegramId,previousTier:currentTier,newTier:premiumTier,source:'owner_grant',sourceKey:sourceId,activatedAt:now,payload:normalizedTier==='elite_plus'?(plan?.activation||{}):{fromLevel:seasonPassLevelFromXp(player?.xp),toLevel:seasonPassLevelFromXp(player?.xp),bonusLevels:0}}); }
  catch (error) { console.error("owner season pass activation notice failed", error); }
  try {
    await recordPlayerTimeline(env, telegramId, "season_pass_owner_grant", `получил тариф «${ownerPanelSeasonPassTierLabel(normalizedTier)}» от владельца`, {
      seasonId: season.id, previousTier: currentTier, premiumTier, requestedTier: normalizedTier, received, sourceId, reason
    }, sourceId, ctx.user, now);
  } catch (error) { console.error("owner season pass grant timeline failed", error); }
  await logStaffAction(env, ctx.user, ctx.access, "owner_panel_season_pass_grant", telegramId, "season_pass", null, null, {
    seasonId: season.id, previousTier: currentTier, requestedTier: normalizedTier, premiumTier, received, reason, sourceId
  });
  const notifyPromise = ownerPanelNotifySeasonPassGrant(env, telegramId, { tier: normalizedTier, reason });
  if (ctx.executionCtx?.waitUntil) ctx.executionCtx.waitUntil(notifyPromise); else await notifyPromise;
  return {
    ok: true,
    grantType: "season_pass",
    seasonId: String(season.id),
    seasonTitle: String(season.title || ""),
    requestedTier: normalizedTier,
    premiumTier,
    compensated: false,
    received,
    message: `Тариф «${ownerPanelSeasonPassTierLabel(normalizedTier)}» выдан игроку.`
  };
}

async function ownerPanelGrantSeasonPassXp(env,ctx,telegramId,amount,reason){
  await ensurePlayerAccountRevisionAvailable(env);
  await ensureSeasonPassSchema(env);await assertSeasonPassNotForceClosed(env);
  const season=await loadSeasonPassSeason(env);
  if(!season||String(season.status)!=='active')throw new ApiError(409,'Выдать XP можно только в активный сезон сезонного пропуска.');
  const player=await ensureSeasonPassPlayer(env,season,telegramId);
  const beforeXp=Math.max(0,Number(player?.xp)||0);const now=Math.floor(Date.now()/1000);
  await env.DB.batch([
    env.DB.prepare(`UPDATE season_pass_players SET xp=xp+?,revision=revision+1,updated_at=? WHERE season_id=? AND telegram_id=?`).bind(amount,now,season.id,telegramId),
    bumpPlayerAccountRevisionStatement(env, telegramId, now)
  ]);
  const afterXp=beforeXp+amount;const afterLevel=seasonPassLevelFromXp(afterXp);const overflow=seasonPassOverflowView(afterXp,0);
  const sourceId=`owner_pass_xp_${season.id}_${telegramId}_${now}_${crypto.randomUUID().replaceAll('-','').slice(0,6)}`;
  try{await recordPlayerTimeline(env,telegramId,'season_pass_owner_xp',`получил ${amount.toLocaleString('ru-RU')} XP сезонного пропуска от владельца`,{seasonId:season.id,beforeXp,afterXp,level:afterLevel,reason},sourceId,ctx.user,now);}catch(error){console.error('owner season pass xp timeline failed',error);}
  await logStaffAction(env,ctx.user,ctx.access,'owner_panel_season_pass_xp_grant',telegramId,'season_pass',beforeXp,afterXp,{seasonId:season.id,seasonTitle:String(season.title||''),amount,level:afterLevel,displayLevel:overflow.unlocked?'50+':String(afterLevel),reason,sourceId});
  try{const subscriber=await env.DB.prepare(`SELECT chat_id FROM bot_subscribers WHERE telegram_id=? AND active=1 LIMIT 1`).bind(telegramId).first();if(subscriber?.chat_id){const send=sendTelegramMessage(env,subscriber.chat_id,`<b>⚡ Начислен XP сезонного пропуска</b>\n\n+<b>${amount.toLocaleString('ru-RU')} XP</b> · ${escapeHtml(String(season.title||'Сезонный пропуск'))}${reason?`\nПричина: ${escapeHtml(reason)}`:''}`,{inline_keyboard:[[{text:'🎟 Открыть пропуск',web_app:{url:configuredSeasonPassTasksUrl(env)}}]]});if(ctx.executionCtx?.waitUntil)ctx.executionCtx.waitUntil(send);else await send;}}catch(error){console.error('owner season pass xp notification failed',error);}
  return {ok:true,grantType:'season_pass_xp',amount,beforeXp,afterXp,level:afterLevel,displayLevel:overflow.unlocked?'50+':String(afterLevel),message:`Начислено ${amount.toLocaleString('ru-RU')} XP сезонного пропуска.`};
}

async function ownerPanelGrantRatingRecord(env, ctx, telegramId, score, reason) {
  await reconcileLeaderboardSeasonTimeline(env);
  const now = Math.floor(Date.now() / 1000);
  const season = await ensureSeason(env, now);
  if (!season || String(season.status) !== "active" || Number(season.starts_at || 0) > now || Number(season.ends_at || 0) <= now) {
    throw new ApiError(409, "Выдать рекорд можно только в активный рейтинговый сезон.");
  }
  const identity = await env.DB.prepare(`SELECT p.telegram_id,p.best_score,p.profile_xp,
      COALESCE(NULLIF(b.display_name,''),NULLIF(a.display_name,''),p.telegram_id) AS display_name,
      COALESCE(NULLIF(b.username,''),NULLIF(a.username,''),'') AS username,
      COALESCE(a.photo_url,'') AS photo_url
    FROM admin_profile_state p
    LEFT JOIN bot_subscribers b ON b.telegram_id=p.telegram_id
    LEFT JOIN leaderboard_all_time a ON a.telegram_id=p.telegram_id
    WHERE p.telegram_id=? LIMIT 1`).bind(telegramId).first();
  if (!identity) throw new ApiError(404, "Профиль игрока не найден.");
  const existing = await env.DB.prepare(`SELECT best_score FROM leaderboard_entries WHERE season_id=? AND telegram_id=? LIMIT 1`).bind(String(season.id), telegramId).first();
  const previousScore = Math.max(0, Number(existing?.best_score || 0));
  if (score <= previousScore) throw new ApiError(409, `В текущем рейтинге у игрока уже ${previousScore.toLocaleString("ru-RU")} очков. Новый рекорд должен быть выше.`);
  const caseEnsured = await ensureCasePlayerState(env, telegramId, {});
  const testerRow = await getTesterAccountSafe(telegramId, env);
  const hidden = Number(testerRow?.exclude_from_rating || 0) === 1 ? 1 : 0;
  const displayName = String(identity.display_name || telegramId).slice(0, 120);
  const username = String(identity.username || "").slice(0, 64);
  const photoUrl = String(identity.photo_url || "").slice(0, 500);
  const level = profileLevelFromXp(Number(identity.profile_xp || 0));
  const caseAvatarId = normalizeCaseCosmeticId("avatar", caseEnsured?.state?.activeAvatarId);
  const caseFrameId = normalizeCaseCosmeticId("frame", caseEnsured?.state?.activeFrameId);
  const nextProfileBest = Math.max(Math.max(0, Number(identity.best_score || 0)), score);
  await env.DB.batch([
    env.DB.prepare(`INSERT INTO leaderboard_entries (
      season_id,telegram_id,display_name,username,photo_url,best_score,level,achieved_at,updated_at,hidden,case_avatar_id,case_frame_id
    ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)
    ON CONFLICT(season_id,telegram_id) DO UPDATE SET
      display_name=excluded.display_name,username=excluded.username,photo_url=excluded.photo_url,
      case_avatar_id=excluded.case_avatar_id,case_frame_id=excluded.case_frame_id,level=excluded.level,
      best_score=CASE WHEN excluded.best_score>leaderboard_entries.best_score THEN excluded.best_score ELSE leaderboard_entries.best_score END,
      achieved_at=CASE WHEN excluded.best_score>leaderboard_entries.best_score THEN excluded.achieved_at ELSE leaderboard_entries.achieved_at END,
      updated_at=excluded.updated_at,hidden=excluded.hidden`).bind(
        String(season.id), telegramId, displayName, username, photoUrl, score, level, now, now, hidden, caseAvatarId, caseFrameId
      ),
    env.DB.prepare(`UPDATE admin_profile_state SET best_score=?,best_score_override=?,revision=revision+1,updated_at=?,updated_by=? WHERE telegram_id=?`).bind(
      nextProfileBest, nextProfileBest, now, `owner-rating:${ctx.user.id}`, telegramId
    )
  ]);
  const allTimeScore = await syncLeaderboardAllTimeFromSeasonEntries(env, {
    telegramId, displayName, username, photoUrl, level, hidden, caseAvatarId, caseFrameId, now
  });
  const sourceId = `owner_rating_${season.id}_${telegramId}_${now}`;
  try {
    await recordPlayerTimeline(env, telegramId, "rating_owner_grant", `владелец установил рекорд ${score.toLocaleString("ru-RU")} в текущем рейтинге`, {
      seasonId: String(season.id), previousScore, score, allTimeScore, reason
    }, sourceId, ctx.user, now);
  } catch (error) { console.error("owner rating grant timeline failed", error); }
  await logStaffAction(env, ctx.user, ctx.access, "owner_panel_rating_record_grant", telegramId, "rating", previousScore, score, {
    seasonId: String(season.id), seasonTitle: String(season.title || ""), allTimeScore, reason
  });
  return {
    ok: true,
    grantType: "rating_record",
    seasonId: String(season.id),
    seasonTitle: String(season.title || ""),
    previousScore,
    score,
    allTimeScore,
    message: `Рекорд текущего рейтинга установлен: ${score.toLocaleString("ru-RU")} очков.`
  };
}

function ownerPanelDirectGrantUi(htmlValue) {
  let html = String(htmlValue || "");
  if (!html || html.includes("zefirok-owner-reward-grant-ui-v2")) return html;
  // Older owner.html builds did not yet know how to grant Season Pass items.
  // Keep that compatibility patch only for those old assets; the current source
  // already owns the compensation catalog and must not receive duplicate options.
  if (!html.includes("season_pass_xp_grant")) {
    html = html.replace(
      "${group('Следы','trail',c.trails)}`;}",
      "${group('Следы','trail',c.trails)}${option('season_pass_tier:elite','Тариф · Элитный')}${option('season_pass_tier:elite_plus','Тариф · Элитный+')}${option('season_pass_xp_grant','EXP пропуска (+ к текущему)')}`;}"
    );
    html = html.replace(
      "function compCustomChoiceMeta(choice=''){const [kind,id='']=String(choice||'').split(':');const cosmetic=['skin','avatar','frame','trail'].includes(kind);const isCase=kind==='case';return{kind,id,cosmetic,isCase,max:cosmetic?1:isCase?20:5000000};}",
      "function compCustomChoiceMeta(choice=''){const [kind,id='']=String(choice||'').split(':');const cosmetic=['skin','avatar','frame','trail'].includes(kind);const isCase=kind==='case';if(kind==='season_pass_tier')return{kind,id,cosmetic:true,isCase:false,max:1};if(kind==='season_pass_xp_grant')return{kind,id:'',cosmetic:false,isCase:false,max:5000000};return{kind,id,cosmetic,isCase,max:cosmetic?1:isCase?20:5000000};}"
    );
    html = html.replace(
      "function compCustomRewardTitle(choice=''){const [kind,id='']=String(choice||'').split(':');if(kind==='points')return'Очки';if(kind==='zefir')return'Зефир';if(kind==='coffee')return'Кофе';const c=state.compensations?.rewardCatalog||{};const key={case:'cases',skin:'skins',avatar:'avatars',frame:'frames',trail:'trails'}[kind];return(c[key]||[]).find(x=>String(x.id)===id)?.title||id||'Награда';}",
      "function compCustomRewardTitle(choice=''){const [kind,id='']=String(choice||'').split(':');if(kind==='points')return'Очки';if(kind==='zefir')return'Зефир';if(kind==='coffee')return'Кофе';if(kind==='season_pass_tier')return id==='elite_plus'?'Тариф «Элитный+»':'Тариф «Элитный»';if(kind==='season_pass_xp_grant')return'EXP сезонного пропуска';const c=state.compensations?.rewardCatalog||{};const key={case:'cases',skin:'skins',avatar:'avatars',frame:'frames',trail:'trails'}[kind];return(c[key]||[]).find(x=>String(x.id)===id)?.title||id||'Награда';}"
    );
  }
  const script = `<script id="zefirok-owner-reward-grant-ui-v2">(()=>{
    const options=[['booster:points','⚡ ×2 очки · 2 забега'],['booster:treats','⚡ ×2 зефир · 2 забега'],['booster:coffee','⚡ ×2 кофе · 2 забега'],['booster:shield','🛡 Щит Зеффи · 1 забег'],['booster:second_chance','💗 Второй шанс · 1 забег'],['booster:pause','⏸ Пауза Зеффи · 1 забег'],['season_pass:elite','🎟 Пропуск · Элит'],['season_pass:elite_plus','✨ Пропуск · Элит+'],['season_pass_xp','⚡ EXP пропуска (+ к текущему)']];
    const enhance=()=>{const select=document.getElementById('playerGrantKind');if(!select)return;for(const [value,label] of options){if(!Array.from(select.options||[]).some(option=>option.value===value)){const option=document.createElement('option');option.value=value;option.textContent=label;select.appendChild(option);}}const card=select.closest('.card');const description=card?.querySelector('.section-head p');if(description)description.textContent='Начисляется напрямую на аккаунт, без Почты Зеффи. Компенсации работают отдельно через письма.';const amount=document.getElementById('playerGrantAmount');const amountLabel=amount?.closest('.field')?.querySelector('label');if(amountLabel)amountLabel.textContent='Количество / EXP';const sync=()=>{if(!amount)return;const isTier=select.value==='season_pass:elite'||select.value==='season_pass:elite_plus';const isShowcase=String(select.value||'').startsWith('showcase_style:');const fixed=isTier||isShowcase;amount.disabled=fixed;if(fixed)amount.value='1';};if(select.dataset.directGrantUiV2!=='1'){select.dataset.directGrantUiV2='1';select.addEventListener('change',sync);}sync();};
    const start=()=>{enhance();new MutationObserver(enhance).observe(document.body,{childList:true,subtree:true});};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
  })();</script>`;
  const closeIndex = html.lastIndexOf("</body>");
  if (closeIndex >= 0) html = `${html.slice(0, closeIndex)}${script}${html.slice(closeIndex)}`;
  else html += script;
  return html.replace("toast('Награда отправлена');", "toast('Награда начислена');");
}

async function ownerPanelGrantDirectReward(env, ctx, telegramId, kind, itemId, amount, reason) {
  await ensurePlayerAccountRevisionAvailable(env);
  const now = Math.floor(Date.now() / 1000);
  const sourceId = `owner_direct_${Date.now()}_${crypto.randomUUID().replaceAll("-", "").slice(0, 10)}`;
  let alreadyOwned = false;

  if (["points", "zefir", "coffee"].includes(kind)) {
    const field = ({ points:"pending_wallet", zefir:"pending_treats", coffee:"pending_coffee" })[kind];
    const results = await env.DB.batch([
      env.DB.prepare(`UPDATE admin_profile_state SET ${field}=${field}+?,revision=revision+1,updated_at=?,updated_by=? WHERE telegram_id=?`)
        .bind(amount, now, `owner-direct:${ctx.user.id}:${sourceId}`, telegramId),
      // pending_* is intentionally not covered by the economy trigger because
      // it is folded into the base wallet later. Bump the global revision in
      // the same batch so an open client can invalidate its account snapshot.
      bumpPlayerAccountRevisionStatement(env, telegramId, now)
    ]);
    if (Number(results?.[0]?.meta?.changes || 0) < 1) throw new ApiError(404, "Профиль игрока не найден.");
  } else if (kind === "case") {
    await createGrantedCases(env, telegramId, itemId, amount, `owner-direct:${ctx.user.id}`, reason);
  } else if (kind === "booster") {
    const booster = runBoosterDefinition(itemId);
    if (!booster) throw new ApiError(400, "Неизвестный усилитель.");
    await ensureCasePlayerState(env, telegramId, {});
    let update;
    if (CASE_REWARD_BOOSTER_TYPES.includes(booster.id)) {
      const column = booster.id === "points" ? "boosters_points" : booster.id === "treats" ? "boosters_treats" : "boosters_coffee";
      update = env.DB.prepare(`UPDATE case_player_state SET ${column}=MAX(0,${column})+?,revision=revision+1,updated_at=? WHERE telegram_id=?`).bind(amount,now,telegramId);
    } else {
      const jsonPath = `$.${booster.id}`;
      update = env.DB.prepare(`UPDATE case_player_state SET boosters_extra_json=json_set(CASE WHEN json_valid(boosters_extra_json) THEN boosters_extra_json ELSE '{}' END,'${jsonPath}',MAX(0,CAST(COALESCE(json_extract(CASE WHEN json_valid(boosters_extra_json) THEN boosters_extra_json ELSE '{}' END,'${jsonPath}'),0) AS INTEGER))+?),revision=revision+1,updated_at=? WHERE telegram_id=?`).bind(amount,now,telegramId);
    }
    const results = await env.DB.batch([update,bumpPlayerAccountRevisionStatement(env,telegramId,now)]);
    if (Number(results?.[0]?.meta?.changes || 0) < 1) throw new ApiError(404, "Профиль усилителей игрока не найден.");
  } else if (kind === "showcase_style") {
    await ensureAchievementConfigSchema(env);
    const style = achievementShowcaseDirectGrantStyleDefinition(itemId);
    if (!style) throw new ApiError(400, "Неизвестная витрина достижений.");
    const results = await env.DB.batch([
      env.DB.prepare(`INSERT OR IGNORE INTO achievement_showcase_style_ownership(telegram_id,style_id,source_type,source_id,unlocked_at,updated_at) VALUES(?,?,'owner_direct',?,?,?)`)
        .bind(telegramId, String(style.id), sourceId, now, now),
      bumpPlayerAccountRevisionStatement(env, telegramId, now)
    ]);
    alreadyOwned = Number(results?.[0]?.meta?.changes || 0) < 1;
  } else if (kind === "skin") {
    const cosmetic = await grantCosmeticToPlayer(env, telegramId, kind, itemId);
    alreadyOwned = Boolean(cosmetic?.alreadyOwned);
  } else {
    throw new ApiError(400, "Неизвестный тип прямой награды.");
  }

  const description = safeRewardDescription({ kind, id:itemId, amount });
  const details = { kind, itemId, amount, reason, sourceId, direct:true, alreadyOwned };
  await logStaffAction(env, ctx.user, ctx.access, "owner_panel_grant", telegramId, "direct_reward", null, amount, details);
  try {
    await recordPlayerTimeline(
      env,
      telegramId,
      "owner_direct_grant",
      alreadyOwned ? `повторная ручная выдача: ${description}` : `владелец напрямую выдал: ${description}`,
      details,
      sourceId,
      ctx.user,
      now
    );
  } catch (error) { console.error("owner direct grant timeline failed", error); }

  if (alreadyOwned) {
    return { ok:true, grantType:"direct", sourceId, alreadyOwned:true, message:"Предмет уже был у игрока. Повторная копия не добавлена." };
  }
  return { ok:true, grantType:"direct", sourceId, direct:true, message:`Начислено напрямую: ${description}.` };
}

async function ownerPanelGrantPlayer(env, ctx) {
  const telegramId = String(ctx.body?.telegramId || "").trim();
  if (!/^\d{4,20}$/.test(telegramId)) throw new ApiError(400, "Некорректный Telegram ID игрока.");
  const profile = await env.DB.prepare(`SELECT telegram_id FROM admin_profile_state WHERE telegram_id=? LIMIT 1`).bind(telegramId).first();
  if (!profile) throw new ApiError(404, "Профиль игрока не найден.");
  const rawKind = String(ctx.body?.kind || "");
  const reason = String(ctx.body?.reason || "Выдача из панели владельца").trim().slice(0, 300) || "Выдача из панели владельца";

  if (rawKind === "season_pass") {
    return ownerPanelGrantSeasonPassTier(env, ctx, telegramId, String(ctx.body?.itemId || ""), reason);
  }
  if (rawKind === "rating_record") {
    const score = ownerPanelInteger(ctx.body?.amount, 1, 999999999);
    if (score == null) throw new ApiError(400, "Некорректный рекорд рейтинга.");
    return ownerPanelGrantRatingRecord(env, ctx, telegramId, score, reason);
  }
  if (rawKind === "season_pass_xp") {
    const amount = ownerPanelInteger(ctx.body?.amount, 1, 5000000);
    if (amount == null) throw new ApiError(400, "XP сезонного пропуска должен быть от 1 до 5 000 000.");
    return ownerPanelGrantSeasonPassXp(env, ctx, telegramId, amount, reason);
  }

  const kind = rawKind === "treats" ? "zefir" : rawKind;
  if (!["points", "zefir", "coffee", "case", "skin", "booster", "showcase_style"].includes(kind)) throw new ApiError(400, "Неизвестный тип награды.");
  const singleItemReward = kind === "skin" || kind === "showcase_style";
  const cosmeticSkin = kind === "skin";
  const amount = singleItemReward ? 1 : ownerPanelInteger(ctx.body?.amount, 1, kind === "case" ? 20 : kind === "booster" ? 999 : 10000000);
  if (amount == null) throw new ApiError(400, "Некорректное количество награды.");
  let itemId = "";
  if (kind === "case") {
    itemId = normalizeCaseType(ctx.body?.itemId);
    if (!itemId) throw new ApiError(400, "Выберите тип кейса.");
  } else if (kind === "booster") {
    itemId = String(ctx.body?.itemId || "").trim().toLowerCase();
    if (!runBoosterDefinition(itemId)) throw new ApiError(400, "Выберите доступный усилитель.");
  } else if (kind === "showcase_style") {
    itemId = String(ctx.body?.itemId || "").trim();
    if (!achievementShowcaseDirectGrantStyleDefinition(itemId)) throw new ApiError(400, "Выберите доступную витрину достижений.");
  } else if (cosmeticSkin) {
    itemId = String(ctx.body?.itemId || "").trim().toLowerCase();
    if (!SKINS[itemId] || itemId === "default") throw new ApiError(400, "Выберите доступный скин.");
  }
  return ownerPanelGrantDirectReward(env, ctx, telegramId, kind, itemId, amount, reason);
}

function ownerPanelRatingSeasonView(row) {
  if (!row) return null;
  const reward = leaderboardRewardPresentation(row.reward_type, row.reward_amount, row.reward_item_id, row.reward_title, row.reward_image_url);
  return {
    id: String(row.id || ""), title: String(row.title || ""),
    startsAt: Number(row.starts_at || 0), endsAt: Number(row.ends_at || 0),
    status: String(row.status || ""), finalizedAt: Number(row.finalized_at || 0),
    reward: { type: reward.type, amount: reward.amount, title: reward.title, itemId: reward.itemId, imageUrl: ownerPanelRewardAsset(reward.type, reward.itemId) || reward.imageUrl },
    manualOverride: Number(row.manual_override || 0) === 1
  };
}

async function ownerPanelRating(env, ctx) {
  await reconcileLeaderboardSeasonTimeline(env);
  const seasonsResult = await env.DB.prepare(`SELECT * FROM leaderboard_seasons ORDER BY CASE status WHEN 'active' THEN 0 WHEN 'scheduled' THEN 1 WHEN 'ended' THEN 2 ELSE 3 END, starts_at DESC LIMIT 30`).all();
  const active = (seasonsResult.results || []).find((row) => String(row.status) === "active") || await ensureSeason(env);
  const topResult = active ? await env.DB.prepare(`SELECT telegram_id,display_name,username,photo_url,best_score,level,achieved_at FROM leaderboard_entries WHERE season_id=? AND hidden=0 ORDER BY best_score DESC,achieved_at ASC,telegram_id ASC LIMIT 20`).bind(String(active.id)).all() : { results: [] };
  return {
    ok: true,
    seasons: (seasonsResult.results || []).map(ownerPanelRatingSeasonView),
    active: ownerPanelRatingSeasonView(active),
    top: (topResult.results || []).map((row, index) => ({ place: index + 1, telegramId: String(row.telegram_id), name: String(row.display_name || row.username || row.telegram_id), username: String(row.username || ""), photoUrl: String(row.photo_url || ""), score: Number(row.best_score || 0), level: Number(row.level || 1) })),
    banners: { current: "/assets/rating/v8/season-1-cafe-opening.png", allTime: "/assets/rating/v8/all-time-rating.png" }
  };
}

async function ownerPanelCreateRatingSeason(env, ctx) {
  const title = String(ctx.body?.title || "").trim().slice(0, 80);
  const startsAt = ownerPanelInteger(ctx.body?.startsAt, 1, 4102444800);
  const endsAt = ownerPanelInteger(ctx.body?.endsAt, 1, 4102444800);
  if (title.length < 3) throw new ApiError(400, "Название сезона слишком короткое.");
  if (startsAt == null || endsAt == null || endsAt <= startsAt + 3600) throw new ApiError(400, "Проверьте даты сезона: длительность должна быть больше часа.");
  if (endsAt - startsAt > 180 * 24 * 3600) throw new ApiError(400, "Рейтинговый сезон не может длиться больше 180 дней.");
  const overlap = await findLeaderboardSeasonOverlap(env, startsAt, endsAt);
  if (overlap) throw new ApiError(409, `Период пересекается с сезоном «${String(overlap.title || overlap.id)}».`);
  const type = normalizeLeaderboardRewardType(ctx.body?.rewardType || "case");
  const amount = ownerPanelInteger(ctx.body?.rewardAmount, 1, type === "case" ? 20 : 999999999);
  if (amount == null) throw new ApiError(400, "Некорректное количество награды.");
  const itemId = type === "case" ? normalizeCaseType(ctx.body?.rewardItemId || "legendary") : "";
  if (type === "case" && !itemId) throw new ApiError(400, "Некорректный тип кейса.");
  const reward = leaderboardRewardPresentation(type, amount, itemId, "", "");
  const now = Math.floor(Date.now() / 1000);
  if (endsAt <= now) throw new ApiError(400, "Дата окончания уже прошла.");
  const seasonId = leaderboardSeasonCreateId(startsAt);
  const status = startsAt <= now ? "active" : "scheduled";
  await env.DB.prepare(`INSERT INTO leaderboard_seasons(id,title,starts_at,ends_at,status,reward_type,reward_amount,reward_claim_days,reset_plan_json,close_reason,created_at,updated_at,finalized_at,manual_override,reward_title,reward_image_url,reward_item_id) VALUES(?,?,?,?,?,?,?,?,?,'',?,?,NULL,1,?,?,?)`).bind(
    seasonId,title,startsAt,endsAt,status,reward.type,reward.amount,DEFAULT_SEASON_REWARD_CLAIM_DAYS,JSON.stringify(leaderboardSeasonResetPlan(seasonId)),now,now,reward.title,reward.imageUrl,reward.itemId
  ).run();
  await logStaffAction(env, ctx.user, ctx.access, "owner_panel_rating_create", null, "season", null, null, { seasonId,title,startsAt,endsAt,rewardType:reward.type,rewardAmount:reward.amount,rewardItemId:reward.itemId });
  return { ok: true, season: ownerPanelRatingSeasonView(await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=?`).bind(seasonId).first()) };
}

async function ownerPanelStartRatingSeason(env, ctx) {
  await reconcileLeaderboardSeasonTimeline(env);
  const seasonId = String(ctx.body?.seasonId || "").trim();
  if (!seasonId) throw new ApiError(400, "Не выбран рейтинговый сезон.");
  const season = await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();
  if (!season) throw new ApiError(404, "Рейтинговый сезон не найден.");
  const now = Math.floor(Date.now() / 1000);
  if (season.finalized_at || String(season.status) !== "scheduled" || Number(season.starts_at || 0) <= now) {
    throw new ApiError(409, "Запустить раньше времени можно только будущий запланированный сезон.");
  }
  if (Number(season.ends_at || 0) <= now) throw new ApiError(409, "Дата окончания этого сезона уже прошла.");

  const update = await env.DB.prepare(
    `UPDATE leaderboard_seasons
     SET starts_at=?,status='active',manual_override=1,updated_at=?
     WHERE id=? AND status='scheduled' AND finalized_at IS NULL AND starts_at>? AND ends_at=?
       AND NOT EXISTS (
         SELECT 1 FROM leaderboard_seasons other
         WHERE other.id<>? AND other.status IN ('scheduled','active') AND other.finalized_at IS NULL
           AND other.starts_at<? AND other.ends_at>?
       )`
  ).bind(now, now, seasonId, now, Number(season.ends_at), seasonId, Number(season.ends_at), now).run();

  if (Number(update?.meta?.changes || 0) < 1) {
    const fresh = await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();
    if (!fresh || fresh.finalized_at || String(fresh.status) !== "scheduled" || Number(fresh.starts_at || 0) <= now) {
      throw new ApiError(409, "Состояние сезона уже изменилось. Обновите список сезонов.");
    }
    const overlap = await findLeaderboardSeasonOverlap(env, now, Number(fresh.ends_at || season.ends_at), seasonId);
    if (overlap) throw new ApiError(409, `Нельзя запустить сезон: период пересечётся с «${String(overlap.title || overlap.id)}».`);
    throw new ApiError(409, "Не удалось безопасно запустить сезон. Обновите данные и повторите попытку.");
  }

  const updated = await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();
  let broadcastId = null;
  try { broadcastId = await queueRatingSeasonStartBroadcast(env, updated); }
  catch (error) { console.error("rating season start broadcast queue failed", error); }
  await logStaffAction(env, ctx.user, ctx.access, "owner_panel_rating_start", null, "season", null, null, {
    seasonId, title: String(updated?.title || season.title || ""), previousStartsAt: Number(season.starts_at || 0), startsAt: now,
    endsAt: Number(updated?.ends_at || season.ends_at || 0), broadcastId: String(broadcastId || "")
  });
  return { ok:true, season:ownerPanelRatingSeasonView(updated), notificationQueued:Boolean(broadcastId) };
}

async function ownerPanelAdjustRatingSeason(env, ctx) {
  await reconcileLeaderboardSeasonTimeline(env);
  const seasonId = String(ctx.body?.seasonId || "").trim();
  const direction = String(ctx.body?.direction || "");
  const days = ownerPanelInteger(ctx.body?.days, 1, 7);
  if (!seasonId || !["extend","shorten"].includes(direction) || ![1,7].includes(days)) throw new ApiError(400, "Выберите сезон и изменение срока на 1 или 7 дней.");
  const season = await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();
  if (!season) throw new ApiError(404, "Рейтинговый сезон не найден.");
  if (season.finalized_at || !["scheduled","active"].includes(String(season.status))) throw new ApiError(409, "Срок можно менять только у активного или запланированного сезона.");
  const now = Math.floor(Date.now()/1000);const startsAt=Number(season.starts_at||0);const currentEnd=Number(season.ends_at||0);const delta=days*24*60*60;const nextEnd=direction==="extend"?currentEnd+delta:currentEnd-delta;
  if (direction==="shorten" && String(season.status)==="active" && nextEnd<=now) throw new ApiError(409, "После сокращения дата окажется в прошлом. Используйте «Закончить сейчас».");
  if (nextEnd<=startsAt+3600) throw new ApiError(409, "Сезон должен длиться больше часа.");
  if (nextEnd-startsAt>180*24*60*60) throw new ApiError(409, "Рейтинговый сезон не может длиться больше 180 дней.");
  const overlap=await findLeaderboardSeasonOverlap(env,startsAt,nextEnd,seasonId);if(overlap)throw new ApiError(409,`Новая дата пересечётся с сезоном «${String(overlap.title||overlap.id)}».`);
  const update=await env.DB.prepare(`UPDATE leaderboard_seasons SET ends_at=?,manual_override=1,status=CASE WHEN starts_at<=? THEN 'active' ELSE 'scheduled' END,updated_at=? WHERE id=? AND finalized_at IS NULL AND status IN ('scheduled','active') AND ends_at=? AND NOT EXISTS(SELECT 1 FROM leaderboard_seasons other WHERE other.id<>? AND other.status IN ('scheduled','active') AND other.finalized_at IS NULL AND other.starts_at<? AND other.ends_at>?)`).bind(nextEnd,now,now,seasonId,currentEnd,seasonId,nextEnd,startsAt).run();
  if(Number(update?.meta?.changes||0)<1)throw new ApiError(409,"Состояние сезона изменилось или новая дата конфликтует с другим сезоном. Обновите список.");
  const updated=await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();
  await logStaffAction(env,ctx.user,ctx.access,"owner_panel_rating_timing",null,"season",currentEnd,nextEnd,{seasonId,title:String(season.title||""),direction,days});
  return {ok:true,season:ownerPanelRatingSeasonView(updated)};
}

async function ownerPanelEndRatingSeason(env, ctx) {
  await reconcileLeaderboardSeasonTimeline(env);
  const seasonId=String(ctx.body?.seasonId||"").trim();if(!seasonId)throw new ApiError(400,"Не выбран рейтинговый сезон.");
  const season=await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();if(!season)throw new ApiError(404,"Рейтинговый сезон не найден.");
  if(season.finalized_at||String(season.status)!=="active")throw new ApiError(409,"Закончить сейчас можно только активный рейтинговый сезон.");
  const now=Math.floor(Date.now()/1000);const update=await env.DB.prepare(`UPDATE leaderboard_seasons SET ends_at=?,status='ended',manual_override=1,close_reason='Завершён досрочно через Control Center',updated_at=? WHERE id=? AND status='active' AND finalized_at IS NULL AND ends_at>?`).bind(now,now,seasonId,now).run();
  if(Number(update?.meta?.changes||0)<1)throw new ApiError(409,"Сезон уже изменился. Обновите список.");
  const updated=await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();await finalizeSeason(env,updated,now);const finalRow=await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();
  await logStaffAction(env,ctx.user,ctx.access,"owner_panel_rating_end",null,"season",Number(season.ends_at||0),now,{seasonId,title:String(season.title||"")});
  return {ok:true,season:ownerPanelRatingSeasonView(finalRow)};
}

async function ownerPanelCancelRatingSeason(env, ctx) {
  const seasonId = String(ctx.body?.seasonId || "").trim();
  const season = await env.DB.prepare(`SELECT * FROM leaderboard_seasons WHERE id=? LIMIT 1`).bind(seasonId).first();
  if (!season || String(season.status) !== "scheduled" || season.finalized_at) throw new ApiError(409, "Отменить можно только запланированный сезон.");
  const now = Math.floor(Date.now() / 1000);
  await env.DB.prepare(`UPDATE leaderboard_seasons SET status='cancelled',finalized_at=COALESCE(finalized_at,?),close_reason='Запланированный сезон отменён из панели владельца',updated_at=? WHERE id=? AND status='scheduled' AND finalized_at IS NULL`).bind(now,now,seasonId).run();
  await logStaffAction(env, ctx.user, ctx.access, "owner_panel_rating_cancel", null, "season", null, null, { seasonId, title: season.title });
  return { ok: true };
}

