  if(storyVisualAssetRefs.length&&!boundAssetKey)add('story_asset_key','Папка сезонных ассетов','error','Для сезона не привязана папка ассетов. Выберите s2/s3/... в редакторе сюжета.',true);
  else if(boundAssetKey){for(const ref of storyVisualAssetRefs){const leaf=ref.target==='coffee'?'coffee':'currency',canonical=`/assets/season/${boundAssetKey}/minigame/${leaf}/`,legacy=`/assets/seasons/${boundAssetKey}/minigame/${leaf}/`;if(!ref.path.startsWith(canonical)&&!ref.path.startsWith(legacy))wrongVisualFolders.push(ref);}if(wrongVisualFolders.length)add('story_asset_key','Папка сезонных ассетов','error',`${wrongVisualFolders.length} сюжетных визуалов ссылаются не на assetKey ${boundAssetKey}.`,true,{items:wrongVisualFolders});else add('story_asset_key','Папка сезонных ассетов','pass',`assetKey ${boundAssetKey} · assets/season/${boundAssetKey}/`);}
  if(emptyStory.length)add('story','Сюжет сезона','error',`${emptyStory.length} опубликованных глав не имеют полноценного содержимого.`,true,{eventIds:emptyStory});
  else if(!enabledStory.length)add('story','Сюжет сезона','warning',`Опубликованных глав нет${draftStory.length?`; черновиков: ${draftStory.length}`:''}.`);
  else add('story','Сюжет сезона','pass',`Опубликовано ${enabledStory.length} глав${draftStory.length?` · черновиков ${draftStory.length}`:''}.`);
  if(storyActionErrors.length)add('story_actions','Сюжетные действия','error',`Некорректные действия: ${storyActionErrors.slice(0,3).join('; ')}${storyActionErrors.length>3?'…':''}`,true,{items:storyActionErrors});
  else if(storyActionCount)add('story_actions','Сюжетные действия','pass',`Проверено действий после открытия главы: ${storyActionCount}.`);
